}

.admin-notice {
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px dashed Rgba(255, 255, 0, 0.2);
  color: $yellow;
  font-size: 8px;
  @include pixelated;
  text-align: center;
  opacity: 0.8;
}

.caught-icon {
  width: 16px;
  height: 16px;
  @include sprite-render;

  @media (max-width: 600px) {
    width: 12px;
    height: 12px;
  }
}
</style>

// [PureVue-Ignore-Length]
<script setup>
import { computed, ref, onUnmounted, onMounted } from 'vue'
import PVTooltip from '@/components/common/PVTooltip.vue'
import AtmosphereLayer from '@/components/common/AtmosphereLayer.vue'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'
import { MAP_ROUTE_MAPPING } from '@/data/map-assets'

import { useUIStore } from '@/stores/ui'
import { useBattleStore } from '@/stores/battle'
import { useGameStore } from '@/stores/game'
import { useMapStore } from '@/stores/map'
import { getRouteWeather } from '@/logic/weatherUtils'

import { checkPlayerWinner, calculateSpawnGrid } from '@/logic/map/mapCardHelper'

const props = defineProps({
  map: { type: Object, required: true },
  isLocked: { type: Boolean, default: false },
  isSafariLocked: { type: Boolean, default: false },
  cycle: { type: String, default: 'day' }, 
  weather: { type: String, default: 'clear' },
  badgeCount: { type: Number, default: 0 },
  dominance: { type: Object, default: null },
  isRocketExtorted: { type: Boolean, default: false },
  spawnPool: { type: Object, default: () => ({ generic: [], specific: [], rates: {} }) },
  forcedWeather: { type: String, default: null }
})

const emit = defineEmits(['navigate'])

const uiStore = useUIStore()
const battleStore = useBattleStore()
const mapStore = useMapStore()

const cardRef = ref(null)


const isPerformanceMode = computed(() => {
  return uiStore.isAnyBlockingModalOpen || battleStore.isBattleActive || uiStore.isDebugPerformanceMode
})

const imgPath = computed(() => {
  const fileName = MAP_ROUTE_MAPPING[props.map.id] || 'default'
  return getAssetUrl(ASSET_TYPES.MAP, fileName, { cycle: props.cycle })
})

const cycleEmoji = computed(() => {
  const emojis = { morning: '🌅', day: '☀️', dusk: '🌇', night: '🌙' }
  return emojis[props.cycle] || '☀️'
})

const cycleName = computed(() => {
  const names = { morning: 'Mañana', day: 'Día', afternoon: 'Tarde', dusk: 'Atardecer', night: 'Noche' }
  return names[props.cycle] || 'Normal'
})

const seasonName = computed(() => mapStore.currentSeason.label)
const seasonEmoji = computed(() => mapStore.currentSeason.icon)

const computedWeather = computed(() => {
  // Sincronización absoluta: Usar el clima que generó el pool si está disponible
  if (props.forcedWeather) return props.forcedWeather
  if (mapStore.globalWeather) return mapStore.globalWeather
  return getRouteWeather(props.map.id, mapStore.currentSeason.id, mapStore.currentEpochHour)
})

const weatherEmoji = computed(() => {
  const emojis = { clear: '', rain: '🌧️', storm: '⚡', fog: '🌫️', snow: '🌨️', blizzard: '❄️', sandstorm: '🏜️', heatwave: '🔥' }
  return emojis[computedWeather.value] || ''
})

const weatherName = computed(() => {
  const names = { clear: 'Despejado', rain: 'Lluvia', storm: 'Tormenta', snow: 'Nieve', blizzard: 'Ventisca', sandstorm: 'Tormenta de Arena', fog: 'Niebla', heatwave: 'Ola de Calor' }
  return names[computedWeather.value] || 'Normal'
})

const atmosphere = ref(null)

const factionAnimClass = computed(() => {
  if (!props.dominance?.winner) return ''
  return props.dominance.winner === 'union' ? 'anim-shine' : 'anim-thump'
})

const gameStore = useGameStore()
const getPokemonSprite = (id) => getAssetUrl(ASSET_TYPES.POKEMON, id)

const processedGuardian = computed(() => {
  if (!props.dominance?.guardian) return null
  const id = props.dominance.guardian.id
  let isSeen = gameStore.state.seenPokedex?.includes(id) || gameStore.state.pokedex?.includes(id)
  let isCaught = gameStore.state.pokedex?.includes(id)

  if (uiStore.debugPokedexMode === 'caught') {
    isSeen = true; isCaught = true
  } else if (uiStore.debugPokedexMode === 'seen') {
    isSeen = true
  } else if (uiStore.debugPokedexMode === 'none') {
    isSeen = false; isCaught = false
  }

  const data = isSeen ? pokemonDataProvider.getPokemonData(id) : null
  const name = isSeen ? (data?.name || id.toUpperCase()) : 'Desconocido'
  const typeInfo = (isSeen && data?.type) ? data.type.toUpperCase() : '???'
  const captured = props.dominance.guardian.captured || false

  return { 
    ...props.dominance.guardian, 
    isSeen, 
    isCaught, 
    name, 
    typeInfo, 
    captured,
    sprite: getPokemonSprite(id), 
    seed: id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0) / 100
  }
})

const isPlayerWinner = computed(() => checkPlayerWinner(props.dominance?.winner, gameStore.state.faction))

const processedGrid = computed(() => {
  const gridData = spawnGrid.value
  const slots = gridData.slots || []
  const seenPokedex = gameStore.state.seenPokedex || []
  const caughtPokedex = gameStore.state.pokedex || []

  const weatherBoosts = {
    rain: ['water', 'bug', 'grass'],
    storm: ['electric', 'dragon'],
    sun: ['fire', 'grass'],
    snow: ['ice', 'steel'],
    sandstorm: ['rock', 'ground', 'steel'],
    fog: ['ghost', 'psychic', 'dark'],
    heatwave: ['fire']
  };

  const isSpeciesBoostedLocal = (id, weather) => {
    const data = pokemonDataProvider.getPokemonData(id);
    if (!data || !weatherBoosts[weather]) return false;
    const types = Array.isArray(data.type) ? data.type : [data.type];
    return types.some(t => weatherBoosts[weather].includes(t.toLowerCase()));
  }

  return slots.map((id, index) => {
    if (!id) return { id: null, key: `empty-${index}` }
    let isSeen = seenPokedex.includes(id) || caughtPokedex.includes(id)
    let isCaught = caughtPokedex.includes(id)

    if (uiStore.debugPokedexMode === 'caught') {
      isSeen = true; isCaught = true
    } else if (uiStore.debugPokedexMode === 'seen') {
      isSeen = true
    } else if (uiStore.debugPokedexMode === 'none') {
      isSeen = false; isCaught = false
    }
    const rate = props.spawnPool?.rates?.[id] || 10
    const isRare = rate < 10
    const data = isSeen ? pokemonDataProvider.getPokemonData(id) : null
    const name = isSeen ? (data?.name || id.toUpperCase()) : 'Desconocido'
    const typeInfo = (isSeen && data?.type) ? `Tipo: ${data.type.toUpperCase()}` : ''

    const cycles = ['morning', 'day', 'dusk', 'night']
    const appearingCycles = cycles.filter(c => props.map.wild?.[c]?.includes(id))
    const isLimited = appearingCycles.length > 0 && appearingCycles.length < cycles.length

    const emojiMap = { morning: '🌅', day: '☀️', dusk: '🌇', night: '🌙' }

    // Detección Atmosférica temprana para el texto
    const weather = computedWeather.value
    const isVisitor = !!props.map.weather?.[weather]?.visitors?.[id]
    const isExclusive = !!props.map.weather?.[weather]?.exclusive?.[id]

    const isBoosted = !isVisitor && !isExclusive && isSpeciesBoostedLocal(id, weather)
    const isAtmospheric = isVisitor || isExclusive || isBoosted

    let timeText = ''

    // 1. Información de Ciclo (Si es limitado y lo hemos visto)
    if (isLimited && isSeen) {
      const emojis = appearingCycles.map(c => emojiMap[c] || c).join(' ')
      timeText = `Aparición: ${emojis}`
    }

    // 2. Información Atmosférica
    if (isAtmospheric) {
      if (isSeen) {
        const weatherTag = isVisitor ? 'Visitante' : (isExclusive ? 'Exclusivo' : 'Potenciado')
        const weatherLine = `${weatherEmoji.value} ${weatherTag} por el clima.`
        timeText = timeText ? `${timeText}\n${weatherLine}` : weatherLine
      } else {
        timeText = `${weatherEmoji.value} Anomalía Atmosférica detectada.`
      }
    }

    // 3. Fallback: Habitante común (Solo si no hay ciclo ni clima)
    if (!timeText) {
      timeText = 'Habitante común.'
    }



    return {
      id, 
      key: `${id}-${index}`, 
      name, 
      sprite: getAssetUrl(ASSET_TYPES.POKEMON, id), 
      isSeen, 
      isCaught, 
      isRare: (rate < 10) || isVisitor || isExclusive, // Solo roja para raros, visitantes o exclusivos
      isAtmospheric,
      tooltipTitle: name, 
      tooltipDesc: typeInfo ? `${typeInfo}\n${timeText}` : timeText, 
      seed: (id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0) + index) / 100
    }

  })
})


const allSpawns = computed(() => [...props.spawnPool.generic, ...props.spawnPool.specific])
const currentCols = ref(3)
let resizeObserver = null

onMounted(() => {
  if (cardRef.value) {
    resizeObserver = new ResizeObserver((entries) => {
      const width = entries[0]?.contentRect.width || 0
      if (width > 580) currentCols.value = 5
      else if (width > 420) currentCols.value = 4
      else currentCols.value = 3
    })
    resizeObserver.observe(cardRef.value)
  }
})

onUnmounted(() => { if (resizeObserver) resizeObserver.disconnect() })

const lockReason = computed(() => {
  if (props.isSafariLocked) return 'REQUIERE TICKET SAFARI'
  if (!props.isLocked) return ''
  if (props.badgeCount < props.map.badges) return `REQUIERE ${props.map.badges} MEDALLAS`
  return 'BLOQUEADO'
})

const lockDescription = computed(() => {
  if (props.isSafariLocked) return 'Necesitas un Ticket Safari para entrar a esta zona.'
  if (!props.isLocked) return ''
  return `Consigue ${props.map.badges} medallas para acceder a esta zona.`
})

const spawnGrid = computed(() => {
  const { rows, cols, totalSlots } = calculateSpawnGrid(allSpawns.value.length, currentCols.value)
  const grid = new Array(totalSlots).fill(null)
  allSpawns.value.forEach((id, index) => { grid[totalSlots - 1 - index] = id })
  return { slots: grid, rows, cols }
})
</script>

<template>
  <div
    ref="cardRef"
    :class="['location-card map-card legacy-panel', { locked: isLocked, 'safari-locked': isSafariLocked }]"
    :style="{ 
      '--atmosphere-filter': atmosphere?.atmosphereStyles?.filter,
      '--bg-image': `url('${imgPath}')`
    }"
    @click.stop="!isLocked && !isPerformanceMode && emit('navigate', map.id)"
  >
    <AtmosphereLayer
      ref="atmosphere"
      :weather="computedWeather"
      :cycle="cycle"
      :season="mapStore.currentSeason.id"
      :is-performance-mode="isPerformanceMode"
      :is-locked="isLocked || isSafariLocked"
      :seed="props.map.id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0)"
    />

    <div
      v-if="isLocked || isSafariLocked"
      class="lock-overlay"
    >
      <span class="lock-text">{{ lockReason }}</span>
    </div>

    <!-- 1. Guardian (Top Left) -->
    <PVTooltip
      v-if="processedGuardian && !isLocked && !isSafariLocked"
      class="guardian-status-badge"
      :title="!processedGuardian.isSeen ? 'POKÉMON DESCONOCIDO' : (processedGuardian.captured ? 'GUARDIÁN DERROTADO' : 'POKÉMON GUARDIÁN')"
      :description="processedGuardian.captured 
        ? 'El protector de esta ruta ha sido vencido, permitiendo que una facción tome el control total.' 
        : `Un Pokémon poderoso que protege la ruta. ${processedGuardian.isSeen ? 'Es un ' + processedGuardian.name + ' (' + processedGuardian.typeInfo + '). ' : ''}Derrótalo para liberar la zona y permitir que tu facción la domine, activando bonus de captura.`"
      position="top"
    >
      <img 
        :src="processedGuardian.sprite" 
        class="guardian-mini-sprite" 
        :class="{ captured: processedGuardian.captured, 'spawn-silhouette': !processedGuardian.isCaught }"
        :style="{ '--spawn-seed': processedGuardian.seed }"
        @error="e => e.target.style.display = 'none'"
      >
      <span :class="['guardian-label', { captured: processedGuardian.captured }]">
        {{ processedGuardian.captured ? 'DERROTADO' : 'GUARDIÁN' }}
      </span>
    </PVTooltip>

    <!-- 2. Cycle Pill (Top Right) -->
    <PVTooltip
      :class="['location-tag', (isLocked || isSafariLocked) ? 'tag-locked' : 'tag-wild', atmosphere?.animClass]"
      :title="(isLocked || isSafariLocked) ? 'ZONA BLOQUEADA' : 'ESTADO AMBIENTAL'"
      :description="(isLocked || isSafariLocked) ? lockDescription : `Clima: ${weatherName} | Ciclo: ${cycleName} | Estación: ${seasonName}`"
      position="top"
    >
      <span class="pill-content">
        {{ (isLocked || isSafariLocked) ? '🔒' : (cycleEmoji + seasonEmoji + weatherEmoji) }}
      </span>
    </PVTooltip>

    <!-- 3. Faction Status (Middle Left, below Guardian) -->
    <PVTooltip
      v-if="dominance?.winner && dominance?.winner !== 'none' && !isPerformanceMode && !isLocked && !isSafariLocked"
      class="faction-status-pill"
      title="DOMINIO FACCIÓN"
      :description="`Controlado por ${dominance.winner === 'union' ? 'Unión' : 'Poder'}`"
      position="top"
    >
      <div :class="['pill-content', factionAnimClass]">
        <span class="faction-emoji">
          {{ dominance.winner === 'union' ? '⭐' : '✊' }}
        </span>
      </div>
    </PVTooltip>

    <!-- 4. Fishing Icon (Bottom Left) -->
    <PVTooltip
      v-if="map.fishing && !isPerformanceMode && !isLocked && !isSafariLocked"
      class="fishing-pill-standalone"
      title="PESCA"
      description="¡Esta zona tiene agua! Puedes pescar Pokémon aquí."
      position="top"
    >
      <div class="interactive-pill fishing-pill map-pill">
        <span class="pill-icon">🎣</span>
      </div>
    </PVTooltip>

    <!-- 5. Spawns Grid (MOVED UP to be behind other UI elements) -->
    <div
      v-if="!isLocked && !isPerformanceMode"
      class="location-spawns"
    >
      <div 
        class="spawn-grid-container" 
        :style="{ '--grid-cols': spawnGrid.cols, '--grid-rows': spawnGrid.rows }"
        :class="{ 'show-debug-grid': uiStore.isDebugGridMode }"
      >
        <div
          v-for="item in processedGrid"
          :key="item.key"
          class="spawn-slot"
        >
          <div
            v-if="item.id"
            class="spawn-content"
          >
            <div 
              :class="['sprite-wrapper', { 'rare-spawn': item.isRare, 'atmospheric-spawn': item.isAtmospheric }]"
              :style="{ '--spawn-seed': item.seed }"
            >
              <PVTooltip
                :title="item.tooltipTitle"
                :description="item.tooltipDesc"
                position="top"
                class="spawn-tooltip-trigger"
              >
                <img
                  :src="item.sprite"
                  class="pixelated"
                  :class="{ 'spawn-silhouette': !item.isCaught }"
                  @error="e => e.target.style.display = 'none'"
                >
              </PVTooltip>
            </div>
          </div>
        </div>
      </div>
    </div>

    <div
      v-if="!isPerformanceMode"
      class="location-header"
    >
      <div class="location-name">
        {{ map.name }}
      </div>
      <div class="location-desc">
        {{ map.desc }}
      </div>
    </div>

    <!-- 6. Winner Crown (Bottom Right) -->
    <PVTooltip
      v-if="isPlayerWinner && !isPerformanceMode && !isLocked && !isSafariLocked"
      class="dom-badge winning anim-aura"
      title="DOMINADO"
      description="¡Bonus de captura activo por dominio de facción!"
      position="top"
    >
      <span class="pill-content">👑</span>
    </PVTooltip>
  </div>
</template>

<style scoped lang="scss">
@use "@/styles/components/map-card-weather" as *;
.spawn-tooltip-trigger { width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; pointer-events: auto; }
</style>

import { ref, computed, nextTick, watch, toValue } from 'vue'
import { gameBus } from '@/logic/gameBus'

export function useBattleAnimations(battleStore, enemyRef) {
  // Estados de Entrada Salvaje
  const isWildEntryAnimation = ref(false)
  const isEmerging = ref(false)
  const isWildSilhouette = ref(false)
  const wildRevealActive = ref(false)
  const upcomingIsEmerging = ref(false)
  const isWildSilhouetteHalfway = ref(false)
  const isInitialLoad = ref(true)

  // Estados de Captura / Debilitamiento
  const playerCaptureActive = ref(false)
  const enemyCaptureActive = ref(false)
  const isCaptureSequenceActive = computed(() => playerCaptureActive.value || enemyCaptureActive.value)
  const caughtPokemonSnapshot = ref(null) 
  const isFaintInProgress = ref(false)
  const faintedPokemonSnapshot = ref(null)

  // Estados de Energía y Poké Ball
  const playerAnimState = ref(null) 
  const enemyAnimState = ref(null)
  const activePokeballId = ref('pokeball')
  const catchSparkles = ref([])

  const playerIsShaking = ref(false)
  const playerIsBlinking = ref(false)
  const enemyIsShaking = ref(false)
  const enemyIsBlinking = ref(false)

  // Estados de Entrenador
  const trainerAnimState = ref(null) // 'entering' | 'retreating' | 'idle'
  const isTrainerVisible = ref(false)

  // Transiciones Globales
  const isGlobalFadeActive = ref(false)

  const isIntroInProgress = computed(() => {
    const s = toValue(battleStore.fsm.currentState)
    return s === 'INITIALIZING' ||
           s === 'FIRST_INTRO' ||
           isWildEntryAnimation.value || 
           wildRevealActive.value || 
           isEmerging.value || 
           upcomingIsEmerging.value || 
           playerAnimState.value !== null || 
           enemyAnimState.value !== null ||
           trainerAnimState.value !== null ||
           isCaptureSequenceActive.value
  })

  const isPlayerSpriteSuppressed = computed(() => {
    return !toValue(battleStore.player)
  })

  const isEnemySpriteSuppressed = computed(() => {
    return !toValue(battleStore.enemy)
  })

  const revealWildPokemon = (isInstant = false) => {
    if (isInstant) {
      isWildSilhouette.value = false
      isWildEntryAnimation.value = false
      wildRevealActive.value = false
      return
    }

    wildRevealActive.value = true
    isWildSilhouette.value = true
    isWildEntryAnimation.value = true
    isEmerging.value = false 

    setTimeout(() => {
      isWildSilhouette.value = false
      isWildEntryAnimation.value = false
      wildRevealActive.value = false
    }, 600)
  }

  // SEARCH_PHASE - ENTRY_ANIM: muestra arbustos + silueta sin animar el salto
  const triggerSearchEntry = () => {
    wildRevealActive.value = true
    isWildEntryAnimation.value = false
    isWildSilhouette.value = true // Aseguramos silueta inicial en arbustos
  }

  // Sincroniza las banderas de animación visual con el estado lógico de la FSM.
  watch(
    () => [toValue(battleStore.fsm.currentState), toValue(battleStore.fsm.currentSubState)],
    ([state, sub]) => {
      if (!state) return

      // CASOS DE LIMPIEZA GLOBAL (Garantiza estado puro al iniciar o volver a búsqueda)
      const isCleanupState = [
        'INITIALIZING', 
        'SEARCH_PHASE', 
        'CONTEXT_SETUP', 
        'EXIT_BATTLE'
      ].includes(state) || sub === 'WAIT_INPUT'

      if (isCleanupState) {
        isGlobalFadeActive.value = (state === 'EXIT_BATTLE')
        isWildEntryAnimation.value = false
        isEmerging.value = false
        wildRevealActive.value = false
        upcomingIsEmerging.value = false
        isWildSilhouette.value = false
        playerAnimState.value = null
        enemyAnimState.value = null
        trainerAnimState.value = null
        isTrainerVisible.value = false

        // Limpieza profunda de estados de desmayo y captura
        isFaintInProgress.value = false
        faintedPokemonSnapshot.value = null
        playerCaptureActive.value = false
        enemyCaptureActive.value = false
        caughtPokemonSnapshot.value = null
        return
      }

      if (sub) console.log(`[useBattleAnimations] SubState: ${sub}`);

      switch (sub) {
        // 1. ENTRADA PARALELA (Búsqueda o Primer Encuentro)
        case 'INITIALIZING':
          isWildSilhouette.value = true
          wildRevealActive.value = true
          isWildEntryAnimation.value = false
          isEmerging.value = false // RESET AL INICIO ABSOLUTO
          break

        case 'PARALLEL_PREP':
        case 'PARALLEL_ENTRY':
        case 'ENTRY_ANIM':
        case 'WILD_ENTRY':
        case 'BUSH_IDLE':
        case 'BUSH_VISIBLE':
        case 'SILHOUETTE_MODE':
          isWildSilhouette.value = true
          wildRevealActive.value = true
          isWildEntryAnimation.value = false
          // Mantenemos isEmerging como esté (evita parpadeos)
          break

        // 2. SALTO PARALELO (Salto + Desvanecimiento de Arbustos)
        case 'PARALLEL_JUMP':
        case 'ENCOUNTER_ANIM':
        case 'JUMP_SHADOW':
        case 'JUMP_COLOR':
        case 'BUSH_FADE':
          console.log('[useBattleAnimations] TRIGGER JUMP');
          isWildEntryAnimation.value = true
          wildRevealActive.value = true 
          isWildSilhouette.value = true

          if (!isEmerging.value) {
            setTimeout(() => {
              isEmerging.value = true
            }, 0);
          }
          break

        case 'REVEAL_COLORS':
          isWildEntryAnimation.value = true
          wildRevealActive.value = false 
          isWildSilhouette.value = false
          isEmerging.value = false // RESET AL ATERRIZAR
          break

        // 3. GESTIÓN DE Poké Ball (LLAMADO / RETIRO)
        case 'POKEMON_CALL':
        case 'ENERGY_RELEASE':
          playerAnimState.value = 'releasing'
          break

        case 'POKEMON_RECALL':
        case 'ENERGY_RECALL':
          playerAnimState.value = 'catching'
          break

        // 4. GESTIÓN DE ENTRENADORES (VISUAL OVERLAY)
        case 'TRAINER_ENTRY':
        case 'T_VISUAL':
          trainerAnimState.value = 'entering'
          isTrainerVisible.value = true
          break

        case 'TRAINER_RETREAT':
          trainerAnimState.value = 'retreating'
          setTimeout(() => { isTrainerVisible.value = false; trainerAnimState.value = null }, 800)
          break

        case 'EMPTY_WAIT':
          isEmerging.value = false
          isWildEntryAnimation.value = false
          wildRevealActive.value = false
          isWildSilhouette.value = false
          playerAnimState.value = null
          enemyAnimState.value = null
          trainerAnimState.value = null
          isTrainerVisible.value = false
          break

        case null:
          playerAnimState.value = null
          enemyAnimState.value = null
          isEmerging.value = false
          isWildEntryAnimation.value = false
          break
      }
    }
  )

  // Funciones legacy para mantener compatibilidad con BattleArenaView.vue (se pueden limpiar luego)
  const triggerWildEmergence = () => Promise.resolve()

  // SEARCH_PHASE → ENCOUNTER_ANIM: Solo el jump + reveal.
  // Asume que triggerSearchEntry() (ENTRY_ANIM) ya corrió y los arbustos + silueta están visibles.
  const triggerSearchEncounter = () => {
    return new Promise((resolve) => {
      isWildEntryAnimation.value = true
      isEmerging.value = false

      // ENCOUNTER_JUMP (600ms)
      setTimeout(() => {
        isEmerging.value = true
      }, 600)

      // BUSH_FADE (600ms) - Sincronizado con el salto
      setTimeout(() => {
        wildRevealActive.value = false
      }, 600)

      // REVEAL_COLORS (1400ms)
      setTimeout(() => {
        isWildSilhouette.value = false
      }, 1400)

      // CLEANUP (2000ms)
      setTimeout(() => {
        isWildEntryAnimation.value = false
        isEmerging.value = false
        resolve()
      }, 2000)
    })
  }

  const triggerCatchSparkles = (side) => {
    const count = 8 // Subido un poco para que se vea más lleno
    for (let i = 0; i < count; i++) {
      // Alternar bando para asegurar dispersión equilibrada
      const direction = i % 2 === 0 ? -1 : 1
      const tx = direction * (60 + Math.random() * 120) 
      const ty = -(60 + Math.random() * 40) 
      const tf = ty + (90 + Math.random() * 40) 
      const scale = 0.5 + Math.random() * 0.8 // Variación de tamaño

      catchSparkles.value.push({
        id: `sparkle-${side}-${Date.now()}-${i}-${Math.random()}`,
        side,
        tx: tx, // Pasar solo número
        ty: ty, 
        tf: tf,
        scale,
        delay: `${Math.random() * 0.2}s` // Ráfaga más compacta (0.2s max)
      })
    }
    setTimeout(() => {
      catchSparkles.value = catchSparkles.value.filter(s => s.side !== side)
    }, 1200)
  }

  const handleReleaseRequest = (detail) => {
    const side = detail?.side || detail

    // Limpiar estados de captura inmediatamente al liberar
    if (side === 'player') playerCaptureActive.value = false
    else enemyCaptureActive.value = false

    if (side === 'player') playerAnimState.value = 'releasing'
    else enemyAnimState.value = 'releasing'

    setTimeout(() => {
      if (side === 'player') playerAnimState.value = null
      else enemyAnimState.value = null
    }, 800)
  }

  const handleCatchRequest = (detail) => {
    const side = detail?.side || detail
    if (detail?.ballId) activePokeballId.value = detail.ballId

    if (side === 'player') playerAnimState.value = 'catching'
    else enemyAnimState.value = 'catching'
    setTimeout(() => {
      if (side === 'player') playerAnimState.value = 'trapped'
      else enemyAnimState.value = 'trapped'
    }, 800)
  }

  const handleShakeRequest = (detail) => {
    const side = detail?.side || detail
    if (side === 'player') {
      playerIsShaking.value = false
      playerIsBlinking.value = false
      nextTick(() => { 
        playerIsShaking.value = true 
        playerIsBlinking.value = true
      })
      setTimeout(() => { 
        playerIsShaking.value = false 
        playerIsBlinking.value = false
      }, 600)
    } else {
      enemyIsShaking.value = false
      enemyIsBlinking.value = false
      nextTick(() => { 
        enemyIsShaking.value = true 
        enemyIsBlinking.value = true
      })
      setTimeout(() => { 
        enemyIsShaking.value = false 
        enemyIsBlinking.value = false
      }, 600)
    }
  }

  const handleFaintAnim = (e) => {
    if (isFaintInProgress.value) return // Idempotente

    const data = e?.detail || e
    const side = typeof data === 'string' ? data : (data?.side || 'enemy')
    if (side === 'enemy') {
      faintedPokemonSnapshot.value = enemyRef.value ? { ...enemyRef.value, side: 'enemy' } : { side: 'enemy' }
      isFaintInProgress.value = true
      setTimeout(() => { isFaintInProgress.value = false; faintedPokemonSnapshot.value = null }, 1300)
    } else {
      faintedPokemonSnapshot.value = { side: 'player' }
      isFaintInProgress.value = true
      setTimeout(() => { isFaintInProgress.value = false; faintedPokemonSnapshot.value = null }, 1300)
    }
  }

  const initListeners = () => {
    gameBus.on('PLAY_CATCH_ENERGY', (e) => {
      const data = e?.detail || e
      handleCatchRequest(data)
    })
    gameBus.on('PLAY_WITHDRAW', (e) => {
      const data = e?.detail || e
      handleCatchRequest(data)
    })
    gameBus.on('PLAY_RELEASE_ENERGY', (e) => handleReleaseRequest(e.detail || e))
    gameBus.on('PLAY_SEND_OUT', (e) => handleReleaseRequest(e.detail || e))

    gameBus.on('CATCH_SHAKE', (e) => {
      const data = e?.detail || e
      handleShakeRequest(data)
    })

    gameBus.on('PLAY_DAMAGE', (e) => {
      const data = e?.detail || e
      handleShakeRequest(data)
    })

    gameBus.on('POKEMON_FAINT', (e) => handleFaintAnim(e))
    gameBus.on('PLAY_FAINT', (e) => handleFaintAnim(e))

    gameBus.on('PLAY_ATTACK_ANIM', (e) => {
      const data = e?.detail || e
      const side = typeof data === 'string' ? data : (data?.side || 'player')
      const cat = data?.cat || 'physical'

      battleStore.attackerSide = side
      battleStore.activeMove = { cat, side } 

      setTimeout(() => {
        battleStore.attackerSide = null
        battleStore.activeMove = null
      }, 500)
    })

    gameBus.on('CATCH_SUCCESS', (e) => {
      const data = e?.detail || e
      const side = typeof data === 'string' ? data : (data?.side || 'enemy')

      if (side === 'player') playerCaptureActive.value = true
      else enemyCaptureActive.value = true

      const targetRef = side === 'player' ? battleStore.player : enemyRef.value
      caughtPokemonSnapshot.value = targetRef ? { ...targetRef } : null
      triggerCatchSparkles(side)

      setTimeout(() => {
        if (side === 'player') playerAnimState.value = null
        else enemyAnimState.value = null
      }, 1000)

      setTimeout(() => {
        playerCaptureActive.value = false
        enemyCaptureActive.value = false
        caughtPokemonSnapshot.value = null
      }, 2000)
    })

    gameBus.on('START_BATTLE', (e) => {
      // Solo resetear estado de captura/ball.
      // La orquestación de animaciones de intro (ENTRY_ANIM / ENCOUNTER_ANIM)
      // es responsabilidad exclusiva del watcher FSM en BattleArenaView.vue.
      playerCaptureActive.value = false
      enemyCaptureActive.value = false
      caughtPokemonSnapshot.value = null
      activePokeballId.value = 'pokeball'
    })

    watch(() => battleStore.upcomingPokemon, (newVal) => {
      if (newVal && battleStore.isSearching) {
        upcomingIsEmerging.value = true
        setTimeout(() => { upcomingIsEmerging.value = false }, 1200)
      }
    })
  }

  return {
    isWildEntryAnimation,
    isEmerging,
    isWildSilhouette,
    wildRevealActive,
    upcomingIsEmerging,
    isWildSilhouetteHalfway,
    isInitialLoad,
    isCaptureSequenceActive,
    caughtPokemonSnapshot,
    isFaintInProgress,
    faintedPokemonSnapshot,
    playerAnimState,
    enemyAnimState,
    activePokeballId,
    catchSparkles,
    playerCaptureActive,
    enemyCaptureActive,
    playerIsShaking,
    playerIsBlinking,
    enemyIsShaking,
    enemyIsBlinking,
    trainerAnimState,
    isTrainerVisible,
    isGlobalFadeActive,
    isIntroInProgress,
    revealWildPokemon,
    triggerWildEmergence,
    triggerSearchEncounter,
    triggerCatchSparkles,
    initListeners,
    isPlayerSpriteSuppressed
  }
}

import { computed } from 'vue'
import { useGameStore } from '@/stores/game'

/**
 * Composable para gestionar la visibilidad y estados del HUD en combate.
 * Centraliza la lógica de supresión para evitar interferencias entre bandos.
 */
export function useBattleHud(animations, battleStore, enemyRef) {
  const {
    playerAnimState,
    enemyAnimState,
    isFaintInProgress,
    faintedPokemonSnapshot,
    enemyCaptureActive,
    isCaptureSequenceActive,
    caughtPokemonSnapshot,
    isIntroInProgress
  } = animations

  const unwrap = (val) => (val && typeof val === 'object' && 'value' in val ? val.value : val)

  /**
   * Determina si el HUD del enemigo debe estar oculto.
   * REGLA MAESTRA: Asiento ocupado -> HUD Visible. Asiento vacío -> HUD Oculto.
   */
  const isEnemyHudSuppressed = computed(() => {
    const s = unwrap(battleStore.state)
    // REGLA MAESTRA: Ocultar si no hay enemigo activo Y no hay previsualización inicial
    return !s?.enemy && !s?._initialEnemy
  })

  /**
   * Determina si el HUD del jugador debe estar oculto.
   * REGLA MAESTRA: Asiento ocupado -> HUD Visible. Asiento vacío -> HUD Oculto.
   */
  const isPlayerHudSuppressed = computed(() => {
    return !battleStore.state.player
  })

  /**
   * Datos del enemigo activo a mostrar en el HUD, 
   * manejando snapshots de captura y desmayo.
   */
  /**
   * Datos del enemigo activo a mostrar en el HUD, 
   * manejando snapshots de captura y desmayo.
   * [FASE 2] Soporte para previsualización de próximo encuentro.
   */
  const activeEnemyHudData = computed(() => {
    const state = unwrap(battleStore.fsm?.currentState)
    const subState = unwrap(battleStore.fsm?.currentSubState)
    if (state === 'REWARDS_PHASE' && subState === 'EMPTY_WAIT') return null

    // 1. Prioridad: Snapshot de captura (durante la animación de éxito)
    if (isCaptureSequenceActive.value && caughtPokemonSnapshot.value) return caughtPokemonSnapshot.value

    // 2. Prioridad: Snapshot de desmayo (mientras desaparece)
    if (isFaintInProgress.value && faintedPokemonSnapshot.value?.side === 'enemy') return faintedPokemonSnapshot.value

    // 3. Prioridad: Búsqueda / Previsualización (Encuentro Actual)
    if (battleStore.isSearching || battleStore.isFinishing) {
      return enemyRef.value || unwrap(battleStore.state)?._initialEnemy
    }

    // 4. Default: El enemigo actual del combate
    return enemyRef.value || unwrap(battleStore.state)?._initialEnemy
  })

  const gs = useGameStore()

  /**
   * Determina si los datos del enemigo deben mostrarse como "?" (Scrambled).
   * REGLA: Durante ENTRY_ANIM, ocultar datos a menos que se tenga BINOCULARES.
   */
  const shouldScrambleEnemyData = computed(() => {
    const subState = unwrap(battleStore.fsm?.currentSubState)
    const hasBinoculars = gs.state.inventory?.binoculars > 0

    const isSilhouetteState = [
      'ENTRY_ANIM', 
      'PARALLEL_PREP', 
      'PARALLEL_ENTRY', 
      'SILHOUETTE_MODE', 
      'BUSH_IDLE'
    ].includes(subState)

    return isSilhouetteState && !hasBinoculars
  })

  return {
    isEnemyHudSuppressed,
    isPlayerHudSuppressed,
    activeEnemyHudData,
    shouldScrambleEnemyData
  }
}

import { STATUS_ACTIONS } from './statusActions';

export const SPECIAL_ACTIONS = {
  'leech_seed': (src, tgt, srcStages, tgtStages, addLogFn, _battleCtx) => {
    if (tgt.type === 'grass' || tgt.type2 === 'grass') {
      addLogFn(`¡No afecta a ${tgt.name}!`, 'log-info', tgt);
    } else if (!tgt.seeded) {
      tgt.seeded = true;
      addLogFn(`¡${tgt.name} fue infectado por drenadoras!`, 'log-info', tgt);
    } else {
      addLogFn(`¡${tgt.name} ya está infectado!`, 'log-info', tgt);
    }
  },
  'roar': (src, tgt, srcStages, tgtStages, addLogFn, battleCtx) => {
    if (!battleCtx) return;
    const b = battleCtx.activeBattle || battleCtx;

    if (tgt.ability === 'Succión' || tgt.ability === 'Ventosa') {
      addLogFn(`¡La ${tgt.ability} de ${tgt.name} impidió ser arrastrado!`, 'log-info', tgt);
      return;
    }

    const isPlayerAttacking = (src === b.player);

    if (isPlayerAttacking) {
      if (!b.isTrainer && !b.isGym) {
        addLogFn(`¡El ${tgt.name} salvaje huyó asustado!`, 'log-player', tgt);
        b.over = true;
      } else {
        const team = b.enemyTeam || [];
        const aliveOthers = team.filter(p => p.uid !== tgt.uid && p.hp > 0);
        if (aliveOthers.length === 0) {
          addLogFn('¡Pero no hay nadie para sustituirle!', 'log-info', tgt);
          return;
        }
        const randomPick = aliveOthers[Math.floor(Math.random() * aliveOthers.length)];
        addLogFn(`¡${tgt.name} fue expulsado del campo!`, 'log-player', 'player');
        b.enemy = randomPick;
        Object.keys(tgtStages).forEach(k => tgtStages[k] = 0);
        addLogFn(`¡${randomPick.name} entra al combate!`, 'log-info', 'enemy_trainer');
      }
    } else {
      if (!b.isTrainer && !b.isGym) {
        addLogFn(`¡${src.name} expulsó a ${tgt.name} del combate!`, 'log-enemy', src);
        b.over = true;
      } else {
        const team = b.playerTeam || [];
        const aliveOthers = team.filter(p => p.uid !== tgt.uid && p.hp > 0);
        if (aliveOthers.length === 0) {
          addLogFn('¡Pero no surtió efecto!', 'log-enemy', src);
          return;
        }
        const randomPick = aliveOthers[Math.floor(Math.random() * aliveOthers.length)];
        addLogFn(`¡${tgt.name} fue expulsado del campo!`, 'log-enemy', 'enemy_trainer');
        b.player = randomPick;
        Object.keys(tgtStages).forEach(k => tgtStages[k] = 0);
        addLogFn(`¡Envía a ${randomPick.name}!`, 'log-info', 'player');
      }
    }
  },
  'curse': (src, tgt, srcStages, tgtStages, addLogFn, _battleCtx) => {
    const isGhost = src.type === 'ghost' || src.type2 === 'ghost';
    if (isGhost) {
      const cost = Math.floor(src.maxHp / 2);
      src.hp = Math.max(0, src.hp - cost);
      tgt.cursed = true;
      addLogFn(`¡${src.name} sacrificó PS para maldecir a ${tgt.name}!`, 'log-info', src);
    } else {
      srcStages.atk = Math.min(6, (srcStages.atk || 0) + 1);
      srcStages.def = Math.min(6, (srcStages.def || 0) + 1);
      srcStages.spe = Math.max(-6, (srcStages.spe || 0) - 1);
      addLogFn(`¡${src.name} redujo su Velocidad pero subió su Ataque y Defensa!`, 'log-info', src);
    }
  },
  'destiny_bond': (src, tgt, srcStages, tgtStages, addLogFn, _battleCtx) => {
    src.destinyBond = true;
    addLogFn(`¡${src.name} intenta llevarse a su rival al destino común!`, 'log-info', src);
  },
  'perish_song': (src, tgt, srcStages, tgtStages, addLogFn, _battleCtx) => {
    if (src.perishSongCount === undefined) src.perishSongCount = 3;
    if (tgt.perishSongCount === undefined) tgt.perishSongCount = 3;
    addLogFn('¡Todos los que escucharon el canto morirán en 3 turnos!', 'log-info', src);
  },
  'transform': (src, tgt, srcStages, tgtStages, addLogFn, _battleCtx) => {
    const originalName = src.name;
    if (!src.isTransformed) {
      src.originalForm = JSON.parse(JSON.stringify(src));
      src.isTransformed = true;
    }
    src.id = tgt.id;
    src.name = tgt.name;
    src.type = tgt.type;
    src.type2 = tgt.type2;
    src.atk = tgt.atk;
    src.def = tgt.def;
    src.spa = tgt.spa;
    src.spd = tgt.spd;
    src.spe = tgt.spe;
    // Copy moves with 5 PP
    src.moves = JSON.parse(JSON.stringify(tgt.moves)).map(m => {
      m.pp = 5;
      m.maxPP = 5;
      return m;
    });
    addLogFn(`¡${originalName} se transformó en ${tgt.name}!`, 'log-info', src);
  },
  'tri_attack': (src, tgt, srcStages, tgtStages, addLogFn) => {
    const roll = Math.random();
    if (roll < 0.066) STATUS_ACTIONS.burn(src, tgt, srcStages, tgtStages, addLogFn);
    else if (roll < 0.132) STATUS_ACTIONS.paralyze(src, tgt, srcStages, tgtStages, addLogFn);
    else if (roll < 0.20) STATUS_ACTIONS.freeze(src, tgt, srcStages, tgtStages, addLogFn);
  },
  'focus_energy': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    src.focusEnergy = true;
    addLogFn(`¡${src.name} se está concentrando!`, 'log-info', src);
  },
  'lock_on': (src, tgt, _srcStages, _tgtStages, addLogFn) => {
    src.lockOn = true;
    addLogFn(`¡${src.name} fijó el blanco en ${tgt.name}!`, 'log-info', src);
  },
  'mirror_move': (src, tgt, srcStages, tgtStages, addLogFn, battleCtx) => {
    if (tgt.lastMove && tgt.lastMove.name !== 'Movimiento Espejo') {
      const move = tgt.lastMove;
      addLogFn(`¡Movimiento Espejo copió ${move.name}!`, 'log-info', src);
      // Simular ejecución: Si tiene efecto, intentar ejecutarlo
      if (move.effect) {
        // Buscamos en los módulos ya importados (o que se pueden importar)
        // Por ahora, manejamos los más comunes o usamos un log
        console.log(`[MirrorMove] Triggering: ${move.effect}`);
      }
    } else {
      addLogFn("¡Pero falló!", 'log-info', src);
    }
  },
  'thrash': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    if (!src.thrashTurns) {
      src.thrashTurns = 2 + Math.floor(Math.random() * 2);
      addLogFn(`¡${src.name} está entrando en un frenesí!`, 'log-info', src);
    }
  },
  'false_swipe': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    addLogFn(`¡Un ataque contenido!`, 'log-info', src);
  },
  'trap': (_src, tgt, _srcStages, _tgtStages, addLogFn) => {
    tgt.trapped = true;
    addLogFn(`¡${tgt.name} no puede escapar!`, 'log-info', tgt);
  },
  'ingrain': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    src.ingrain = true;
    addLogFn(`¡${src.name} echó raíces!`, 'log-info', src);
  },
  'endure': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    src.endure = true;
    addLogFn(`¡${src.name} aguantará el próximo golpe!`, 'log-info', src);
  },
  'protect': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    src.protect = true;
    addLogFn(`¡${src.name} se protegió!`, 'log-info', src);
  },
  'belly_drum': (src, _tgt, srcStages, _tgtStages, addLogFn) => {
    const cost = Math.floor(src.maxHp / 2);
    if (src.hp > cost && srcStages.atk < 6) {
      src.hp -= cost;
      srcStages.atk = 6;
      addLogFn(`¡${src.name} redujo su HP y maximizó su Ataque!`, 'log-info', src);
    } else {
      addLogFn("¡Pero falló!", 'log-info', src);
    }
  },
  'teleport': (src, tgt, srcStages, tgtStages, addLogFn, battleCtx) => {
    if (!battleCtx) return;
    const b = battleCtx.activeBattle || battleCtx;
    const isWild = !b.isTrainer && !b.isGym;

    if (isWild) {
      addLogFn(`¡${src.name} se teletransportó fuera del combate!`, 'log-info', src);
      b.over = true;
    } else {
      const isPlayer = (src === b.player);
      const team = isPlayer ? b.playerTeam : b.enemyTeam;
      const aliveOthers = (team || []).filter(p => p.uid !== src.uid && p.hp > 0);

      if (aliveOthers.length === 0) {
        addLogFn(`¡${src.name} se teletransportó fuera del combate!`, 'log-info', src);
        b.over = true;
      } else {
        addLogFn(`¡${src.name} se teletransportó!`, 'log-info', src);
        if (!isPlayer) {
          const randomPick = aliveOthers[Math.floor(Math.random() * aliveOthers.length)];
          b.enemy = randomPick;
          addLogFn(`¡${randomPick.name} entra al combate!`, 'log-info', randomPick);
        } else {
          // Para el jugador, por simplicidad en este punto, fallamos si no es el último
          addLogFn("¡Pero no hay nadie para sustituirle!", 'log-info', src);
        }
      }
    }
  },
  'rapid_spin': (src, _tgt, srcStages, _tgtStages, addLogFn) => {
    let cleared = false;
    if (src.seeded) { src.seeded = false; cleared = true; }
    if (src.bound) { src.bound = 0; cleared = true; }
    if (srcStages.spikes) { srcStages.spikes = 0; cleared = true; }

    if (cleared) {
      addLogFn(`¡${src.name} se libró de las trampas girando!`, 'log-info', src);
    }
  },
  'identify': (src, tgt, _srcStages, _tgtStages, addLogFn) => {
    tgt.identified = true;
    addLogFn(`¡${src.name} identificó a ${tgt.name}!`, 'log-info', src);
  },
  'swagger': (src, tgt, srcStages, tgtStages, addLogFn) => {
    tgtStages.atk = Math.min(6, (tgtStages.atk || 0) + 2);
    addLogFn(`¡Subió mucho el Ataque de ${tgt.name}!`, 'log-info', tgt);
    STATUS_ACTIONS.confuse(src, tgt, srcStages, tgtStages, addLogFn);
  },
  'recharge': (src, _tgt, _srcStages, _tgtStages, _addLogFn) => {
    src.mustRecharge = true;
  },
  'taunt': (_src, tgt, _srcStages, _tgtStages, addLogFn) => {
    tgt.tauntTurns = 3;
    addLogFn(`¡${tgt.name} cayó en la mofa!`, 'log-info', tgt);
  },
  'torment': (_src, tgt, _srcStages, _tgtStages, addLogFn) => {
    tgt.tormentActive = true;
    addLogFn(`¡${tgt.name} sufre de tormento!`, 'log-info', tgt);
  },
  'disable': (src, tgt, _srcStages, _tgtStages, addLogFn) => {
    if (tgt.lastMove && !tgt.disabledMove) {
      tgt.disabledMove = tgt.lastMove;
      tgt.disabledTurns = 4;
      addLogFn(`¡El movimiento ${tgt.lastMove.name} de ${tgt.name} ha sido desactivado!`, 'log-info', tgt);
    } else {
      addLogFn("¡Pero falló!", 'log-info', src);
    }
  },
  'dream_eater': (src, _tgt, _srcStages, _tgtStages, addLogFn, battleCtx) => {
    if (battleCtx && battleCtx.lastDamage) {
      const heal = Math.floor(battleCtx.lastDamage / 2);
      src.hp = Math.min(src.maxHp, src.hp + heal);
      addLogFn(`¡${src.name} absorbió los sueños de su rival! (+${heal} HP)`, 'log-info', src);
    }
  },
  'drain_50': (src, _tgt, _srcStages, _tgtStages, addLogFn, battleCtx) => {
    if (battleCtx && battleCtx.lastDamage) {
      const heal = Math.max(1, Math.floor(battleCtx.lastDamage / 2));
      src.hp = Math.min(src.maxHp, src.hp + heal);
      addLogFn(`¡${src.name} recuperó salud absorbiendo energía! (+${heal} HP)`, 'log-info', src);
    }
  },
  'recoil_25': (src, _tgt, _srcStages, _tgtStages, addLogFn, battleCtx) => {
    if (battleCtx && battleCtx.lastDamage) {
      const recoil = Math.max(1, Math.floor(battleCtx.lastDamage / 4));
      src.hp = Math.max(0, src.hp - recoil);
      addLogFn(`¡${src.name} recibió daño por el retroceso! (-${recoil} HP)`, 'log-info', src);
    }
  },
  'recoil_33': (src, _tgt, _srcStages, _tgtStages, addLogFn, battleCtx) => {
    if (battleCtx && battleCtx.lastDamage) {
