// [PureVue-Ignore-Length]
import { calculateDamage, getEffectiveSpeed } from './battleEngine'
import { canAttack } from './battleFlow'
import { dispatchMoveEffect } from './actions/actionRegistry'
import { decideEnemyMove, shouldEnemySwitch, findBestSwitchIndex } from './ai/battleAI'
import { gameBus } from '@/logic/gameBus'
import { recalcPokemonStats } from '@/logic/pokemonFactory'
import { getMechanicalWeather, WEATHER_MECHANICAL } from './weatherMapper'
import { getDayCycle } from '@/logic/timeUtils'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { MOVE_DATA } from '@/data/moves'

/**
 * Handles the turn logic for a single move execution.
 */
export async function executeTurn(store, moveIndex) {
  const p = store.activeBattle.player
  const e = store.activeBattle.enemy

  if (!p || !e) {
    console.warn('[BattleTurn] Aborting turn: Player or Enemy is null', { p, e })
    return
  }

  const fsm = store.fsm
  const BATTLE_STATES = store.BATTLE_STATES || { ACTIVE_BATTLE: 'ACTIVE_BATTLE' }
  const BATTLE_SUBSTATES = store.BATTLE_SUBSTATES || { 
    BUILD_QUEUE: 'BUILD_QUEUE', POP_ACTION: 'POP_ACTION', APPLY_MOVE: 'APPLY_MOVE', 
    EVAL_HP: 'EVAL_HP', RESOLVE_PLAYER_FAINT: 'RESOLVE_PLAYER_FAINT', 
    RESOLVE_ENEMY_FAINT: 'RESOLVE_ENEMY_FAINT', EVAL_CONTINUE: 'EVAL_CONTINUE',
    TURN_ENGINE: 'TURN_ENGINE'
  }

  // Thrash check
  if (p.thrashTurns > 0) {
    const forcedIdx = p.moves.findIndex(m => m.effect === 'thrash');
    if (forcedIdx !== -1) moveIndex = forcedIdx;
  } else if (p.encoreTurns > 0 && p.encoreMove) {
    const forcedIdx = p.moves.findIndex(m => m.id === p.encoreMove.id);
    if (forcedIdx !== -1) moveIndex = forcedIdx;
  }

  const move = p.moves[moveIndex]
  if (move.pp <= 0) {
    store.addLog(`¡No queda PP para ${move.name}!`, 'log-info', p)
    return
  }

  fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.BUILD_QUEUE)

  // Determine Turn Order (Consider Priority)
  const isWild = !store.activeBattle.isTrainer && !store.activeBattle.isGym
  const eMove = decideEnemyMove(e, p, store.playerStages, isWild)

  const pPrio = move?.priority || 0
  const ePrio = eMove?.priority || 0

  const pSpe = getEffectiveSpeed(p, store.playerStages, { weather: store.activeBattle.weather, getStatMultiplier: (s) => 1 + (0.5 * s) })
  const eSpe = getEffectiveSpeed(e, store.enemyStages, { weather: store.activeBattle.weather, getStatMultiplier: (s) => 1 + (0.5 * s) })

  let playerFirst = true
  if (pPrio > ePrio) playerFirst = true
  else if (ePrio > pPrio) playerFirst = false
  else playerFirst = pSpe >= eSpe

  let queue = []
  if (playerFirst) {
    queue.push({ source: 'player', action: () => runPlayerAction(store, moveIndex) })
    if (eMove) queue.push({ source: 'enemy', action: () => runEnemyAction(store) })
  } else {
    if (eMove) queue.push({ source: 'enemy', action: () => runEnemyAction(store) })
    queue.push({ source: 'player', action: () => runPlayerAction(store, moveIndex) })
  }

  fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.BUILD_QUEUE)

  while (queue.length > 0) {
    fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POP_ACTION)
    const currentAction = queue.shift()

    fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.APPLY_MOVE)
    await currentAction.action()

    fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.EVAL_HP)

    if (store.activeBattle.player.hp <= 0) {
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.RESOLVE_PLAYER_FAINT)
      if (store.handleFaint) await store.handleFaint('player')
      break;
    }

    if (store.activeBattle.enemy.hp <= 0) {
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.RESOLVE_ENEMY_FAINT)
      if (store.handleFaint) await store.handleFaint('enemy')
      break;
    }

    if (store.activeBattle.over) break;

    if (queue.length > 0) {
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.EVAL_CONTINUE)
      await new Promise(r => setTimeout(r, 400)) // Reducido de 600
    }
  }

  if (store.activeBattle?.over) {
    // Si la batalla terminó durante este turno (ej. por un efecto secundario o captura),
    // simplemente retornamos. Los orquestadores ya se encargaron de la terminación.
    return
  }

  if (store.persistBattle) store.persistBattle()
}

export async function runPlayerAction(store, moveIndex) {
  const p = store.activeBattle.player
  const e = store.activeBattle.enemy
  const fsm = store.fsm
  const BATTLE_STATES = store.BATTLE_STATES || { ACTIVE_BATTLE: 'ACTIVE_BATTLE' }
  const BATTLE_SUBSTATES = store.BATTLE_SUBSTATES || {}
  const move = p.moves[moveIndex]

  if (p.tauntTurns > 0 && move.cat === 'status') {
    store.addLog(`¡La mofa impide a ${p.name} usar ${move.name}!`, 'log-info', p)
    return
  }
  if (p.disabledMove && move.id === p.disabledMove.id) {
    store.addLog(`¡${move.name} está desactivado!`, 'log-info', p)
    return
  }

  if (!canAttack(p, store.addLog)) return

  if (p.furyCutterCount && move.effect !== 'fury_cutter') p.furyCutterCount = 0;
  p.destinyBond = false;
  p.snatching = false;
  p.lastMove = move;
  store.attackerSide = 'player'

  move.pp--
  store.addLog(`¡${p.name} usó ${move.name}!`, 'log-player', p)

  let executableMove = { ...move };
  if (move.effect === 'metronome') {
    const moveNames = Object.keys(MOVE_DATA).filter(n => n !== 'Metrónomo');
    const randomName = moveNames[Math.floor(Math.random() * moveNames.length)];
    executableMove = { ...MOVE_DATA[randomName], name: randomName, id: randomName.toLowerCase().replace(/\s/g, '_') };
    store.addLog(`¡El Metrónomo escogió ${randomName}!`, 'log-info', p);
  } else if (move.effect === 'mirror_move') {
    if (e.lastMove) {
      executableMove = { ...e.lastMove };
      store.addLog(`¡Espejo copió ${executableMove.name}!`, 'log-info', p);
    } else {
      store.addLog("¡Pero falló!", 'log-info', p);
      return;
    }
  }

  const normalizeCat = (c) => {
    if (c === 'Estado' || c === 'status' || c === 3) return 'status'
    if (c === 'Especial' || c === 'special' || c === 2) return 'special'
    return 'physical'
  }

  store.activeMove = { ...executableMove, side: 'player' }
  gameBus.emit('PLAY_ATTACK_ANIM', { side: 'player', cat: normalizeCat(executableMove.cat) })

  // Sanity check for stats & level & moves
  if (!p.atk || !p.maxHp || executableMove.power === undefined) recalcPokemonStats(p)
  if (!e.atk || !e.maxHp) recalcPokemonStats(e)

  if (!p.level) p.level = 5 // Fallback

  if (!p.atk || !e.def || (executableMove.power === undefined && executableMove.cat !== 'status')) {
    store.addLog(`[Error] Datos faltantes: Atk:${p.atk} Def:${e.def} Pwr:${executableMove.power}`, 'log-error', p)
  }
  if (!store.activeBattle.participants.includes(p.uid)) {
    store.activeBattle.participants.push(p.uid)
  }

  // Precision Check
  const moveAcc = executableMove.acc || 100;
  if (moveAcc < 100 && !p.lockOn) {
    const accStage = store.playerStages.acc || 0;
    const evaStage = store.enemyStages.eva || 0;
    const weather = store.activeBattle.weather?.type;
    const mechWeather = getMechanicalWeather(weather);
    const cycle = getDayCycle();
    const isSunActive = mechWeather === WEATHER_MECHANICAL.SUN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'day' || cycle === 'morning'))
    const isRainActive = mechWeather === WEATHER_MECHANICAL.RAIN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'night' || cycle === 'dusk'))
    let finalAcc = moveAcc;

    // Reglas de Clima para Precisión
    if (isRainActive && (executableMove.id === 'thunder' || executableMove.id === 'hurricane')) finalAcc = 100;
    else if (isSunActive && (executableMove.id === 'thunder' || executableMove.id === 'hurricane')) finalAcc = 50;
    else if ((mechWeather === WEATHER_MECHANICAL.HAIL || mechWeather === WEATHER_MECHANICAL.SNOW) && executableMove.id === 'blizzard') finalAcc = 100;
    else if (mechWeather === WEATHER_MECHANICAL.FOG) finalAcc = Math.floor(moveAcc * 0.6);

    finalAcc = finalAcc * (1 + (0.33 * accStage)) * (1 - (0.33 * evaStage));
    if (Math.random() * 100 > finalAcc) {
      store.addLog(`¡El ataque de ${p.name} falló!`, 'log-info', p);
      return;
    }
  }
  if (p.lockOn) p.lockOn = false; // Se consume el efecto

  // [FIX] Asegurar que el efecto esté presente (Self-Healing de datos antiguos en el equipo)
  if (executableMove && (executableMove.effect === undefined || executableMove.effect === null)) {
    const freshMoveData = pokemonDataProvider.getMoveData(executableMove.name);
    if (freshMoveData && freshMoveData.effect) {
      executableMove.effect = freshMoveData.effect;
    }
  }

  // 1. Determinar número de golpes
  let totalHits = 1;
  if (executableMove.hits) {
    if (typeof executableMove.hits === 'number') totalHits = executableMove.hits;
    else if (executableMove.hits === '2-5') {
      const rolls = [2, 2, 2, 3, 3, 3, 4, 5];
      totalHits = rolls[Math.floor(Math.random() * rolls.length)];
    }
  }

  let hitsDealt = 0;
  let totalDamageDealt = 0;

  try {
    for (let i = 0; i < totalHits; i++) {
      if (e.hp <= 0) break;

      const result = calculateDamage(p, e, executableMove, { 
        atkStages: store.playerStages.atk, 
        defStages: store.enemyStages.def,
        weather: store.activeBattle.weather
      })

      if (result.isNoEffect) {
        store.addLog('¡No afecta!', 'log-enemy', e)
        break;
      } else {
        const damage = Math.floor(result.dmg || 0)

        if (move.cat !== 'status') {
          if (totalHits === 1) store.addLog(`¡${e.name} recibió ${damage} de daño!`, 'log-info', e)
          totalDamageDealt += damage;
        }

        if (result.isNotVeryEffective && i === 0) store.addLog('No es muy eficaz...', 'log-player', p)
        if (result.isSuperEffective && i === 0) store.addLog('¡Es muy eficaz!', 'log-player', p)

        // Magnitude log
        if (move.effect === 'magnitude' && result.power) {
          const magMap = { 10: 4, 30: 5, 50: 6, 70: 7, 90: 8, 110: 9, 150: 10 };
          const mag = magMap[result.power] || 7;
          store.addLog(`¡Magnitud ${mag}!`, 'log-info', e);
        }

        // Update HP and Context
        store.activeBattle.enemy.hp = Math.max(0, e.hp - damage)
        gameBus.emit('PLAY_DAMAGE', { side: 'enemy', damage })
        store.activeBattle.lastDamage = damage
        hitsDealt++;

        if (e.hp <= 0) {
          // El handleFaint se procesará en EVAL_HP
          break;
        }

        // Rage check
        if (e.rageActive && damage > 0 && e.hp > 0) {
          store.enemyStages.atk = Math.min(6, (store.enemyStages.atk || 0) + 1);
          store.addLog(`¡La furia de ${e.name} está creciendo!`, 'log-info', e);
        }

        if (move.cat !== 'status') {
          await new Promise(r => setTimeout(r, 200))
        }
      }
    }

    if (totalHits > 1 && hitsDealt > 0) {
      store.addLog(`¡Golpeó ${hitsDealt} veces!`, 'log-info', e);
    }

    // [Post-Action] Recoil, Drain, Self-KO
    if (totalDamageDealt > 0) {
      // Recoil
      if (executableMove.recoil) {
        const recoilDiv = typeof executableMove.recoil === 'number' ? executableMove.recoil : 2; // recoil: true -> 1/2 damage (standard fail jump)
        const recoilDmg = Math.floor(totalDamageDealt / recoilDiv);
        if (recoilDmg > 0) {
          p.hp = Math.max(0, p.hp - recoilDmg);
          store.addLog(`¡${p.name} recibió daño por retroceso!`, 'log-info', p);
        }
      }
      // Drain
      if (executableMove.drain) {
        const heal = Math.floor(totalDamageDealt / 2);
        if (heal > 0) {
          p.hp = Math.min(p.maxHp, p.hp + heal);
          store.addLog(`¡${p.name} absorbió energía!`, 'log-info', p);
        }
      }
    }

    if (executableMove.selfKO) {
      p.hp = 0;
      store.addLog(`¡${p.name} se sacrificó!`, 'log-info', p);
    }

    store.attackerSide = null

    // Execute Move Effect (Pass the battleCtx)
    if (executableMove.effect && hitsDealt > 0) {
      dispatchMoveEffect(executableMove.effect, p, e, store.playerStages, store.enemyStages, store.addLog, store.activeBattle)
    }

  } catch (err) {
    console.error('[Battle] Error in runPlayerAction:', err)
    store.addLog('¡Error en el turno del jugador!', 'log-error', p)
  }
}

export async function runEnemyAction(store) {
  const p = store.activeBattle.player
  const e = store.activeBattle.enemy
  if (e.hp <= 0) return
  const fsm = store.fsm
  const BATTLE_STATES = store.BATTLE_STATES || { ACTIVE_BATTLE: 'ACTIVE_BATTLE' }
  const BATTLE_SUBSTATES = store.BATTLE_SUBSTATES || {}
  const s = store.enemyStages

  if (e.tauntTurns > 0 && e.lastMove?.cat === 'status') {
    // Note: Enemy selection already happened, but if they were taunted during turn
    // (e.g. player faster and used Taunt), we block it here.
    // However, enemy AI should handle it. This is a safety check.
  }

  if (!canAttack(e, store.addLog)) return

  const isWild = !store.activeBattle.isTrainer && !store.activeBattle.isGym

  if (!isWild && shouldEnemySwitch(e, p, store.activeBattle.enemyTeam)) {
    const bestIdx = findBestSwitchIndex(store.activeBattle.enemyTeam, p, e.uid)
    if (bestIdx !== -1) {
      const newPoke = store.activeBattle.enemyTeam[bestIdx]
      store.addLog(`¡${store.activeBattle.trainerName || 'El entrenador'} retira a ${e.name}!`, 'log-enemy', 'enemy_trainer')

      // AI SWITCH FLOW (Manual Standard Alignment)
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.TRAINER_RETREAT)
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_RECALL)
      gameBus.emit('PLAY_WITHDRAW', { side: 'enemy' })
      await new Promise(r => setTimeout(r, 800))
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT)

      const _oldEnemy = e
      store.activeBattle.enemy = newPoke

      // Limpiar estadísticas del enemigo pero preservar efectos de campo
      const s = store.enemyStages
      store.enemyStages.atk = 0; store.enemyStages.def = 0; store.enemyStages.spa = 0; store.enemyStages.spd = 0; store.enemyStages.spe = 0; store.enemyStages.acc = 0; store.enemyStages.eva = 0;

      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_CALL)
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.OCCUPY_SEAT)
      store.addLog(`¡Envía a ${newPoke.name}!`, 'log-enemy', newPoke)
      gameBus.emit('PLAY_SEND_OUT', { side: 'enemy', pokemon: newPoke })
      await new Promise(r => setTimeout(r, 800))

      // Daño por Púas
      if (s.spikes > 0 && newPoke.type !== 'flying' && newPoke.type2 !== 'flying' && newPoke.ability !== 'Levitación') {
        const dmg = Math.floor(newPoke.maxHp * (s.spikes / 8))
        newPoke.hp = Math.max(0, newPoke.hp - dmg)
        store.addLog(`¡${newPoke.name} recibió daño por las púas!`, 'log-info', newPoke)
        gameBus.emit('PLAY_SOUND', 'statusDamage')
      }
      return
    }
  }

  if ((store.activeBattle.isGym) && e.hp < (e.maxHp * 0.25) && !store.activeBattle.enemyUsedItem) {
    store.activeBattle.enemyUsedItem = true
    const heal = Math.floor(e.maxHp * 0.5)
    e.hp = Math.min(e.maxHp, e.hp + heal)
    store.addLog(`¡El Líder usó una Hiper Poción!`, 'log-enemy', 'enemy_trainer')
    store.addLog(`¡${e.name} recuperó salud!`, 'log-info', e, 'enemy')
    return
  }

  const enemyMove = decideEnemyMove(e, p, store.playerStages, isWild)
  if (!enemyMove) {
    store.addLog(`¡${e.name} no tiene más PP y usa Forcejeo!`, 'log-enemy', e)
    return
  }

  // Sanity check for stats & moves
  if (!e.atk || !e.maxHp || enemyMove.power === undefined) recalcPokemonStats(e)
  if (!p.atk || !p.maxHp) recalcPokemonStats(p)
  if (!e.level) e.level = 5

  if (e.furyCutterCount && enemyMove.effect !== 'fury_cutter') e.furyCutterCount = 0;
  e.destinyBond = false;
  e.snatching = false;
  e.lastMove = enemyMove
  store.attackerSide = 'enemy'
  store.addLog(`¡${e.name} usó ${enemyMove.name}!`, 'log-enemy', e)

  let executableMove = { ...enemyMove };
  if (enemyMove.effect === 'metronome') {
    const moveNames = Object.keys(MOVE_DATA).filter(n => n !== 'Metrónomo');
    const randomName = moveNames[Math.floor(Math.random() * moveNames.length)];
    executableMove = { ...MOVE_DATA[randomName], name: randomName, id: randomName.toLowerCase().replace(/\s/g, '_') };
    store.addLog(`¡El Metrónomo escogió ${randomName}!`, 'log-info', e);
  } else if (enemyMove.effect === 'mirror_move') {
    if (p.lastMove) {
      executableMove = { ...p.lastMove };
      store.addLog(`¡Espejo copió ${executableMove.name}!`, 'log-info', e);
    } else {
      store.addLog("¡Pero falló!", 'log-info', e);
      return;
    }
  }

  const normalizeCat = (c) => {
    if (c === 'Estado' || c === 'status' || c === 3) return 'status'
    if (c === 'Especial' || c === 'special' || c === 2) return 'special'
    return 'physical'
  }

  store.activeMove = { ...executableMove, side: 'enemy' }
  gameBus.emit('PLAY_ATTACK_ANIM', { side: 'enemy', cat: normalizeCat(executableMove.cat) })

  // Precision Check
  const moveAcc = executableMove.acc || 100;
  if (moveAcc < 100 && !e.lockOn) {
    const accStage = store.enemyStages.acc || 0;
    const evaStage = store.playerStages.eva || 0;
    const weather = store.activeBattle.weather?.type;
    const mechWeather = getMechanicalWeather(weather);
    const cycle = getDayCycle();
    const isRaining = mechWeather === WEATHER_MECHANICAL.RAIN
    const isSunny = mechWeather === WEATHER_MECHANICAL.SUN
    const isDayTime = cycle === 'day' || cycle === 'morning'
    const isNightTime = cycle === 'night' || cycle === 'dusk'

    // Potenciadores de Horario (Daño) - No afectan precisión aquí directamente pero definimos para claridad
    const isSunActive = isSunny || (mechWeather === WEATHER_MECHANICAL.CLEAR && isDayTime)
    const isRainActive = isRaining || (mechWeather === WEATHER_MECHANICAL.CLEAR && isNightTime)

    let finalAcc = moveAcc;

    // Reglas de Clima para Precisión (Solo clima real, no horario)
    if (isRaining && (executableMove.id === 'thunder' || executableMove.id === 'hurricane')) finalAcc = 100;
    else if (isSunny && (executableMove.id === 'thunder' || executableMove.id === 'hurricane')) finalAcc = 50;
    else if ((mechWeather === WEATHER_MECHANICAL.HAIL || mechWeather === WEATHER_MECHANICAL.SNOW) && executableMove.id === 'blizzard') finalAcc = 100;
    else if (mechWeather === WEATHER_MECHANICAL.FOG) finalAcc = Math.floor(moveAcc * 0.6);

    finalAcc = finalAcc * (1 + (0.33 * accStage)) * (1 - (0.33 * evaStage));
    if (Math.random() * 100 > finalAcc) {
      store.addLog(`¡El ataque de ${e.name} falló!`, 'log-info', e);
      return;
    }
  }
  if (e.lockOn) e.lockOn = false; // Se consume el efecto

  // 1. Determinar número de golpes
  let totalHits = 1;
  if (executableMove.hits) {
    if (typeof executableMove.hits === 'number') totalHits = executableMove.hits;
    else if (executableMove.hits === '2-5') {
      const rolls = [2, 2, 2, 3, 3, 3, 4, 5];
      totalHits = rolls[Math.floor(Math.random() * rolls.length)];
    }
  }

  let hitsDealt = 0;
  let totalDamageDealt = 0;

  try {
    for (let i = 0; i < totalHits; i++) {
      if (p.hp <= 0) break;

      const eResult = calculateDamage(e, p, executableMove, {
        atkStages: store.enemyStages.atk,
        defStages: store.playerStages.def,
        weather: store.activeBattle.weather
      })

      if (eResult.isNoEffect) {
        store.addLog('¡No afecta!', 'log-player', p)
        break;
      } else {
        const damage = Math.floor(eResult.dmg || 0)

        if (enemyMove.cat !== 'status') {
          if (totalHits === 1) store.addLog(`¡${p.name} recibió ${damage} de daño!`, 'log-info', p)
          totalDamageDealt += damage;
        }

        if (eResult.isCrit && i === 0) store.addLog('¡Un golpe crítico!', 'log-enemy', e)
        if (eResult.isSuperEffective && i === 0) store.addLog('¡Es muy eficaz!', 'log-enemy', e)
        if (eResult.isNotVeryEffective && i === 0) store.addLog('No es muy eficaz...', 'log-enemy', e)

        // Magnitude log
        if (enemyMove.effect === 'magnitude' && eResult.power) {
          const magMap = { 10: 4, 30: 5, 50: 6, 70: 7, 90: 8, 110: 9, 150: 10 };
          const mag = magMap[eResult.power] || 7;
          store.addLog(`¡Magnitud ${mag}!`, 'log-info', p);
        }

        p.hp = Math.max(0, p.hp - damage)
        gameBus.emit('PLAY_DAMAGE', { side: 'player', damage })
        store.activeBattle.lastDamage = damage
        hitsDealt++;

        if (p.hp <= 0) {
          break;
        }

        // Rage check
        if (p.rageActive && damage > 0 && p.hp > 0) {
          store.playerStages.atk = Math.min(6, (store.playerStages.atk || 0) + 1);
          store.addLog(`¡La furia de ${p.name} está creciendo!`, 'log-info', p);
        }

        if (enemyMove.cat !== 'status') {
          await new Promise(r => setTimeout(r, 200))
        }
      }
    }

    if (totalHits > 1 && hitsDealt > 0) {
      store.addLog(`¡Golpeó ${hitsDealt} veces!`, 'log-info', p);
    }

    // [Post-Action] Recoil, Drain, Self-KO
    if (totalDamageDealt > 0) {
      // Recoil
      if (executableMove.recoil) {
        const recoilDiv = typeof executableMove.recoil === 'number' ? executableMove.recoil : 2;
        const recoilDmg = Math.floor(totalDamageDealt / recoilDiv);
        if (recoilDmg > 0) {
          e.hp = Math.max(0, e.hp - recoilDmg);
          store.addLog(`¡${e.name} recibió daño por retroceso!`, 'log-info', e);
        }
      }
      // Drain
      if (executableMove.drain) {
        const heal = Math.floor(totalDamageDealt / 2);
        if (heal > 0) {
          e.hp = Math.min(e.maxHp, e.hp + heal);
          store.addLog(`¡${e.name} absorbió energía!`, 'log-info', e);
        }
      }
    }

    if (executableMove.selfKO) {
      e.hp = 0;
      store.addLog(`¡${e.name} se sacrificó!`, 'log-info', e);
    }

    store.attackerSide = null

    if (executableMove.effect && hitsDealt > 0) {
      dispatchMoveEffect(executableMove.effect, e, p, store.enemyStages, store.playerStages, store.addLog, store.activeBattle)
    }
  } catch (err) {
    console.error('[Battle] Error in runEnemyAction:', err)
    store.addLog('¡Error en el turno del oponente!', 'log-error', e)
  }
}

import { generateEncounter } from '@/logic/encounters'
import { handleEntryAbilities } from './battleFlow'
import { getMechanicalWeather } from './weatherMapper'
import { FIRE_RED_MAPS } from '@/data/maps'
import { useUIStore } from '@/stores/ui'
import { useMapStore } from '@/stores/map'
import { useEventStore } from '@/stores/events'

/**
 * Orchestrates the start of a battle.
 * @param {Object} ctx - The battle store context (refs, state, etc)
 */
export async function startBattleSequence(ctx, enemyPoke, options = {}) {
  const { 
    isGym = false, gymId = null, locationId = 'plains', 
    isTrainer = false, enemyTeam = null, trainerName = 'Entrenador',
    battleOptions = {}, isFishing = false, wasSearching: wasSearchingOpt = null
  } = options

  const playerPoke = ctx.gs.state.team.find(p => p.hp > 0 && !p.onMission && !p.onDefense)
  if (!playerPoke) {
    useUIStore().notify('No tienes Pokémon sanos para combatir', '❌')
    return
  }

  // Si hay un combate activo pero NO está en fase de finalización, forzamos huida.
  if (ctx.isBattleActive && !ctx.isFinishing && !ctx.activeBattle.value?.over && !ctx.isSearching) {
    console.warn('[BATTLE] Combate en curso detectado. Forzando huida del anterior.')
    await ctx.endBattle(false, true)
  }

  // [PROYECTO VICIO] Absolutamente todos los combates inician con wasSearching: true por defecto
  // para garantizar que pasen por la fase de inicialización de slots/arbustos
  const wasSearching = wasSearchingOpt !== null ? wasSearchingOpt : true

  const { sanitizePokemon } = await import('@/logic/pokemonFactory')
  const mapStore = useMapStore()

  const isFromUpcoming = wasSearching && ctx.upcomingPokemon.value && (ctx.upcomingPokemon.value.id === enemyPoke.id)
  const finalEnemyPoke = isFromUpcoming ? ctx.upcomingPokemon.value : enemyPoke

  sanitizePokemon(playerPoke)
  sanitizePokemon(finalEnemyPoke)

  // LIMPIEZA DE ESTADOS VOLÁTILES
  ctx.clearVolatileStatus(playerPoke)
  ctx.clearVolatileStatus(finalEnemyPoke)

  // Initial context values
  let rarity = 50

  ctx.activeBattle.value = {
    // Escenario Limpio: Iniciamos SIEMPRE en NULL para permitir animaciones de entrada
    enemy: null, 
    player: null, 
    // Data real preservada para la activación controlada
    _initialEnemy: finalEnemyPoke,
    _initialPlayer: playerPoke,
    isGym, gymId, isTrainer, enemyTeam,
    playerTeam: ctx.gs.state.team,
    trainerName, locationId, turn: 'player', turnCount: 1, over: false,
    isFishing, rarity,
    weather: { 
      type: getMechanicalWeather(mapStore.currentWeather), 
      visual: mapStore.currentWeather, 
      turns: -1 
    },
    playerTeamIndex: ctx.gs.state.team.indexOf(playerPoke),
    participants: [playerPoke.uid], learnQueue: [], ...battleOptions
  }

  if (battleOptions.isDebug) {
    ctx.debugLoopPokemon.value = JSON.parse(JSON.stringify(enemyPoke))
    if (!wasSearching) ctx.debugLoopPokemon.value = null
  }

  ctx.gs.registerPokedex(enemyPoke.id, false)
  if (isTrainer && enemyTeam) enemyTeam.forEach(p => ctx.gs.registerPokedex(p.id, false))
  ctx.persistBattle()

  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  ctx.isIntroAnimating.value = true

  // PROTOCOLO DE ASIENTOS: Fuente de Verdad para Visibilidad
  ctx.activeBattle.value.enemy = null // El enemigo siempre se vacía al empezar un encuentro

  // El jugador solo se vacía si el Pokémon líder ha cambiado (Modo Persistente)
  const currentP = ctx.activeBattle.value.player
  const leaderP = ctx.player.value?.team?.[0]
  if (!currentP || !leaderP || currentP.uid !== leaderP.uid) {
    ctx.activeBattle.value.player = null
  }

  ctx.clearLogs()

  // [PHASE] CONTEXT_SETUP (Manual 4. Context Setup)
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.RECEIVE_CONFIG)

  // Apply Item Modifiers (Manual 356)
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.APPLY_ITEM_MODIFIERS)
  const hasBinoculars = ctx.debugBinoculars.value || (ctx.gs.state.inventory?.['binoculars'] > 0)

  // Weight Calculation (Manual 344)
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.WEIGHT_CALCULATION)
  if (isFishing) {
    const loc = FIRE_RED_MAPS.find(l => l.id === locationId)
    if (loc && loc.fishing) {
      const pool = loc.fishing.pool
      const rates = loc.fishing.rates
      const idx = pool.indexOf(finalEnemyPoke.id)
      if (idx !== -1) {
        const totalRate = rates.reduce((a, b) => a + b, 0)
        rarity = (rates[idx] / totalRate) * 100
      }
    }
  }
  ctx.activeBattle.value.rarity = rarity

  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.INJECT_FILTERS)
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.READY_FOR_GEN)
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.VACATE_ALL_SEATS)

  // [PHASE] INITIALIZING (Manual 2. Initialization Phase)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.CHECK_CONTEXT)

  // ASYNC_THREAD START (Manual 409)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.ASYNC_THREAD)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.GEN_TEAMS)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.MARK_EVENT)

  // PRELOAD_FINAL_COORDS (Manual 412)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.PRELOAD_FINAL_COORDS, 50)

  // SET_SEARCH_FLAG (Manual 413)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.SET_SEARCH_FLAG)
  ctx.isSearching.value = wasSearching

  if (wasSearching) {
    // FLUJO DE BÚSQUEDA (Manual 6. SEARCH PHASE)
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.PARALLEL_PREP)
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.UPDATE_BUTTON)
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.BUSH_VISIBLE)
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.SILHOUETTE_MODE)

    // OCUPACIÓN DEL ASIENTO: El Pokémon aparece visualmente con su silueta ya preparada
    ctx.activeBattle.value.enemy = finalEnemyPoke

    return // BLOQUEO: Esperamos interacción del usuario
  } else {
    // ENTRADA DIRECTA (Wild, Trainer o Gym)
    fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENTRY_ANIM)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENCOUNTER_TYPE_CHECK)

    if (isTrainer || isGym) {
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.TRAINER_ENTRY)
      fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.T_VISUAL)
    } else {
      // Wild Entry Directa
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.WILD_ENTRY)
      ctx.activeBattle.value.enemy = finalEnemyPoke
    }
  }

  await initBattleSequence(ctx, { 
    locationId, isTrainer, trainerName, isGym, gymId, wasSearching,
    initialEnemy: finalEnemyPoke,
    initialPlayer: playerPoke
  })
}

/**
 * Visual initialization and first turn setup.
 */
export async function initBattleSequence(ctx, { locationId, isTrainer, trainerName, isGym, gymId, wasSearching, initialEnemy, initialPlayer }) {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  ctx.isIntroAnimating.value = true

  // PRECARGA DE COORDENADAS FINAL (Manual 412)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.PRELOAD_FINAL_COORDS, 50)

  if (wasSearching) {
    // --- FLUJO BÚSQUEDA (Manual 7. ENCOUNTER ANIMATION) ---
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENCOUNTER_TYPE_CHECK)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.WILD_ENCOUNTER)

    // SALTO PARALELO (Bushes + Jump + Binoculars Check)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.CHECK_BINOCULARS)
    fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.PARALLEL_JUMP)

    const hasBinoculars = ctx.debugBinoculars.value || (ctx.gs.state.inventory?.['binoculars'] > 0)
    if (!hasBinoculars) {
      await new Promise(r => setTimeout(r, 150))
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.BUSH_FADE, 100)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.REVEAL_COLORS, 500)
    } else {
      await new Promise(r => setTimeout(r, 600))
    }
  } else {
    // --- FLUJO DIRECTO (Manual 5. FIRST_INTRO / 7. ENCOUNTER_ANIM) ---
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENCOUNTER_TYPE_CHECK)

    if (isTrainer || isGym) {
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.TRAINER_ENCOUNTER)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.SHOW_DIALOGS)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.TRAINER_RETREAT, 800)

      // Llamado del Pokémon del rival (Según diagrama 840)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.POKEMON_CALL, 100)
      ctx.activeBattle.value.enemy = initialEnemy
    } else {
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.WILD_ENTRY)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.PARALLEL_PREP, 400)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.BUSH_VISIBLE)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.SILHOUETTE_MODE)
      // El asiento ya fue ocupado en startBattleSequence
    }
  }

  // --- LLAMADO DEL JUGADOR (Identity Guard) ---
  const currentPlayer = ctx.activeBattle.value.player
  const needsCall = !currentPlayer || (currentPlayer.uid !== initialPlayer.uid)

  if (needsCall) {
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_CALL, 100)
    ctx.activeBattle.value.player = initialPlayer
  } else {
    console.log('[Orchestrator] Player already in seat, maintaining presence')
  }

  // --- SINCRONIZACIÓN FINAL (Audit-Compliance) ---
  await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.ANIM_SYNC, 800)
  await fsm.transition(BATTLE_STATES.REORDER_TEAM, null)

  // Forzar actualización de cámara tras la activación paralela
  window.dispatchEvent(new Event('resize'))

  ctx.attackerSide.value = null
  ctx.activeMove.value = null

  // Usar la data preservada para logs y habilidades (ya que player/enemy pueden ser null por el protocolo Clean Stage)

  const startMsg = isTrainer || isGym 
    ? `¡${trainerName} te desafía!` 
    : `¡Un ${initialEnemy.name} salvaje apareció!`

  ctx.addLog(startMsg, 'log-info', initialEnemy)
  handleEntryAbilities(initialPlayer, initialEnemy, ctx.playerStages.value, ctx.enemyStages.value, ctx.addLog)

  if (isTrainer || isGym) await ctx.gs.save()

  if (!isTrainer && !isGym) {
    const encounterOptions = {
      activeEvents: useMapStore().activeEvents,
      dominanceData: useMapStore().mapWinners,
      shinyMultiplier: useEventStore().globalMultipliers?.shiny || 1,
      forceEncounter: true 
    }

    generateEncounter(locationId, ctx.gs.state, encounterOptions).then(encounter => {
      if (encounter && encounter.type === 'wild') {
        if (fsm.currentState.value !== BATTLE_STATES.EXIT_BATTLE) {
          fsm.transition(null, BATTLE_SUBSTATES.GEN_NEW_S2)
          ctx.upcomingPokemon.value = { ...encounter.pokemon }
        }
      }
    })
  }

  // Flujo normal de inicio de combate directo (Entrenadores o encuentro forzado)
  ctx.isIntroAnimating.value = false
  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.WAIT_INPUT, 300)

  ctx.upcomingPokemon.value = null 


  ctx.isIntroAnimating.value = false
}

/**
 * Restores a battle state from saved data.
 */
export function restoreBattleState(ctx, battleData) {
  if (!battleData) {
    ctx.activeBattle.value = null
    ctx.fsm.transition(ctx.BATTLE_STATES.EXIT_BATTLE)
    return
  }
  ctx.activeBattle.value = battleData
  if (battleData.playerStages) ctx.playerStages.value = battleData.playerStages
  if (battleData.enemyStages) ctx.enemyStages.value = battleData.enemyStages
  if (battleData.battleLogs) ctx.battleLogs.value = battleData.battleLogs

  if (!battleData.over) {
    ctx.fsm.transition(ctx.BATTLE_STATES.ACTIVE_BATTLE, ctx.BATTLE_SUBSTATES.WAIT_INPUT)
  } else {
    ctx.fsm.transition(ctx.BATTLE_STATES.EXIT_BATTLE)
  }
}

import { gameBus } from '@/logic/gameBus'
import { calculateBaseExp, processExpGain, calculateMoneyGain } from './battleRewards'
import { getBattleRewardModifiers } from '@/logic/war/bonusEngine'
import { levelUpPokemon } from '@/logic/pokemonFactory'
import { useUIStore } from '@/stores/ui'

/**
 * Handles the fainting of a Pokémon.
 */
export async function processFaint(ctx, side) {
  const isPlayer = side === 'player'
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, isPlayer ? BATTLE_SUBSTATES.PLAYER_FAINT_SEQ : BATTLE_SUBSTATES.ENEMY_FAINT)

  if (ctx.faintedSides.value.has(side)) return
  ctx.faintedSides.value.add(side)

  const pokemon = isPlayer ? ctx.player.value : ctx.enemy.value
  const opponent = isPlayer ? ctx.enemy.value : ctx.player.value

  if (pokemon.destinyBond && opponent && opponent.hp > 0) {
    ctx.addLog(`¡${pokemon.name} se llevó a ${opponent.name} con él!`, 'log-info', pokemon)
    opponent.hp = 0
    await new Promise(r => setTimeout(r, 500))
    await processFaint(ctx, isPlayer ? 'enemy' : 'player')
  }

  if (isPlayer) {
    ctx.addLog(`¡${pokemon.name} se ha debilitado!`, 'log-player', pokemon)

    // PLAYER_FAINT_SEQ (Manual 10. Player Faint Sequence)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAYER_FAINT_SEQ)

    // RECALL_FLOW (Manual 668)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.RECALL_FLOW)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_RECALL)
    gameBus.emit('PLAY_WITHDRAW', { side: 'player', isFaint: true })
    await new Promise(r => setTimeout(r, 800))
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT)
    ctx.activeBattle.value.player = null // Liberar asiento tras retiro

    // CHECK_TEAM (Manual 674)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.CHECK_TEAM)
    const nextPoke = ctx.gs.state.team.find(p => p.hp > 0)

    if (!nextPoke) {
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ALL_FAINTED)
      ctx.activeBattle.value.over = true
      ctx.addLog('¡No te quedan Pokémon sanos!', 'log-error', 'player')
      // Esperar a que la animación de faint/retiro termine antes del fade out
      await new Promise(r => setTimeout(r, 1500))
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.DEFEAT_SCREEN)
      await terminateBattle(ctx, false)
    } else {
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.HAS_HEALTHY)
      ctx.addLog('¡Elige a tu próximo Pokémon!', 'log-info', 'player')
      ctx.faintedSides.value.delete('player')
      useUIStore().isBattleSwitchForced = true
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.SWITCH_MENU)
    }
  } else {
    const isTr = ctx.activeBattle.value.isTrainer || ctx.activeBattle.value.isGym
    const enemyName = isTr ? pokemon.name : `¡${pokemon.name} salvaje`
    ctx.addLog(`${enemyName} fue derrotado!`, 'log-enemy', pokemon)

    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ENEMY_DEFEAT)

    // Secuencia de Salto + Faint (ahora bajo PLAY_ENEMY_FAINT según manual)
    gameBus.emit('PLAY_SOUND', 'faint')
    gameBus.emit('PLAY_FAINT', { side: 'enemy' })
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAY_ENEMY_FAINT)

    // Espera proporcional a la animación (1.0s según manual)
    await new Promise(r => setTimeout(r, 1000))

    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT)
    ctx.activeBattle.value.enemy = null

    if (isTr && ctx.activeBattle.value.enemyTeam) {
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ENEMY_REPLACEMENT_SEQ)
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.CLEANUP_MEMORY)

      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.CHECK_REMAINING)
      const nextEnemy = ctx.activeBattle.value.enemyTeam.find(p => p.hp > 0)
      if (nextEnemy) {
        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.STABILIZE_STAGE)

        const s = ctx.enemyStages.value
        ctx.enemyStages.value = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, 
          reflect: s.reflect || 0, lightScreen: s.lightScreen || 0, safeguard: s.safeguard || 0, mist: s.mist || 0, spikes: s.spikes || 0 }

        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.AI_NEXT_PICK)
        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.SELECT_COUNTER)

        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_CALL)
        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.OCCUPY_SEAT)
        ctx.activeBattle.value.enemy = nextEnemy
        ctx.addLog(`¡Entrenador envía a ${nextEnemy.name}!`, 'log-enemy', 'enemy_trainer')
        gameBus.emit('PLAY_SEND_OUT', { side: 'enemy', pokemon: nextEnemy })
        await new Promise(r => setTimeout(r, 800))
        return
      }
    }

    ctx.activeBattle.value.over = true 
    ctx.activeBattle.value.enemy = null
    ctx.faintedSides.value.add('enemy')
    await terminateBattle(ctx, true)
  }
}

/**
 * Terminates the battle and processes results.
 */
export async function terminateBattle(ctx, win, fled = false) {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  if (!ctx.activeBattle.value) {
    fsm.transition(BATTLE_STATES.EXIT_BATTLE)
    return
  }

  const battleData = { ...ctx.activeBattle.value }
  const enemyRef = battleData.enemy
  const locId = battleData.locationId

  ctx.activeBattle.value.over = true
  ctx.faintedSides.value.clear()

  if (win && !fled) calculateBattleRewards(ctx)

  syncAndPersist(ctx)

  if (ctx.activeBattle.value) {
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT)
    ctx.activeBattle.value.enemy = null
    ctx.activeBattle.value._initialEnemy = null
  }

  fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.CHECK_OUTCOME)

  if (!win && !fled) {
    await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT)
    await new Promise(r => setTimeout(r, 1000))
    await ctx.gs.save(false)

    fsm.transition(BATTLE_STATES.EXIT_BATTLE)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.ENTRY_CHECK)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.DEFEAT_SCREEN)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.DEFEAT_WAIT)
    return
  }

  if (fled) {
    fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.WAIT_LOG_QUEUE_ONLY)
    await ctx.waitForLogs()

    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.ENTRY_CHECK)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.EXECUTE_CLEANUP)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.CLEAR_UI)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.TRIGGER_CLOSE)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.RESET_FLAGS)
    await ctx.completeBattleFlow('map')
    return
  }

  if (win && !fled) {
    await calculateBattleRewards(ctx)
  }

  await ctx.gs.save(false)
  await ctx.waitForLogs()
  syncTeamHP(ctx)

  // Asegurar 1 segundo de "escenario vacío" tras el faint
  await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT)
  await new Promise(r => setTimeout(r, 1000))

  // REORDER_TEAM (Manual 7. Reorder Team / Switch)
  // Siempre intentamos sincronizar al primer miembro sano al final del combate
  const firstHealthy = ctx.gs.state.team.find(p => p.hp > 0)
  const currentActive = ctx.player.value
  const needsReorder = firstHealthy && (!currentActive || firstHealthy.uid !== currentActive.uid)

  if (needsReorder) {
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.SWITCHING)
    if (currentActive && currentActive.hp > 0) {
      // RECALL_FLOW
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_RECALL)
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.RENDER_BALL)
      gameBus.emit('PLAY_WITHDRAW', { side: 'player' })
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.ENERGY_RECALL)
      await new Promise(r => setTimeout(r, 800))
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.VACATE_SEAT)
      ctx.activeBattle.value.player = null
    }

    if (ctx.activeBattle.value) {
      // CALL_FLOW
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_CALL)
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.RENDER_BALL)

      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.OCCUPY_SEAT)
      ctx.activeBattle.value.player = firstHealthy
      ctx.activeBattle.value.playerTeamIndex = ctx.gs.state.team.findIndex(p => p.uid === firstHealthy.uid)

      gameBus.emit('PLAY_SEND_OUT', { side: 'player', pokemon: firstHealthy })
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.ENERGY_RELEASE)
      await new Promise(r => setTimeout(r, 800))

      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_APPEAR)
      await new Promise(r => setTimeout(r, 400))
    }
  }

  const persistenceMode = ctx.activeBattle.value?.persistenceMode || 'PERSISTENT'
  const isSingle = persistenceMode === 'SINGLE' || ctx.activeBattle.value?.isTrainer

  await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.CHECK_PERSISTENCE)

  if (!isSingle) {
    await ctx.completeBattleFlow('search')
  } else {
    // Para combates únicos, nos quedamos en REWARDS_PHASE con sub-estado final para mostrar botones
    fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT)
  }
}

/**
 * Calculates and distributes XP and money rewards.
 */
export async function calculateBattleRewards(ctx) {
  const e = ctx.activeBattle.value.enemy || ctx.activeBattle.value._initialEnemy
  if (!e) return

  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.DISTRIBUTE_XP)

  const isTr = ctx.activeBattle.value.isTrainer || ctx.activeBattle.value.isGym
  const locId = ctx.activeBattle.value.locationId
  const enemyRef = e

  if (enemyRef?.isGuardian) await ctx.warStore.addPoints(locId, 'guardian', true)
  else await ctx.warStore.addPoints(locId, isTr ? 'trainer_win' : 'wild_win', true)

  if (ctx.activeBattle.value.isCapture) await ctx.eventStore.submitCompetitionEntry(enemyRef, 'hourly_competition')

  if (ctx.activeBattle.value.isGym && ctx.activeBattle.value.gymId) {
    const gid = ctx.activeBattle.value.gymId
    if (!ctx.gs.state.defeatedGyms.includes(gid)) {
      ctx.gs.state.defeatedGyms.push(gid); ctx.gs.state.badges++
      if (ctx.activeBattle.value.rewardTM) { 
        ctx.gs.state.inventory[ctx.activeBattle.value.rewardTM] = (ctx.gs.state.inventory[ctx.activeBattle.value.rewardTM] || 0) + 1
        ctx.addLog(`¡Recibiste la ${ctx.activeBattle.value.rewardTM}!`, 'log-info', ctx.activeBattle.value.rewardTM) 
      }
      useUIStore().notify(`¡Ganaste la medalla del Gimnasio ${gid}!`, '🏆')
      await ctx.gs.save(false)
    }
  }

  const baseExp = calculateBaseExp(e)
  const warMods = getBattleRewardModifiers(ctx.activeBattle.value.locationId, ctx.gs.state.faction, ctx.warStore.mapDominance)
  const totalExpMult = warMods.expMult + ((ctx.eventStore.globalMultipliers?.exp || 1) - 1)
  const classMult = ctx.classStore.getModifier('expMult', { isTrainer: ctx.activeBattle.value.isTrainer })
  const participantsSet = new Set(ctx.activeBattle.value.participants)

  for (const p of ctx.gs.state.team) {
    const reward = processExpGain(p, baseExp, participantsSet, {
      isActive: p.uid === ctx.activeBattle.value.player.uid,
      classMult,
      totalExpMult,
      participantsSet
    })
    if (!reward) continue
    ctx.addLog(`${p.name} ganó ${reward.gained} EXP.`, 'log-player', p)

    if (reward.levelUp) {
      const audio = ctx.audio
      audio.levelUp()
      ctx.addLog(`¡${p.name} subió al nivel ${p.level}!`, 'log-info', p)

      await fsm.transition(BATTLE_STATES.LEVEL_UP_MODAL, BATTLE_SUBSTATES.CHECK_PENDING)
      const pendingMoves = levelUpPokemon(p)

      if (pendingMoves && pendingMoves.length > 0) {
        await fsm.transition(BATTLE_STATES.LEVEL_UP_MODAL, BATTLE_SUBSTATES.SHOW_CHOICE)
        p.pendingMoves = pendingMoves
      }
    }
  }

  const moneyGained = calculateMoneyGain(e, { 
    bcMult: ctx.classStore.getModifier('bcMult', { isGym: ctx.activeBattle.value.isGym }), 
    totalMoneyMult: warMods.moneyMult + ((ctx.eventStore.globalMultipliers?.money || 1) - 1) 
  })

  ctx.gs.state.money += moneyGained
  if (moneyGained > 0) ctx.audio.money()
  ctx.addLog(`¡Ganaste ₽${moneyGained}!`, 'log-info', 'player')
}

/**
 * Syncs team HP to GameStore.
 */
export function syncTeamHP(ctx) {
  if (!ctx.activeBattle.value) return;

  if (ctx.activeBattle.value.player) {
    const currentIdx = ctx.activeBattle.value.playerTeamIndex ?? ctx.gs.state.team.findIndex(p => p.uid === ctx.activeBattle.value.player.uid);
    if (currentIdx !== -1) {
      ctx.gs.state.team[currentIdx].hp = ctx.activeBattle.value.player.hp;
      ctx.gs.state.team[currentIdx].status = ctx.activeBattle.value.player.status;
    }
  }
}

/**
 * Persists battle state to GameStore.
 */
export function syncAndPersist(ctx) {
  if (!ctx.activeBattle.value || ctx.activeBattle.value.over) {
    ctx.gs.state.activeBattle = null
    return
  }
  ctx.gs.state.activeBattle = {
    ...ctx.activeBattle.value,
    playerStages: ctx.playerStages.value,
    enemyStages: ctx.enemyStages.value,
    battleLogs: ctx.battleLogs.value.slice(-10)
  }
  ctx.gs.save(false)
}

import { generateEncounter } from '@/logic/encounters'
import { useUIStore } from '@/stores/ui'
import { useMapStore } from '@/stores/map'
import { useEventStore } from '@/stores/events'

/**
 * Handles the completion of a battle flow (either going to map or search loop).
 */
export async function handleBattleFlowCompletion(ctx, option = 'map') {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm
  const uiStore = useUIStore()

  if (option === 'search' && ctx.activeBattle.value) {
    ctx.isProcessing.value = true

    // FASE: INITIALIZING
    fsm.transition(BATTLE_STATES.INITIALIZING)
    fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.CHECK_SLOTS)
    fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.PROMOTE_AND_REPOPULATE)
    fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.PROMOTE)

    const locId = ctx.activeBattle.value.locationId
    const hasBinoculars = ctx.debugBinoculars.value

    // PROMOTE: Slot 2 -> Slot 1 (Ya manejado implícitamente por la lógica de slots, pero aquí lo formalizamos)
    if (ctx.upcomingPokemon.value) {
      ctx.activeBattle.value._initialEnemy = { ...ctx.upcomingPokemon.value }
    }
    // GEN_NEW_S2: Generar próximo encuentro si no hay uno en el slot
    if (!ctx.upcomingPokemon.value) {
      const encounterOptions = {
        activeEvents: useMapStore().activeEvents,
        dominanceData: useMapStore().mapWinners,
        shinyMultiplier: useEventStore().globalMultipliers?.shiny || 1,
        forceEncounter: true
      }
      const encounter = await generateEncounter(locId, ctx.gs.state, encounterOptions)
      if (encounter && encounter.type === 'wild') {
        ctx.upcomingPokemon.value = { ...encounter.pokemon }
      }
    }

    // Sincronizar _initialEnemy para que cualquier silueta use los datos correctos del Slot 1 (Promovido)
    if (ctx.upcomingPokemon.value) {
      ctx.activeBattle.value._initialEnemy = { ...ctx.upcomingPokemon.value }
    }

    fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.GEN_NEW_S2)

    // PRELOAD_COORDS: Pre-calculo de anclajes antes de la fase visual
    await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.PRELOAD_COORDS, 100)

    // FASE: SEARCH_PHASE (Fase Visual - Sincronizada con Protocolo de Asientos)
    // 1. Preparación Paralela (Arbustos, Siluetas, etc.)
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.PARALLEL_PREP)

    // 2. OCUPACIÓN DEL ASIENTO: El Pokémon aparece visualmente con su silueta ya preparada
    if (ctx.upcomingPokemon.value) {
      ctx.activeBattle.value.enemy = { ...ctx.upcomingPokemon.value }
    }

    ctx.isProcessing.value = false
    return
  }

  fsm.transition(BATTLE_STATES.EXIT_BATTLE)
  ctx.activeBattle.value = null
  ctx.isProcessing.value = false
  ctx.clearLogs() 

  if (option === 'map') {
    uiStore.activeTab = 'map'
  }
}

/**
 * Triggers an encounter from the search loop.
 */
export async function triggerNextEncounter(ctx) {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  ctx.isProcessing.value = false
  const locId = ctx.activeBattle.value?.locationId
  if (!ctx.upcomingPokemon.value || !locId) {
    console.warn('[Battle] triggerNextEncounter: sin upcomingPokemon o locationId.')
    return
  }

  await fsm.transition(BATTLE_STATES.INITIALIZING)
  if (ctx.activeBattle.value?.isFishing) {
    fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.MINIGAME_CHECK)
  }
  fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.ENCOUNTER_ANIM)

  const nextPoke = ctx.upcomingPokemon.value
  ctx.upcomingPokemon.value = null
  await ctx._startBattle(nextPoke, {
    locationId: locId,
    wasSearching: true,
    battleOptions: { isDebug: !!ctx.debugLoopPokemon.value }
  })
}

/**
 * Transition from SEARCH_PHASE to ACTIVE_BATTLE.
 */
export async function startEncounter(ctx) {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  ctx.isIntroAnimating.value = true

  // 1. Delegar al orquestador oficial para garantizar paridad con el manual
  const locId = ctx.activeBattle.value?.locationId
  const isTr = ctx.activeBattle.value?.isTrainer
  const trName = ctx.activeBattle.value?.trainerName
  const isGym = ctx.activeBattle.value?.isGym
  const gymId = ctx.activeBattle.value?.gymId

  await ctx.initBattle(locId, isTr, trName, isGym, gymId, true)

  ctx.isIntroAnimating.value = false
}

import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider';
import { GAME_RATIOS } from '@/data/constants';
import { makePokemon } from '@/logic/pokemonFactory';
import { getDayCycle } from '@/logic/timeUtils';
import { isDisputePhase } from '@/logic/war/warEngine';
import { getGuardianData, GUARDIAN_CHANCE } from '@/logic/war/guardianEngine';
import { applyEncounterBonuses } from '@/logic/war/bonusEngine';
import { useEventStore } from '@/stores/events';

const WEATHER_BUFF_MULTIPLIER = 1.5;
const VISITOR_TOTAL_WEIGHT_PERCENT = 10;

/**
 * Determina si una especie recibe el buff del clima actual basado en sus tipos.
 */
function isSpeciesBoosted(id, weather) {
  const pData = pokemonDataProvider.getPokemonData(id);
  if (!pData || !weather || weather === 'clear') return false;

  const types = Array.isArray(pData.type) ? pData.type : [pData.type];
  const w = weather.toLowerCase();

  const weatherBoosts = {
    rain: ['water', 'bug', 'grass'],
    storm: ['electric', 'dragon'],
    sun: ['fire', 'grass'],
    snow: ['ice', 'steel'],
    sandstorm: ['rock', 'ground', 'steel'],
    fog: ['ghost', 'psychic', 'dark'],
    heatwave: ['fire']
  };

  const boostedTypes = weatherBoosts[w] || [];
  return types.some(t => boostedTypes.includes(t.toLowerCase()));
}


/**
 * Gets the valid pool of Pokémon for a location and time cycle.
 * Incorporates active events.
 */
export function getEncounterPool(loc, cycle, weather = 'clear', activeEvents = []) {
  if (!loc || !loc.wild) return { pool: [], rates: [] };

  let pool = [...(loc.wild[cycle] || loc.wild.day || [])];
  let rates = [...(loc.rates && (loc.rates[cycle] || loc.rates.day) ? (loc.rates[cycle] || loc.rates.day) : [])];

  // Ensure rates match pool length before transformations
  while (rates.length < pool.length) rates.push(10);

  // 1. Inyección por Clima (Visitantes y Exclusivos)
  if (weather && weather !== 'clear' && loc.weather?.[weather]) {
    const wConfig = loc.weather[weather];

    // Especies Exclusivas (Pesos dinámicos o base 5)
    if (wConfig.exclusive) {
      const exclusives = Array.isArray(wConfig.exclusive) ? wConfig.exclusive : Object.keys(wConfig.exclusive);
      exclusives.forEach(id => {
        if (!pool.includes(id)) {
          pool.push(id);
          const weight = Array.isArray(wConfig.exclusive) ? 5 : (wConfig.exclusive[id] || 5);
          rates.push(weight); 
        }
      });
    }

    // Visitantes (Marcados con peso negativo para normalización proporcional)
    if (wConfig.visitors) {
      const visitors = Array.isArray(wConfig.visitors) ? wConfig.visitors : Object.keys(wConfig.visitors);
      visitors.forEach(id => {
        if (!pool.includes(id)) {
          pool.push(id);
          const weight = Array.isArray(wConfig.visitors) ? -10 : -(wConfig.visitors[id] || 10);
          rates.push(weight); 
        }
      });
    }

  }

  // 2. Apply Event Injections
  activeEvents.forEach(ev => {
    if (ev.active && ev.config?.ignoreTimeRestrictions && ev.config.species) {
      const eventSpecies = ev.config.species.split(',').map(s => s.trim().toLowerCase());
      eventSpecies.forEach(spId => {
        if (!pool.includes(spId)) {
          // Check if species exists in other cycles for this map
          for (const c in loc.wild) {
            const idx = loc.wild[c].indexOf(spId);
            if (idx !== -1) {
              pool.push(spId);
              const originalRates = loc.rates?.[c] || [];
              rates.push(originalRates[idx] || 10);
              break;
            }
          }
        }
      });
    }
  });

  return { pool, rates };
}


/**
 * Selects a random Pokémon ID from a pool using weights.
 */
export function selectFromPool(pool, rates) {
  if (!pool.length) return null;
  const totalRate = rates.reduce((a, b) => a + b, 0);
  let rand = Math.random() * totalRate;
  let cumulative = 0;

  for (let i = 0; i < pool.length; i++) {
    cumulative += rates[i] || 0;
    if (rand <= cumulative) return pool[i];
  }
  return pool[0];
}

/**
 * Main logic to generate a wild encounter.
 * Handles repellent, incense, fishing, and specialty spawns.
 */
export async function generateEncounter(locId, state, options = {}) {
  const loc = pokemonDataProvider.getMaps().find(l => l.id === locId);
  if (!loc) return null;

  const cycle = getDayCycle();
  const eventStore = useEventStore();
  const activeEvents = options.activeEvents || (eventStore.activeEvents || []) || [];
  const maps = pokemonDataProvider.getMaps();
  const allMapIds = maps.map(m => m.id);

  // 1. Especial: Fase de Dominancia (Finde) - Batallas de Defensores
  if (!isDisputePhase() && !options.forceEncounter) {
    // Chance de encontrar defensor (20% normal)
    if (Math.random() < 0.20 && state.faction) {
      // Determinamos si el mapa está dominado por el enemigo
      const winner = (options.dominanceData || {})[locId];
      if (winner && winner !== state.faction) {
        return { type: 'defender', faction: winner };
      }
    }
  }

  // 2. Especial: Guardianes (Pokémon Alfa)
  const guardian = getGuardianData(locId, allMapIds);
  if (guardian && !options.forceEncounter) {
    // Verificar si ya fue capturado hoy
    const capturedToday = (state.dailyGuardianCaptures || []).includes(locId);
    if (!capturedToday && Math.random() < GUARDIAN_CHANCE) {
      return { 
        type: 'guardian', 
        pokemon: makePokemon(guardian.id, guardian.lv, { shinyMultiplier: options.shinyMultiplier }),
        pts: guardian.pts
      };
    }
  }

  // 3. Repellent Logic
  const repellentActive = (state.repelSecs || 0) > 0;
  const firstPokemon = state.team?.[0];

  if (repellentActive && !options.forceEncounter) {
    if (Math.random() < GAME_RATIOS.encounters.trainerRepel) {
      return { type: 'trainer' };
    }

    const weather = options.weather || 'clear';
    const { pool, rates: rawRates } = getEncounterPool(loc, cycle, weather, activeEvents);

    // Normalizar pesos para Repelente
    const rates = rawRates.map(r => r === -1 ? 5 : r); 

    // Find a pokemon with level >= firstPokemon.level
    for (let attempt = 0; attempt < 10; attempt++) {
      const selectedId = selectFromPool(pool, rates);
      const level = Math.floor(Math.random() * (loc.lv[1] - loc.lv[0] + 1)) + loc.lv[0];

      if (!firstPokemon || level >= firstPokemon.level) {
        return { type: 'wild', pokemon: makePokemon(selectedId, level, { shinyMultiplier: options.shinyMultiplier }) };
      }
    }
    return { type: 'trainer' }; // Fallback to trainer
  }

  // 2. Base Trainer Chance
  const trainerBonus = options.eventTrainerBonus || 1;
  const tChance = Math.min(state.trainerChance || GAME_RATIOS.encounters.trainerBase, GAME_RATIOS.encounters.trainerMax) * trainerBonus;
  if (!options.forceEncounter && Math.random() * 100 < tChance) {
    return { type: 'trainer' };
  }

  // 3. Fishing Chance (if applicable)
  const fishingBonus = options.eventFishingBonus || 1;
  if (loc.fishing && Math.random() < GAME_RATIOS.encounters.fishing * fishingBonus) {
    const { pool, rates } = loc.fishing;
    const selectedId = selectFromPool(pool, rates);
    const level = Math.floor(Math.random() * (loc.fishing.lv[1] - loc.fishing.lv[0] + 1)) + loc.fishing.lv[0];
    const totalRate = rates.reduce((a, b) => a + b, 0);
    const rarity = (rates[pool.indexOf(selectedId)] / totalRate) * 100;

    return { 
      type: 'fishing', 
      pokemon: makePokemon(selectedId, level, { shinyMultiplier: options.shinyMultiplier }),
      rarity 
    };
  }

  // 4. Wild Pokemon Pool Selection (Normal)
  const weather = options.weather || 'clear';
  let { pool, rates } = getEncounterPool(loc, cycle, weather, activeEvents);

  // 4.1 Lógica de Clima: Multiplicadores e Invasiones
  if (weather && weather !== 'clear') {
    const visitorIndices = rates.map((r, i) => r < 0 ? i : -1).filter(i => i !== -1);
    const nativeIndices = rates.map((r, i) => r >= 0 ? i : -1).filter(i => i !== -1);

    // Buff x1.5 a nativos que coinciden con el clima
    nativeIndices.forEach(idx => {
      if (isSpeciesBoosted(pool[idx], weather)) {
        rates[idx] *= WEATHER_BUFF_MULTIPLIER;
      }
    });

    // Normalización Proporcional de Visitantes (10% del peso total)
    if (visitorIndices.length > 0) {
      const totalNativeWeight = nativeIndices.reduce((sum, idx) => sum + rates[idx], 0);
      const visitorQuota = totalNativeWeight / 9; // 10% del total final

      // Calculamos la suma de los pesos relativos (valores absolutos de los pesos negativos)
      const sumRelativeWeights = visitorIndices.reduce((sum, idx) => sum + Math.abs(rates[idx]), 0);

      visitorIndices.forEach(idx => {
        const relativeWeight = Math.abs(rates[idx]) / sumRelativeWeights;
        rates[idx] = visitorQuota * relativeWeight;
      });
    }
  }

  // 5. Incense Effect
  if (state.incenseSecs > 0 && state.incenseType) {
    const typeIndices = pool.map((id, idx) => {
      const pData = pokemonDataProvider.getPokemonData(id);
      return (pData && pData.type === state.incenseType) ? idx : -1;
    }).filter(idx => idx !== -1);

    if (typeIndices.length > 0) {
      pool = typeIndices.map(idx => pool[idx]);
      rates = typeIndices.map(idx => rates[idx]);
    }
  }

  // 6. Final Select
  const selectedId = selectFromPool(pool, rates);
  const level = Math.floor(Math.random() * (loc.lv[1] - loc.lv[0] + 1)) + loc.lv[0];

  const pokemon = makePokemon(selectedId, level, { shinyMultiplier: options.shinyMultiplier });

  // Marcar si es atmosférico para efectos visuales posteriores
  const isVisitor = !!loc.weather?.[weather]?.visitors?.[selectedId];
  const isExclusive = !!loc.weather?.[weather]?.exclusive?.[selectedId];

  const isBuffed = !isVisitor && !isExclusive && isSpeciesBoosted(selectedId, weather);

  if (isVisitor || isExclusive || isBuffed) {
    pokemon.isAtmospheric = true;
    pokemon.weatherOrigin = weather;
  }


  // 7. Apply War Dominance Bonuses
  return { 
    type: 'wild', 
    pokemon: applyEncounterBonuses(pokemon, locId, state.faction, options.dominanceData) 
  };
}

import { gameBus } from '@/logic/gameBus'
import { useAudioStore } from '@/stores/audio'

export function registerAudioTools({ register }, context) {
  const audio = useAudioStore()

  register({
    id: 'play_sound',
    command: 'playSound',
    description: 'Reproducir un sonido del sistema.',
    action: (type) => {
      audio.play(type)
      return `Reproduciendo sonido: ${type}`
    }
  })

  register({
    id: 'trigger_anim',
    command: 'triggerAnim',
    description: 'Disparar una animación de combate via Bus.',
    action: (type, side = 'enemy', options = {}) => {
      const eventMap = {
        'release': 'PLAY_RELEASE_ENERGY',
        'catch': 'PLAY_CATCH_ENERGY',
        'shake': 'CATCH_SHAKE',
        'success': 'CATCH_SUCCESS',
        'faint': 'POKEMON_FAINT',
        'attack': 'PLAY_ATTACK_ANIM',
        'emergence': 'START_BATTLE',
        'reveal': 'START_BATTLE'
      }

      const event = eventMap[type] || type
      let payload = { side, ...options }

      // Manejo especial para START_BATTLE (Introducciones)
      if (type === 'emergence') payload.animationPhase = 1
      if (type === 'reveal') payload.animationPhase = 3

      gameBus.emit(event, payload)
      return `Evento emitido: ${event} para ${side}`
    }
  })

  register({
    id: 'set_status',
    command: 'setStatus',
    description: 'Cambiar estado de un pokemon (burn, poison, paralyze, freeze, sleep, null). Toggle si ya lo tiene.',
    action: (side, status) => {
      import('@/stores/battle').then(({ useBattleStore }) => {
        const battle = useBattleStore()
        const poke = side === 'player' ? battle.state?.player : (battle.upcomingPokemon || battle.state?.enemy)
        if (poke) {
          if (status === 'null') {
            poke.status = null
          } else {
            // Toggle logic
            poke.status = poke.status === status ? null : status
            if (poke.status === 'sleep') poke.sleepTurns = 3
          }
        }
      })
      return `Comando setStatus(${side}, ${status}) enviado.`
    }
  })

  register({
    id: 'set_secondary_status',
    command: 'setSecondaryStatus',
    description: 'Cambiar estados secundarios (confused, attracted, cursed, seeded). Toggle automático.',
    action: (side, type) => {
      import('@/stores/battle').then(({ useBattleStore }) => {
        const battle = useBattleStore()
        const poke = side === 'player' ? battle.state?.player : (battle.upcomingPokemon || battle.state?.enemy)
        if (poke) {
          if (type === 'confused') poke.confused = poke.confused > 0 ? 0 : 4
          if (type === 'attracted') poke.attracted = !poke.attracted
          if (type === 'cursed') poke.cursed = !poke.cursed
          if (type === 'seeded') poke.seeded = !poke.seeded
          if (type === 'trapped') poke.trapped = !poke.trapped
          if (type === 'ingrain') poke.ingrain = !poke.ingrain
          if (type === 'protect') poke.protect = !poke.protect
          if (type === 'endure') poke.endure = !poke.endure
          if (type === 'focus_energy') poke.focusEnergy = !poke.focusEnergy
          if (type === 'lock_on') poke.lockOn = !poke.lockOn
        }
      })
      return `Comando setSecondaryStatus(${side}, ${type}) enviado.`
    }
  })

  register({
    id: 'set_stat_stage',
    command: 'setStatStage',
    description: 'Cambiar nivel de estadística (-6 a +6).',
    action: (side, stat, val) => {
      import('@/stores/battle').then(({ useBattleStore }) => {
        const battle = useBattleStore()
        const stages = side === 'player' ? battle.playerStages : battle.enemyStages
        if (stages && stages[stat] !== undefined) {
          stages[stat] = Math.max(-6, Math.min(6, parseInt(val)))
        }
      })
      return `setStatStage(${side}, ${stat}, ${val})`
    }
  })

  register({
    id: 'modify_stat_stage',
    command: 'modifyStatStage',
    description: 'Modificar nivel de estadística relativo (ej: +1, -1).',
    action: (side, stat, delta) => {
      import('@/stores/battle').then(({ useBattleStore }) => {
        const battle = useBattleStore()
        const stages = side === 'player' ? battle.playerStages : battle.enemyStages
        if (stages && stages[stat] !== undefined) {
          stages[stat] = Math.max(-6, Math.min(6, (stages[stat] || 0) + parseInt(delta)))
        }
      })
      return `modifyStatStage(${side}, ${stat}, ${delta})`
    }
  })

  register({
    id: 'set_field_effect',
    command: 'setFieldEffect',
    description: 'Activar efecto de campo (screens, weather). Toggle automático.',
    action: (side, effect, val) => {
      import('@/stores/battle').then(({ useBattleStore }) => {
        const battle = useBattleStore()
        const stages = side === 'player' ? battle.playerStages : battle.enemyStages

        // Screens & Hazards (Stage based)
        const isStageEffect = ['reflect', 'lightScreen', 'safeguard', 'mist', 'spikes'].includes(effect)
        if (isStageEffect && stages) {
          // Lógica FLIP: si ya tiene el efecto (>0), lo quitamos (0). Si no, lo ponemos (val o 5).
          stages[effect] = stages[effect] > 0 ? 0 : (parseInt(val) || 5)
        }

        // Weather (Context based)
        const ALL_WEATHER = ['sun', 'rain', 'hail', 'sandstorm', 'snow', 'fog', 'clear', 'storm', 'blizzard', 'heatwave']
        if (ALL_WEATHER.includes(effect)) {
          if (battle.state) {
            const current = battle.state.weather?.type
            // Lógica FLIP: si el clima actual es el mismo que tocamos, lo limpiamos.
            if (current === effect && effect !== 'clear') {
              battle.state.weather = { type: 'clear', visual: 'clear', turns: -1 }
            } else {
              battle.state.weather = { 
                type: effect, 
                visual: effect,
                turns: effect === 'clear' ? -1 : (parseInt(val) || 5) 
              }
            }
          }
        }
      })
      return `setFieldEffect(${side}, ${effect}, ${val})`
    }
  })
}

/**
 * tests/unit/battle.spec.js
 * Consolidated unit tests for Battle Engine mechanics.
 */
import { describe, it, expect, vi } from 'vitest';
import { calculateDamage, getEffectiveSpeed, getStatMultiplier } from '@/logic/battle/battleEngine';

describe('Battle Engine', () => {
  // Mock Math.random to return 1.0 for deterministic results (max damage roll)
  vi.spyOn(Math, 'random').mockReturnValue(1.0);

  describe('Damage Formula & Stat Stages', () => {
    const attacker = { level: 100, atk: 200, spa: 200, type: 'electric' };
    const defender = { level: 100, def: 100, spd: 100, type: 'normal' };
    const move = { name: 'Rayo', type: 'electric', power: 90, cat: 'special' };

    it('should calculate base special damage correctly', () => {
      const result = calculateDamage(attacker, defender, move, { atkStages: 0, defStages: 0 });
      expect(result.dmg).toBe(229);
    });

    it('should scale damage with attack stages (+2 stages = 2x)', () => {
      const result = calculateDamage(attacker, defender, move, { atkStages: 2, defStages: 0 });
      expect(result.dmg).toBe(456);
    });

    it('should scale damage with defense stages (+2 stages = 0.5x)', () => {
      const result = calculateDamage(attacker, defender, move, { atkStages: 0, defStages: 2 });
      expect(result.dmg).toBe(115);
    });
  });

  describe('Abilities', () => {
    it('Intrépido should hit Ghost types with Normal moves', () => {
      const attacker = { id: 'miltank', type: 'normal', atk: 100, level: 50, ability: 'Intrépido' };
      const defender = { id: 'gastly', type: 'ghost', def: 50, level: 50 };
      const move = { name: 'Pisotón', type: 'normal', power: 65, cat: 'physical' };

      const result = calculateDamage(attacker, defender, move);
      expect(result.dmg).toBeGreaterThan(0);
      expect(result.eff).toBe(1);
    });

    it('Sebo should reduce Fire/Ice damage by 50%', () => {
      const attacker = { id: 'charmander', type: 'fire', spa: 100, level: 50 };
      const defender = { id: 'snarlax', type: 'normal', spd: 100, level: 50, ability: 'Sebo' };
      const move = { name: 'Lanzallamas', type: 'fire', power: 90, cat: 'special' };

      const noSeboResult = calculateDamage(attacker, { ...defender, ability: null }, move);
      const seboResult = calculateDamage(attacker, defender, move);

      expect(seboResult.dmg).toBe(Math.floor(noSeboResult.dmg * 0.5));
    });
  });

  describe('Weather', () => {
    const attacker = { level: 50, spa: 100, type: 'fire' };
    const defender = { level: 50, spd: 100, type: 'normal' };
    const move = { name: 'Lanzallamas', type: 'fire', power: 90, cat: 'special' };

    it('should boost Fire damage in Sun', () => {
      const noWeather = calculateDamage(attacker, defender, move, { weather: null });
      const sun = calculateDamage(attacker, defender, move, { weather: { type: 'sun', turns: 5 } });

      expect(sun.dmg).toBe(92);
    });

    it('should reduce Fire damage in Rain', () => {
      const noWeather = calculateDamage(attacker, defender, move, { weather: null });
      const rain = calculateDamage(attacker, defender, move, { weather: { type: 'rain', turns: 5 } });

      expect(rain.dmg).toBe(30);
    });
  });

  describe('Speed Calculation', () => {
    it('Clorofila should double speed in Day/Morning', () => {
      const p = { spe: 50, ability: 'Clorofila' };
      const options = { getStatMultiplier, getDayCycle: () => 'day' };
      expect(getEffectiveSpeed(p, { spe: 0 }, options)).toBe(100);
    });

    it('Paralysis should reduce speed by 50%', () => {
      const p = { spe: 100, status: 'paralyze' };
      const options = { getStatMultiplier };
      expect(getEffectiveSpeed(p, { spe: 0 }, options)).toBe(50);
    });
  });
});

