    });

    it('should respect level limits', () => {
      const p = makePokemon('charmander', 150);
      expect(p.level).toBe(100);
    });

    it('should assign a gender unless genderless', () => {
      const p = makePokemon('charmander', 5);
      expect(['M', 'F']).toContain(p.gender);

