  const activePokeballId = ref('pokeball')
  const catchSparkles = ref<any[]>([])

  const playerIsShaking = ref(false)
  const playerIsBlinking = ref(false)
  const enemyIsShaking = ref(false)
  const enemyIsBlinking = ref(false)

  // Estados de Entrenador
  const trainerAnimState = ref<string | null>(null) // 'entering' | 'retreating' | 'idle'
  const isTrainerVisible = ref(false)

  // Transiciones Globales
  const isGlobalFadeActive = ref(false)

  const isIntroInProgress = computed(() => {
    const s = toValue(battleStore.fsm.currentState)
    return s === 'INITIALIZING' ||
           s === 'FIRST_INTRO' ||
           isWildEntryAnimation.value || 
           wildRevealActive.value || 
           isEmerging.value || 
           upcomingIsEmerging.value || 
           playerAnimState.value !== null || 
           enemyAnimState.value !== null ||
           trainerAnimState.value !== null ||
           isCaptureSequenceActive.value
  })

  const isPlayerSpriteSuppressed = computed(() => {
    return !toValue(battleStore.player)
  })

  const revealWildPokemon = (isInstant = false) => {
    if (isInstant) {
      isWildSilhouette.value = false
      isWildEntryAnimation.value = false
      wildRevealActive.value = false
      return
    }

    wildRevealActive.value = true
    isWildSilhouette.value = true
    isWildEntryAnimation.value = true
    isEmerging.value = false 

    setTimeout(() => {
      isWildSilhouette.value = false
      isWildEntryAnimation.value = false
      wildRevealActive.value = false
    }, 600)
  }

  // Sincroniza las banderas de animación visual con el estado lógico de la FSM.
  watch(
    () => [toValue(battleStore.fsm.currentState), toValue(battleStore.fsm.currentSubState)],
    ([state, sub]) => {
      if (!state) return

      // CASOS DE LIMPIEZA GLOBAL (Garantiza estado puro al iniciar o volver a búsqueda)
      const isCleanupState = [
        'INITIALIZING', 
        'SEARCH_PHASE', 
        'CONTEXT_SETUP', 
        'EXIT_BATTLE'
      ].includes(state) || sub === 'WAIT_INPUT'

      if (isCleanupState) {
        isGlobalFadeActive.value = (state === 'EXIT_BATTLE')
        isWildEntryAnimation.value = false
        isEmerging.value = false
        wildRevealActive.value = false
        upcomingIsEmerging.value = false
        isWildSilhouette.value = false
        playerAnimState.value = null
        enemyAnimState.value = null
        trainerAnimState.value = null
        isTrainerVisible.value = false

        // Limpieza profunda de estados de desmayo y captura
        isFaintInProgress.value = false
        faintedPokemonSnapshot.value = null
        playerCaptureActive.value = false
        enemyCaptureActive.value = false
        caughtPokemonSnapshot.value = null
        return
      }

      if (sub) console.log(`[useBattleAnimations] SubState: ${sub}`);

      switch (sub) {
        // 1. ENTRADA PARALELA (Búsqueda o Primer Encuentro)
        case 'INITIALIZING':
          isWildSilhouette.value = true
          wildRevealActive.value = true
          isWildEntryAnimation.value = false
          isEmerging.value = false // RESET AL ATERRIZAR
          break

        case 'PARALLEL_PREP':
        case 'PARALLEL_ENTRY':
        case 'ENTRY_ANIM':
        case 'WILD_ENTRY':
        case 'BUSH_IDLE':
        case 'BUSH_VISIBLE':
        case 'SILHOUETTE_MODE':
          isWildSilhouette.value = true
          wildRevealActive.value = true
          isWildEntryAnimation.value = false
          // Mantenemos isEmerging como esté (evita parpadeos)
          break

        // 2. SALTO PARALELO (Salto + Desvanecimiento de Arbustos)
        case 'PARALLEL_JUMP':
        case 'ENCOUNTER_ANIM':
        case 'JUMP_SHADOW':
        case 'JUMP_COLOR':
        case 'BUSH_FADE':
          console.log('[useBattleAnimations] TRIGGER JUMP');
          isWildEntryAnimation.value = true
          wildRevealActive.value = true 
          isWildSilhouette.value = true

          if (!isEmerging.value) {
            setTimeout(() => {
              isEmerging.value = true
            }, 0);
          }
          break

        case 'REVEAL_COLORS':
          isWildEntryAnimation.value = true
          wildRevealActive.value = false 
          isWildSilhouette.value = false
          isEmerging.value = false // RESET AL ATERRIZAR
          break

        // 3. GESTIÓN DE Poké Ball (LLAMADO / RETIRO)
        case 'POKEMON_CALL':
        case 'ENERGY_RELEASE':
          playerAnimState.value = 'releasing'
          break

        case 'POKEMON_RECALL':
        case 'ENERGY_RECALL':
          playerAnimState.value = 'catching'
          break

        // 4. GESTIÓN DE ENTRENADORES (VISUAL OVERLAY)
        case 'TRAINER_ENTRY':
        case 'T_VISUAL':
          trainerAnimState.value = 'entering'
          isTrainerVisible.value = true
          break

        case 'TRAINER_RETREAT':
          trainerAnimState.value = 'retreating'
          setTimeout(() => { isTrainerVisible.value = false; trainerAnimState.value = null }, 800)
          break

        case 'EMPTY_WAIT':
          isEmerging.value = false
          isWildEntryAnimation.value = false
          wildRevealActive.value = false
          isWildSilhouette.value = false
          playerAnimState.value = null
          enemyAnimState.value = null
          trainerAnimState.value = null
          isTrainerVisible.value = false
          break

        case null:
          playerAnimState.value = null
          enemyAnimState.value = null
          isEmerging.value = false
          isWildEntryAnimation.value = false
          break
      }
    }
  )

  // Funciones legacy para mantener compatibilidad con BattleArenaView.vue (se pueden limpiar luego)
  const triggerWildEmergence = () => Promise.resolve()

  // SEARCH_PHASE → ENCOUNTER_ANIM: Solo el jump + reveal.
  // Asume que triggerSearchEntry() (ENTRY_ANIM) ya corrió y los arbustos + silueta están visibles.
  const triggerSearchEncounter = () => {
    return new Promise((resolve) => {
      isWildEntryAnimation.value = true
      isEmerging.value = false

      // ENCOUNTER_JUMP (600ms)
      setTimeout(() => {
        isEmerging.value = true
      }, 600)

      // BUSH_FADE (600ms) - Sincronizado con el salto
      setTimeout(() => {
        wildRevealActive.value = false
      }, 600)

      // REVEAL_COLORS (1400ms)
      setTimeout(() => {
        isWildSilhouette.value = false
      }, 1400)

      // CLEANUP (2000ms)
      setTimeout(() => {
        isWildEntryAnimation.value = false
        isEmerging.value = false
        resolve(true)
      }, 2000)
    })
  }

  const triggerCatchSparkles = (side: string) => {
    const count = 8 // Subido un poco para que se vea más lleno
    for (let i = 0; i < count; i++) {
      // Alternar bando para asegurar dispersión equilibrada
      const direction = i % 2 === 0 ? -1 : 1
      const tx = direction * (60 + Math.random() * 120) 
      const ty = -(60 + Math.random() * 40) 
      const tf = ty + (90 + Math.random() * 40) 
      const scale = 0.5 + Math.random() * 0.8 // Variación de tamaño

      catchSparkles.value.push({
        id: `sparkle-${side}-${Date.now()}-${i}-${Math.random()}`,
        side,
        tx: tx, // Pasar solo número
        ty: ty, 
        tf: tf,
        scale,
        delay: `${Math.random() * 0.2}s` // Ráfaga más compacta (0.2s max)
      })
    }
    setTimeout(() => {
      catchSparkles.value = catchSparkles.value.filter(s => s.side !== side)
    }, 1200)
  }

  const handleReleaseRequest = (detail: any) => {
    const side = detail?.side || detail

    // Limpiar estados de captura inmediatamente al liberar
    if (side === 'player') playerCaptureActive.value = false
    else enemyCaptureActive.value = false

    if (side === 'player') playerAnimState.value = 'releasing'
    else enemyAnimState.value = 'releasing'

    setTimeout(() => {
      if (side === 'player') playerAnimState.value = null
      else enemyAnimState.value = null
    }, 800)
  }

  const handleCatchRequest = (detail: any) => {
    const side = detail?.side || detail
    if (detail?.ballId) activePokeballId.value = detail.ballId

    if (side === 'player') playerAnimState.value = 'catching'
    else enemyAnimState.value = 'catching'
    setTimeout(() => {
      if (side === 'player') playerAnimState.value = 'trapped'
      else enemyAnimState.value = 'trapped'
    }, 800)
  }

  const handleShakeRequest = (detail: any) => {
    const side = detail?.side || detail
    if (side === 'player') {
      playerIsShaking.value = false
      playerIsBlinking.value = false
      nextTick(() => { 
        playerIsShaking.value = true 
        playerIsBlinking.value = true
      })
      setTimeout(() => { 
        playerIsShaking.value = false 
        playerIsBlinking.value = false
      }, 600)
    } else {
      enemyIsShaking.value = false
      enemyIsBlinking.value = false
      nextTick(() => { 
        enemyIsShaking.value = true 
        enemyIsBlinking.value = true
      })
      setTimeout(() => { 
        enemyIsShaking.value = false 
        enemyIsBlinking.value = false
      }, 600)
    }
  }

  const handleFaintAnim = (e: any) => {
    if (isFaintInProgress.value) return // Idempotente

    const data = e?.detail || e
    const side = typeof data === 'string' ? data : (data?.side || 'enemy')
    if (side === 'enemy') {
      faintedPokemonSnapshot.value = enemyRef.value ? { ...enemyRef.value, side: 'enemy' } : { side: 'enemy' }
      isFaintInProgress.value = true
      setTimeout(() => { isFaintInProgress.value = false; faintedPokemonSnapshot.value = null }, 1300)
    } else {
      faintedPokemonSnapshot.value = { side: 'player' }
      isFaintInProgress.value = true
      setTimeout(() => { isFaintInProgress.value = false; faintedPokemonSnapshot.value = null }, 1300)
    }
  }

  const initListeners = () => {
    gameBus.on('PLAY_CATCH_ENERGY', (e: any) => {
      const data = e?.detail || e
      handleCatchRequest(data)
    })
    gameBus.on('PLAY_WITHDRAW', (e: any) => {
      const data = e?.detail || e
      handleCatchRequest(data)
    })
    gameBus.on('PLAY_RELEASE_ENERGY', (e: any) => handleReleaseRequest(e.detail || e))
    gameBus.on('PLAY_SEND_OUT', (e: any) => handleReleaseRequest(e.detail || e))

    gameBus.on('CATCH_SHAKE', (e: any) => {
      const data = e?.detail || e
      handleShakeRequest(data)
    })

    gameBus.on('PLAY_DAMAGE', (e: any) => {
      const data = e?.detail || e
      handleShakeRequest(data)
    })

    gameBus.on('POKEMON_FAINT', (e: any) => handleFaintAnim(e))
    gameBus.on('PLAY_FAINT', (e: any) => handleFaintAnim(e))

    gameBus.on('PLAY_ATTACK_ANIM', (e: any) => {
      const data = e?.detail || e
      const side = typeof data === 'string' ? data : (data?.side || 'player')
      const cat = data?.cat || 'physical'

      battleStore.attackerSide = side
      battleStore.activeMove = { cat, side } 

      setTimeout(() => {
        battleStore.attackerSide = null
        battleStore.activeMove = null
      }, 500)
    })

    gameBus.on('CATCH_SUCCESS', (e: any) => {
      const data = e?.detail || e
      const side = typeof data === 'string' ? data : (data?.side || 'enemy')

      if (side === 'player') playerCaptureActive.value = true
      else enemyCaptureActive.value = true

      const targetRef = side === 'player' ? battleStore.player : enemyRef.value
      caughtPokemonSnapshot.value = targetRef ? { ...targetRef } : null
      triggerCatchSparkles(side)

      setTimeout(() => {
        if (side === 'player') playerAnimState.value = null
        else enemyAnimState.value = null
      }, 1000)

      setTimeout(() => {
        playerCaptureActive.value = false
        enemyCaptureActive.value = false
        caughtPokemonSnapshot.value = null
      }, 2000)
    })

    gameBus.on('START_BATTLE', (_e) => {
      // Solo resetear estado de captura/ball.
      // La orquestación de animaciones de intro (ENTRY_ANIM / ENCOUNTER_ANIM)
      // es responsabilidad exclusiva del watcher FSM en BattleArenaView.vue.
      playerCaptureActive.value = false
      enemyCaptureActive.value = false
      caughtPokemonSnapshot.value = null
      activePokeballId.value = 'pokeball'
    })

    watch(() => battleStore.upcomingPokemon, (newVal) => {
      if (newVal && battleStore.isSearching) {
        upcomingIsEmerging.value = true
        setTimeout(() => { upcomingIsEmerging.value = false }, 1200)
      }
    })
  }

  return {
    isWildEntryAnimation,
    isEmerging,
    isWildSilhouette,
    wildRevealActive,
    upcomingIsEmerging,
    isWildSilhouetteHalfway,
    isInitialLoad,
    isCaptureSequenceActive,
    caughtPokemonSnapshot,
    isFaintInProgress,
    faintedPokemonSnapshot,
    playerAnimState,
    enemyAnimState,
    activePokeballId,
    catchSparkles,
    playerCaptureActive,
    enemyCaptureActive,
    playerIsShaking,
    playerIsBlinking,
    enemyIsShaking,
    enemyIsBlinking,
    trainerAnimState,
    isTrainerVisible,
    isGlobalFadeActive,
    isIntroInProgress,
    revealWildPokemon,
    triggerWildEmergence,
    triggerSearchEncounter,
    triggerCatchSparkles,
    initListeners,
    isPlayerSpriteSuppressed
  }
}

import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'

/**
 * Maps each location to a biome key.
 * Biomes: bosque | montana | playa | puente | ruta | pvp | tower | safari | mansion | celeste | espuma | central
 */
const BIOME_MAP = {
  // Forest / jungle
  forest: 'bosque', route2: 'bosque', route25: 'puente',
  // Mountain / cave
  cave: 'montana', mt_moon: 'montana', rock_tunnel: 'montana',
  victory_road: 'montana', diglett_cave: 'montana',
  cerulean_cave: 'celeste',
  // Water / beach
  water: 'playa', seafoam_islands: 'espuma',
  // Safaris & Mansions
  safari_zone: 'safari', mansion: 'mansion',
  // Bridge routes
  route24: 'puente', route12: 'puente',
  // Pokemon Tower
  pokemon_tower: 'tower',
  // Gym / pvp
  gym: 'pvp', pvp: 'pvp',
  // Central / Power Plant
  power_plant: 'central',
  // Default routes → ruta
}

const BG_ASSETS = {
  bosque: ['dawn', 'day', 'night'],
  montana: ['dawn', 'day', 'dusk', 'night'],
  playa: ['dawn', 'day', 'night'],
  puente: ['dawn', 'day', 'dusk', 'night'],
  ruta: ['dawn', 'day', 'night'],
  pvp: ['dawn', 'day', 'night'],
  // Special ones with single image or specific names
  tower: 'pokemon_tower_bg',
  safari: 'zonasafari',
  mansion: 'mansionpokemon',
  celeste: 'cuevaceleste',
  espuma: 'islasespuma',
  central: 'centralenergía',
  fishing: 'bg_fishing'
}

export function useBattleBackground() {
  /**
   * Returns the asset URL for a given location and time of day.
   * @param {string} locationId 
   * @param {string} cycle - dawn | day | dusk | night
   * @param {boolean} isFishing 
   * @returns {{ url: string, isBakedIn: boolean }}
   */
  function getBackgroundUrl(locationId: string, cycle = 'day', isFishing = false) {
    if (isFishing) return { url: getAssetUrl(ASSET_TYPES.BATTLE_BG, 'bg_fishing'), isBakedIn: false }

    const biome = (BIOME_MAP as any)[locationId] || 'ruta'
    const assetDef = (BG_ASSETS as any)[biome]

    let fileName;
    let isBakedIn = false
    if (Array.isArray(assetDef)) {
      // Check if the specific cycle exists for this biome, fallback to 'day'
      const variant = assetDef.includes(cycle) ? cycle : 'day'
      fileName = `${biome}_${variant}`
      isBakedIn = variant !== 'day' // Si no es el default, tiene el ciclo horneado
    } else {
      // Static biome image
      fileName = assetDef
    }

    return {
      url: getAssetUrl(ASSET_TYPES.BATTLE_BG, fileName),
      isBakedIn
    }
  }

  return {
    getBackgroundUrl
  }
}

import { computed } from 'vue'
import { useGameStore } from '@/stores/game'
import type { useBattleStore } from '@/stores/battle'
import type { useBattleAnimations } from '@/composables/useBattleAnimations'

/**
 * Composable para gestionar la visibilidad y estados del HUD en combate.
 * Centraliza la lógica de supresión para evitar interferencias entre bandos.
 */
export function useBattleHud(
  animations: ReturnType<typeof useBattleAnimations>, 
  battleStore: ReturnType<typeof useBattleStore>, 
  enemyRef: any
) {
  const {
    isFaintInProgress,
    faintedPokemonSnapshot,
    isCaptureSequenceActive,
    caughtPokemonSnapshot
  } = animations

  const unwrap = (val: any) => (val && typeof val === 'object' && 'value' in val ? val.value : val)

  /**
   * Determina si el HUD del enemigo debe estar oculto.
   * REGLA MAESTRA: Asiento ocupado -> HUD Visible. Asiento vacío -> HUD Oculto.
   */
  const isEnemyHudSuppressed = computed(() => {
    const s = unwrap(battleStore.state)
    // REGLA MAESTRA: Ocultar si no hay enemigo activo Y no hay previsualización inicial
    return !s?.enemy && !s?._initialEnemy
  })

  /**
   * Determina si el HUD del jugador debe estar oculto.
   * REGLA MAESTRA: Asiento ocupado -> HUD Visible. Asiento vacío -> HUD Oculto.
   */
  const isPlayerHudSuppressed = computed(() => {
    return !unwrap(battleStore.state)?.player
  })

  /**
   * Datos del enemigo activo a mostrar en el HUD, 
   * manejando snapshots de captura y desmayo.
   */
  /**
   * Datos del enemigo activo a mostrar en el HUD, 
   * manejando snapshots de captura y desmayo.
   * [FASE 2] Soporte para previsualización de próximo encuentro.
   */
  const activeEnemyHudData = computed(() => {
    const state = unwrap(battleStore.fsm?.currentState)
    const subState = unwrap(battleStore.fsm?.currentSubState)
    if (state === 'REWARDS_PHASE' && subState === 'EMPTY_WAIT') return null

    // 1. Prioridad: Snapshot de captura (durante la animación de éxito)
    if (isCaptureSequenceActive.value && caughtPokemonSnapshot.value) return caughtPokemonSnapshot.value

    // 2. Prioridad: Snapshot de desmayo (mientras desaparece)
    if (isFaintInProgress.value && (faintedPokemonSnapshot.value as any)?.side === 'enemy') return faintedPokemonSnapshot.value

    // 3. Prioridad: Búsqueda / Previsualización (Encuentro Actual)
    if (battleStore.isSearching || battleStore.isFinishing) {
      return enemyRef.value || unwrap(battleStore.state)?._initialEnemy
    }

    // 4. Default: El enemigo actual del combate
    return enemyRef.value || unwrap(battleStore.state)?._initialEnemy
  })

  const gs = useGameStore()

  /**
   * Determina si los datos del enemigo deben mostrarse como "?" (Scrambled).
   * REGLA: Durante ENTRY_ANIM, ocultar datos a menos que se tenga BINOCULARES.
   */
  const shouldScrambleEnemyData = computed(() => {
    const subState = unwrap(battleStore.fsm?.currentSubState)
    const inventory = (gs.state as any).inventory || {}
    const hasBinoculars = (inventory.binoculars || 0) > 0

    const isSilhouetteState = [
      'ENTRY_ANIM', 
      'PARALLEL_PREP', 
      'PARALLEL_ENTRY', 
      'SILHOUETTE_MODE', 
      'BUSH_IDLE'
    ].includes(subState)

    return isSilhouetteState && !hasBinoculars
  })

  return {
    isEnemyHudSuppressed,
    isPlayerHudSuppressed,
    activeEnemyHudData,
    shouldScrambleEnemyData
  }
}

import { ref, computed, watch, onUnmounted } from 'vue'
import { useCombatShadowStore } from '@/stores/combatShadows'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'
import { WORLD_CONSTANTS } from '@/logic/combat/spatialCoordinator'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import type { Pokemon } from '@/types/pokemon'

const { ENTITY_SIZE_PLAYER, ENTITY_SIZE_ENEMY } = WORLD_CONSTANTS

interface Position {
  x: number
  y: number
}

export function useBattleShadows() {
  const shadowStore = useCombatShadowStore()

  // Claves únicas para las sombras en el store
  const currentPlayerShadowKey = ref<string | null>(null)
  const currentEnemyShadowKey = ref<string | null>(null)

  const lastEnemyShadowId = ref<string | null>(null)
  const lastPlayerShadowId = ref<string | null>(null)

  // Coordenadas de "suelo" persistentes para evitar saltos
  const stableEnemyGroundY = ref('90%')
  const stablePlayerGroundY = ref('90%')

  const enemyGroundY = computed(() => stableEnemyGroundY.value)
  const playerGroundY = computed(() => stablePlayerGroundY.value)

  function getStableShadowId(pokemon: Pokemon | null, side: string): string | null {
    if (!pokemon) return null
    if (pokemon.uid) return `shadow_${pokemon.uid}`
    return `${side}_${pokemon.id}`
  }

  const isFlying = (pokemon: Pokemon | null) => {
    if (!pokemon || !pokemon.id) return false
    // Si el objeto ya trae la propiedad (ej: inyectada), la usamos
    if (pokemon.isFloating !== undefined) return pokemon.isFloating
    // Si no, consultamos al provider centralizado de estética
    const data = pokemonDataProvider.getPokemonData(pokemon.id)
    return data?.isFloating || false
  }

  // Sincronizar visibilidad y posición de la sombra enemiga
  const syncEnemyShadow = async (visible: boolean, data: Pokemon | null, pos: Position, animState: any) => {
    const shadowId = getStableShadowId(data, 'enemy')

    // Limpieza de sombras huérfanas si el ID cambia (evita duplicados al capturar/cambiar)
    if (lastEnemyShadowId.value && lastEnemyShadowId.value !== shadowId) {
      if (lastEnemyShadowId.value) shadowStore.hideShadow(lastEnemyShadowId.value)

      // Intentar usar caché inmediatamente para evitar saltos al 90% si no es necesario
      const url = data ? getAssetUrl(ASSET_TYPES.POKEMON, data.id, { isShiny: data.isShiny, isBack: false }) : null
      const cached = url ? shadowStore.feetCache.get(url) : null
      const isFlyingPoke = isFlying(data)

      stableEnemyGroundY.value = isFlyingPoke ? '90%' : (cached ? `${cached.feetY * 100}%` : '90%')
    }
    lastEnemyShadowId.value = shadowId
    currentEnemyShadowKey.value = shadowId

    // Ocultar sombra si está en cualquier estado de transición de Poké Ball (energía)
    const isEnergyState = !!animState 
    if (!visible || !data || data.hp <= 0 || isEnergyState) {
      if (shadowId) shadowStore.hideShadow(shadowId)
      return
    }

    if (shadowId) {
      await shadowStore.requestShadow(shadowId, {
        side: 'enemy',
        entityX: pos.x,
        entityY: pos.y,
        entitySize: ENTITY_SIZE_ENEMY,
        isFlying: isFlying(data),
        spriteUrl: getAssetUrl(ASSET_TYPES.POKEMON, data.id, { isShiny: data.isShiny, isBack: false }),
        precalculate: true,
        visible: true
      })
    }
  }

  // Sincronizar visibilidad y posición de la sombra del jugador
  const syncPlayerShadow = async (pokemon: Pokemon | null, pos: Position, animState: any) => {
    const shadowId = getStableShadowId(pokemon, 'player')

    // Limpieza de sombras huérfanas
    if (lastPlayerShadowId.value && lastPlayerShadowId.value !== shadowId) {
      if (lastPlayerShadowId.value) shadowStore.hideShadow(lastPlayerShadowId.value)

      const url = pokemon ? getAssetUrl(ASSET_TYPES.POKEMON, pokemon.id, { isShiny: pokemon.isShiny, isBack: true }) : null
      const cached = url ? shadowStore.feetCache.get(url) : null
      const isFlyingPoke = isFlying(pokemon)

      stablePlayerGroundY.value = isFlyingPoke ? '90%' : (cached ? `${cached.feetY * 100}%` : '90%')
    }
    lastPlayerShadowId.value = shadowId
    currentPlayerShadowKey.value = shadowId

    // Ocultar sombra durante transiciones de energía
    const isEnergyState = !!animState
    if (!pokemon || pokemon.hp <= 0 || isEnergyState) {
      if (shadowId) shadowStore.hideShadow(shadowId)
      return
    }

    if (shadowId) {
      await shadowStore.requestShadow(shadowId, {
        side: 'player',
        entityX: pos.x,
        entityY: pos.y,
        entitySize: ENTITY_SIZE_PLAYER,
        isFlying: isFlying(pokemon),
        spriteUrl: getAssetUrl(ASSET_TYPES.POKEMON, pokemon.id, { isShiny: pokemon.isShiny, isBack: true }),
        precalculate: true,
        visible: true
      })
    }
  }

  // Watchers de actualización de feetY basados en el store
  watch(() => shadowStore.activeShadows.get(currentEnemyShadowKey.value || ''), (shadow) => {
    if (shadow) stableEnemyGroundY.value = `${shadow.feetY * 100}%`
  }, { deep: true })

  watch(() => shadowStore.activeShadows.get(currentPlayerShadowKey.value || ''), (shadow) => {
    if (shadow) stablePlayerGroundY.value = `${shadow.feetY * 100}%`
  }, { deep: true })

  // Solo resetear si no hay un shadowKey válido (limpieza profunda)
  watch(currentEnemyShadowKey, (val) => {
    if (!val) stableEnemyGroundY.value = '90%'
  })
  watch(currentPlayerShadowKey, (val) => {
    if (!val) stablePlayerGroundY.value = '90%'
  })

  const preloadTeamFeet = async (team: Pokemon[], side: string) => {
    if (!team || !Array.isArray(team)) return
    const tasks = team.map(p => {
      const isBack = side === 'player'
      const url = getAssetUrl(ASSET_TYPES.POKEMON, p.id, { isShiny: p.isShiny, isBack })
      return shadowStore.detectFeetPoints(url)
    })
    return Promise.all(tasks)
  }

  const preloadCombatCoords = async (
    p1Data: Pokemon | null, 
    p2Data: Pokemon | null, 
    p1Position: Position, 
    p2Position: Position, 
    p1Team: Pokemon[], 
    p2Team: Pokemon[]
  ) => {
    const tasks = []

    // Pre-cargar puntos de pies de TODOS los equipos para evitar el lag de la "primera vez"
    if (p1Team) tasks.push(preloadTeamFeet(p1Team, 'player'))
    if (p2Team) tasks.push(preloadTeamFeet(p2Team, 'enemy'))

    if (p1Data) {
      const shadowId = getStableShadowId(p1Data, 'player')
      currentPlayerShadowKey.value = shadowId
      const url = getAssetUrl(ASSET_TYPES.POKEMON, p1Data.id, { isShiny: p1Data.isShiny, isBack: true })
      if (shadowId) {
        tasks.push(shadowStore.requestShadow(shadowId, {
          side: 'player',
          entityX: p1Position.x,
          entityY: p1Position.y,
          entitySize: ENTITY_SIZE_PLAYER,
          isFlying: isFlying(p1Data),
          spriteUrl: url,
          visible: true
        }))
      }
    }

    if (p2Data) {
      const shadowId = getStableShadowId(p2Data, 'enemy')
      currentEnemyShadowKey.value = shadowId
      const url = getAssetUrl(ASSET_TYPES.POKEMON, p2Data.id, { isShiny: p2Data.isShiny, isBack: false })
      if (shadowId) {
        tasks.push(shadowStore.requestShadow(shadowId, {
          side: 'enemy',
          entityX: p2Position.x,
          entityY: p2Position.y,
          entitySize: ENTITY_SIZE_ENEMY,
          isFlying: isFlying(p2Data),
          spriteUrl: url,
          visible: true
        }))
      }
    }
    if (tasks.length > 0) {
      await Promise.all(tasks).catch(err => console.warn('[useBattleShadows] Preloading failed:', err))
    }
  }

  onUnmounted(() => {
    shadowStore.clearAll()
  })

  return {
    currentPlayerShadowKey,
    currentEnemyShadowKey,
    enemyGroundY,
    playerGroundY,
    syncEnemyShadow,
    syncPlayerShadow,
    preloadCombatCoords,
    getStableShadowId
  }
}

import { ref } from 'vue'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'

export function useBattleVisuals() {
  const canvasRef = ref<HTMLCanvasElement | null>(null)
  const containerRef = ref<HTMLElement | null>(null)

  const getHpPct = (cur: number, max: number) => (cur / max) * 100
  const getHpClass = (pct: number) => {
    if (pct > 50) return 'hp-high'
    if (pct > 25) return 'hp-mid'
    return 'hp-low'
  }

  const getHpColor = (pct: number) => {
    if (pct > 50) return '#4ade80'
    if (pct > 20) return '#facc15'
    return '#f87171'
  }

  const getSprite = (id: string, isShiny: boolean, isBack = false) => {
    return getAssetUrl(ASSET_TYPES.POKEMON, id, { shiny: isShiny, isBack })
  }

  const redrawBackground = (isBattleActive: boolean, locationId: string, cycle: string) => {
    if (isBattleActive && typeof (window as any).drawBattleBackground === 'function') {
      const arena = containerRef.value
      const canvas = canvasRef.value
      if (arena && canvas) {
        canvas.width = arena.offsetWidth
        canvas.height = arena.offsetHeight
        ;(window as any).drawBattleBackground(locationId || 'wild', cycle)
      }
    }
  }

  const getStatusIcon = (s: string) => {
    const icons: Record<string, string> = { 
      burn: '🔥', poison: '☠️', paralyze: '⚡', sleep: '💤', freeze: '🧊' 
    }
    return icons[s] || ''
  }

  const getGenderText = (g: string) => {
    const texts: Record<string, string> = { M: '♂', F: '♀' }
    return texts[g] || ''
  }

  const getGenderCls = (g: string) => {
    const classes: Record<string, string> = { M: 'gender-male', F: 'gender-female' }
    return classes[g] || 'gender-none'
  }

  return {
    canvasRef,
    containerRef,
    getHpPct,
    getHpClass,
    getHpColor,
    getSprite,
    redrawBackground,
    getStatusIcon,
    getGenderText,
    getGenderCls
  }
}

import { watch, onUnmounted } from 'vue'
// [PureVue-Ignore]

/**
 * useBodyClass
 * Reactively manages a class on the document.body.
 * Ensures the class is removed when the component is unmounted.
 */
export function useBodyClass(className: string, isEnabled: any) {
  const updateClass = (val: boolean) => {
    if (val) {
      document.body.classList.add(className)
    } else {
      document.body.classList.remove(className)
    }
  }

  // Support both Ref and Getter function
  watch(
    typeof isEnabled === 'function' ? isEnabled : () => isEnabled.value,
    (val) => {
      updateClass(val)
    },
    { immediate: true }
  )

  onUnmounted(() => {
    document.body.classList.remove(className)
  })
}

import { computed, ref } from 'vue';
import { getPokemonTier } from '@/logic/pokemon/tierEngine';
import { PDEX_ORDER } from '@/data/pokedex';
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider';

export function useBoxFilters(boxArray: any, _currentBoxIndex: any) {
  const filters = ref({
    tier: 'all',
    type: 'all',
    levelMin: 1,
    levelMax: 100,
    ivHP: 0,
    ivATK: 0,
    ivDEF: 0,
    ivSPA: 0,
    ivSPD: 0,
    ivSPE: 0,
    ivAny31: false,
    ivMin: 0,
    ivMax: 31,
    ivTotalMin: 0,
    ivTotalMax: 186,
    bstMin: 0,
    bstMax: 1000,
    search: '',
    tags: [] as string[]
  });

  const sortMode = ref('none'); 
  const sortDirection = ref('desc'); 
  const isFiltersOpen = ref(false);

  const hasActiveFilters = computed(() => {
    const f = filters.value;
    return f.tier !== 'all' || 
           f.type !== 'all' || 
           f.levelMin > 1 || 
           f.levelMax < 100 ||
           f.ivHP > 0 || f.ivATK > 0 || f.ivDEF > 0 || 
           f.ivSPA > 0 || f.ivSPD > 0 || f.ivSPE > 0 ||
           f.ivAny31 || 
           f.ivMin > 0 || f.ivMax < 31 ||
           f.ivTotalMin > 0 || f.ivTotalMax < 186 ||
           f.bstMin > 0 || f.bstMax < 1000 ||
           f.search !== '' ||
           f.tags.length > 0;
  });

  const processedBoxList = computed(() => {
    const isFiltered = hasActiveFilters.value;
    const isSorted = sortMode.value !== 'none';

    const rawList = boxArray.value || [];
    let result = rawList.map((p: any, index: number) => ({ p, index }));

    if (isFiltered || isSorted) {
      result = result.filter((item: any) => item.p != null);

      if (isFiltered) {
      result = result.filter(({ p }: any) => {
        const f = filters.value;
        const tierInfo = getPokemonTier(p);
        const ivs = p.ivs || {};
        const allIvs = [ivs.hp||0, ivs.atk||0, ivs.def||0, ivs.spa||0, ivs.spd||0, ivs.spe||0];
        const totalIvs = allIvs.reduce((s: number, v: number) => s + v, 0);

        const species = pokemonDataProvider.getPokemonData(p.id);
        const bst = species ? ((species.hp||0)+(species.atk||0)+(species.def||0)+(species.spa||0)+(species.spd||0)+(species.spe||0)) : 0;
        const totalPower = bst + totalIvs;

        if (f.tier !== 'all' && tierInfo.tier !== f.tier) return false;
        if (f.type !== 'all' && p.type !== f.type && p.type2 !== f.type) return false;
        if (p.level < f.levelMin || p.level > f.levelMax) return false;

        if (f.ivAny31 && !allIvs.some(v => v === 31)) return false;
        if (allIvs.some(v => v < f.ivMin || v > f.ivMax)) return false;

        if (totalIvs < f.ivTotalMin || totalIvs > f.ivTotalMax) return false;
        if (totalPower < f.bstMin || totalPower > f.bstMax) return false;

        if ((ivs.hp || 0) < f.ivHP) return false;
        if ((ivs.atk || 0) < f.ivATK) return false;
        if ((ivs.def || 0) < f.ivDEF) return false;
        if ((ivs.spa || 0) < f.ivSPA) return false;
        if ((ivs.spd || 0) < f.ivSPD) return false;
        if ((ivs.spe || 0) < f.ivSPE) return false;

        if (f.search) {
          const q = f.search.toLowerCase();
          const matchesName = p.name?.toLowerCase().includes(q);
          const matchesNick = p.nickname?.toLowerCase().includes(q);
          if (!matchesName && !matchesNick) return false;
        }

        if (f.tags.length > 0) {
          const pTags = p.tags || [];
          const hasRequiredTag = f.tags.every(t => {
            if (t === 'iv31') return pTags.includes('iv31') || allIvs.some(v => v === 31);
            if (t === 'shy') return p.isShiny;
            return pTags.includes(t);
          });
          if (!hasRequiredTag) return false;
        }

        return true;
      });
    }

    if (isSorted) {
      const isAsc = sortDirection.value === 'asc';
      result.sort((a: any, b: any) => {
        let cmp = 0;
        const pA = a.p;
        const pB = b.p;

        if (sortMode.value === 'level') cmp = pB.level - pA.level;
        else if (sortMode.value === 'tier') cmp = getPokemonTier(pB).total - getPokemonTier(pA).total;
        else if (sortMode.value === 'type') cmp = (pA.type || '').localeCompare(pB.type || '');
        else if (sortMode.value === 'pokedex') {
          const idxA = PDEX_ORDER.indexOf(pA.id);
          const idxB = PDEX_ORDER.indexOf(pB.id);
          cmp = (idxA === -1 ? 9999 : idxA) - (idxB === -1 ? 9999 : idxB);
        }
        else if (sortMode.value === 'bst') {
          const specA = pokemonDataProvider.getPokemonData(pA.id);
          const specB = pokemonDataProvider.getPokemonData(pB.id);
          const bstA = specA ? ((specA.hp||0)+(specA.atk||0)+(specA.def||0)+(specA.spa||0)+(specA.spd||0)+(specA.spe||0)) : 0;
          const bstB = specB ? ((specB.hp||0)+(specB.atk||0)+(specB.def||0)+(specB.spa||0)+(specB.spd||0)+(specB.spe||0)) : 0;

          const ivsA = pA.ivs || {};
          const totalIvsA = (ivsA.hp||0)+(ivsA.atk||0)+(ivsA.def||0)+(ivsA.spa||0)+(ivsA.spd||0)+(ivsA.spe||0);
          const ivsB = pB.ivs || {};
          const totalIvsB = (ivsB.hp||0)+(ivsB.atk||0)+(ivsB.def||0)+(ivsB.spa||0)+(ivsB.spd||0)+(ivsB.spe||0);

          cmp = (bstB + totalIvsB) - (bstA + totalIvsA);
        }
        else if (sortMode.value === 'recent') {
          const dateA = pA.captureDate || pA.timestamp || pA.date || pA.created_at || pA.obtainedAt || 0;
          const dateB = pB.captureDate || pB.timestamp || pB.date || pB.created_at || pB.obtainedAt || 0;
          cmp = dateB - dateA;
        }

        if (cmp === 0) {
          return isAsc ? a.index - b.index : b.index - a.index;
        }
        return isAsc ? -cmp : cmp;
      });
    }
  }

    return result;
  });

  function resetFilters() {
    filters.value = {
      tier: 'all',
      type: 'all',
      levelMin: 1,
      levelMax: 100,
      ivHP: 0, ivATK: 0, ivDEF: 0,
      ivSPA: 0, ivSPD: 0, ivSPE: 0,
      ivAny31: false,
      ivMin: 0,
      ivMax: 31,
      ivTotalMin: 0,
      ivTotalMax: 186,
      bstMin: 0,
      bstMax: 1000,
      search: '',
      tags: []
    };

    sortMode.value = 'none';
    sortDirection.value = 'desc';
  }

  return {
    filters,
    isFiltersOpen,
    sortMode,
    sortDirection,
    hasActiveFilters,
    processedBoxList,
    resetFilters
  };
}

import { computed } from 'vue';
import { useGameStore } from '@/stores/game';
import { useBattleStore } from '@/stores/battle';

/**
 * Composable to access class-based multipliers and bonuses.
 */
export function useClassModifiers() {
  const gameStore = useGameStore();
  const battleStore = useBattleStore();

  const isPvP = computed(() => battleStore.isBattleActive && (battleStore as any).isPvP);
  const playerClass = computed(() => gameStore.state.playerClass);

  /**
   * Generic function to get a modifier.
   * Returns 1.0 (no change) if not applicable or in PvP.
   */
  const getModifier = (type: any, context: any = {}) => {
    // PvP Balance: No class advantages allowed in competitive matches
    if (isPvP.value) {
      if (type === 'shopDiscount') return 0;
      return 1.0;
    }

    if (!playerClass.value) return 1.0;

    // We can't easily import the PLAYER_CLASSES object here to avoid circular dependencies
    // if the logic file imports the store. We'll use the reactive state directly or
    // raw values for critical performance.

    switch (playerClass.value) {
      case 'rocket':
        if (type === 'expMult') return 1.0;
        if (type === 'bcMult') return 0.90;
        if (type === 'healCostMult') return 2.0;
        if (type === 'shopDiscount') return 0.20; // Private Black Market discount
        break;

      case 'cazabichos':
        if (type === 'expMult') {
          return (context as any).isTrainer ? 0.80 : 1.0;
        }
        if (type === 'bcMult') return 0.85;
        if (type === 'daycareCostMult') return 1.5;
        break;

      case 'entrenador':
        if (type === 'expMult') return 1.10;
        if (type === 'bcMult') return (context as any).isGym ? 1.30 : 1.0;
        if (type === 'daycareCostMult') return 1.5;
        break;

      case 'criador':
        if (type === 'expMult') return 0.90;
        if (type === 'hatchStepsMult') return 0.75;
        break;
    }

    return 1.0;
  };

  const expMultiplier = computed(() => (context = {}) => getModifier('expMult', context));
  const moneyMultiplier = computed(() => (context = {}) => getModifier('bcMult', context));
  const shopDiscount = computed(() => getModifier('shopDiscount'));

  return {
    getModifier,
    expMultiplier,
    moneyMultiplier,
    shopDiscount
  };
}

import { ref, onMounted, onUnmounted, computed, CSSProperties } from 'vue'
import { gameBus } from '@/logic/gameBus'
import { WORLD_CONSTANTS } from '@/logic/combat/spatialCoordinator'

/**
 * useCombatCamera
 * Implements a dynamic 2D camera system based on docs/architecture/combat_camera.md
 */
export function useCombatCamera(viewportRef: any) {
  // Reactive State
  const vpWidth = ref(0)
  const vpHeight = ref(0)
  const camWidth = ref(0)
  const camHeight = ref(0)
  const tx = ref(0)
  const ty = ref(0)
  const scale = ref(1)
  const showGuides = ref(false)
  const debugZoom = ref(1)

  // Computed Styles
  const cameraStyles = computed<CSSProperties>(() => ({
    width: `${camWidth.value}px`,
    height: `${camHeight.value}px`,
    position: 'relative' as const,
    overflow: 'hidden' as const,
    backgroundColor: '#000',
    display: 'flex' as const,
    alignItems: 'center' as const,
    justifyContent: 'center' as const
  }))

  const worldStyles = computed<any>(() => ({
    position: 'absolute' as const,
    top: '0',
    left: '0',
    width: `${WORLD_CONSTANTS.MAP_WIDTH}px`,
    height: `${WORLD_CONSTANTS.MAP_HEIGHT}px`,
    transform: `Translate(${tx.value}px, ${ty.value}px) Scale(${scale.value})`,
    transformOrigin: '0 0',
    willChange: 'transform',
    // Inyectamos escalas estandarizadas para uso en CSS
    '--obj-scale': WORLD_CONSTANTS.OBJECT_SCALE,
    '--bush-size': WORLD_CONSTANTS.BUSH_SIZE,
    '--preview-size': WORLD_CONSTANTS.PREVIEW_SIZE
  }))

  const updateCamera = (width: any, height: any) => {
    // Filtro de Estabilidad: Ignoramos dimensiones nulas o valores de inicialización del navegador (0 o window.innerWidth exacto si no es fullscreen)
    if (!width || !height || width < 100 || height < 100) return

    let cw = width
    let ch = height

    // Mantener la proporción dentro de los límites del manual
    const ratio = cw / ch
    if (ratio > WORLD_CONSTANTS.RATIO_MAX) {
      cw = ch * WORLD_CONSTANTS.RATIO_MAX
    } else if (ratio < WORLD_CONSTANTS.RATIO_MIN) {
      ch = cw / WORLD_CONSTANTS.RATIO_MIN
    }

    camWidth.value = cw
    camHeight.value = ch

    // Cálculo de escala basado estrictamente en el manual (VisibleX/Y)
    const scaleX = cw / WORLD_CONSTANTS.VISIBLE_UNITS_X
    const scaleY = ch / WORLD_CONSTANTS.VISIBLE_UNITS_Y
    const currentScale = Math.min(scaleX, scaleY) * debugZoom.value
    scale.value = currentScale

    // Focal Point (Bottom-Alignment Centering)
    // El desplazamiento Tx/Ty centra el TARGET_X/Y del coordinador en el centro del viewport físico
    tx.value = (cw / 2) - (WORLD_CONSTANTS.TARGET_X * currentScale)
    ty.value = (ch / 2) - (WORLD_CONSTANTS.TARGET_Y * currentScale)
  }

  let resizeObserver: ResizeObserver | null = null

  onMounted(() => {
    resizeObserver = new ResizeObserver((entries) => {
      requestAnimationFrame(() => {
        if (!resizeObserver) return // Safety check if unmounted
        for (const entry of entries) {
          const { width, height } = entry.contentRect
          vpWidth.value = width
          vpHeight.value = height
          updateCamera(width, height)
        }
      })
    })

    if (viewportRef.value) {
      resizeObserver.observe(viewportRef.value)
      const rect = viewportRef.value.getBoundingClientRect()
      updateCamera(rect.width, rect.height)
    }

    gameBus.on('TOGGLE_CAMERA_GUIDES', () => {
      showGuides.value = !showGuides.value
    })

    gameBus.on('TOGGLE_DEBUG_ZOOM', () => {
      debugZoom.value = debugZoom.value === 1 ? 0.4 : 1
      if (viewportRef.value) {
        const rect = viewportRef.value.getBoundingClientRect()
        updateCamera(rect.width, rect.height)
      }
    })
  })

  onUnmounted(() => {
    if (resizeObserver) resizeObserver.disconnect()
  })

  return {
    cameraStyles,
    worldStyles,
    showGuides,
    scale,
    objectScale: WORLD_CONSTANTS.OBJECT_SCALE
  }
}

import { ref, computed, watch } from 'vue'
import { useUIStore } from '@/stores/ui'
import { useGameStore } from '@/stores/game'
import { useWindowListener, useDocumentListener } from '@/composables/useWindowListener'

export function useMainLayout(hudRef: any, hudBottomRef: any, innerHudRef: any) {
  const uiStore = useUIStore()
  const gameStore = useGameStore()

  const hudHeight = ref(110)
  const hudBottomHeight = ref(gameStore.state.starterChosen ? 80 : 0)
  const isHudHidden = ref(false)

  const activeTab = computed(() => uiStore.activeTab)
  watch(activeTab, () => {
    isHudHidden.value = false
  })

  // 1. Outside Click logic
  function handleOutsideClick(e: any) {
    if (!uiStore.openHudGroup) return

    const isInsideTopHud = hudRef.value?.contains(e.target)
    const bottomEl = hudBottomRef.value?.$el || hudBottomRef.value
    const isInsideBottomHud = bottomEl ? bottomEl.contains(e.target) : false

    if (!isInsideTopHud && !isInsideBottomHud) {
      uiStore.openHudGroup = null
    }
  }

  // 2. Scroll logic
  let lastScrollY = 0
  let scrollTicking = false
  function handleScroll(e: any) {
    if (scrollTicking) return
    scrollTicking = true

    requestAnimationFrame(() => {
      let target = e.target
      if (target === document || target === window) target = document.documentElement

      if (target.tagName !== 'HTML' && (!target.classList || !target.classList.contains('tab-content'))) {
        scrollTicking = false
        return
      }

      const currentScrollY = target.scrollTop

      if (currentScrollY <= 50) {
        if (isHudHidden.value) isHudHidden.value = false
        lastScrollY = currentScrollY
        scrollTicking = false
        return
      }

      const diff = currentScrollY - lastScrollY
      const threshold = 60

      if (Math.abs(diff) > threshold) {
        const nextHidden = diff > 0
        if (isHudHidden.value !== nextHidden) {
          isHudHidden.value = nextHidden
        }
        lastScrollY = currentScrollY
      }

      scrollTicking = false
    })
  }

  // 3. Height calculation logic
  let isUpdatingHeight = false
  function updateHudHeight() {
    if (isUpdatingHeight) return
    isUpdatingHeight = true

    requestAnimationFrame(() => {
      if (isHudHidden.value) {
        isUpdatingHeight = false
        return
      }

      let newHeight = 0
      if (innerHudRef.value) {
        newHeight = innerHudRef.value.offsetHeight
      } else if (hudRef.value) {
        newHeight = hudRef.value.offsetHeight
      }

      if (Math.abs(hudHeight.value - newHeight) > 2) {
        hudHeight.value = newHeight
      }

      const bottomEl = hudBottomRef.value?.$el || hudBottomRef.value
      const newBottomHeight = bottomEl ? bottomEl.offsetHeight : 0
      if (Math.abs(hudBottomHeight.value - newBottomHeight) > 2) {
        hudBottomHeight.value = newBottomHeight
      }

      isUpdatingHeight = false
    })
  }

  // Lifecycle listeners
  useWindowListener('resize', () => {
    updateHudHeight()
  }, { passive: true })

  useWindowListener('scroll', handleScroll, { passive: true, capture: true })
  useDocumentListener('click', handleOutsideClick)

  return {
    hudHeight,
    hudBottomHeight,
    isHudHidden,
    updateHudHeight
  }
}

import { ref, onMounted, onUnmounted } from 'vue'
import { registerSW } from 'virtual:pwa-register'

export function usePWA() {
  const installEvent = ref<any>(null)
  const canInstall = ref(false)
  const isInstalled = ref(false)

  // Vite PWA auto-update logic (Manual reactivity for better compatibility)
  const needRefresh = ref(false)
  const updateServiceWorker = registerSW({
    onNeedRefresh() {
      needRefresh.value = true
      console.log('SW Update available')
    },
    onOfflineReady() {
      console.log('PWA Offline Ready')
    },
    onRegistered(r: any) {
      console.log('SW Registered:', r)
    },
    onRegisterError(error: any) {
      console.error('SW registration error', error)
    },
  })

  const handleInstallPrompt = (e: any) => {
    // Prevent the mini-infobar from appearing on mobile
    e.preventDefault()
    // Stash the event so it can be triggered later.
    installEvent.value = e
    canInstall.value = true
    console.log('PWA Install Prompt captured')
  }

  const checkInstallState = () => {
    if (window.matchMedia('(display-mode: standalone)').matches || 
        window.matchMedia('(display-mode: fullscreen)').matches ||
        (window.navigator as any).standalone) {
      isInstalled.value = true
      canInstall.value = false
    }
  }

  const installApp = async () => {
    if (!installEvent.value) return false

    // Show the install prompt
    const event = installEvent.value;
    if (event && typeof event.prompt === 'function') {
      event.prompt()

      // Wait for the user to respond to the prompt
      const { outcome } = await event.userChoice
      console.log(`User response to the install prompt: ${outcome}`)

      // We've used the prompt, and can't use it again, throw it away
      installEvent.value = null
      canInstall.value = false

      return outcome === 'accepted'
    }
    return false
  }

  onMounted(() => {
    window.addEventListener('beforeinstallprompt', handleInstallPrompt)
    window.addEventListener('appinstalled', () => {
      isInstalled.value = true
      canInstall.value = false
      installEvent.value = null
      console.log('PWA installed successfully')
    })
    checkInstallState()
  })

  onUnmounted(() => {
    window.removeEventListener('beforeinstallprompt', handleInstallPrompt)
  })

  return {
    canInstall,
    isInstalled,
    installApp,
    needRefresh,
    updateServiceWorker
  }
}

import { computed, toValue } from 'vue'
import { useUIStore } from '@/stores/ui'
import { useGameStore } from '@/stores/game'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { POKEMON_SPRITE_IDS } from '@/logic/pokedexConstants'
import { MOVE_DATA } from '@/data/moves'
import { EVOLUTION_TABLE, STONE_EVOLUTIONS, TRADE_EVOLUTIONS } from '@/data/evolutionData'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'

export function usePokemonDetail(propsRefs: Record<string, any>) {
  const uiStore = useUIStore()
  const gameStore = useGameStore()

  // Normalize inputs (props are passed as a reactive object or refs)
  const getProp = (key: string) => toValue(propsRefs[key])

  const uiData = computed(() => (uiStore as any).modals?.PokemonDetail?.data || {})

  const finalIndex = computed(() => {
    const pIdx = getProp('index')
    return pIdx !== -1 ? pIdx : (uiData.value.index ?? -1)
  })

  const finalContext = computed(() => {
    const pCtx = getProp('context')
    return (pCtx && pCtx !== 'pokedex') ? pCtx : (uiData.value.context || 'pokedex')
  })

  const targetPokemon = computed(() => {
    if (finalIndex.value > -1) {
      if (finalContext.value === 'team') return gameStore.state.team[finalIndex.value]
      if (finalContext.value === 'box') return gameStore.state.box[finalIndex.value]
    }
    return getProp('pokemon') || uiData.value.pokemon
  })

  const isInstance = computed(() => !!targetPokemon.value)

  const targetSpeciesId = computed(() => {
    const id = isInstance.value ? targetPokemon.value.id : getProp('speciesId')
    return String(id).toLowerCase()
  })

  const speciesRaw = computed(() => pokemonDataProvider.getPokemonData(targetSpeciesId.value))

  const species = computed(() => {
    if (!speciesRaw.value) return null
    const s = speciesRaw.value
    const types = Array.isArray(s.type) ? s.type : [s.type]
    const nationalId = POKEMON_SPRITE_IDS[targetSpeciesId.value] || 0

    return {
      ...s,
      nationalId: nationalId.toString(),
      type: types,
      stats: {
        hp: s.hp || 0,
        atk: s.atk || 0,
        def: s.def || 0,
        spa: s.spa || 0,
        spd: s.spd || 0,
        spe: s.spe || 0
      }
    }
  })

  const cleanCategory = computed(() => {
    if (!species.value?.category) return 'Desconocido'
    return species.value.category.replace(/^Pokémon\s+/i, '')
  })

  const evolutions = computed(() => {
    const list = []
    const id = targetSpeciesId.value
    const caught = gameStore.state.pokedex || []
    const seen = gameStore.state.seenPokedex || []

    const enrichEvo = (evo: any) => {
      const toId = evo.to.toLowerCase()
      const isCaught = caught.includes(toId)
      const isSeen = isCaught || seen.includes(toId)
      return { ...evo, isSeen, isCaught }
    }

    if ((EVOLUTION_TABLE as any)[id]) {
      const ev = (EVOLUTION_TABLE as any)[id]
      list.push(enrichEvo({ type: 'level', requirement: `Nv. ${ev.level}`, to: ev.to }))
    }

    Object.keys(STONE_EVOLUTIONS).forEach(key => {
      if (key === id || key.startsWith(`${id}_`)) {
        const ev = (STONE_EVOLUTIONS as any)[key]
        list.push(enrichEvo({ type: 'stone', requirement: ev.stone, to: ev.to }))
      }
    })

    if ((TRADE_EVOLUTIONS as any)[id]) {
      list.push(enrichEvo({ type: 'trade', requirement: 'Intercambio', to: (TRADE_EVOLUTIONS as any)[id] }))
    }
    return list
  })

  const displayStats = computed(() => {
    if (!species.value) return []
    const labels: Record<string, string> = { hp: 'HP', atk: 'ATK', def: 'DEF', spa: 'SPA', spd: 'SPD', spe: 'SPE' }
    const colors: Record<string, string> = { 
      hp: 'Rgba(255, 89, 89, 1)', 
      atk: 'Rgba(245, 172, 120, 1)', 
      def: 'Rgba(250, 224, 120, 1)', 
      spa: 'Rgba(157, 183, 245, 1)', 
      spd: 'Rgba(167, 219, 141, 1)', 
      spe: 'Rgba(250, 146, 178, 1)' 
    }
    return Object.keys(species.value.stats).map(key => {
      const base = (species.value?.stats as any)[key]
      const current = isInstance.value ? (targetPokemon.value[key] || base) : base
      return {
        id: key,
        label: labels[key],
        value: current,
        baseValue: base,
        max: 255,
        color: colors[key],
        iv: isInstance.value ? targetPokemon.value.ivs?.[key] : null
      }
    })
  })

  const moveDetails = computed(() => {
    if (!species.value || !species.value.learnset) return []
    return species.value.learnset.map((m: any) => {
      const data = (MOVE_DATA as any)[m.name] || {}
      return {
        level: m.lv,
        name: m.name,
        type: data.type || 'normal',
        cat: data.cat || 'physical',
        power: data.power || '-',
        acc: data.acc || '-',
        pp: data.pp || '-'
      }
    }).sort((a: any, b: any) => a.level - b.level)
  })

  const currentMoves = computed(() => {
    if (!isInstance.value || !targetPokemon.value.moves) return []
    return targetPokemon.value.moves.map((m: any) => {
      const data = (MOVE_DATA as any)[m.name] || {}
      return { ...m, ...data }
    })
  })

  const canStoneEvolve = computed(() => {
    const id = targetSpeciesId.value
    return Object.keys(STONE_EVOLUTIONS).some(key => key === id || key.startsWith(`${id}_`))
  })

  const instancePhysicalData = computed(() => {
    if (!isInstance.value || !species.value) return null
    const p = targetPokemon.value
    const uid = p.uid || 'def'
    const getRand = (seed: string, range: any) => {
      if (!range) return '0.0'
      const min = Array.isArray(range) ? range[0] : range * 0.85
      const max = Array.isArray(range) ? range[1] : range * 1.15
      let hash = 0
      for (let i = 0; i < seed.length; i++) hash = seed.charCodeAt(i) + ((hash << 5) - hash)
      const normalized = (Math.abs(hash) % 100) / 100
      return (min + normalized * (max - min)).toFixed(1)
    }
    return {
      height: p.height || getRand(uid + 'h', species.value.height),
      weight: p.weight || getRand(uid + 'w', species.value.weight)
    }
  })

  const captureDateFormatted = computed(() => {
    const p = targetPokemon.value
    if (!p) return null
    const dateVal = p.captureDate || p.timestamp || p.date || p.created_at || p.obtainedAt
    if (!dateVal) return isInstance.value ? 'SIN FECHA' : null

    try {
      const date = new Date(dateVal)
      return date.toLocaleDateString('es-ES', { 
        year: 'numeric', month: 'long', day: 'numeric',
        hour: '2-digit', minute: '2-digit'
      })
    } catch (_) {
      return null
    }
  })

  const getSprite = (id: string, isShiny: boolean = false) => getAssetUrl(ASSET_TYPES.POKEMON, id, { shiny: isShiny })

  return {
    targetPokemon,
    isInstance,
    targetSpeciesId,
    species,
    cleanCategory,
    evolutions,
    displayStats,
    moveDetails,
    currentMoves,
    canStoneEvolve,
    instancePhysicalData,
    captureDateFormatted,
    getSprite,
    finalIndex,
    finalContext
  }
}

import { usePvPStore } from '@/stores/pvp';

export function useRankedValidation() {
  const rankedStore = usePvPStore();

  /**
   * Valida un único Pokémon contra las reglas actuales.
   */
  const validatePokemon = (pokemon: any) => {
    if (!pokemon) return { ok: false, reason: 'Pokémon inválido.' };

    const rules = rankedStore.rules;
    const pokeId = String(pokemon.id || '').toLowerCase();

    // 1. Ban List
    if (rules.bannedPokemonIds?.includes(pokeId)) {
      return { ok: false, reason: `${pokemon.name} está baneado esta temporada.` };
    }

    // 2. Level Cap
    if (pokemon.level > rules.levelCap) {
      return { ok: false, reason: `${pokemon.name} supera el nivel máximo (${rules.levelCap}).` };
    }

    // 3. Type Restrictions
    if (rules.allowedTypes?.length > 0) {
      const types = Array.isArray(pokemon.type) ? pokemon.type : [pokemon.type];
      const hasAllowedType = types.some((t: any) => rules.allowedTypes.includes(t.toLowerCase()));
      if (!hasAllowedType) {
        return { ok: false, reason: `${pokemon.name} no cumple con los tipos permitidos.` };
      }
    }

    return { ok: true };
  };

  /**
   * Valida un equipo completo.
   */
  const validateTeam = (team: any[]) => {
    if (!team || team.length === 0) {
      return { ok: false, reason: 'El equipo está vacío.' };
    }

    const rules = rankedStore.rules;
    if (team.length > rules.maxPokemon) {
      return { ok: false, reason: `Máximo ${rules.maxPokemon} Pokémon permitidos.` };
    }

    for (const p of team) {
      const result = validatePokemon(p);
      if (!result.ok) return result;
    }

    return { ok: true };
  };

  return {
    validatePokemon,
    validateTeam
  };
}

import { computed, toValue } from 'vue'
import { toVirtualStyles } from '@/logic/combat/spatialCoordinator'

/**
 * useVirtualPosition
 * Converts virtual units (0-3000) into CSS styles for absolute positioning.
 * Accepts MaybeRefOrGetter for all parameters.
 * 
 * @param {number} x - Virtual X coordinate
 * @param {number} y - Virtual Y coordinate
 * @param {number} w - Optional virtual width (will be multiplied by OBJECT_SCALE)
 * @param {number} h - Optional virtual height (will be multiplied by OBJECT_SCALE)
 */
export function useVirtualPosition(x: any, y: any, w?: any, h?: any) {
  const styles = computed(() => {
    return toVirtualStyles(toValue(x), toValue(y), toValue(w), toValue(h))
  })

  return {
    styles
  }
}

import { onMounted, onUnmounted } from 'vue'

/**
 * useWindowListener
 * Specialized composable to manage global listeners with strict lifecycle cleanup.
 * Prevents hybrid pattern leaks and centralizes window interactions.
 */
export function useWindowListener(event: string, callback: any, options: any = {}) {
  onMounted(() => {
    window.addEventListener(event, callback, options)
  })

  onUnmounted(() => {
    window.removeEventListener(event, callback, options)
  })
}

/**
 * useDocumentListener
 * Same but for document.
 */
export function useDocumentListener(event: string, callback: any, options: any = {}) {
  onMounted(() => {
    document.addEventListener(event, callback, options)
  })

  onUnmounted(() => {
    document.removeEventListener(event, callback, options)
  })
}

