import { getCombinedEffectiveness } from '../battleEngine'

/**
 * Motor de Inteligencia Artificial para el Combate
 * Portado y modernizado desde public/js/07_battle.js
 */

export const decideEnemyMove = (enemy: any, player: any, playerStages: any, isWild = false) => {
  const validMoves = enemy.moves.filter((m: any) => m.pp > 0)
  if (validMoves.length === 0) return null

  // Si es salvaje, elige al azar (Gen 3 wild behavior)
  if (isWild) {
    return validMoves[Math.floor(Math.random() * validMoves.length)]
  }

  // Si es Entrenador o Gimnasio, usa lógica de puntuación
  let bestMove = validMoves[0]
  let maxScore = -1

  validMoves.forEach((m: any) => {
    const s = scoreMove(m, enemy, player, playerStages)
    if (s > maxScore) {
      maxScore = s
      bestMove = m
    }
  })

  return bestMove
}

export const scoreMove = (move: any, attacker: any, defender: any, defStages: any) => {
  // md = move data (placeholder or from global data)
  let score = move.power || 40
  if (move.cat === 'status') score = 30

  const totalEff = getCombinedEffectiveness(move.type, defender, attacker)

  if (totalEff === 0 && move.cat !== 'status') return 0
  score *= totalEff

  // STAB
  if (move.type === attacker.type || move.type === attacker.type2) {
    score *= 1.5
  }

  // Status moves refinement
  if (move.cat === 'status') {
    // Don't repeat status
    const statusEffects = ['sleep', 'paralyze', 'poison', 'toxic', 'burn', 'freeze']
    if (statusEffects.includes(move.effect) && defender.status) score = 0

    // Stage modifiers penalization if already lowered
    const effect = move.effect || ''
    if (effect === 'lower_atk' && (defStages.atk || 0) <= -2) score = 5
    if (effect === 'lower_def' && (defStages.def || 0) <= -2) score = 5
    if (effect === 'lower_spa' && (defStages.spa || 0) <= -2) score = 5
    if (effect === 'lower_spd' && (defStages.spd || 0) <= -2) score = 5
    if (effect === 'lower_spe' && (defStages.spe || 0) <= -2) score = 5

    // High priority for non-statused sleep/paralyze
    if ((effect === 'sleep' || effect === 'paralyze') && !defender.status) score = 60
  }

  // Self-destruct logic (smart usage)
  if (move.selfKO) {
    const hpPct = attacker.hp / attacker.maxHp
    const canKO = (score >= defender.hp)
    if (hpPct > 0.25 && !canKO) score *= 0.01 
    else if (canKO) score *= 1.5
    else score *= 0.8
  }

  // Add randomness to be less predictable (80% - 120%)
  return score * (0.8 + Math.random() * 0.4)
}

/**
 * Evalúa si el oponente debería cambiar de Pokémon
 */
export const shouldEnemySwitch = (enemy: any, player: any, enemyTeam: any) => {
  if (!enemyTeam || enemyTeam.filter((p: any) => p.hp > 0).length <= 1) return false

  const playerEff = getCombinedEffectiveness(player.type, enemy)
  const isBadMatch = playerEff >= 2

  // Si tiene mala ventaja de tipo, hay un 20% - 40% de chance de cambio
  if (isBadMatch && Math.random() < 0.3) {
    return true
  }

  return false
}

export const findBestSwitchIndex = (enemyTeam: any, player: any, currentEnemyUid: any) => {
  let bestIdx = -1
  let bestScore = -1

  enemyTeam.forEach((p: any, idx: any) => {
    if (p.hp <= 0 || p.uid === currentEnemyUid) return

    let score = 0
    // Defense: how well we tank the player
    const playerEff = getCombinedEffectiveness(player.type, p)
    score += (2 - playerEff) * 50

    // Offense: how well we hit the player
    const maxOffense = Math.max(...p.moves.map((m: any) => {
      const eff = getCombinedEffectiveness(m.type, player, p)
      return eff * (m.power || 40)
    }))
    score += maxOffense

    if (score > bestScore) {
      bestScore = score
      bestIdx = idx
    }
  })

  return bestIdx
}

export const getBattleAITools = () => {
  return {
    scoreMove,
    decideEnemyMove,
    shouldEnemySwitch,
    findBestSwitchIndex
  };
}

import type { Pokemon } from '@/types/pokemon';
import type { BattleStages, LogFn } from '@/types/battle';

interface BattleMove {
  name: string
  flinch?: boolean
}

interface BattleMoveData {
  cat?: 'physical' | 'special' | 'status'
  type?: string
  sound?: boolean
  [key: string]: unknown
}

export function handleEntryAbilities(p1: Pokemon, p2: Pokemon, p1Stages: BattleStages, p2Stages: BattleStages, addLogFn: LogFn) {
  if (!p1 || !p2) return;

  // Intimidación (Intimidate)
  if (p1.ability === 'Intimidación') {
    p2Stages.atk = Math.max(-6, (p2Stages.atk || 0) - 1);
    addLogFn(`¡La Intimidación de ${p1.name} bajó el ataque de ${p2.name}!`, 'log-info', p1);
  }
  if (p2.ability === 'Intimidación') {
    p1Stages.atk = Math.max(-6, (p1Stages.atk || 0) - 1);
    addLogFn(`¡La Intimidación de ${p2.name} bajó el ataque de ${p1.name}!`, 'log-info', p2);
  }

  // Trace (Rastro)
  if (p1.ability === 'Rastro' && p2.ability) {
    p1.ability = p2.ability;
    addLogFn(`¡${p1.name} copió la habilidad ${p2.ability} de ${p2.name} con Rastro!`, 'log-info', p1);
  }
  if (p2.ability === 'Rastro' && p1.ability) {
    p2.ability = p1.ability;
    addLogFn(`¡${p2.name} copió la habilidad ${p1.ability} de ${p1.name} con Rastro!`, 'log-info', p2);
  }
}

export function applyAbilityEffects(attacker: Pokemon, defender: Pokemon, move: BattleMove, _damageResult: unknown, MOVE_DATA: Record<string, BattleMoveData>, addLogFn: LogFn) {
  const ab = defender.ability;
  const md = MOVE_DATA[move.name] || {};

  // Contact abilities (Physical moves)
  if (md.cat === 'physical' && Math.random() < 0.3) {
    if (ab === 'Electricidad estática' && !attacker.status && attacker.type !== 'electric') {
      attacker.status = 'paralyze';
      addLogFn(`¡La Electricidad estática de ${defender.name} paralizó a ${attacker.name}!`, 'log-info', defender);
    }
    if (ab === 'Punto tóxico' && !attacker.status && attacker.type !== 'poison' && attacker.type !== 'steel') {
      attacker.status = 'poison';
      addLogFn(`¡El Punto tóxico de ${defender.name} envenenó a ${attacker.name}!`, 'log-info', defender);
    }
    if (ab === 'Cuerpo Llama' && !attacker.status && attacker.type !== 'fire') {
      attacker.status = 'burn';
      addLogFn(`¡El Cuerpo Llama de ${defender.name} quemó a ${attacker.name}!`, 'log-info', defender);
    }
    if (ab === 'Efecto Espora' && !attacker.status) {
      const roll = Math.random();
      if (roll < 0.33) {
        attacker.status = 'sleep'; 
        (attacker as any).sleepTurns = 1 + Math.floor(Math.random() * 3);
        addLogFn(`¡El Efecto Espora de ${defender.name} durmió a ${attacker.name}!`, 'log-info', defender);
      } else if (roll < 0.66) {
        attacker.status = 'paralyze';
        addLogFn(`¡El Efecto Espora de ${defender.name} paralizó a ${attacker.name}!`, 'log-info', defender);
      } else {
        attacker.status = 'poison';
        addLogFn(`¡El Efecto Espora de ${defender.name} envenenó a ${attacker.name}!`, 'log-info', defender);
      }
    }
  }

  // Stench (Hedor)
  if (attacker.ability === 'Hedor' && Math.random() < 0.1) {
    if (!(defender as any).flinched) {
      (defender as any).flinched = true;
      addLogFn(`¡El Hedor de ${attacker.name} hizo retroceder a ${defender.name}!`, 'log-info', attacker);
    }
  }
}

/**
 * Checks for ability-based immunities (Absorb, Levitate, etc.)
 */
export function checkAbilityImmunity(_attacker: Pokemon, defender: Pokemon, move: BattleMove, MOVE_DATA: Record<string, BattleMoveData>, addLogFn: LogFn, ctx: { b?: { player: Pokemon, enemy: Pokemon }, playerStages?: BattleStages, enemyStages?: BattleStages } = {}) {
  const ab = defender.ability;
  const md = MOVE_DATA[move.name] || {};

  if (ab === 'Pararrayos' && md.type === 'electric') {
    addLogFn(`¡El Pararrayos de ${defender.name} absorbió el ataque!`, 'log-info', defender);
    const b = ctx.b;
    const stages = (b && b.enemy === defender) ? ctx.enemyStages : (b ? ctx.playerStages : null);
    if (stages) {
      stages.spa = Math.min(6, (stages.spa || 0) + 1);
      addLogFn(`¡Subió el At. Esp de ${defender.name}!`, 'log-info', defender);
    }
    return true;
  }

  if (ab === 'Absorbe Agua' && md.type === 'water') {
    addLogFn(`¡El Absorbe Agua de ${defender.name} absorbió el ataque!`, 'log-info', defender);
    const heal = Math.floor(defender.maxHp / 4);
    defender.hp = Math.min(defender.maxHp, defender.hp + heal);
    addLogFn(`¡${defender.name} recuperó HP!`, 'log-info', defender);
    return true;
  }

  if (ab === 'Absorbe Voltio' && md.type === 'electric') {
    addLogFn(`¡El Absorbe Voltio de ${defender.name} absorbió el ataque!`, 'log-info', defender);
    const heal = Math.floor(defender.maxHp / 4);
    defender.hp = Math.min(defender.maxHp, defender.hp + heal);
    addLogFn(`¡${defender.name} recuperó HP!`, 'log-info', defender);
    return true;
  }

  if (ab === 'Absorbe Fuego' && md.type === 'fire') {
    addLogFn(`¡El Absorbe Fuego de ${defender.name} absorbió el ataque!`, 'log-info', defender);
    return true;
  }

  if (ab === 'Insonorizar' && md.sound) {
    addLogFn(`¡El Insonorizar de ${defender.name} bloqueó el ataque de sonido!`, 'log-info', defender);
    return true;
  }

  if (ab === 'Levitación' && md.type === 'ground' && md.cat !== 'status') {
    addLogFn(`¡${defender.name} levita y evita el ataque!`, 'log-info', defender);
    return true;
  }

  if (ab === 'Foco Interno' && move.flinch) {
    addLogFn(`¡El Foco Interno de ${defender.name} evitó el retroceso!`, 'log-info', defender);
    return true;
  }

  return false;
}

export function handleOnSwitchOut(pokemon: Pokemon, addLogFn: LogFn) {
  if (pokemon.ability === 'Cura Natural' && pokemon.status) {
    pokemon.status = null;
    addLogFn(`¡La Cura Natural de ${pokemon.name} sanó sus problemas de estado!`, 'log-info', pokemon);
  }
}

export function handleStatusSync(attacker: Pokemon, defender: Pokemon, status: string | null, addLogFn: LogFn) {
  if (defender.ability === 'Sincronía' && status) {
    if (!attacker.status) {
      attacker.status = status;
      addLogFn(`¡La Sincronía de ${defender.name} pasó el estado a ${attacker.name}!`, 'log-info', defender);
    }
  }
}

import { gameBus } from '@/logic/gameBus'
import { getMechanicalWeather, WEATHER_MECHANICAL } from './weatherMapper'

export function handleEntryAbilities(playerPoke: any, enemyPoke: any, playerStages: any, enemyStages: any, addLog: any) {
  if (!playerPoke || !enemyPoke) return // GUARDIA CRÍTICA

  if (playerPoke.ability === 'Intimidación') {
    enemyStages.atk = Math.max(-6, enemyStages.atk - 1)
    addLog(`¡La Intimidación de ${playerPoke.name} bajó el ataque de ${enemyPoke.name}!`, 'log-info', playerPoke)
  }
  if (enemyPoke.ability === 'Intimidación') {
    playerStages.atk = Math.max(-6, playerStages.atk - 1)
    addLog(`¡La Intimidación de ${enemyPoke.name} bajó el ataque de ${playerPoke.name}!`, 'log-info', enemyPoke)
  }
}

export function canAttack(pokemon: any, addLog: any) {
  if (pokemon.mustRecharge) {
    addLog(`¡${pokemon.name} tiene que recargar!`, 'log-info', pokemon)
    pokemon.mustRecharge = false
    return false
  }
  if (pokemon.flinched) {
    addLog(`¡${pokemon.name} retrocedió!`, 'log-info', pokemon)
    pokemon.flinched = false
    return false
  }
  if (pokemon.status === 'sleep') {
    if (pokemon.sleepTurns > 0) {
      pokemon.sleepTurns--
      addLog(`¡${pokemon.name} está profundamente dormido!`, 'log-info', pokemon)
      return false
    } else {
      pokemon.status = null
      addLog(`¡${pokemon.name} se despertó!`, 'log-info', pokemon)
    }
  }
  if (pokemon.status === 'freeze') {
    if (Math.random() < 0.8) {
      addLog(`¡${pokemon.name} está congelado!`, 'log-info', pokemon)
      return false
    } else {
      pokemon.status = null
      addLog(`¡${pokemon.name} se descongeló!`, 'log-info', pokemon)
    }
  }
  if (pokemon.status === 'paralyze') {
    if (Math.random() < 0.25) {
      addLog(`¡${pokemon.name} está paralizado! ¡No puede moverse!`, 'log-info', pokemon)
      return false
    }
  }
  if (pokemon.confused > 0) {
    pokemon.confused--
    if (pokemon.confused <= 0) {
      addLog(`¡${pokemon.name} ya no está confundido!`, 'log-info', pokemon)
    } else {
      addLog(`¡${pokemon.name} está confundido!`, 'log-info', pokemon)
      if (Math.random() < 0.5) {
        const selfDmg = Math.max(1, Math.floor(((2 * pokemon.level / 5 + 2) * 40 * (pokemon.atk || 10) / (pokemon.def || 10)) / 50) + 2)
        pokemon.hp = Math.max(0, pokemon.hp - selfDmg)
        addLog(`¡Tan confundido que se hirió a sí mismo! (-${selfDmg} HP)`, 'log-info', pokemon)
        gameBus.emit('PLAY_SOUND', 'statusDamage')
        return false
      }
    }
  }
  if (pokemon.attracted) {
    addLog(`¡${pokemon.name} está enamorado!`, 'log-info', pokemon)
    if (Math.random() < 0.5) {
      addLog(`¡La atracción le impide atacar!`, 'log-info', pokemon)
      return false
    }
  }
  return true
}

export function applyEndTurnWeather(p: any, e: any, weather: any, addLog: any) {
  const mechWeather = getMechanicalWeather(weather?.type);

  if (mechWeather === WEATHER_MECHANICAL.SANDSTORM) {
    const isSandImmune = (poke: any) => ['rock', 'ground', 'steel'].includes(poke.type) || ['rock', 'ground', 'steel'].includes(poke.type2)
    if (!isSandImmune(p)) {
      const dmg = Math.floor(p.maxHp / 16)
      p.hp = Math.max(0, p.hp - dmg)
      addLog(`¡La tormenta de arena alcanza a ${p.name}!`, 'log-player', p)
      gameBus.emit('PLAY_SOUND', 'statusDamage')
    }
    if (!isSandImmune(e)) {
      const dmg = Math.floor(e.maxHp / 16)
      e.hp = Math.max(0, e.hp - dmg)
      addLog(`¡La tormenta de arena alcanza a ${e.name}!`, 'log-enemy', e)
      gameBus.emit('PLAY_SOUND', 'statusDamage')
    }
  }

  if (mechWeather === WEATHER_MECHANICAL.HAIL) {
    const isHailImmune = (poke: any) => poke.type === 'ice' || poke.type2 === 'ice'
    if (!isHailImmune(p)) {
      const dmg = Math.floor(p.maxHp / 16)
      p.hp = Math.max(0, p.hp - dmg)
      addLog(`¡El granizo alcanza a ${p.name}!`, 'log-player', p)
      gameBus.emit('PLAY_SOUND', 'statusDamage')
    }
    if (!isHailImmune(e)) {
      const dmg = Math.floor(e.maxHp / 16)
      e.hp = Math.max(0, e.hp - dmg)
      addLog(`¡El granizo alcanza a ${e.name}!`, 'log-enemy', e)
      gameBus.emit('PLAY_SOUND', 'statusDamage')
    }
  }

  if (mechWeather === WEATHER_MECHANICAL.SNOW) {
    // La nieve normal NO hace daño residual (Gen 9)
  }
}

