 */
export const STAGE_MULTIPLIERS_STAT: Record<string, number> = {
  '-6': 0.25, '-5': 0.28, '-4': 0.33, '-3': 0.40, '-2': 0.50, '-1': 0.66,
  '0': 1.0, '1': 1.5, '2': 2.0, '3': 2.5, '4': 3.0, '5': 3.5, '6': 4.0
};
export const STAGE_MULTIPLIERS_ACC: Record<string, number> = {
  '-6': 0.33, '-5': 0.37, '-4': 0.43, '-3': 0.50, '-2': 0.60, '-1': 0.75,
  '0': 1.0, '1': 1.33, '2': 1.66, '3': 2.0, '4': 2.33, '5': 2.66, '6': 3.0
};

/**
 * Returns the effective stat of a pokemon considering stages, weather, status, and abilities.
 */
export function getEffectiveStat(pokemon: Pokemon, statKey: keyof Pokemon, stages: Partial<BattleStages>, weather: BattleWeather | null) {
  const breakdown = getStatBreakdown(pokemon, statKey, stages, weather);
  return breakdown.final;
}

export function getStatBreakdown(pokemon: Pokemon, statKey: keyof Pokemon, stages: Partial<BattleStages>, weather: BattleWeather | null) {
  const mechWeather = getMechanicalWeather(weather?.type);
  const cycle = getDayCycle();

  let baseVal = (pokemon[statKey] as number) || 10;
  if (statKey === 'spa' && !pokemon.spa) baseVal = pokemon.atk;
  if (statKey === 'spd' && !pokemon.spd) baseVal = pokemon.def;

  const results = {
    base: baseVal,
    weatherMult: 1,
    stageMult: 1,
    statusMult: 1,
    abilityMult: 1,
    final: baseVal
  };

  // Weather Modifiers (Apply to Base in Gen 4+)
  if (statKey === 'def') {
    if ((mechWeather === WEATHER_MECHANICAL.SNOW || mechWeather === WEATHER_MECHANICAL.HAIL) && (pokemon.type === 'ice' || pokemon.type2 === 'ice')) {
      results.weatherMult = 1.5;
      baseVal = Math.floor(baseVal * 1.5);
    }
  }
  if (statKey === 'spd') {
    if (mechWeather === WEATHER_MECHANICAL.SANDSTORM && (pokemon.type === 'rock' || pokemon.type2 === 'rock')) {
      results.weatherMult = 1.5;
      baseVal = Math.floor(baseVal * 1.5);
    }
  }

  // Stage Multipliers
  const stage = stages ? Math.max(-6, Math.min(6, (stages[statKey as keyof BattleStages] || 0))) : 0;
  results.stageMult = (STAGE_MULTIPLIERS_STAT[String(stage)] as number) || 1.0;
  let val = Math.floor(baseVal * results.stageMult);

  // Ability & Status Modifiers
  const ab = pokemon.ability;
  const isSun = mechWeather === WEATHER_MECHANICAL.SUN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'day' || cycle === 'morning'));
  const isRain = mechWeather === WEATHER_MECHANICAL.RAIN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'night' || cycle === 'dusk'));

  if (statKey === 'atk') {
    if (ab === 'Potencia' || ab === 'Energía pura') results.abilityMult *= 2;
    if (ab === 'Agallas' && pokemon.status) results.abilityMult *= 1.5;

    val = Math.floor(val * results.abilityMult);

    if (pokemon.status === 'burn' && ab !== 'Agallas') {
      results.statusMult = 0.5;
      val = Math.floor(val * 0.5);
    }
  }

  if (statKey === 'def') {
    if (ab === 'Escama especial' && pokemon.status) {
      results.abilityMult = 1.5;
      val = Math.floor(val * 1.5);
    }
  }

  if (statKey === 'spe') {
    if (ab === 'Clorofila' && isSun) results.abilityMult *= 2;
    if (ab === 'Nado rápido' && isRain) results.abilityMult *= 2;
    if (ab === 'Ímpetu arena' && mechWeather === WEATHER_MECHANICAL.SANDSTORM) results.abilityMult *= 2;
    if (ab === 'Quitanieves' && (mechWeather === WEATHER_MECHANICAL.SNOW || mechWeather === WEATHER_MECHANICAL.HAIL)) results.abilityMult *= 2;

    val = Math.floor(val * results.abilityMult);

    if (pokemon.status === 'paralysis') {
      results.statusMult = 0.5; // Modern mechanics (Gen 7+): 50% speed reduction
      val = Math.floor(val * 0.5);
    }
  }

  results.final = Math.max(1, val);
  return results;
}

/**
 * Determines the category of a move based on Generation rules.
 */
export function getMoveCategory(move: Partial<Move>): 'status' | 'physical' | 'special' {
  if (ACTIVE_RULE_SET === 2) {
    // Category by Type
    const physicalTypes = ['normal', 'fighting', 'flying', 'poison', 'ground', 'rock', 'bug', 'ghost', 'steel'];
    const specialTypes = ['fire', 'water', 'grass', 'electric', 'psychic', 'ice', 'dragon', 'dark'];

    if (move.cat === 'status') return 'status'; // Status moves keep their category

    if (move.type && physicalTypes.includes(move.type)) return 'physical';
    if (move.type && specialTypes.includes(move.type)) return 'special';
  }
  // Gen 4+ uses direct category
  return (move.cat as any) || 'physical';
}

/**
 * Returns ability multiplier for offensive calculations.
 */
export function getAbilityMultiplier(attacker: Pokemon, _defender: Pokemon, move: Partial<Move>) {
  let mult = 1;
  let triggeredAbility: string | null = null;
  const ab = attacker.ability;
  const power = move.power || 0;

  // Damage boosters at low HP (1/3)
  const isLowHp = attacker.hp <= (attacker.maxHp / 3);
  if (isLowHp) {
    if (ab === 'Mar llamas' && move.type === 'fire') { mult *= 1.5; triggeredAbility = ab; }
    if (ab === 'Torrente' && move.type === 'water') { mult *= 1.5; triggeredAbility = ab; }
    if (ab === 'Espesura' && move.type === 'grass') { mult *= 1.5; triggeredAbility = ab; }
    if (ab === 'Enjambre' && move.type === 'bug') { mult *= 1.5; triggeredAbility = ab; }
  }

  if (ab === 'Agallas' && attacker.status && getMoveCategory(move) === 'physical') {
    mult *= 1.5;
    triggeredAbility = ab;
  }

  if (ab === 'Experto' && power > 0 && power <= 60) {
    mult *= 1.5;
    triggeredAbility = ab;
  }

  return { mult, triggeredAbility };
}

/**
 * Central Damage Formula.
 */
export function calculateDamage(attacker: Pokemon, defender: Pokemon, move: Partial<Move>, ctx: BattleContext = {}) {
  const { atkStages = 0, defStages = 0, weather = null } = ctx;

  let power = move.power;
  let moveType = move.type;

  if (power === undefined || !moveType) {
    const md = pokemonDataProvider.getMoveData(move.name || '');
    if (md) {
      if (power === undefined) power = md.power || 0;
      if (!moveType) moveType = md.type || 'normal';
    } else {
      power = power || 0;
      moveType = moveType || 'normal';
    }
  }

  const moveCat = getMoveCategory({ ...move, type: moveType });

  if (move.effect === 'dream_eater' && defender.status !== 'sleep') {
    return { dmg: 0, eff: 0, isNoEffect: true };
  }

  if (move.effect === 'magnitude' && !ctx.magnitudeSet) {
    const magRoll = Math.random() * 100;
    if (magRoll < 5) power = 10;
    else if (magRoll < 15) power = 30;
    else if (magRoll < 35) power = 50;
    else if (magRoll < 65) power = 70;
    else if (magRoll < 85) power = 90;
    else if (magRoll < 95) power = 110;
    else power = 150;
  }

  if (move.id === 'fury_cutter' && attacker.furyCutterCount) {
    power = Math.min(160, (power || 0) * Math.pow(2, attacker.furyCutterCount - 1));
  }

  const mechWeather = getMechanicalWeather(weather?.type);
  const cycle = getDayCycle();
  const isSolarBoosted = mechWeather === WEATHER_MECHANICAL.SUN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'day' || cycle === 'morning'));

  if ((move.id === 'solar_beam' || move.id === 'solar_blade') && !isSolarBoosted && mechWeather !== WEATHER_MECHANICAL.CLEAR) {
    power = Math.floor((power || 0) * 0.5);
  }

  if (move.fixedDmg) return { dmg: move.fixedDmg, eff: 1, isNoEffect: false };
  if (move.levelDmg) return { dmg: attacker.level, eff: 1, isNoEffect: false };
  if (move.halfHP) {
    const dmg = Math.max(1, Math.floor(defender.hp / 2));
    return { dmg, eff: 1, isNoEffect: false };
  }

  const eff = getCombinedEffectiveness(moveType, defender, attacker);

  if ((moveCat as string) === 'status' || (power === 0 && (moveCat as string) !== 'status')) {
    return { dmg: 0, eff, isNoEffect: eff === 0 };
  }

  const isPhysical = moveCat === 'physical';
  const aStages = { [isPhysical ? 'atk' : 'spa']: atkStages };
  const dStages = { [isPhysical ? 'def' : 'spd']: defStages };

  // Critical Hit logic
  let critRate = (attacker.heldItem === 'Lente Zoom') ? 0.12 : 0.06;
  if (attacker.focusEnergy) critRate = 0.25;
  if (ACTIVE_RULE_SET === 2) critRate = 0.0625; // Base probability 1/16

  let isCrit = Math.random() < critRate;
  if (defender.ability === 'Caparazón' || defender.ability === 'Armadura Batalla') isCrit = false;

  // Stat Reset Rule for Crits
  if (isCrit) {
    const aKey = isPhysical ? 'atk' : 'spa' as keyof Partial<BattleStages>;
    const dKey = isPhysical ? 'def' : 'spd' as keyof Partial<BattleStages>;
    if ((aStages[aKey] ?? 0) < 0) aStages[aKey] = 0;
    if ((dStages[dKey] ?? 0) > 0) dStages[dKey] = 0;
  }

  const critMult = isCrit ? (ACTIVE_RULE_SET === 2 ? 2.0 : 1.5) : 1;

  const A = getEffectiveStat(attacker, isPhysical ? 'atk' : 'spa', aStages, weather);
  const D = getEffectiveStat(defender, isPhysical ? 'def' : 'spd', dStages, weather);

  // Base Damage Formula
  const baseDamage = Math.floor(((2 * attacker.level / 5 + 2) * (power || 0) * A / D) / 50) + 2;

  let { mult: finalAbilityMult, triggeredAbility } = getAbilityMultiplier(attacker, defender, { ...move, type: moveType, power, cat: moveCat });

  if (defender.ability === 'Sebo' && (moveType === 'fire' || moveType === 'ice')) {
    finalAbilityMult *= 0.5;
    triggeredAbility = 'Sebo';
  }

  let itemMult = 1;
  if (attacker.heldItem) {
    const h = attacker.heldItem;
    const typeBoosters: Record<string, string> = { 'Carbón': 'fire', 'Imán': 'electric', 'Agua Mística': 'water', 'Semilla Milagro': 'grass', 'Cinturón Negro': 'fighting', 'Cuchara Torcida': 'psychic', 'Hechizo': 'ghost', 'Polvo Plata': 'bug', 'Flecha Venenosa': 'poison' };
    if (typeBoosters[h] === moveType) itemMult = 1.2;
    if (h === 'Cinta Elegida' && moveCat === 'physical') itemMult = 1.5;
  }

  let stab = (moveType === attacker.type || moveType === attacker.type2) ? 1.5 : 1;
  if (attacker.ability === 'Adaptable' && stab > 1) stab = 2;

  let weatherMult = 1;
  if (weather && weather.turns !== 0) {
    if (mechWeather === WEATHER_MECHANICAL.SUN) {
      if (moveType === 'fire') weatherMult = 1.5;
      else if (moveType === 'water') weatherMult = 0.5;
    } else if (mechWeather === WEATHER_MECHANICAL.RAIN) {
      if (moveType === 'water') weatherMult = 1.5;
      else if (moveType === 'fire') weatherMult = 0.5;
    }
  }

  if (weatherMult === 1 && (mechWeather === WEATHER_MECHANICAL.CLEAR || !weather)) {
    if (cycle === 'day' || cycle === 'morning') {
      if (moveType === 'fire') weatherMult = 1.2;
    } else if (cycle === 'night' || cycle === 'dusk') {
      if (moveType === 'water') weatherMult = 1.2;
    }
  }

  const random = 0.85 + Math.random() * 0.15;

  const finalDmg = eff > 0 
    ? Math.max(1, Math.floor(baseDamage * stab * finalAbilityMult * eff * random * critMult * weatherMult * itemMult)) 
    : 0;

  return {
    dmg: finalDmg,
    eff,
    stab,
    power,
    isCrit,
    isSuperEffective: eff > 1,
    isNotVeryEffective: eff < 1 && eff > 0,
    isNoEffect: eff === 0,
    triggeredAbility
  };
}

/**
 * Capture Math
 */
export function calculateCatchRate(pokemon: Pokemon, rawBallType = 'poke-ball', eventCatchMult = 1, ctx: BattleContext = {}) {
  const ballName = String(rawBallType || '').toLowerCase();

  const BALL_BEHAVIORS: Record<string, { guaranteed?: boolean, mult?: number | ((p: Pokemon, c: any) => number) }> = {
    'master': { guaranteed: true },
    '100': { guaranteed: true },
    'ultra': { mult: 2.0 },
    'super': { mult: 1.5 },
    'súper': { mult: 1.5 },
    'red': { 
      mult: (p, c) => {
        const isWaterOrBug = [p.type, p.type2].some(t => t === 'water' || t === 'bug');
        const isRain = c.weather && (c.weather.type === 'rain' || c.weather.type === 'storm');
        return (isWaterOrBug || isRain) ? 3.5 : 1.0;
      }
    },
    'net': { 
      mult: (p, c) => {
        const isWaterOrBug = [p.type, p.type2].some(t => t === 'water' || t === 'bug');
        const isRain = c.weather && (c.weather.type === 'rain' || c.weather.type === 'storm');
        return (isWaterOrBug || isRain) ? 3.5 : 1.0;
      }
    },
    'ocaso': {
      mult: (_p, c) => {
        const cycle = c.cycle || getDayCycle();
        const isNight = cycle === 'night' || cycle === 'dusk';
        const isCave = c.locationId && /cave|moon|tunnel|islands|mountain|victory|mansion/i.test(c.locationId);
        const isFog = c.weather && c.weather.type === 'fog';
        return (isNight || isCave || isFog) ? 3.0 : 1.0;
      }
    },
    'dusk': { 
      mult: (_p, c) => {
        const cycle = c.cycle || getDayCycle();
        const isNight = cycle === 'night' || cycle === 'dusk';
        const isCave = c.locationId && /cave|moon|tunnel|islands|mountain|victory|mansion/i.test(c.locationId);
        const isFog = c.weather && c.weather.type === 'fog';
        return (isNight || isCave || isFog) ? 3.0 : 1.0;
      }
    },
    'turno': {
      mult: (_p, c) => Math.min(4.0, 1.0 + ((c.turnCount || 1) * 0.3))
    },
    'timer': { 
      mult: (_p, c) => Math.min(4.0, 1.0 + ((c.turnCount || 1) * 0.3))
    }
  };

  const behaviorEntry = Object.entries(BALL_BEHAVIORS).find(([key]) => ballName.includes(key));
  const behavior = behaviorEntry ? behaviorEntry[1] : { mult: 1.0 };

  if (behavior.guaranteed) {
    return { caught: true, shakes: 3 };
  }

  let ballMult = 1.0;
  if (typeof behavior.mult === 'function') {
    ballMult = behavior.mult(pokemon, ctx);
  } else if (behavior.mult) {
    ballMult = behavior.mult;
  }

  const hpFactor = (3 * pokemon.maxHp - 2 * pokemon.hp) / (3 * pokemon.maxHp);
  const catchRate = pokemon.catchRate ?? 45;
  if (!pokemon.catchRate) {
    console.warn(`Capture warning: Pokémon ${pokemon.name} (${pokemon.id}) missing catchRate. Falling back to 45.`);
  }
  const statusMult = (pokemon.status === 'sleep' || pokemon.status === 'freeze') ? 2.0 : 
                     (pokemon.status ? 1.5 : 1.0);

  const eventBonus = eventCatchMult - 1;
  const totalMult = Math.max(0.1, ballMult + eventBonus);

  const finalRate = Math.min(255, Math.max(1, Math.floor(catchRate * totalMult * hpFactor * statusMult)));

  const b = Math.floor(65535 * Math.pow(finalRate / 255, 0.25));

  let shakes = 0;
  for (let i = 0; i < 4; i++) {
    if (Math.random() * 65535 < b) {
      shakes++;
    } else {
      break;
    }
  }

  return {
    caught: shakes === 4,
    shakes: Math.min(3, shakes)
  };
}

/**
 * Calculates escape chance from Wild Pokémon.
 * @param {Pokemon} playerPoke 
 * @param {Pokemon} wildPoke 
 * @param {number} attempts 
 * @param {Object} ctx 
 * @returns {boolean} Whether escape is successful.
 */
export function calculateEscapeChance(playerPoke: Pokemon, wildPoke: Pokemon, attempts: number, ctx: BattleContext = {}) {
  const pSpe = getEffectiveStat(playerPoke, 'spe', ctx.playerStages || {}, ctx.weather || null);
  const eSpe = getEffectiveStat(wildPoke, 'spe', ctx.enemyStages || {}, ctx.weather || null);

  // Guard against division by zero
  const safeESpe = Math.max(1, eSpe);

  if (ACTIVE_RULE_SET === 2) {
    const f = Math.floor((pSpe * 32) / Math.floor(safeESpe / 4)) + 30 * attempts;
    if (f > 255) return true;
    return Math.floor(Math.random() * 256) < f;
  } else {
    // Gen 4+
    const f = Math.floor((pSpe * 128) / safeESpe) + 30 * attempts;
    return Math.floor(Math.random() * 256) < f;
  }
}

/**
 * battleItems.js
 * Logic for using items (balls and healing) in battle.
 */
import { calculateCatchRate } from './battleEngine'
import { useItemOnPokemon } from '../providers/itemProvider'
import { gameBus } from '@/logic/gameBus'

export async function handleItemUsage(itemName: any, p: any, e: any, options: any = {}) {
  const { 
    eventStore, 
    addLog, 
    audio, 
    consumeItem 
  } = options

  const nameLower = itemName.toLowerCase()
  const isBall = nameLower.includes('ball') || nameLower.includes('bola')

  if (isBall) {
    if (options.fsm) {
      options.fsm.transition('ACTIVE_BATTLE', 'CATCH_PROCESS')
    }
    addLog(`Usaste ${itemName}`, 'log-info', 'player')
    addLog(`¡Has lanzado una ${itemName}!`, 'log-catch', itemName, 'player')

    // El ítem se consume inmediatamente al lanzarse
    consumeItem(itemName)

    const eventCatchMult = eventStore.globalMultipliers?.catch || 1
    const { caught, shakes } = calculateCatchRate(e, itemName, eventCatchMult, options.ctx || {})

    // 1. Iniciar animación de entrada (energía azul)
    audio.ballHit()
    gameBus.emit('PLAY_CATCH_ENERGY', { side: 'enemy', ballId: itemName })

    // Esperar a que el Pokémon termine de entrar en la bola (800ms aprox)
    await new Promise(r => setTimeout(r, 1000))

    // 2. Ejecutar los intentos de agitación (shakes)
    for (let i = 0; i < shakes; i++) {
      if (options.fsm) {
        options.fsm.transition('ACTIVE_BATTLE', 'CATCH_SHAKE')
      }
      audio.wobble()
      gameBus.emit('CATCH_SHAKE', { side: 'enemy' })
      // Duración de un shake + pequeña pausa
      await new Promise(r => setTimeout(r, 1000))
    }

    // 3. Resultado final
    if (caught) {
      // Pequeña pausa dramática antes del click de éxito
      await new Promise(r => setTimeout(r, 500))
      if (options.fsm) {
        options.fsm.transition('ACTIVE_BATTLE', 'CATCH_SUCCESS')
      }
      audio.caught()
      gameBus.emit('CATCH_SUCCESS', { side: 'enemy' })
      addLog(`¡Ya está! ¡${e.name} atrapado!`, 'log-catch', e)

      // Captured!
      if (options.fsm) {
        options.fsm.transition('ACTIVE_BATTLE', 'ADD_TO_STORAGE')
      }
      return { action: 'capture', pokemon: e }
    } else {
      // Esperar un instante tras el último shake fallido
      await new Promise(r => setTimeout(r, 300))
      if (options.fsm) {
        options.fsm.transition('ACTIVE_BATTLE', 'CATCH_BREAK')
      }
      gameBus.emit('CATCH_BREAK', { side: 'enemy' })
      addLog(`¡Oh, no! ¡El Pokémon se ha escapado!`, 'log-info', e)
      // Trigger energy release animation because it broke free
      gameBus.emit('PLAY_RELEASE_ENERGY', { side: 'enemy' })

      // Wait for release animation to finish before showing HUD again
      await new Promise(r => setTimeout(r, 800))
    }
  } else {
    // Entrada de entrenador (siempre, para feedback inmediato)
    addLog(`Usaste ${itemName}`, 'log-info', 'player')

    const res = (useItemOnPokemon as any)(itemName, p)
    if (res) {
      audio.heal()
      addLog(`¡${p.name} ${res.message}!`, 'log-info', itemName, 'player')
      consumeItem(itemName)
      return { action: 'heal', pokemon: res.pokemon }
    } else {
      addLog('No tuvo efecto.', 'log-info', p)
      return { action: 'fail' }
    }
  }

  return { action: 'enemy_turn' }
}

/**
 * Módulo de Registro de Combate (Battle Logger)
 * Encargado de procesar y estandarizar los logs de batalla.
 */

import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService';
import { SHOP_ITEMS } from '@/data/items';
import { PLAYER_CLASSES } from '@/data/playerClasses';
import type { Pokemon } from '@/types/pokemon';

interface LogContext {
  gs: {
    state: {
      playerClass: string
      avatar_style?: string
      team: Pokemon[]
    }
  }
  activeBattle?: {
    trainerSprite?: string
    enemy?: Pokemon
  }
  attackerSide?: 'player' | 'enemy'
}

interface FormattedLog {
  id: number
  msg: string
  type: string
  side: string
  icon: string | null
  iconType: string | null
}

/**
 * Procesa un mensaje de log y devuelve el objeto listo para la cola del store.
 * @param {string} msg Mensaje
 * @param {string} type Tipo de log (log-info, log-player, log-enemy, log-error)
 * @param {Object|string} source Fuente del sprite (Pokemon, 'player', 'enemy_trainer', o nombre de ítem)
 * @param {Object} ctx Contexto necesario (gs, activeBattle, attackerSide)
 */
export function formatBattleLog(msg: string, type: string, source: any, ctx: LogContext): FormattedLog {
  const { gs, activeBattle, attackerSide } = ctx;
  let icon: string | null = null;
  let iconType: string | null = null;

  if (!source && !msg.startsWith('DEBUG:')) {
    console.warn(`[BattleLogger] Log sin fuente detectado: "${msg}". Se recomienda pasar un Pokémon o 'player'/'enemy_trainer'.`);
  }

  if (msg.startsWith('DEBUG:')) {
    icon = '😈';
    iconType = 'emoji';
  } else if (source) {
    if (source === 'player') {
      const cls = (PLAYER_CLASSES as any)[gs.state.playerClass];
      const spriteId = cls?.avatarSpriteId || gs.state.avatar_style || 'entrenador';
      icon = getAssetUrl(ASSET_TYPES.TRAINER, spriteId);
      iconType = 'trainer';
    } else if (source === 'enemy_trainer') {
      const spriteId = activeBattle?.trainerSprite || 'entrenador';
      icon = getAssetUrl(ASSET_TYPES.TRAINER, spriteId);
      iconType = 'trainer';
    } else if (typeof source === 'object' && source) {
      const poke = source as Partial<Pokemon>;
      const pokeId = poke.id || poke.id_pokemon;
      if (pokeId) {
        icon = getAssetUrl(ASSET_TYPES.POKEMON, pokeId, { shiny: poke.isShiny });
        iconType = 'pokemon';
      }
    } else if (typeof source === 'string') {
      const sLower = source.toLowerCase();
      const item = SHOP_ITEMS.find((i) => i.name.toLowerCase() === sLower || i.id.toLowerCase() === sLower);
      const spriteId = item ? item.sprite : source;
      icon = getAssetUrl(ASSET_TYPES.ITEM, spriteId);
      iconType = 'item';
    }
  }

  let side = 'enemy';
  if (source === 'player' || (source && typeof source === 'object' && gs.state.team.some((p) => p && p.uid === (source as Pokemon).uid))) {
    side = 'player';
  } else if (source === 'enemy_trainer' || (source && typeof source === 'object' && (source as Pokemon).uid === activeBattle?.enemy?.uid)) {
    side = 'enemy';
  } else if (attackerSide) {
    side = attackerSide;
  }

  return {
    id: Date.now() + Math.random(),
    msg,
    type,
    side,
    icon,
    iconType
  };
}

/**
 * Move Effects logic (Buffs, Debuffs, Weather, Field).
 */

export function applyMoveEffect(effect: any, src: any, tgt: any, srcStages: any, tgtStages: any, addLogFn: any, options: any = {}) {
  const { b } = options;

  switch (effect) {
    case 'atk+1': 
      srcStages.atk = Math.min(6, (srcStages.atk || 0) + 1);
      addLogFn(`¡El Ataque de ${src.name} subió!`, 'log-info', src); break;
    case 'def+1': 
      srcStages.def = Math.min(6, (srcStages.def || 0) + 1);
      addLogFn(`¡La Defensa de ${src.name} subió!`, 'log-info', src); break;
    case 'spa+1': 
      srcStages.spa = Math.min(6, (srcStages.spa || 0) + 1);
      addLogFn(`¡El At. Esp de ${src.name} subió!`, 'log-info', src); break;
    case 'spd+1': 
      srcStages.spd = Math.min(6, (srcStages.spd || 0) + 1);
      addLogFn(`¡La Def. Esp de ${src.name} subió!`, 'log-info', src); break;
    case 'spe+1': 
      srcStages.spe = Math.min(6, (srcStages.spe || 0) + 1);
      addLogFn(`¡La Velocidad de ${src.name} subió!`, 'log-info', src); break;

    case 'atk-1': 
      tgtStages.atk = Math.max(-6, (tgtStages.atk || 0) - 1);
      addLogFn(`¡El Ataque de ${tgt.name} bajó!`, 'log-info', tgt); break;
    case 'def-1': 
      tgtStages.def = Math.max(-6, (tgtStages.def || 0) - 1);
      addLogFn(`¡La Defensa de ${tgt.name} bajó!`, 'log-info', tgt); break;
    case 'spe-1': 
      tgtStages.spe = Math.max(-6, (tgtStages.spe || 0) - 1);
      addLogFn(`¡La Velocidad de ${tgt.name} bajó!`, 'log-info', tgt); break;

    case 'poison':
      if (tgt.status) { addLogFn('¡Pero falló!', 'log-info', src); }
      else if (tgt.type === 'poison' || tgt.type === 'steel' || tgt.type2 === 'poison' || tgt.type2 === 'steel') {
        addLogFn(`¡No afecta a ${tgt.name}!`, 'log-info', tgt);
      } else {
        tgt.status = 'poison'; addLogFn(`¡${tgt.name} fue envenenado!`, 'log-info', tgt);
      }
      break;
    case 'paralyze':
      if (tgt.status) { addLogFn('¡Pero falló!', 'log-info', src); }
      else if (tgt.type === 'electric' || tgt.type2 === 'electric') {
        addLogFn(`¡No afecta a ${tgt.name}!`, 'log-info', tgt);
      } else {
        tgt.status = 'paralyze'; addLogFn(`¡${tgt.name} fue paralizado!`, 'log-info', tgt);
      }
      break;
    case 'burn':
      if (tgt.status) { addLogFn('¡Pero falló!', 'log-info', src); }
      else if (tgt.type === 'fire' || tgt.type2 === 'fire') {
        addLogFn(`¡No afecta a ${tgt.name}!`, 'log-info', tgt);
      } else {
        tgt.status = 'burn'; addLogFn(`¡${tgt.name} fue quemado!`, 'log-info', tgt);
      }
      break;
    case 'sleep':
      if (tgt.status) { addLogFn('¡Pero falló!', 'log-info', src); }
      else {
        tgt.status = 'sleep';
        tgt.sleepTurns = 1 + Math.floor(Math.random() * 3);
        addLogFn(`¡${tgt.name} se quedó dormido!`, 'log-info', tgt);
      }
      break;

    case 'confusion':
      if (tgt.confused) { addLogFn('¡Pero falló!', 'log-info', src); }
      else {
        tgt.confused = 2 + Math.floor(Math.random() * 4);
        addLogFn(`¡${tgt.name} está confundido!`, 'log-info', tgt);
      }
      break;

    case 'sun': 
      if (b) {
        b.weather = { type: 'sun', turns: 5 }; 
        addLogFn("¡El sol empezó a brillar con fuerza!", 'log-info', src);
      }
      break;
    case 'rain': 
      if (b) {
        b.weather = { type: 'rain', turns: 5 }; 
        addLogFn("¡Empezó a llover!", 'log-info', src);
      }
      break;
    case 'hail': 
      if (b) {
        b.weather = { type: 'hail', turns: 5 }; 
        addLogFn("¡Empezó a granizar!", 'log-info', src);
      }
      break;
    case 'sandstorm': 
      if (b) {
        b.weather = { type: 'sandstorm', turns: 5 }; 
        addLogFn("¡Empezó una tormenta de arena!", 'log-info', src);
      }
      break;

    case 'reflect':
      if (srcStages.reflect) { addLogFn("¡Pero falló!", 'log-info', src); }
      else {
        srcStages.reflect = 5;
        addLogFn(`¡Un muro de luz protege a ${src.name} contra ataques físicos!`, 'log-info', src);
      }
      break;
    case 'light_screen':
      if (srcStages.lightScreen) { addLogFn("¡Pero falló!", 'log-info', src); }
      else {
        srcStages.lightScreen = 5;
        addLogFn(`¡Un muro de luz protege a ${src.name} contra ataques especiales!`, 'log-info', src);
      }
      break;
  }
}

/**
 * battleRewards.js
 * Logic for calculating EXP and Money rewards.
 */

export function calculateBaseExp(enemyPoke: any) {
  return Math.floor(enemyPoke.level * 4)
}

export function processExpGain(p: any, baseExp: any, _participants: any, options: any = {}) {
  const { 
    isActive = false, 
    classMult = 1, 
    totalExpMult = 1, 
    participantsSet = null 
  } = options

  if (!participantsSet?.has(p.uid) && p.heldItem !== 'Compartir EXP') return null

  const share = isActive ? 1 : 0.5
  const gained = Math.floor(baseExp * share * classMult * totalExpMult);
  p.exp += gained

  let levelUp = false
  if (p.exp >= p.expNeeded) {
    p.level++
    p.exp -= p.expNeeded
    p.expNeeded = Math.floor(p.expNeeded * 1.2)
    levelUp = true
  }

  return { gained, levelUp }
}

export function calculateMoneyGain(enemyPoke: any, options: any = {}) {
  const { bcMult = 1, totalMoneyMult = 1 } = options
  const baseMoney = enemyPoke.level * 10 * bcMult
  return Math.floor(baseMoney * totalMoneyMult)
}

