export type BattleSubStateName = typeof BATTLE_SUBSTATES[keyof typeof BATTLE_SUBSTATES];

export function createBattleStateMachine() {
  const currentState = ref<BattleStateName>(BATTLE_STATES.EXIT_BATTLE);
  const currentSubState = ref<BattleSubStateName | null>(null);
  let transitionTimeout: any = null;

  // Simple strict transitions check based on the Mermaid diagram.
  const validTransitions: Record<string, string[]> = {
    [BATTLE_STATES.CONTEXT_SETUP]: [BATTLE_STATES.INITIALIZING],
    [BATTLE_STATES.INITIALIZING]: [BATTLE_STATES.FIRST_INTRO, BATTLE_STATES.SEARCH_PHASE],
    [BATTLE_STATES.FIRST_INTRO]: [BATTLE_STATES.ACTIVE_BATTLE, BATTLE_STATES.REORDER_TEAM],
    [BATTLE_STATES.SEARCH_PHASE]: [BATTLE_STATES.ACTIVE_BATTLE, BATTLE_STATES.EXIT_BATTLE, BATTLE_STATES.INITIALIZING, BATTLE_STATES.FIRST_INTRO, BATTLE_STATES.REWARDS_PHASE],
    [BATTLE_STATES.ACTIVE_BATTLE]: [BATTLE_STATES.REWARDS_PHASE, BATTLE_STATES.EXIT_BATTLE, BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.RESOLVE_ENEMY_FAINT, BATTLE_SUBSTATES.RESOLVE_PLAYER_FAINT], 
    [BATTLE_STATES.REWARDS_PHASE]: [BATTLE_STATES.REORDER_TEAM, BATTLE_STATES.SEARCH_PHASE, BATTLE_STATES.INITIALIZING, BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.EMPTY_WAIT, BATTLE_SUBSTATES.DISTRIBUTE_XP],
    [BATTLE_STATES.LEVEL_UP_MODAL]: [BATTLE_STATES.REWARDS_PHASE, BATTLE_STATES.SEARCH_PHASE, BATTLE_STATES.INITIALIZING],
    [BATTLE_STATES.REORDER_TEAM]: [BATTLE_STATES.SEARCH_PHASE, BATTLE_STATES.INITIALIZING, BATTLE_STATES.ACTIVE_BATTLE, BATTLE_STATES.EXIT_BATTLE],
    [BATTLE_SUBSTATES.RESOLVE_ENEMY_FAINT]: [BATTLE_SUBSTATES.ENEMY_DEFEAT],
    [BATTLE_SUBSTATES.RESOLVE_PLAYER_FAINT]: [BATTLE_SUBSTATES.PLAYER_FAINT_SEQ],
    [BATTLE_SUBSTATES.ENEMY_DEFEAT]: [BATTLE_STATES.REWARDS_PHASE],
    [BATTLE_SUBSTATES.PLAYER_FAINT_SEQ]: [BATTLE_STATES.ACTIVE_BATTLE, BATTLE_STATES.EXIT_BATTLE],
    [BATTLE_SUBSTATES.ESCAPE_PROCESS]: [BATTLE_STATES.REWARDS_PHASE, BATTLE_STATES.EXIT_BATTLE],
    [BATTLE_STATES.EXIT_BATTLE]: [BATTLE_STATES.CONTEXT_SETUP, BATTLE_STATES.INITIALIZING]
  };

  /**
   * Translates to a specific state or substate.
   * If a delay is provided, returns a Promise that resolves when the transition happens.
   */
  const transition = (newState: BattleStateName | BattleSubStateName, newSubState: BattleSubStateName | null = null, delayMs: number = 0) => {
    return new Promise((resolve) => {
      if (transitionTimeout) {
        clearTimeout(transitionTimeout);
        transitionTimeout = null;
      }

      const executeTransition = () => {
        // Validation check (can be expanded for strict enforcement)
        if (newState && Object.values(BATTLE_STATES).includes(newState as any)) {
          const isSameState = currentState.value === newState;
          const allowedTransitions = validTransitions[currentState.value];
          if (!isSameState && allowedTransitions && !allowedTransitions.includes(newState) && newState !== BATTLE_STATES.EXIT_BATTLE) {
            console.warn(`[FSM] Unexpected transition: ${currentState.value} -> ${newState}`);
          }
          currentState.value = newState as BattleStateName;
        } else if (newState && Object.values(BATTLE_SUBSTATES).includes(newState as any)) {
          // Si recibimos un sub-estado como primer argumento, mantenemos el estado actual 
          newSubState = newState as BattleSubStateName;
        }

        if (newSubState) {
          currentSubState.value = newSubState;
        } else if (newState && currentState.value !== BATTLE_STATES.ACTIVE_BATTLE) {
          currentSubState.value = null; // Solo limpiamos substate si estamos cambiando de fase principal
        }

        console.log(`[Battle FSM] Transitioned to ${currentState.value}${currentSubState.value ? ' (' + currentSubState.value + ')' : ''}`);
        resolve(undefined);
      };

      if (delayMs > 0) {
        transitionTimeout = setTimeout(executeTransition, delayMs);
      } else {
        executeTransition();
      }
    });
  };

  const isState = (state: string) => currentState.value === state;
  const isSubState = (subState: string | null) => currentSubState.value === subState;

  return {
    currentState,
    currentSubState,
    transition,
    isState,
    isSubState
  };
}

/**
 * Módulo de gestión de Estados Alterados y Efectos de Turno
 * Portado de js/07_battle.js para cumplir con el estándar modular v6.
 */

import { gameBus } from '@/logic/gameBus'

export function getStatusIcon(status: any) {
  if (!status) return '';
  const icons: any = {
    burn: '🔥',
    poison: '☠️',
    paralyze: '⚡',
    sleep: '💤',
    freeze: '🧊'
  };
  return icons[status] || '';
}

/**
 * Procesa los efectos permanentes y temporales al final del turno.
 * @returns {boolean} True si el Pokémon sigue en combate, False si se debilitó (aunque las funciones de daño usualmente no despachan muerte aquí)
 */
export function tickStatus(pokemon: any, addLogFn: any, role = 'info') {
  if (!pokemon) return false;
  // 1. Efectos de control temporal
  if (pokemon.disabledTurns > 0) {
    pokemon.disabledTurns--;
    if (pokemon.disabledTurns <= 0) {
      addLogFn(`¡${pokemon.name} ya puede usar ${pokemon.disabledMove || 'su movimiento'} de nuevo!`, 'log-info', pokemon);
      pokemon.disabledMove = null;
    }
  }

  if (pokemon.encoreTurns > 0) {
    pokemon.encoreTurns--;
    if (pokemon.encoreTurns <= 0) {
      addLogFn(`¡${pokemon.name} ya no está bajo el efecto de Otra Vez!`, 'log-info', pokemon);
      pokemon.encoreMove = null;
    }
  }

  if (pokemon.tauntTurns > 0) {
    pokemon.tauntTurns--;
    if (pokemon.tauntTurns <= 0) {
      addLogFn(`¡La mofa sobre ${pokemon.name} ha terminado!`, 'log-info', pokemon);
    }
  }

  if (pokemon.thrashTurns > 0) {
    pokemon.thrashTurns--;
    if (pokemon.thrashTurns <= 0) {
      addLogFn(`¡${pokemon.name} se calmó, pero terminó confundido!`, 'log-info', pokemon);
      pokemon.confused = 2 + Math.floor(Math.random() * 3);
    }
  }

  // 2. Estados alterados persistentes (Daño)
  if (!pokemon.status) return false;

  const logCls = role === 'player' ? 'log-enemy' : role === 'enemy' ? 'log-player' : 'log-info';

  switch (pokemon.status) {
    case 'burn': {
      const dmg = Math.max(1, Math.floor(pokemon.maxHp / 8));
      pokemon.hp = Math.max(0, pokemon.hp - dmg);
      addLogFn(`¡${pokemon.name} sufre quemaduras! (-${dmg} HP)`, logCls, pokemon);
      gameBus.emit('PLAY_SOUND', 'statusDamage');
      return true;
    }
    case 'poison': {
      let dmg = Math.max(1, Math.floor(pokemon.maxHp / 8));
      if (pokemon.badPoison) {
        dmg = Math.max(1, Math.floor((pokemon.maxHp * pokemon.badPoison) / 16));
        pokemon.badPoison++;
      }
      pokemon.hp = Math.max(0, pokemon.hp - dmg);
      addLogFn(`¡${pokemon.name} sufre el veneno! (-${dmg} HP)`, logCls, pokemon);
      gameBus.emit('PLAY_SOUND', 'statusDamage');
      return true;
    }
  }

  // 3. Daño por atadura
  if (pokemon.bound > 0) {
    pokemon.bound--;
    if (pokemon.bound <= 0) {
      addLogFn(`¡${pokemon.name} se libró de la atadura!`, 'log-info', pokemon);
    } else {
      const dmg = Math.max(1, Math.floor(pokemon.maxHp / 16));
      pokemon.hp = Math.max(0, pokemon.hp - dmg);
      addLogFn(`¡${pokemon.name} sufre por la atadura! (-${dmg} HP)`, 'log-info', pokemon);
      gameBus.emit('PLAY_SOUND', 'statusDamage');
    }
  }

  // 4. Arraigo (Ingrain)
  if (pokemon.ingrain && pokemon.hp > 0 && pokemon.hp < pokemon.maxHp) {
    const heal = Math.max(1, Math.floor(pokemon.maxHp / 16));
    pokemon.hp = Math.min(pokemon.maxHp, pokemon.hp + heal);
    addLogFn(`¡${pokemon.name} recuperó salud por sus raíces!`, 'log-info', pokemon);
    gameBus.emit('PLAY_SOUND', 'heal');
  }

  // 5. Canto Mortal (Perish Song)
  if (pokemon.perishSongCount > 0) {
    pokemon.perishSongCount--;
    addLogFn(`¡La cuenta de Canto Mortal de ${pokemon.name} bajó a ${pokemon.perishSongCount}!`, 'log-info', pokemon);
    if (pokemon.perishSongCount === 0) {
      pokemon.hp = 0;
      addLogFn(`¡El destino de ${pokemon.name} se cumplió!`, 'log-info', pokemon);
    }
  }

  // 6. Maldición (Ghost Curse)
  if (pokemon.cursed && pokemon.hp > 0) {
    const dmg = Math.max(1, Math.floor(pokemon.maxHp / 4));
    pokemon.hp = Math.max(0, pokemon.hp - dmg);
    addLogFn(`¡${pokemon.name} sufre por la maldición! (-${dmg} HP)`, 'log-info', pokemon);
    gameBus.emit('PLAY_SOUND', 'statusDamage');
  }

  return false;
}

/**
 * Procesa efectos de campo como Drenadoras.
 */
export function tickLeechSeed(pokemon: any, opponent: any, addLogFn: any) {
  if (!pokemon || !pokemon.seeded || pokemon.hp <= 0) return false;

  const dmg = Math.max(1, Math.floor(pokemon.maxHp / 8));
  pokemon.hp = Math.max(0, pokemon.hp - dmg);
  addLogFn(`¡Drenadoras resta salud a ${pokemon.name}! (-${dmg} HP)`, 'log-enemy', pokemon);
  gameBus.emit('PLAY_SOUND', 'statusDamage');

  if (opponent && opponent.hp > 0) {
    const heal = dmg;
    opponent.hp = Math.min(opponent.maxHp, opponent.hp + heal);
    addLogFn(`¡${opponent.name} recuperó salud!`, 'log-info', opponent);
    gameBus.emit('PLAY_SOUND', 'heal');
  }

  return true;
}

/**
 * Limpia todos los estados temporales/volátiles de un Pokémon al salir o entrar en combate.
 */
export function clearVolatileStatus(poke: any) {
  if (!poke) return;
  poke.confused = 0
  poke.flinched = false
  poke.substitute = 0
  poke.seeded = false
  poke.attracted = false
  poke.cursed = false
  poke.protect = false
  poke.detect = false
  poke.destinyBond = false
  poke.perishSongCount = 0
  poke.tauntTurns = 0
  poke.disabledTurns = 0
  poke.disabledMove = null
  poke.encoreTurns = 0
  poke.encoreMove = null
  poke.focusEnergy = false
  poke.lockOn = false
  poke.ingrain = false
  poke.futureSightTurns = 0
  poke.futureSightDmg = 0
  poke.badPoison = 0
}

// [PureVue-Ignore-Length]
import { calculateDamage, getEffectiveSpeed } from './battleEngine'
import { canAttack } from './battleFlow'
import { dispatchMoveEffect } from './actions/actionRegistry'
import { decideEnemyMove, shouldEnemySwitch, findBestSwitchIndex } from './ai/battleAI'
import { gameBus } from '@/logic/gameBus'
import { recalcPokemonStats } from '@/logic/pokemonFactory'
import { getMechanicalWeather, WEATHER_MECHANICAL } from './weatherMapper'
import { getDayCycle } from '@/logic/timeUtils'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { MOVE_DATA } from '@/data/moves'
import type { BattleContext } from '@/types/battleContext'
// import type { Pokemon, Move } from '@/types/pokemon'

/**
 * Handles the turn logic for a single move execution.
 */
export async function executeTurn(store: BattleContext, moveIndex: number) {
  const p = store.activeBattle.value?.player
  const e = store.activeBattle.value?.enemy

  if (!p || !e) {
    console.warn('[BattleTurn] Aborting turn: Player or Enemy is null', { p, e })
    return
  }

  const fsm = store.fsm
  const { BATTLE_STATES, BATTLE_SUBSTATES } = store

  // Thrash check
  if (p.thrashTurns && p.thrashTurns > 0) {
    const forcedIdx = p.moves.findIndex((m) => m?.effect === 'thrash');
    if (forcedIdx !== -1) moveIndex = forcedIdx;
  } else if (p.encoreTurns && p.encoreTurns > 0 && p.encoreMove) {
    const forcedIdx = p.moves.findIndex((m) => m?.id === p.encoreMove?.id);
    if (forcedIdx !== -1) moveIndex = forcedIdx;
  }

  const move = p.moves[moveIndex]
  if (!move || move.pp <= 0) {
    store.addLog(`¡No queda PP para ${move?.name || 'este movimiento'}!`, 'log-info', p)
    return
  }

  fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.BUILD_QUEUE)

  // Determine Turn Order (Consider Priority)
  const isWild = !store.activeBattle.value?.isTrainer && !store.activeBattle.value?.isGym
  const eMove = decideEnemyMove(e, p, store.enemyStages.value, isWild)

  const pPrio = move.priority || 0
  const ePrio = eMove?.priority || 0

  const pSpe = getEffectiveSpeed(p, store.playerStages.value, { weather: store.activeBattle.value?.weather })
  const eSpe = getEffectiveSpeed(e, store.enemyStages.value, { weather: store.activeBattle.value?.weather })

  let playerFirst = true
  if (pPrio > ePrio) playerFirst = true
  else if (ePrio > pPrio) playerFirst = false
  else playerFirst = pSpe >= eSpe

  const queue: { source: 'player' | 'enemy'; action: () => Promise<void> }[] = []
  if (playerFirst) {
    queue.push({ source: 'player', action: () => runPlayerAction(store, moveIndex) })
    if (eMove) queue.push({ source: 'enemy', action: () => runEnemyAction(store) })
  } else {
    if (eMove) queue.push({ source: 'enemy', action: () => runEnemyAction(store) })
    queue.push({ source: 'player', action: () => runPlayerAction(store, moveIndex) })
  }

  fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.BUILD_QUEUE)

  while (queue.length > 0) {
    fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POP_ACTION)
    const currentAction = queue.shift()
    if (!currentAction) break

    fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.APPLY_MOVE)
    await currentAction.action()

    fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.EVAL_HP)

    if (store.activeBattle.value?.player && store.activeBattle.value.player.hp <= 0) {
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.RESOLVE_PLAYER_FAINT)
      await store.handleFaint('player')
      break;
    }

    if (store.activeBattle.value?.enemy && store.activeBattle.value.enemy.hp <= 0) {
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.RESOLVE_ENEMY_FAINT)
      await store.handleFaint('enemy')
      break;
    }

    if (store.activeBattle.value?.over) break;

    if (queue.length > 0) {
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.EVAL_CONTINUE)
      await new Promise(r => setTimeout(r, 400))
    }
  }

  if (store.activeBattle.value?.over) {
    return
  }

  if (store.persistBattle) store.persistBattle()
}

export async function runPlayerAction(store: BattleContext, moveIndex: number) {
  const p = store.activeBattle.value?.player
  const e = store.activeBattle.value?.enemy
  if (!p || !e) return

  const move = p.moves[moveIndex]
  if (!move) return

  if (p.tauntTurns && p.tauntTurns > 0 && move.cat === 'status') {
    store.addLog(`¡La mofa impide a ${p.name} usar ${move.name}!`, 'log-info', p)
    return
  }
  if (p.disabledMove && move.id === p.disabledMove.id) {
    store.addLog(`¡${move.name} está desactivado!`, 'log-info', p)
    return
  }

  if (!canAttack(p, store.addLog)) return

  if (p.furyCutterCount && move.effect !== 'fury_cutter') p.furyCutterCount = 0;
  p.destinyBond = false;
  p.snatching = false;
  p.lastMove = move;
  store.attackerSide.value = 'player'

  move.pp--
  store.addLog(`¡${p.name} usó ${move.name}!`, 'log-player', p)

  let executableMove: any = { ...move };
  if (move.effect === 'metronome') {
    const moveNames = Object.keys(MOVE_DATA).filter(n => n !== 'Metrónomo');
    const randomName = moveNames[Math.floor(Math.random() * moveNames.length)] || 'Combate';
    executableMove = { ...((MOVE_DATA as any)[randomName] || {}), name: randomName, id: randomName.toLowerCase().replace(/\s/g, '_') };
    store.addLog(`¡El Metrónomo escogió ${randomName}!`, 'log-info', p);
  } else if (move.effect === 'mirror_move') {
    if (e.lastMove) {
      executableMove = { ...e.lastMove };
      store.addLog(`¡Espejo copió ${executableMove.name}!`, 'log-info', p);
    } else {
      store.addLog("¡Pero falló!", 'log-info', p);
      return;
    }
  }

  const normalizeCat = (c: any): 'status' | 'special' | 'physical' => {
    if (c === 'Estado' || c === 'status' || c === 3) return 'status'
    if (c === 'Especial' || c === 'special' || c === 2) return 'special'
    return 'physical'
  }

  store.activeMove.value = { ...executableMove, side: 'player' }
  gameBus.emit('PLAY_ATTACK_ANIM', { side: 'player', cat: normalizeCat(executableMove.cat) })

  // Sanity check
  if (!p.atk || !p.maxHp || executableMove.power === undefined) recalcPokemonStats(p)
  if (!e.atk || !e.maxHp) recalcPokemonStats(e)

  if (!p.level) p.level = 5

  if (!p.atk || !e.def || (executableMove.power === undefined && executableMove.cat !== 'status')) {
    store.addLog(`[Error] Datos faltantes: Atk:${p.atk} Def:${e.def} Pwr:${executableMove.power}`, 'log-error', p)
  }
  if (store.activeBattle.value && !store.activeBattle.value.participants.includes(p.uid)) {
    store.activeBattle.value.participants.push(p.uid)
  }

  // Precision Check
  const moveAcc = executableMove.acc || 100;
  if (moveAcc < 100 && !p.lockOn) {
    const accStage = store.playerStages.value.acc || 0;
    const evaStage = store.enemyStages.value.eva || 0;
    const weather = store.activeBattle.value?.weather?.type;
    const mechWeather = getMechanicalWeather(weather);
    const cycle = getDayCycle();
    const isSunActive = mechWeather === WEATHER_MECHANICAL.SUN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'day' || cycle === 'morning'))
    const isRainActive = mechWeather === WEATHER_MECHANICAL.RAIN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'night' || cycle === 'dusk'))
    let finalAcc = moveAcc;

    if (isRainActive && (executableMove.id === 'thunder' || executableMove.id === 'hurricane')) finalAcc = 100;
    else if (isSunActive && (executableMove.id === 'thunder' || executableMove.id === 'hurricane')) finalAcc = 50;
    else if ((mechWeather === WEATHER_MECHANICAL.HAIL || mechWeather === WEATHER_MECHANICAL.SNOW) && executableMove.id === 'blizzard') finalAcc = 100;
    else if (mechWeather === WEATHER_MECHANICAL.FOG) finalAcc = Math.floor(moveAcc * 0.6);

    finalAcc = finalAcc * (1 + (0.33 * accStage)) * (1 - (0.33 * evaStage));
    if (Math.random() * 100 > finalAcc) {
      store.addLog(`¡El ataque de ${p.name} falló!`, 'log-info', p);
      return;
    }
  }
  if (p.lockOn) p.lockOn = false;

  if (executableMove && (executableMove.effect === undefined || executableMove.effect === null)) {
    const freshMoveData = pokemonDataProvider.getMoveData(executableMove.name);
    if (freshMoveData && freshMoveData.effect) {
      executableMove.effect = freshMoveData.effect;
    }
  }

  let totalHits = 1;
  if (executableMove.hits) {
    if (typeof executableMove.hits === 'number') totalHits = executableMove.hits;
    else if (executableMove.hits === '2-5') {
      const rolls = [2, 2, 2, 3, 3, 3, 4, 5];
      totalHits = (rolls[Math.floor(Math.random() * rolls.length)] as number);
    }
  }

  let hitsDealt = 0;
  let totalDamageDealt = 0;

  try {
    for (let i = 0; i < totalHits; i++) {
      if (e.hp <= 0) break;

      const result = calculateDamage(p, e, executableMove, { 
        atkStages: store.playerStages.value.atk, 
        defStages: store.enemyStages.value.def,
        weather: store.activeBattle.value?.weather
      })

      if (result.isNoEffect) {
        store.addLog('¡No afecta!', 'log-enemy', e)
        break;
      } else {
        const damage = Math.floor(result.dmg || 0)

        if (executableMove.cat !== 'status') {
          if (totalHits === 1) store.addLog(`¡${e.name} recibió ${damage} de daño!`, 'log-info', e)
          totalDamageDealt += damage;
        }

        if (result.isNotVeryEffective && i === 0) store.addLog('No es muy eficaz...', 'log-player', p)
        if (result.isSuperEffective && i === 0) store.addLog('¡Es muy eficaz!', 'log-player', p)

        if (executableMove.effect === 'magnitude' && result.power) {
          const magMap: Record<number, number> = { 10: 4, 30: 5, 50: 6, 70: 7, 90: 8, 110: 9, 150: 10 };
          const mag = magMap[result.power] || 7;
          store.addLog(`¡Magnitud ${mag}!`, 'log-info', e);
        }

        e.hp = Math.max(0, e.hp - damage)
        gameBus.emit('PLAY_DAMAGE', { side: 'enemy', damage })
        if (store.activeBattle.value) store.activeBattle.value.lastDamage = damage
        hitsDealt++;

        if (e.hp <= 0) break;

        if (e.rageActive && damage > 0 && e.hp > 0) {
          store.enemyStages.value.atk = Math.min(6, (store.enemyStages.value.atk || 0) + 1);
          store.addLog(`¡La furia de ${e.name} está creciendo!`, 'log-info', e);
        }

        if (executableMove.cat !== 'status') {
          await new Promise(r => setTimeout(r, 200))
        }
      }
    }

    if (totalHits > 1 && hitsDealt > 0) {
      store.addLog(`¡Golpeó ${hitsDealt} veces!`, 'log-info', e);
    }

    if (totalDamageDealt > 0) {
      if (executableMove.recoil) {
        const recoilDiv = typeof executableMove.recoil === 'number' ? executableMove.recoil : 2;
        const recoilDmg = Math.floor(totalDamageDealt / recoilDiv);
        if (recoilDmg > 0) {
          p.hp = Math.max(0, p.hp - recoilDmg);
          store.addLog(`¡${p.name} recibió daño por retroceso!`, 'log-info', p);
        }
      }
      if (executableMove.drain) {
        const heal = Math.floor(totalDamageDealt / 2);
        if (heal > 0) {
          p.hp = Math.min(p.maxHp, p.hp + heal);
          store.addLog(`¡${p.name} absorbió energía!`, 'log-info', p);
        }
      }
    }

    if (executableMove.selfKO) {
      p.hp = 0;
      store.addLog(`¡${p.name} se sacrificó!`, 'log-info', p);
    }

    store.attackerSide.value = null

    if (executableMove.effect && hitsDealt > 0 && store.activeBattle.value) {
      dispatchMoveEffect(executableMove.effect, p, e, store.playerStages.value, store.enemyStages.value, store.addLog, store.activeBattle.value)
    }

  } catch (err) {
    console.error('[Battle] Error in runPlayerAction:', err)
    store.addLog('¡Error en el turno del jugador!', 'log-error', p)
  }
}

export async function runEnemyAction(store: BattleContext) {
  const p = store.activeBattle.value?.player
  const e = store.activeBattle.value?.enemy
  if (!p || !e || e.hp <= 0) return
  const fsm = store.fsm
  const { BATTLE_STATES, BATTLE_SUBSTATES } = store

  if (!canAttack(e, store.addLog)) return

  const isWild = !store.activeBattle.value?.isTrainer && !store.activeBattle.value?.isGym

  if (!isWild && store.activeBattle.value && shouldEnemySwitch(e, p, store.activeBattle.value.enemyTeam)) {
    const bestIdx = findBestSwitchIndex(store.activeBattle.value.enemyTeam, p, e.uid)
    if (store.activeBattle.value.enemyTeam && bestIdx !== -1) {
      const newPoke = store.activeBattle.value.enemyTeam[bestIdx]
      if (!newPoke) return
      store.addLog(`¡${store.activeBattle.value.trainerName || 'El entrenador'} retira a ${e.name}!`, 'log-enemy', 'enemy_trainer')

      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.TRAINER_RETREAT)
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_RECALL)
      gameBus.emit('PLAY_WITHDRAW', { side: 'enemy' })
      await new Promise(r => setTimeout(r, 800))
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT)

      store.activeBattle.value.enemy = newPoke

      store.enemyStages.value.atk = 0; store.enemyStages.value.def = 0; store.enemyStages.value.spa = 0; store.enemyStages.value.spd = 0; store.enemyStages.value.spe = 0; store.enemyStages.value.acc = 0; store.enemyStages.value.eva = 0;

      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_CALL)
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.OCCUPY_SEAT)
      store.addLog(`¡Envía a ${newPoke.name}!`, 'log-enemy', newPoke)
      gameBus.emit('PLAY_SEND_OUT', { side: 'enemy', pokemon: newPoke })
      await new Promise(r => setTimeout(r, 800))

      if (store.enemyStages.value.spikes && store.enemyStages.value.spikes > 0 && newPoke.type !== 'flying' && newPoke.type2 !== 'flying' && newPoke.ability !== 'Levitación') {
        const dmg = Math.floor(newPoke.maxHp * (store.enemyStages.value.spikes / 8))
        newPoke.hp = Math.max(0, newPoke.hp - dmg)
        store.addLog(`¡${newPoke.name} recibió daño por las púas!`, 'log-info', newPoke)
        gameBus.emit('PLAY_SOUND', 'statusDamage')
      }
      return
    }
  }

  if ((store.activeBattle.value?.isGym) && e.hp < (e.maxHp * 0.25) && !store.activeBattle.value.enemyUsedItem) {
    store.activeBattle.value.enemyUsedItem = true
    const heal = Math.floor(e.maxHp * 0.5)
    e.hp = Math.min(e.maxHp, e.hp + heal)
    store.addLog(`¡El Líder usó una Hiper Poción!`, 'log-enemy', 'enemy_trainer')
    store.addLog(`¡${e.name} recuperó salud!`, 'log-info', e, 'enemy')
    return
  }

  const enemyMove = decideEnemyMove(e, p, store.playerStages.value, isWild)
  if (!enemyMove) {
    store.addLog(`¡${e.name} no tiene más PP y usa Forcejeo!`, 'log-enemy', e)
    return
  }

  if (!e.atk || !e.maxHp || enemyMove.power === undefined) recalcPokemonStats(e)
  if (!p.atk || !p.maxHp) recalcPokemonStats(p)
  if (!e.level) e.level = 5

  if (e.furyCutterCount && enemyMove.effect !== 'fury_cutter') e.furyCutterCount = 0;
  e.destinyBond = false;
  e.snatching = false;
  e.lastMove = enemyMove
  store.attackerSide.value = 'enemy'
  store.addLog(`¡${e.name} usó ${enemyMove.name}!`, 'log-enemy', e)

  let executableMove: any = { ...enemyMove };
  if (enemyMove.effect === 'metronome') {
    const moveNames = Object.keys(MOVE_DATA).filter(n => n !== 'Metrónomo');
    const randomName = moveNames[Math.floor(Math.random() * moveNames.length)] || 'Combate';
    executableMove = { ...((MOVE_DATA as any)[randomName] || {}), name: randomName, id: randomName.toLowerCase().replace(/\s/g, '_') };
    store.addLog(`¡El Metrónomo escogió ${randomName}!`, 'log-info', e);
  } else if (enemyMove.effect === 'mirror_move') {
    if (p.lastMove) {
      executableMove = { ...p.lastMove };
      store.addLog(`¡Espejo copió ${executableMove.name}!`, 'log-info', e);
    } else {
      store.addLog("¡Pero falló!", 'log-info', e);
      return;
    }
  }

  const normalizeCat = (c: any): 'status' | 'special' | 'physical' => {
    if (c === 'Estado' || c === 'status' || c === 3) return 'status'
    if (c === 'Especial' || c === 'special' || c === 2) return 'special'
    return 'physical'
  }

  store.activeMove.value = { ...executableMove, side: 'enemy' }
  gameBus.emit('PLAY_ATTACK_ANIM', { side: 'enemy', cat: normalizeCat(executableMove.cat) })

  // Precision Check
  const moveAcc = executableMove.acc || 100;
  if (moveAcc < 100 && !e.lockOn) {
    const accStage = store.enemyStages.value.acc || 0;
    const evaStage = store.playerStages.value.eva || 0;
    const weather = store.activeBattle.value?.weather?.type;
    const mechWeather = getMechanicalWeather(weather);
    const cycle = getDayCycle();
    const isRaining = mechWeather === WEATHER_MECHANICAL.RAIN
    const isSunny = mechWeather === WEATHER_MECHANICAL.SUN
    const isDayTime = cycle === 'day' || cycle === 'morning'

    const isSunActive = isSunny || (mechWeather === WEATHER_MECHANICAL.CLEAR && isDayTime)

    let finalAcc = moveAcc;

    if (isRaining && (executableMove.id === 'thunder' || executableMove.id === 'hurricane')) finalAcc = 100;
    else if (isSunActive && (executableMove.id === 'thunder' || executableMove.id === 'hurricane')) finalAcc = 50;
    else if ((mechWeather === WEATHER_MECHANICAL.HAIL || mechWeather === WEATHER_MECHANICAL.SNOW) && executableMove.id === 'blizzard') finalAcc = 100;
    else if (mechWeather === WEATHER_MECHANICAL.FOG) finalAcc = Math.floor(moveAcc * 0.6);

    finalAcc = finalAcc * (1 + (0.33 * accStage)) * (1 - (0.33 * evaStage));
    if (Math.random() * 100 > finalAcc) {
      store.addLog(`¡El ataque de ${e.name} falló!`, 'log-info', e);
      return;
    }
  }
  if (e.lockOn) e.lockOn = false;

  let totalHits = 1;
  if (executableMove.hits) {
    if (typeof executableMove.hits === 'number') totalHits = executableMove.hits;
    else if (executableMove.hits === '2-5') {
      const rolls = [2, 2, 2, 3, 3, 3, 4, 5];
      totalHits = (rolls[Math.floor(Math.random() * rolls.length)] as number);
    }
  }

  let hitsDealt = 0;
  let totalDamageDealt = 0;

  try {
    for (let i = 0; i < totalHits; i++) {
      if (p.hp <= 0) break;

      const eResult = calculateDamage(e, p, executableMove, {
        atkStages: store.enemyStages.value.atk,
        defStages: store.playerStages.value.def,
        weather: store.activeBattle.value?.weather
      })

      if (eResult.isNoEffect) {
        store.addLog('¡No afecta!', 'log-player', p)
        break;
      } else {
        const damage = Math.floor(eResult.dmg || 0)

        if (enemyMove.cat !== 'status') {
          if (totalHits === 1) store.addLog(`¡${p.name} recibió ${damage} de daño!`, 'log-info', p)
          totalDamageDealt += damage;
        }

        if (eResult.isCrit && i === 0) store.addLog('¡Un golpe crítico!', 'log-enemy', e)
        if (eResult.isSuperEffective && i === 0) store.addLog('¡Es muy eficaz!', 'log-enemy', e)
        if (eResult.isNotVeryEffective && i === 0) store.addLog('No es muy eficaz...', 'log-enemy', e)

        if (enemyMove.effect === 'magnitude' && eResult.power) {
          const magMap: Record<number, number> = { 10: 4, 30: 5, 50: 6, 70: 7, 90: 8, 110: 9, 150: 10 };
          const mag = magMap[eResult.power] || 7;
          store.addLog(`¡Magnitud ${mag}!`, 'log-info', p);
        }

        p.hp = Math.max(0, p.hp - damage)
        gameBus.emit('PLAY_DAMAGE', { side: 'player', damage })
        if (store.activeBattle.value) store.activeBattle.value.lastDamage = damage
        hitsDealt++;

        if (p.hp <= 0) break;

        if (p.rageActive && damage > 0 && p.hp > 0) {
          store.playerStages.value.atk = Math.min(6, (store.playerStages.value.atk || 0) + 1);
          store.addLog(`¡La furia de ${p.name} está creciendo!`, 'log-info', p);
        }

        if (enemyMove.cat !== 'status') {
          await new Promise(r => setTimeout(r, 200))
        }
      }
    }

    if (totalHits > 1 && hitsDealt > 0) {
      store.addLog(`¡Golpeó ${hitsDealt} veces!`, 'log-info', p);
    }

    if (totalDamageDealt > 0) {
      if (executableMove.recoil) {
        const recoilDiv = typeof executableMove.recoil === 'number' ? executableMove.recoil : 2;
        const recoilDmg = Math.floor(totalDamageDealt / recoilDiv);
        if (recoilDmg > 0) {
          e.hp = Math.max(0, e.hp - recoilDmg);
          store.addLog(`¡${e.name} recibió daño por retroceso!`, 'log-info', e);
        }
      }
      if (executableMove.drain) {
        const heal = Math.floor(totalDamageDealt / 2);
        if (heal > 0) {
          e.hp = Math.min(e.maxHp, e.hp + heal);
          store.addLog(`¡${e.name} absorbió energía!`, 'log-info', e);
        }
      }
    }

    if (executableMove.selfKO) {
      e.hp = 0;
      store.addLog(`¡${e.name} se sacrificó!`, 'log-info', e);
    }

    store.attackerSide.value = null

    if (executableMove.effect && hitsDealt > 0 && store.activeBattle.value) {
      dispatchMoveEffect(executableMove.effect, e, p, store.enemyStages.value, store.playerStages.value, store.addLog, store.activeBattle.value)
    }
  } catch (err) {
    console.error('[Battle] Error in runEnemyAction:', err)
    store.addLog('¡Error en el turno del oponente!', 'log-error', e)
  }
}

import { generateEncounter } from '@/logic/encounters'
import { handleEntryAbilities } from './battleFlow'
import { getMechanicalWeather } from './weatherMapper'
import { FIRE_RED_MAPS } from '@/data/maps'
import { useUIStore } from '@/stores/ui'
import { useMapStore } from '@/stores/map'
import { useEventStore } from '@/stores/events'
import type { BattleContext } from '@/types/battleContext'
import type { Pokemon } from '@/types/pokemon'
import type { UIStore, MapStore, EventStore } from '@/types/stores'

/**
 * Orchestrates the start of a battle.
 * @param {BattleContext} ctx - The battle store context (refs, state, etc)
 */
export async function startBattleSequence(ctx: BattleContext, enemyPoke: Pokemon, options: any = {}) {
  const { 
    isGym = false, gymId = null, locationId = 'plains', 
    isTrainer = false, enemyTeam = null, trainerName = 'Entrenador',
    battleOptions = {}, isFishing = false, wasSearching: wasSearchingOpt = null
  } = options

  const playerPoke = ctx.gs.state.team.find((p) => p.hp > 0 && !p.onMission && !p.onDefense)
  if (!playerPoke) {
    (useUIStore() as unknown as UIStore).notify('No tienes Pokémon sanos para combatir', '❌')
    return
  }

  // Si hay un combate activo pero NO está en fase de finalización, forzamos huida.
  if (ctx.isBattleActive.value && !ctx.isFinishing.value && !ctx.activeBattle.value?.over && !ctx.isSearching.value) {
    console.warn('[BATTLE] Combate en curso detectado. Forzando huida del anterior.')
    await ctx.endBattle(false, true)
  }

  const wasSearching = wasSearchingOpt !== null ? wasSearchingOpt : true

  const { sanitizePokemon } = await import('@/logic/pokemonFactory')
  const mapStore = useMapStore() as unknown as MapStore

  const isFromUpcoming = wasSearching && ctx.upcomingPokemon.value && (ctx.upcomingPokemon.value.id === enemyPoke.id)
  const finalEnemyPoke = isFromUpcoming ? ctx.upcomingPokemon.value as Pokemon : enemyPoke

  sanitizePokemon(playerPoke)
  sanitizePokemon(finalEnemyPoke)

  // LIMPIEZA DE ESTADOS VOLÁTILES
  ctx.clearVolatileStatus(playerPoke)
  ctx.clearVolatileStatus(finalEnemyPoke)

  // Initial context values
  let rarity = 50

  ctx.activeBattle.value = {
    enemy: null, 
    player: null, 
    _initialEnemy: finalEnemyPoke,
    _initialPlayer: playerPoke,
    isGym, gymId, isTrainer, enemyTeam,
    playerTeam: ctx.gs.state.team,
    trainerName, locationId, turn: 'player', turnCount: 1, over: false,
    isFishing, rarity,
    weather: { 
      type: getMechanicalWeather(mapStore.currentWeather), 
      visual: mapStore.currentWeather, 
      turns: -1 
    },
    playerTeamIndex: ctx.gs.state.team.indexOf(playerPoke),
    participants: [playerPoke.uid], learnQueue: [], ...battleOptions
  }

  if (battleOptions.isDebug) {
    ctx.debugLoopPokemon.value = JSON.parse(JSON.stringify(enemyPoke))
    if (!wasSearching) ctx.debugLoopPokemon.value = null
  }

  ctx.gs.registerPokedex(enemyPoke.id)
  if (isTrainer && enemyTeam) enemyTeam.forEach((p: any) => ctx.gs.registerPokedex(p.id))
  ctx.persistBattle()

  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  ctx.isIntroAnimating.value = true

  // PROTOCOLO DE ASIENTOS
  if (ctx.activeBattle.value) {
    ctx.activeBattle.value.enemy = null 

    const currentP = ctx.activeBattle.value.player
    const team = (ctx.gs.state.team as any[]) || []
    const leaderP = team[0]
    if (!currentP || !leaderP || currentP.uid !== (leaderP?.uid)) {
      ctx.activeBattle.value.player = null
    }
  }

  ctx.clearLogs()

  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.RECEIVE_CONFIG)
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.APPLY_ITEM_MODIFIERS)

  // Weight Calculation
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.WEIGHT_CALCULATION)
  if (isFishing) {
    const loc = FIRE_RED_MAPS.find(l => l.id === locationId)
    if (loc && loc.fishing) {
      const pool = loc.fishing.pool
      const rates = loc.fishing.rates
      const idx = pool.indexOf(finalEnemyPoke.id)
      if (idx !== -1) {
        const totalRate = rates.reduce((a, b) => a + b, 0)
        const rateVal = rates[idx]
        rarity = ((rateVal !== undefined ? rateVal : 0) / totalRate) * 100
      }
    }
  }
  if (ctx.activeBattle.value) ctx.activeBattle.value.rarity = rarity

  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.INJECT_FILTERS)
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.READY_FOR_GEN)
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.VACATE_ALL_SEATS)

  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.CHECK_CONTEXT)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.ASYNC_THREAD)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.GEN_TEAMS)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.MARK_EVENT)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.PRELOAD_FINAL_COORDS, 50)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.SET_SEARCH_FLAG)
  ctx.isSearching.value = wasSearching

  if (wasSearching) {
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.PARALLEL_PREP)
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.UPDATE_BUTTON)
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.BUSH_VISIBLE)
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.SILHOUETTE_MODE)
    if (ctx.activeBattle.value) ctx.activeBattle.value.enemy = finalEnemyPoke
    return 
  } else {
    fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENTRY_ANIM)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENCOUNTER_TYPE_CHECK)

    if (isTrainer || isGym) {
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.TRAINER_ENTRY)
      fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.T_VISUAL)
    } else {
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.WILD_ENTRY)
      if (ctx.activeBattle.value) ctx.activeBattle.value.enemy = finalEnemyPoke
    }
  }

  await initBattleSequence(ctx, { 
    locationId, isTrainer, trainerName, isGym, gymId, wasSearching,
    initialEnemy: finalEnemyPoke,
    initialPlayer: playerPoke
  })
}

/**
 * Visual initialization and first turn setup.
 */
export async function initBattleSequence(ctx: BattleContext, { locationId, isTrainer, trainerName, isGym, wasSearching, initialEnemy, initialPlayer }: any) {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  ctx.isIntroAnimating.value = true
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.PRELOAD_FINAL_COORDS, 50)

  if (wasSearching) {
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENCOUNTER_TYPE_CHECK)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.WILD_ENCOUNTER)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.CHECK_BINOCULARS)
    fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.PARALLEL_JUMP)

    const inventoryBinoculars = (ctx.gs.state.inventory as any)?.['binoculars'] || 0
    const hasBinoculars = ctx.debugBinoculars.value || (inventoryBinoculars > 0)
    if (!hasBinoculars) {
      await new Promise(r => setTimeout(r, 150))
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.BUSH_FADE, 100)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.REVEAL_COLORS, 500)
    } else {
      await new Promise(r => setTimeout(r, 600))
    }
  } else {
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENCOUNTER_TYPE_CHECK)

    if (isTrainer || isGym) {
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.TRAINER_ENCOUNTER)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.SHOW_DIALOGS)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.TRAINER_RETREAT, 800)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.POKEMON_CALL, 100)
      if (ctx.activeBattle.value) ctx.activeBattle.value.enemy = initialEnemy
    } else {
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.WILD_ENTRY)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.PARALLEL_PREP, 400)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.BUSH_VISIBLE)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.SILHOUETTE_MODE)
    }
  }

  const currentPlayer = ctx.activeBattle.value?.player
  const needsCall = !currentPlayer || (currentPlayer.uid !== initialPlayer.uid)

  if (needsCall && ctx.activeBattle.value) {
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_CALL, 100)
    ctx.activeBattle.value.player = initialPlayer
  }

  await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.ANIM_SYNC, 800)
  await fsm.transition(BATTLE_STATES.REORDER_TEAM, null)

  window.dispatchEvent(new Event('resize'))

  ctx.attackerSide.value = null
  ctx.activeMove.value = null

  const startMsg = isTrainer || isGym 
    ? `¡${trainerName} te desafía!` 
    : `¡Un ${initialEnemy.name} salvaje apareció!`

  ctx.addLog(startMsg, 'log-info', initialEnemy)
  handleEntryAbilities(initialPlayer, initialEnemy, ctx.playerStages.value, ctx.enemyStages.value, ctx.addLog)

  if (isTrainer || isGym) await ctx.gs.scheduleSave()

  if (!isTrainer && !isGym) {
    const mapStore = useMapStore() as unknown as MapStore
    const eventStore = useEventStore() as unknown as EventStore
    const encounterOptions = {
      activeEvents: mapStore.activeEvents,
      dominanceData: mapStore.mapWinners,
      shinyMultiplier: eventStore.globalMultipliers?.shiny || 1,
      forceEncounter: true 
    }

    generateEncounter(locationId, ctx.gs.state, encounterOptions).then((encounter) => {
      if (encounter && encounter.type === 'wild' && encounter.pokemon) {
        if (fsm.currentState.value !== BATTLE_STATES.EXIT_BATTLE) {
          fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.GEN_NEW_S2)
          ctx.upcomingPokemon.value = encounter.pokemon
        }
      }
    })
  }

  ctx.isIntroAnimating.value = false
  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.WAIT_INPUT, 300)
  ctx.upcomingPokemon.value = null 
  ctx.isIntroAnimating.value = false
}

/**
 * Restores a battle state from saved data.
 */
export function restoreBattleState(ctx: BattleContext, battleData: any) {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  if (!battleData) {
    ctx.activeBattle.value = null
    ctx.fsm.transition(BATTLE_STATES.EXIT_BATTLE)
    return
  }
  ctx.activeBattle.value = battleData
  if (battleData.playerStages) ctx.playerStages.value = battleData.playerStages
  if (battleData.enemyStages) ctx.enemyStages.value = battleData.enemyStages
  if (battleData.battleLogs) ctx.battleLogs.value = battleData.battleLogs

  if (!battleData.over) {
    ctx.fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.WAIT_INPUT)
  } else {
    ctx.fsm.transition(BATTLE_STATES.EXIT_BATTLE)
  }
}

import { gameBus } from '@/logic/gameBus'
import { calculateBaseExp, processExpGain, calculateMoneyGain } from './battleRewards'
import { getBattleRewardModifiers } from '@/logic/war/bonusEngine'
import { levelUpPokemon } from '@/logic/pokemonFactory'
import { useUIStore } from '@/stores/ui'
import type { BattleContext } from '@/types/battleContext'
import type { Pokemon } from '@/types/pokemon'

/**
 * Handles the fainting of a Pokémon.
 */
export async function processFaint(ctx: BattleContext, side: 'player' | 'enemy') {
  const isPlayer = side === 'player'
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, isPlayer ? BATTLE_SUBSTATES.PLAYER_FAINT_SEQ : BATTLE_SUBSTATES.ENEMY_FAINT as any)

  if (ctx.faintedSides.value.has(side)) return
  ctx.faintedSides.value.add(side)

  const pokemon = isPlayer ? ctx.activeBattle.value?.player : ctx.activeBattle.value?.enemy
  const opponent = isPlayer ? ctx.activeBattle.value?.enemy : ctx.activeBattle.value?.player

  if (pokemon?.destinyBond && opponent && opponent.hp > 0) {
    ctx.addLog(`¡${pokemon.name} se llevó a ${opponent.name} con él!`, 'log-info', pokemon)
    opponent.hp = 0
    await new Promise(r => setTimeout(r, 500))
    await processFaint(ctx, isPlayer ? 'enemy' : 'player')
  }

  if (isPlayer && pokemon) {
    ctx.addLog(`¡${pokemon.name} se ha debilitado!`, 'log-player', pokemon)

    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAYER_FAINT_SEQ as any)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.RECALL_FLOW as any)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_RECALL as any)
    gameBus.emit('PLAY_WITHDRAW', { side: 'player', isFaint: true })
    await new Promise(r => setTimeout(r, 800))
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT as any)
    if (ctx.activeBattle.value) ctx.activeBattle.value.player = null 

    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.CHECK_TEAM as any)
    const nextPoke = ctx.gs.state.team.find((p: Pokemon) => p.hp > 0)

    if (!nextPoke) {
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ALL_FAINTED as any)
      if (ctx.activeBattle.value) ctx.activeBattle.value.over = true
      ctx.addLog('¡No te quedan Pokémon sanos!', 'log-error', 'player')
      await new Promise(r => setTimeout(r, 1500))
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.DEFEAT_SCREEN as any)
      await terminateBattle(ctx, false)
    } else {
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.HAS_HEALTHY as any)
      ctx.addLog('¡Elige a tu próximo Pokémon!', 'log-info', 'player')
      ctx.faintedSides.value.delete('player')
      (useUIStore() as any).isBattleSwitchForced = true
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.SWITCH_MENU as any)
    }
  } else if (pokemon) {
    const isTr = ctx.activeBattle.value?.isTrainer || ctx.activeBattle.value?.isGym
    const enemyName = isTr ? pokemon.name : `¡${pokemon.name} salvaje`
    ctx.addLog(`${enemyName} fue derrotado!`, 'log-enemy', pokemon)

    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ENEMY_DEFEAT as any)

    gameBus.emit('PLAY_SOUND', 'faint')
    gameBus.emit('PLAY_FAINT', { side: 'enemy' })
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAY_ENEMY_FAINT as any)

    await new Promise(r => setTimeout(r, 1000))

    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT as any)
    if (ctx.activeBattle.value) ctx.activeBattle.value.enemy = null

    if (isTr && ctx.activeBattle.value?.enemyTeam) {
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ENEMY_REPLACEMENT_SEQ as any)
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.CLEANUP_MEMORY as any)

      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.CHECK_REMAINING as any)
      const nextEnemy = ctx.activeBattle.value.enemyTeam.find((p: Pokemon) => p.hp > 0)
      if (nextEnemy) {
        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.STABILIZE_STAGE as any)

        const s = ctx.enemyStages.value
        ctx.enemyStages.value = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, 
          reflect: s.reflect || 0, lightScreen: s.lightScreen || 0, safeguard: s.safeguard || 0, mist: s.mist || 0, spikes: s.spikes || 0 }

        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.AI_NEXT_PICK as any)
        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.SELECT_COUNTER as any)

        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_CALL as any)
        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.OCCUPY_SEAT as any)
        ctx.activeBattle.value.enemy = nextEnemy
        ctx.addLog(`¡Entrenador envía a ${nextEnemy.name}!`, 'log-enemy', 'enemy_trainer')
        gameBus.emit('PLAY_SEND_OUT', { side: 'enemy', pokemon: nextEnemy })
        await new Promise(r => setTimeout(r, 800))
        return
      }
    }

    if (ctx.activeBattle.value) {
      ctx.activeBattle.value.over = true 
      ctx.activeBattle.value.enemy = null
    }
    ctx.faintedSides.value.add('enemy')
    await terminateBattle(ctx, true)
  }
}

/**
 * Terminates the battle and processes results.
 */
export async function terminateBattle(ctx: BattleContext, win: boolean, fled = false) {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  if (!ctx.activeBattle.value) {
    fsm.transition(BATTLE_STATES.EXIT_BATTLE)
    return
  }

  ctx.activeBattle.value.over = true
  ctx.faintedSides.value.clear()

  if (win && !fled) await calculateBattleRewards(ctx)

  syncAndPersist(ctx)

  if (ctx.activeBattle.value) {
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT as any)
    ctx.activeBattle.value.enemy = null
    ctx.activeBattle.value._initialEnemy = null
  }

  fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.CHECK_OUTCOME as any)

  if (!win && !fled) {
    await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT as any)
    await new Promise(r => setTimeout(r, 1000))
    await ctx.gs.save(false)

    fsm.transition(BATTLE_STATES.EXIT_BATTLE)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.ENTRY_CHECK as any)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.DEFEAT_SCREEN as any)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.DEFEAT_WAIT as any)
    return
  }

  if (fled) {
    fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.WAIT_LOG_QUEUE_ONLY as any)
    await ctx.waitForLogs()

    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.ENTRY_CHECK as any)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.EXECUTE_CLEANUP as any)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.CLEAR_UI as any)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.TRIGGER_CLOSE as any)
    fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.RESET_FLAGS as any)
    await ctx.completeBattleFlow('map')
    return
  }

  await ctx.gs.save(false)
  await ctx.waitForLogs()
  syncTeamHP(ctx)

  await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT as any)
  await new Promise(r => setTimeout(r, 1000))

  const firstHealthy = ctx.gs.state.team.find((p: Pokemon) => p.hp > 0)
  const currentActive = ctx.activeBattle.value.player
  const needsReorder = firstHealthy && (!currentActive || firstHealthy.uid !== currentActive.uid)

  if (needsReorder) {
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.SWITCHING as any)
    if (currentActive && currentActive.hp > 0) {
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_RECALL as any)
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.RENDER_BALL as any)
      gameBus.emit('PLAY_WITHDRAW', { side: 'player' })
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.ENERGY_RECALL as any)
      await new Promise(r => setTimeout(r, 800))
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.VACATE_SEAT as any)
      if (ctx.activeBattle.value) ctx.activeBattle.value.player = null
    }

    if (ctx.activeBattle.value) {
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_CALL as any)
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.RENDER_BALL as any)

      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.OCCUPY_SEAT as any)
      ctx.activeBattle.value.player = firstHealthy
      ctx.activeBattle.value.playerTeamIndex = ctx.gs.state.team.findIndex((p: Pokemon) => p.uid === firstHealthy.uid)

      gameBus.emit('PLAY_SEND_OUT', { side: 'player', pokemon: firstHealthy })
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.ENERGY_RELEASE as any)
      await new Promise(r => setTimeout(r, 800))

      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_APPEAR as any)
      await new Promise(r => setTimeout(r, 400))
    }
  }

  const persistenceMode = ctx.activeBattle.value?.persistenceMode || 'PERSISTENT'
  const isSingle = persistenceMode === 'SINGLE' || ctx.activeBattle.value?.isTrainer

  await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.CHECK_PERSISTENCE as any)

  if (!isSingle) {
    await ctx.completeBattleFlow('search')
  } else {
    fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT as any)
  }
}

/**
 * Calculates and distributes XP and money rewards.
 */
export async function calculateBattleRewards(ctx: BattleContext) {
  if (!ctx.activeBattle.value) return
  const e = ctx.activeBattle.value.enemy || ctx.activeBattle.value._initialEnemy
  if (!e) return

  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.DISTRIBUTE_XP as any)

  const isTr = ctx.activeBattle.value.isTrainer || ctx.activeBattle.value.isGym
  const locId = ctx.activeBattle.value.locationId
  const enemyRef = e

  if (enemyRef?.isGuardian) await ctx.warStore.addPoints(locId, 'guardian', true)
  else await ctx.warStore.addPoints(locId, isTr ? 'trainer_win' : 'wild_win', true)

  if (ctx.activeBattle.value.isCapture) await ctx.eventStore.submitCompetitionEntry(enemyRef as any, 'hourly_competition')

  if (ctx.activeBattle.value.isGym && ctx.activeBattle.value.gymId) {
    const gid = ctx.activeBattle.value.gymId
    if (!ctx.gs.state.defeatedGyms.includes(gid)) {
      ctx.gs.state.defeatedGyms.push(gid); ctx.gs.state.badges++
      if (ctx.activeBattle.value.rewardTM) { 
        const tm = ctx.activeBattle.value.rewardTM
        ctx.gs.state.inventory[tm] = (ctx.gs.state.inventory[tm] || 0) + 1
        ctx.addLog(`¡Recibiste la ${tm}!`, 'log-info', tm) 
      }
      (useUIStore() as any).notify(`¡Ganaste la medalla del Gimnasio ${gid}!`, '🏆')
      await ctx.gs.save(false)
    }
  }

  const baseExp = calculateBaseExp(e)
  const warMods = getBattleRewardModifiers(ctx.activeBattle.value.locationId, ctx.gs.state.faction, ctx.warStore.mapDominance)
  const totalExpMult = warMods.expMult + ((ctx.eventStore.globalMultipliers?.exp || 1) - 1)
  const classMult = ctx.classStore.getModifier('expMult', { isTrainer: ctx.activeBattle.value.isTrainer })
  const participantsSet = new Set(ctx.activeBattle.value.participants)

  for (const p of ctx.gs.state.team) {
    const reward = processExpGain(p, baseExp, participantsSet, {
      isActive: p.uid === ctx.activeBattle.value.player?.uid,
      classMult,
      totalExpMult,
      participantsSet
    })
    if (!reward) continue
    ctx.addLog(`${p.name} ganó ${reward.gained} EXP.`, 'log-player', p)

    if (reward.levelUp) {
      ctx.audio.levelUp()
      ctx.addLog(`¡${p.name} subió al nivel ${p.level}!`, 'log-info', p)

      await fsm.transition(BATTLE_STATES.LEVEL_UP_MODAL, BATTLE_SUBSTATES.CHECK_PENDING as any)
      const pendingMoves = levelUpPokemon(p)

      if (pendingMoves && pendingMoves.length > 0) {
        await fsm.transition(BATTLE_STATES.LEVEL_UP_MODAL, BATTLE_SUBSTATES.SHOW_CHOICE as any)
        p.pendingMoves = pendingMoves
      }
    }
  }

  const moneyGained = calculateMoneyGain(e, { 
    bcMult: ctx.classStore.getModifier('bcMult', { isGym: ctx.activeBattle.value.isGym }), 
    totalMoneyMult: warMods.moneyMult + ((ctx.eventStore.globalMultipliers?.money || 1) - 1) 
  })

  ctx.gs.state.money += moneyGained
  if (moneyGained > 0) ctx.audio.money()
  ctx.addLog(`¡Ganaste ₽${moneyGained}!`, 'log-info', 'player')
}

/**
 * Syncs team HP to GameStore.
 */
export function syncTeamHP(ctx: BattleContext) {
  if (!ctx.activeBattle.value) return;

  if (ctx.activeBattle.value.player) {
    const currentIdx = ctx.activeBattle.value.playerTeamIndex ?? ctx.gs.state.team.findIndex((p: Pokemon) => p.uid === ctx.activeBattle.value.player?.uid);
    if (currentIdx !== -1) {
      ctx.gs.state.team[currentIdx].hp = ctx.activeBattle.value.player.hp;
      ctx.gs.state.team[currentIdx].status = ctx.activeBattle.value.player.status;
    }
  }
}

/**
 * Persists battle state to GameStore.
 */
export function syncAndPersist(ctx: BattleContext) {
  if (!ctx.activeBattle.value || ctx.activeBattle.value.over) {
    ctx.gs.state.activeBattle = null
    return
  }
  ctx.gs.state.activeBattle = {
    ...ctx.activeBattle.value,
    playerStages: ctx.playerStages.value,
    enemyStages: ctx.enemyStages.value,
    battleLogs: ctx.battleLogs.value.slice(-10)
  }
  ctx.gs.save(false)
}

  ctx.gs.save(false)
}

/**
 * Weather Mapper System
 * Centralizes the mapping between environmental weather tokens (from Map/Atmosphere)
 * and technical battle mechanical keys.
 */

export const WEATHER_MECHANICAL = {
  SUN: 'sun',
  RAIN: 'rain',
  SANDSTORM: 'sandstorm',
  SNOW: 'snow',
  HAIL: 'hail',
  FOG: 'fog',
  CLEAR: 'clear',
  UNKNOWN: 'unknown'
} as const;

export type WeatherMechanical = typeof WEATHER_MECHANICAL[keyof typeof WEATHER_MECHANICAL];

const MAP_TO_MECHANICAL: Record<string, WeatherMechanical> = {
  // Sun Group
  'sun': WEATHER_MECHANICAL.SUN,
  'heatwave': WEATHER_MECHANICAL.SUN,
  'intense_sun': WEATHER_MECHANICAL.SUN,

  // Rain Group
  'rain': WEATHER_MECHANICAL.RAIN,
  'storm': WEATHER_MECHANICAL.RAIN,
  'thunderstorm': WEATHER_MECHANICAL.RAIN,
  'heavy_rain': WEATHER_MECHANICAL.RAIN,

  // Sand Group
  'sandstorm': WEATHER_MECHANICAL.SANDSTORM,
  'dust_storm': WEATHER_MECHANICAL.SANDSTORM,

  // Snow/Ice Group
  'snow': WEATHER_MECHANICAL.SNOW,
  'hail': WEATHER_MECHANICAL.HAIL,
  'blizzard': WEATHER_MECHANICAL.HAIL,

  // Fog Group
  'fog': WEATHER_MECHANICAL.FOG,
  'mist': WEATHER_MECHANICAL.FOG,

  // Neutral
  'clear': WEATHER_MECHANICAL.CLEAR,
  'null': WEATHER_MECHANICAL.CLEAR
};

/**
 * Converts any environmental weather token to its combat-mechanical equivalent.
 * @param {string} type Environmental weather token (e.g., 'heatwave')
 * @returns {WeatherMechanical} Mechanical weather key (e.g., 'sun')
 */
export function getMechanicalWeather(type: string | null | undefined): WeatherMechanical {
  if (!type || type === 'clear' || type === 'null') return WEATHER_MECHANICAL.CLEAR;

  const lower = type.toLowerCase();
  const result = MAP_TO_MECHANICAL[lower];

  if (!result) {
    console.warn(`[WeatherIntegrity] Token de clima no registrado detectado: "${type}". Por favor regístralo en weatherMapper.ts para evitar inconsistencias mecánicas.`);
    return WEATHER_MECHANICAL.UNKNOWN;
  }

  return result;
}

/**
 * Converts any environmental weather token to its visual AtmosphereLayer equivalent.
 * This preserves visual variants (like 'storm' vs 'rain').
 * @param {string} type Environmental weather token
 * @returns {string} Visual token
 */
export function getVisualWeather(type: string | null | undefined): string {
  if (!type) return 'clear';
  const lower = type.toLowerCase();

  // Lista de tokens soportados directamente por AtmosphereLayer
  const VALID_VISUALS = ['rain', 'storm', 'heatwave', 'snow', 'blizzard', 'sandstorm', 'fog', 'mist'];
  if (VALID_VISUALS.includes(lower)) return lower;

  // Si no es un visual directo, usamos el mapeo mecánico para obtener el fallback visual
  const mech = getMechanicalWeather(lower);
  return (WEATHER_UI_METADATA[mech] as any)?.visual || 'clear';
}

