const NATURES = ['Audaz', 'Firme', 'Pícaro', 'Manso', 'Serio', 'Osado', 'Plácido', 'Agitado', 'Jovial', 'Ingenuo', 'Modesto', 'Moderado', 'Raro', 'Dócil', 'Tímido', 'Activo', 'Alocado', 'Tranquilo', 'Grosero', 'Cauto'];

/**
 * Generates a new mission object.
 */
export function generateMission(trainerLevel: number, dateStr: string): DaycareMission {
  let possibleTargets = [...(POOLS['novice'] || [])];
  if (trainerLevel >= 10) possibleTargets = possibleTargets.concat(POOLS['apprentice'] || []);
  if (trainerLevel >= 25) possibleTargets = possibleTargets.concat(POOLS['veteran'] || []);
  if (trainerLevel >= 40) possibleTargets = possibleTargets.concat(POOLS['master'] || []);

  const targetId = possibleTargets[Math.floor(Math.random() * possibleTargets.length)] || 'magikarp';
  const missionTypes = ['level', 'nature', 'iv_total'];
  if (trainerLevel >= 15) missionTypes.push('iv_31');

  const type = missionTypes[Math.floor(Math.random() * missionTypes.length)] || 'level';
  const requirement: MissionRequirement = { type };
  let reqText = '';

  if (type === 'level') {
    const minLvl = Math.max(5, Math.min(100, trainerLevel + Math.floor(Math.random() * 16) - 5));
    requirement.minLevel = minLvl;
    reqText = `Nv. ${minLvl}+`;
  } else if (type === 'iv_total') {
    const baseIv = 90 + Math.min(trainerLevel, 60);
    const minIvTotal = baseIv + Math.floor(Math.random() * 21);
    requirement.minIvTotal = minIvTotal;
    reqText = `${minIvTotal}+ IVs totales`;
  } else if (type === 'nature') {
    const targetNature = NATURES[Math.floor(Math.random() * NATURES.length)] || 'Serio';
    requirement.nature = targetNature;
    reqText = `naturaleza ${targetNature}`;
  } else if (type === 'iv_31') {
    const stats: (keyof PokemonIVs)[] = ['hp', 'atk', 'def', 'spa', 'spd', 'spe'];
    const statLabels: Record<string, string> = { hp: 'PS', atk: 'Ataque', def: 'Defensa', spa: 'At. Esp', spd: 'Def. Esp', spe: 'Velocidad' };
    const targetStat = stats[Math.floor(Math.random() * stats.length)] || 'hp';
    requirement.stat31 = targetStat;
    reqText = `IV 31 en ${statLabels[targetStat] || 'PS'}`;
  }

  // Rewards
  const rewardQty = trainerLevel >= 40 ? 4 : (trainerLevel >= 20 ? 3 : 2);
  const possibleRewards: MissionReward[] = [
    { id: 'berry_bronze', name: 'Baya de Bronce', qty: rewardQty + 1, icon: '🥉' },
    { id: 'berry_silver', name: 'Baya de Plata', qty: rewardQty, icon: '🥈' },
    { id: 'berry_gold', name: 'Baya de Oro', qty: Math.max(1, rewardQty - 2), icon: '🥇' },
    { id: 'everstone', name: 'Piedra Eterna', qty: 1, icon: '🪨' }
  ];

  if (trainerLevel >= 15) {
    const powerItems: MissionReward[] = [
      { id: 'power_weight', name: 'Pesa Recia', qty: 1, icon: '🏋️' },
      { id: 'power_bracer', name: 'Brazal Recio', qty: 1, icon: '🥊' },
      { id: 'power_belt', name: 'Cinto Recio', qty: 1, icon: '🛡️' },
      { id: 'power_lens', name: 'Lente Recia', qty: 1, icon: '🔍' },
      { id: 'power_band', name: 'Banda Recia', qty: 1, icon: '🎗️' },
      { id: 'power_anklet', name: 'Franja Recia', qty: 1, icon: '👢' }
    ];
    possibleRewards.push(...powerItems);
  }

  const reward = possibleRewards[Math.floor(Math.random() * possibleRewards.length)] || possibleRewards[0] as MissionReward;
  const tKeys = Object.keys(TRAINER_TYPES);
  const tKey = tKeys[Math.floor(Math.random() * tKeys.length)] || 'caza_bichos';
  const trainer = TRAINER_TYPES[tKey] || TRAINER_TYPES['caza_bichos'] as { name: string; sprite: string };

  const targetName = (POKEMON_DB as any)[targetId]?.name || targetId;
  const templates = MISSION_DIALOGUES_BASE[tKey] || MISSION_DIALOGUES_BASE['default'] || [];
  const template = templates[Math.floor(Math.random() * templates.length)] || '...';
  const dialogue = template.replace('${pokemon}', targetName).replace('${req}', reqText);

  return {
    date: dateStr,
    targetId,
    requirement,
    reqText,
    reward,
    completed: false,
    trainerType: tKey,
    trainerName: trainer.name,
    trainerSprite: trainer.sprite, // This is now just an ID like 'cazabichos'
    dialogue
  };
}

/**
 * Validates if the selected pokemon meets the mission requirements.
 */
export function validateMissionPokemon(pokemon: Pokemon, mission: DaycareMission): boolean {
  const req = mission.requirement;
  if (!pokemon) return false;

  // Basic species check (should be handled by picker filtration but safe to keep)
  if (pokemon.id !== mission.targetId) return false;

  if (req.type === 'level') {
    return pokemon.level >= (req.minLevel || 0);
  } else if (req.type === 'iv_total') {
    const total = Object.values(pokemon.ivs || {}).reduce((acc, val) => acc + (val || 0), 0);
    return total >= (req.minIvTotal || 0);
  } else if (req.type === 'nature') {
    return pokemon.nature === req.nature;
  } else if (req.type === 'iv_31') {
    return pokemon.ivs[req.stat31!] === 31;
  }

  return false;
}

/**
 * Virtual World Coordinator (Spatial Standardization)
 * Source of truth for all virtual units, scaling, and positioning logic.
 */

export const WORLD_CONSTANTS = {
  // Virtual World Dimensions
  MAP_WIDTH: 3000,
  MAP_HEIGHT: 3000,

  // Action/Safe Zone (Center of the world)
  SAFE_ZONE_WIDTH: 1000,
  SAFE_ZONE_HEIGHT: 666,
  get SAFE_ZONE_X(): number { return (this.MAP_WIDTH - this.SAFE_ZONE_WIDTH) / 2 }, // 1000
  get SAFE_ZONE_Y(): number { return (this.MAP_HEIGHT - this.SAFE_ZONE_HEIGHT) / 2 }, // 1167

  // Action focus point
  TARGET_X: 1500,
  get TARGET_Y(): number {
    // Aligned to bottom: The bottom of the safe zone coincides with the bottom of the visible units
    return (this.SAFE_ZONE_Y + this.SAFE_ZONE_HEIGHT) - (this.VISIBLE_UNITS_Y / 2)
  },

  // Camera Constraints
  VISIBLE_UNITS_X: 1000,
  VISIBLE_UNITS_Y: 766, // Safe zone height + 100u padding top
  RATIO_MAX: 3.0,
  RATIO_MIN: 0.33,

  // Object Scaling Standards
  OBJECT_SCALE: 2,
  BASE_ENTITY_SIZE: 300,
  BASE_ENTITY_SIZE_PLAYER: 300,
  BASE_ENTITY_SIZE_ENEMY: 150,
  BASE_BUSH_SIZE: 60,
  BASE_PREVIEW_SIZE: 120,
  SHADOW_WIDTH: 10,
  SHADOW_HEIGHT: 7,

  /** 
   * Default entity size (400px by default) 
   * Calculated as BASE_ENTITY_SIZE * OBJECT_SCALE
   */
  get ENTITY_SIZE(): number { return this.BASE_ENTITY_SIZE * this.OBJECT_SCALE },
  get ENTITY_SIZE_PLAYER(): number { return this.BASE_ENTITY_SIZE_PLAYER * this.OBJECT_SCALE },
  get ENTITY_SIZE_ENEMY(): number { return this.BASE_ENTITY_SIZE_ENEMY * this.OBJECT_SCALE },
  get BUSH_SIZE(): number { return this.BASE_BUSH_SIZE * this.OBJECT_SCALE },
  get PREVIEW_SIZE(): number { return this.BASE_PREVIEW_SIZE * this.OBJECT_SCALE }
}

/**
 * Normalizes coordinates into the 3000x3000px virtual space.
 */
export function toVirtualStyles(x: number, y: number, w?: number, h?: number): any {
  const scale = WORLD_CONSTANTS.OBJECT_SCALE
  return {
    position: 'absolute',
    left: `${x}px`,
    top: `${y}px`,
    width: w !== undefined ? `${w * scale}px` : undefined,
    height: h !== undefined ? `${h * scale}px` : undefined
  }
}

/**
 * Returns the standard position for a combatant side.
 */
export function getCombatantPosition(side: 'player' | 'enemy'): { x: number; y: number } {
  const { SAFE_ZONE_X, SAFE_ZONE_Y, SAFE_ZONE_WIDTH, SAFE_ZONE_HEIGHT } = WORLD_CONSTANTS
  if (side === 'player') {
    const size = WORLD_CONSTANTS.ENTITY_SIZE_PLAYER
    return {
      x: SAFE_ZONE_X,
      y: SAFE_ZONE_Y + SAFE_ZONE_HEIGHT - size
    }
  }
  // Enemy (p2)
  const size = WORLD_CONSTANTS.ENTITY_SIZE_ENEMY
  return {
    x: SAFE_ZONE_X + SAFE_ZONE_WIDTH - size,
    y: SAFE_ZONE_Y
  }
}

