/**
 * Returns a unified array of all visual indicators for a pokemon.
 * This is the SINGLE SOURCE OF TRUTH for badge rendering.
 * @param {Object} pokemon 
 * @returns {Array} Array of badge/tag objects
 */
export function getPokemonVisualBadges(pokemon: Partial<Pokemon> | null): TagDefinition[] {
  if (!pokemon) return []
  const badges: TagDefinition[] = []

  // 1. Automatic: Shiny
  const shinyBadge = POKEMON_BADGES['shiny'];
  if (pokemon.isShiny && shinyBadge) {
    badges.push({ ...shinyBadge, isAutomatic: true })
  }

  // 2. Automatic: IV 31 (Perfect)
  const ivs = pokemon.ivs || { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 }
  const iv31Badge = TAG_DEFINITIONS['iv31'];
  if (Object.values(ivs).some(v => v === 31) && iv31Badge) {
    badges.push({ ...iv31Badge, isAutomatic: true })
  }

  // 3. Automatic: Held Item
  const heldItemRaw = pokemon.heldItem || ((pokemon as any).item && (pokemon as any).item !== 'none' ? (pokemon as any).item : null)
  const itemBadge = POKEMON_BADGES['item'];
  if (heldItemRaw && itemBadge) {
    // Normalizar para búsqueda: "Rare Candy" -> "rare_candy" o "Caramelo Raro" -> "Caramelo Raro"
    const normalizedId = String(heldItemRaw).toLowerCase().replace(/ /g, '_')
    const itemData = getItemById(heldItemRaw) || 
                    getItemById(normalizedId) || 
                    getItemByName(heldItemRaw) ||
                    getItemByName(heldItemRaw.charAt(0).toUpperCase() + heldItemRaw.slice(1).toLowerCase())

    badges.push({ 
      ...itemBadge, 
      id: 'item',
      label: itemData ? itemData.name.toUpperCase() : String(heldItemRaw).toUpperCase(),
      shortLabel: itemBadge.shortLabel,
      desc: itemData ? itemData.desc : itemBadge.desc,
      isAutomatic: true,
      itemId: itemData ? itemData.id : normalizedId
    })
  }

  // 4. Manual Tags (From pokemon.tags array)
  const tags = (pokemon as any).tags
  if (tags && Array.isArray(tags)) {
    tags.forEach((tagId: string) => {
      // Avoid duplicating iv31 if already added automatically
      // Also ignore 'box' tag as it's being deprecated/replaced
      if (tagId === 'iv31' || tagId === 'box') return 

      const def = TAG_DEFINITIONS[tagId]
      if (def) badges.push({ ...def, isAutomatic: false })
    })
  }

  return badges
}

/**
 * Returns all manual tags with an 'isActive' flag.
 * Used for the tag editor/detail view.
 */
export function getPokemonEditorBadges(pokemon: Partial<Pokemon> | null): TagDefinition[] {
  const pokemonTags = (pokemon as any)?.tags || []
  const badges: TagDefinition[] = []

  // ONLY add manual definitions for the editor
  Object.values(TAG_DEFINITIONS).forEach(def => {
    // We skip 'iv31' and any other automatic-only tags in the editor
    if (def.id === 'iv31') return

    badges.push({
      ...def,
      isActive: pokemonTags.includes(def.id),
      isLocked: false
    })
  })

  return badges
}

/**
 * Standardized helper to check if a pokemon possesses a specific tag.
 */
export const hasPokemonTag = (pokemon: Partial<Pokemon> | null, tagId: string): boolean => {
  if (!pokemon) return false
  const tags = (pokemon as any).tags || []

  switch (tagId) {
    case 'comp':
    case 'competitive':
      return tags.includes('comp') || tags.includes('competitive')
    case 'iv31':
      return tags.includes('iv31') || Object.values(pokemon.ivs || {}).some(v => v === 31)
    case 'fav':
      return tags.includes('fav') || tags.includes('favorite')
    default:
      return tags.includes(tagId)
  }
}

import { createClient, type SupabaseClient, type RealtimeChannel, type User, type Session } from '@supabase/supabase-js';
import { ProxyQuery } from './proxyQuery';
import { initSQLite, persistSQLite, queryLocal } from './sqliteEngine';
import { DATABASE_MIGRATIONS } from './migrations_data';
import { useLoadingStore } from '@/stores/loading';
import type { DBConfig, DBMode, DBRouterOptions, DBCompatibilityResponse, DBResponse } from '@/types/database';

export type { DBCompatibilityResponse };

/**
 * Unified Data Persistence Layer with Strict Session Isolation.
 * Routes queries to Supabase (Cloud) OR SQLite (Local), NEVER both in the same session.
 */

export class DBRouter {
  config: DBConfig;
  _realClient: SupabaseClient | null;
  mode: DBMode;
  options: DBRouterOptions;
  _initialized: boolean;
  currentSessionId: string | null;
  userSubscription: RealtimeChannel | null;
  _timeOffset: number;

  constructor(config: DBConfig = { url: '', key: '' }, mode: DBMode = 'online', options: DBRouterOptions = {}) {
    this.config = config;
    this._realClient = null;
    this.mode = mode;
    this.options = options;
    this._initialized = false;
    this.currentSessionId = null;
    this.userSubscription = null;
    this._timeOffset = 0; // ms

    console.log(`[DBRouter] Initialized in STRICT ${mode.toUpperCase()} mode.`);
  }

  /**
   * Internal lazy initializer for Supabase client.
   */
  _ensureClient(): SupabaseClient | null {
    if (this._realClient) return this._realClient;

    const { url, key } = this.config;
    if (!url || !key) {
      console.warn('[DBRouter] Missing Supabase config. Online operations will fail.');
      return null;
    }

    try {
      console.log('[DBRouter] Lazily initializing Supabase client...');
      this._realClient = createClient(url, key);
      return this._realClient;
    } catch (err) {
      console.error('[DBRouter] Failed to initialize Supabase client:', err);
      return null;
    }
  }

  /**
   * Getter for the real Supabase client (Lazy).
   */
  get realClient(): SupabaseClient | null {
    if (this.mode === 'offline') return null;
    return this._ensureClient();
  }

  /**
   * Identifies if the instance is running in a local context.
   */
  get isLocal(): boolean {
    return this.mode === 'offline';
  }

  /**
   * Time Mocking Methods (SECURITY: ONLY FOR OFFLINE MODE)
   */
  setTimeOffset(ms: number): void {
    this._timeOffset = ms;
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('time-sync-update', { detail: { offset: ms } }));
    }
    console.log(`[DBRouter] Time offset set to: ${ms}ms`);
  }

  setMockTime(dateStr: string): void {
    const targetDate = new Date(dateStr);
    if (isNaN(targetDate.getTime())) return;
    const offset = targetDate.getTime() - Date.now();
    this.setTimeOffset(offset);
  }

  resetTime(): void {
    this.setTimeOffset(0);
  }

  getTimeOffset(): number {
    return this._timeOffset || 0;
  }

  /**
   * Initializes session monitoring for Last-In-Wins logic.
   */
  async initSession(userId: string, sessionId: string): Promise<void> {
    this.currentSessionId = sessionId;

    const client = this.realClient;
    if (this.mode === 'offline' || !client) return;

    try {
      await client
        .from('profiles')
        .update({ current_session_id: sessionId })
        .eq('id', userId);
    } catch (err) {
      console.error('[DBRouter] Failed to set session ID:', err);
    }

    if (this.userSubscription) this.userSubscription.unsubscribe();

    this.userSubscription = client
      .channel(`session_lock:${userId}`)
      .on('postgres_changes', {
        event: 'UPDATE',
        schema: 'public',
        table: 'profiles',
        filter: `id=eq.${userId}`
      }, (payload: { new: { current_session_id?: string } }) => {
        const newSessionId = payload?.new?.current_session_id;
        if (newSessionId && newSessionId !== this.currentSessionId) {
          this.handleSessionConflict();
        }
      })
      .subscribe();
  }

  handleSessionConflict(): void {
    console.warn('[DBRouter] SESSION CONFLICT DETECTED!');
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('session-conflict'));
    }
  }

  /**
   * Dynamically switches the router mode.
   * @param {String} mode - 'online' | 'offline'
   */
  setMode(mode: DBMode): void {
    if (this.mode === mode) return;
    console.log(`[DBRouter] Switching mode from ${this.mode} to ${mode.toUpperCase()}`);
    this.mode = mode;

    if (mode === 'offline') {
      initSQLite(this.options);
    }
  }

  /**
   * Returns a ProxyQuery instance for the specified table.
   */
  from(table: string): ProxyQuery {
    return new ProxyQuery(this, table);
  }

  /**
   * Returns a reliable timestamp.
   * If offline, uses local Date.now().
   * If online, fetches server time from Supabase.
   */
  async getServerTime(): Promise<number> {
    const baseTime = await this._getRawServerTime();
    // SECURITY: Offset is strictly for local/offline testing
    const offset = this.mode === 'offline' ? (this._timeOffset || 0) : 0;
    return baseTime + offset;
  }

  /** @private */
  async _getRawServerTime(): Promise<number> {
    if (this.mode === 'offline') {
      return Date.now();
    }

    const client = this.realClient;
    if (!client) return Date.now();

    try {
      // Prioritize a dedicated RPC for server time to avoid local clock manipulation
      const { data, error } = await client.rpc('fn_get_server_time');
      if (!error && data) return new Date(data as string).getTime();

      // Fallback: use a fast select if RPC fails
      return Date.now(); 
    } catch (e) {
      console.warn('[DBRouter] getServerTime error, falling back to local.', e);
      return Date.now();
    }
  }

  /**
   * Emulates Supabase RPC calls.
   */
  async rpc(name: string, params: Record<string, unknown> = {}): Promise<DBResponse> {
    if (this.mode === 'offline') {
      console.log(`[DBRouter] Local RPC: ${name}`, params);
      const sqliteDb = await initSQLite();

      // Implement specific local logic for critical RPCs
      if (name === 'fn_report_passive_battle') {
        const { p_opponent_id, p_result, p_report_data } = params;
        if (sqliteDb && typeof sqliteDb.run === 'function') {
          sqliteDb.run(
            `INSERT INTO passive_battle_reports (user_id, opponent_id, result, report_data) VALUES (?, ?, ?, ?)`,
            ['local_user', p_opponent_id, p_result, JSON.stringify(p_report_data)]
          );
        }
        await persistSQLite();
        return { data: { success: true }, error: null };
      }

      // Default mock success for other RPCs in offline mode
      return { data: { success: true }, error: null };
    }

    const client = this.realClient;
    if (!client) return { data: null, error: 'Offline' };

    // Online mode: direct call to Supabase
    try {
      return await client.rpc(name, params) as DBResponse;
    } catch (err: unknown) {
      const errMsg = (err instanceof Error ? err.message : String(err)).toLowerCase();
      if (errMsg.includes('fetch') || errMsg.includes('network') || errMsg.includes('failed to fetch')) {
        if (typeof window !== 'undefined') {
          window.dispatchEvent(new CustomEvent('db-connection-error'));
        }
      }
      throw err;
    }
  }

  /**
   * Emulates Supabase Auth API.
   */
  get auth() {
    if (this.mode === 'offline') {
      const localUserStr = typeof localStorage !== 'undefined' ? localStorage.getItem('pokevicio_local_user') : null;
      const localUser = localUserStr ? JSON.parse(localUserStr) as User : null;
      const user = localUser || { id: 'local_user', email: 'offline@pkv.io' } as User;
      const session = { access_token: 'mock', token_type: 'bearer', user, expires_at: 9999999999 } as unknown as Session;

      return {
        signOut: async () => ({ error: null }),
        signInWithPassword: async () => ({ data: { user, session }, error: null }),
        signUp: async () => ({ data: { user, session }, error: null }),
        getUser: async () => ({ data: { user }, error: null }),
        getSession: async () => ({ data: { session }, error: null }),
        onAuthStateChange: () => ({ data: { subscription: { unsubscribe: () => {} } } })
      };
    }

    const client = this.realClient;
    if (!client) {
      throw new Error('[DBRouter] Attempted to access Auth while online client is not initialized.');
    }

    return client.auth;
  }

  /**
   * Emulates Supabase Realtime Channels.
   */
  channel(name: string): RealtimeChannel {
    if (this.mode === 'offline') {
      const mockChannel = {
        on: (type: string, _filter: any, _callback: any) => {
          console.log(`[DBRouter] Mock Channel '${name}' subscribed to:`, type);
          return mockChannel; 
        },
        subscribe: (cb?: (status: string) => void) => {
          if (cb) setTimeout(() => cb('SUBSCRIBED'), 10);
          return { unsubscribe: () => {} };
        },
        send: (_args: any) => {
          return Promise.resolve('ok');
        },
        unsubscribe: () => {}
      };
      return mockChannel as unknown as RealtimeChannel;
    }

    const client = this.realClient;
    if (!client) {
      console.warn(`[DBRouter] Channel '${name}' requested but online client not ready. Returning mock.`);
      // Return a basic mock that doesn't do anything to avoid crashes
      const basicMock = {
        on: () => basicMock,
        subscribe: (cb?: (status: string) => void) => {
          if (cb) setTimeout(() => cb('SUBSCRIBED'), 10);
          return { unsubscribe: () => {} };
        },
        send: () => Promise.resolve('ok'),
        unsubscribe: () => {}
      } as unknown as RealtimeChannel;
      return basicMock;
    }

    return client.channel(name);
  }
}

/**
 * DB Compatibility Check
 * Ensures the client version is not greater than the DB version.
 */
// Use the last migration ID as the client version (Automated)
const lastMigration = DATABASE_MIGRATIONS.length > 0 ? DATABASE_MIGRATIONS[DATABASE_MIGRATIONS.length - 1] : null;
export const CLIENT_DB_VERSION = lastMigration 
  ? parseInt(lastMigration.id.split('_')[0] || '0') 
  : 0;



export async function checkDBCompatibility(router: DBRouter): Promise<DBCompatibilityResponse> {
  const loadingStore = useLoadingStore();
  loadingStore.start('db_compat', 'Verificando Versión...', 'Comprobando compatibilidad de DB', false)
  try {
    let dbVersion = 0;
    let rawValue: unknown = null;

    const client = router.realClient;
    if (router.mode === 'offline' || !client) {
      const results = await queryLocal("SELECT value FROM system_config WHERE key = 'db_version'");
      if (results.length > 0) rawValue = (results[0] as { value: unknown }).value;
    } else {
      const { data, error } = await client
        .from('system_config')
        .select('value')
        .eq('key', 'db_version')
        .single();

      if (!error && data) rawValue = (data as { value: unknown }).value;
    }

    if (rawValue) {
      // Handle JSON strings (SQLite stores objects as JSON strings)
      if (typeof rawValue === 'string' && (rawValue.startsWith('{') || rawValue.startsWith('['))) {
        try { rawValue = JSON.parse(rawValue); } catch (_e) { /* ignore */ }
      }

      const valObj = rawValue as Record<string, unknown> | null;
      dbVersion = (typeof rawValue === 'object' && valObj !== null && 'db_version' in valObj) 
        ? parseInt((valObj.db_version as string | number) + '' || '0') 
        : parseInt((rawValue as string | number) + '' || '0');
    }

    console.log(`[DBRouter] Compatibility Check: Client v${CLIENT_DB_VERSION} | DB v${dbVersion}`);

    const response: DBCompatibilityResponse = {
      compatible: true,
      client: CLIENT_DB_VERSION,
      db: dbVersion
    };

    if (router.mode !== 'offline' && CLIENT_DB_VERSION > dbVersion) {
      response.compatible = false;
      response.error = 'OUTDATED_SERVER';
    }

    loadingStore.finish('db_compat')
    return response;
  } catch (e: unknown) {
    loadingStore.finish('db_compat')
    console.warn('[DBRouter] Compatibility check failed, assuming compatible.', e);
    return { compatible: true, client: CLIENT_DB_VERSION, db: 0 };
  }
}

/**
 * idbHelper.ts
 * IndexedDB helper for SQLite WASM persistence.
 */

const DB_NAME = 'pokevicio_idb'
const STORE_NAME = 'keyval'

async function openIDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1)
    request.onupgradeneeded = (e: any) => {
      const db = e.target.result
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME)
      }
    }
    request.onsuccess = (e: any) => resolve(e.target.result)
    request.onerror = (e: any) => reject(e.target.error)
  })
}

export async function getFromIDB(key: string): Promise<any> {
  try {
    const db = await openIDB()
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readonly')
      const req = tx.objectStore(STORE_NAME).get(key)
      req.onsuccess = () => resolve(req.result)
      req.onerror = () => reject(req.error)
    })
  } catch (_e) { return null }
}

export async function setToIDB(key: string, val: any): Promise<void> {
  try {
    const db = await openIDB()
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite')
      const req = tx.objectStore(STORE_NAME).put(val, key)
      req.onsuccess = () => resolve()
      req.onerror = () => reject(req.error)
    })
  } catch (e) { console.error('[IDB] Save Error:', e) }
}

import { initSQLite, queryLocal, persistSQLite } from './sqliteEngine';
import type { DBRouter } from './dbRouter';
import type { DBResponse, ProxyQueryChainItem } from '@/types/database';

/**
 * Chainable Query Builder for SQLite that mimics Supabase/PostgREST API.
 */

export class ProxyQuery {
  router: DBRouter;
  table: string;
  chain: ProxyQueryChainItem[];
  action: 'select' | 'upsert' | 'update' | 'delete' | 'insert';
  actionData: unknown;
  actionOpts: unknown;

  constructor(router: DBRouter, table: string) {
    this.router = router;
    this.table = table;
    this.chain = [];
    this.action = 'select'; // select, upsert, update, delete
    this.actionData = null;
    this.actionOpts = null;
  }

  select(cols: string = '*', opts: { count?: 'exact' | 'planned' | 'estimated' | null, head?: boolean } = {}) { 
    this.chain.push({ type: 'select', args: [cols, opts] }); 
    return this; 
  }
  eq(c: string, v: unknown) { this.chain.push({ type: 'eq', args: [c, v] }); return this; }
  neq(c: string, v: unknown) { this.chain.push({ type: 'neq', args: [c, v] }); return this; }
  gt(c: string, v: unknown) { this.chain.push({ type: 'gt', args: [c, v] }); return this; }
  lt(c: string, v: unknown) { this.chain.push({ type: 'lt', args: [c, v] }); return this; }
  gte(c: string, v: unknown) { this.chain.push({ type: 'gte', args: [c, v] }); return this; }
  lte(c: string, v: unknown) { this.chain.push({ type: 'lte', args: [c, v] }); return this; }
  in(c: string, arr: unknown[]) { this.chain.push({ type: 'in', args: [c, arr] }); return this; }
  is(c: string, v: unknown) { this.chain.push({ type: 'is', args: [c, v] }); return this; }
  not(c: string, op: string, v: unknown) { this.chain.push({ type: 'not', args: [c, op, v] }); return this; }
  or(c: string) { this.chain.push({ type: 'or', args: [c] }); return this; }
  order(c: string, opts: { ascending?: boolean } = {}) { this.chain.push({ type: 'order', args: [c, opts] }); return this; }
  limit(n: number) { this.chain.push({ type: 'limit', args: [n] }); return this; }
  match(obj: Record<string, unknown>) { this.chain.push({ type: 'match', args: [obj] }); return this; }
  ilike(c: string, v: string) { this.chain.push({ type: 'ilike', args: [c, v] }); return this; }

  upsert(data: unknown, opts?: unknown) {
    this.action = 'upsert';
    this.actionData = data;
    this.actionOpts = opts;
    return this;
  }

  insert(data: unknown) {
    this.action = 'insert';
    this.actionData = data;
    return this;
  }

  update(data: unknown) {
    this.action = 'update';
    this.actionData = data;
    return this;
  }

  delete() {
    this.action = 'delete';
    return this;
  }

  async maybeSingle(): Promise<DBResponse> { return this.execute('maybeSingle'); }
  async single(): Promise<DBResponse> { return this.execute('single'); }

  // compatibility with 'await q'
  async then<T = DBResponse>(onFulfilled?: (value: DBResponse) => T | Promise<T>, onRejected?: (reason: unknown) => T | Promise<T>): Promise<T | DBResponse> {
    try {
      const res = await this.execute();
      return onFulfilled ? onFulfilled(res) : res;
    } catch (err) {
      if (onRejected) return onRejected(err);
      throw err;
    }
  }

  async execute(final: 'single' | 'maybeSingle' | null = null): Promise<DBResponse> {
    // If router is Online, use Supabase
    if (this.router.mode === 'online') {
      const client = this.router.realClient;
      if (!client) throw new Error('[DBRouter] Online client not available.');

      try {
        let q: any = client.from(this.table);

        if (this.action === 'upsert') return await q.upsert(this.actionData, this.actionOpts);
        if (this.action === 'insert') return await q.insert(this.actionData);

        if (this.action === 'update') {
          q = q.update(this.actionData);
          this.chain.forEach(s => { (q as any)[s.type](...s.args); });
          return await q;
        }

        if (this.action === 'delete') {
          q = q.delete();
          this.chain.forEach(s => { (q as any)[s.type](...s.args); });
          return await q;
        }

        // Default: select
        this.chain.forEach(s => { (q as any)[s.type](...s.args); });
        return final ? await (q as any)[final]() : await q;
      } catch (err: unknown) {
        console.error(`[DBRouter] Online query failed for table ${this.table}:`, err);

        // Detect network errors (fetch failures)
        const errMsg = (err instanceof Error ? err.message : String(err)).toLowerCase();
        if (errMsg.includes('fetch') || errMsg.includes('network') || errMsg.includes('failed to fetch')) {
          if (typeof window !== 'undefined') {
            window.dispatchEvent(new CustomEvent('db-connection-error'));
          }
        }

        throw err;
      }
    }

    // Otherwise, use SQLite
    return this.executeLocal(final);
  }

  async executeLocal(final: 'single' | 'maybeSingle' | null = null): Promise<DBResponse> {
    try {
      const sqliteDb = await initSQLite();
      if (!sqliteDb) return { data: null, error: 'Database not initialized' };

      if (this.action === 'upsert') return await this._executeLocalUpsert(sqliteDb);
      if (this.action === 'insert') return await this._executeLocalUpsert(sqliteDb); // Reusing upsert for simplicity in local mode
      if (this.action === 'update') return await this._executeLocalUpdate(sqliteDb);
      if (this.action === 'delete') return await this._executeLocalDelete(sqliteDb);

      // Default: select
      let sql = `SELECT * FROM ${this.table}`; // Simplistic, cols not used yet
      const where: string[] = [];
      const params: unknown[] = [];

      this.chain.forEach(s => {
        if (s.type === 'eq') { where.push(`${s.args[0]} = ?`); params.push(s.args[1]); }
        if (s.type === 'neq') { where.push(`${s.args[0]} != ?`); params.push(s.args[1]); }
        if (s.type === 'gt') { where.push(`${s.args[0]} > ?`); params.push(s.args[1]); }
        if (s.type === 'lt') { where.push(`${s.args[0]} < ?`); params.push(s.args[1]); }
        if (s.type === 'gte') { where.push(`${s.args[0]} >= ?`); params.push(s.args[1]); }
        if (s.type === 'lte') { where.push(`${s.args[0]} <= ?`); params.push(s.args[1]); }
        if (s.type === 'in') {
          const arr = (s.args[1] as any[]) || [];
          const marks = arr.map(() => '?').join(',');
          where.push(`${s.args[0]} IN (${marks})`);
          params.push(...arr);
        }
        if (s.type === 'is') {
          if (s.args[1] === null) where.push(`${s.args[0]} IS NULL`);
          else { where.push(`${s.args[0]} IS ?`); params.push(s.args[1]); }
        }
        if (s.type === 'not') {
          const [colNot, opNot, valNot] = s.args as [string, string, unknown];
          if (opNot === 'eq') {
            where.push(`${colNot} <> ?`);
            params.push(valNot);
          } else if (opNot === 'is' && valNot === null) {
            where.push(`${colNot} IS NOT NULL`);
          }
        }
        if (s.type === 'match') {
          Object.entries(s.args[0] as Record<string, unknown>).forEach(([k, v]) => {
            where.push(`${k} = ?`);
            params.push(v);
          });
        }
        if (s.type === 'ilike') {
          where.push(`${s.args[0]} LIKE ?`);
          params.push((s.args[1] as string).replace(/\*/g, '%'));
        }
      });

      if (where.length > 0) sql += ` WHERE ${where.join(' AND ')}`;

      // Order and Limit
      this.chain.forEach(s => {
        if (s.type === 'order') {
          const opts = s.args[1] as { ascending?: boolean };
          sql += ` ORDER BY ${s.args[0]} ${opts.ascending ? 'ASC' : 'DESC'}`;
        }
        if (s.type === 'limit') sql += ` LIMIT ${s.args[0]}`;
      });

      let count: number | undefined = undefined;
      const selectItem = this.chain.find(s => s.type === 'select');
      const selectOpts = (selectItem?.args[1] as { count?: string, head?: boolean }) || {};

      if (selectOpts.count) {
        let countSql = `SELECT COUNT(*) as total FROM ${this.table}`;
        if (where.length > 0) countSql += ` WHERE ${where.join(' AND ')}`;
        const countRes = await queryLocal(countSql, params);
        count = countRes[0]?.total || 0;
      }

      if (selectOpts.head) {
        return { data: [], error: null, count };
      }

      const data = await queryLocal(sql, params);

      // Auto-parse JSON fields (known to be JSON in this project)
      data.forEach((row: Record<string, unknown>) => {
        if (row.save_data && typeof row.save_data === 'string') try { row.save_data = JSON.parse(row.save_data); } catch(_e){ /* ignore */ }
        if (row.team_data && typeof row.team_data === 'string') try { row.team_data = JSON.parse(row.team_data); } catch(_e){ /* ignore */ }
        if (row.data && typeof row.data === 'string') try { row.data = JSON.parse(row.data); } catch(_e){ /* ignore */ }
        if (row.config && typeof row.config === 'string') try { row.config = JSON.parse(row.config); } catch(_e){ /* ignore */ }
        if (row.schedule && typeof row.schedule === 'string') try { row.schedule = JSON.parse(row.schedule); } catch(_e){ /* ignore */ }
      });

      if (final === 'single') return { data: data[0] || null, error: data.length === 0 ? { message: 'Not found' } : null, count };
      if (final === 'maybeSingle') return { data: data[0] || null, error: null, count };
      return { data, error: null, count };
    } catch (e: unknown) {
      console.error(`[ProxyQuery] executeLocal critical failure:`, e);
      return { data: null, error: e };
    }
  }

  async _executeLocalUpsert(sqliteDb: { run: (sql: string, params: unknown[]) => void }): Promise<DBResponse> {
    try {
      const values = Array.isArray(this.actionData) ? this.actionData : [this.actionData];
      for (const row of values) {
        if (typeof row !== 'object' || row === null) continue;
        const r = row as Record<string, unknown>;
        const cols = Object.keys(r);
        const marks = cols.map(() => '?').join(',');
        const vals = cols.map(c => typeof r[c] === 'object' ? JSON.stringify(r[c]) : r[c]);
        sqliteDb.run(`INSERT OR REPLACE INTO ${this.table} (${cols.join(',')}) VALUES (${marks})`, vals);
      }
      await persistSQLite();
      return { data: this.actionData, error: null };
    } catch (e: unknown) {
      console.error(`[ProxyQuery] Upsert/Insert failed for ${this.table}:`, e);
      return { data: null, error: e };
    }
  }

  async _executeLocalUpdate(sqliteDb: { run: (sql: string, params: unknown[]) => void }): Promise<DBResponse> {
    try {
      const data = this.actionData as Record<string, unknown>;
      const setClause = Object.keys(data).map(k => `${k} = ?`).join(',');
      const params: unknown[] = Object.values(data).map(v => typeof v === 'object' ? JSON.stringify(v) : v);

      const where: string[] = [];
      this.chain.forEach(s => {
        if (s.type === 'eq') { where.push(`${s.args[0]} = ?`); params.push(s.args[1]); }
        if (s.type === 'match') {
          Object.entries(s.args[0] as Record<string, unknown>).forEach(([k, v]) => {
            where.push(`${k} = ?`); params.push(v);
          });
        }
      });

      let sql = `UPDATE ${this.table} SET ${setClause}`;
      if (where.length > 0) sql += ` WHERE ${where.join(' AND ')}`;
      sqliteDb.run(sql, params);
      await persistSQLite();
      return { data: this.actionData, error: null };
    } catch (e: unknown) {
      console.error(`[ProxyQuery] Update failed for ${this.table}:`, e);
      return { data: null, error: e };
    }
  }

  async _executeLocalDelete(sqliteDb: { run: (sql: string, params: unknown[]) => void }): Promise<DBResponse> {
    try {
      const params: unknown[] = [];
      const where: string[] = [];
      this.chain.forEach(s => {
        if (s.type === 'eq') { where.push(`${s.args[0]} = ?`); params.push(s.args[1]); }
      });

      let sql = `DELETE FROM ${this.table}`;
      if (where.length > 0) sql += ` WHERE ${where.join(' AND ')}`;
      sqliteDb.run(sql, params);
      await persistSQLite();
      return { data: null, error: null };
    } catch (e: unknown) {
      console.error(`[ProxyQuery] Delete failed for ${this.table}:`, e);
      return { data: null, error: e };
    }
  }
}

/**
 * src/logic/db/sqliteEngine.ts
 * Unified SQL.js (SQLite WASM) Engine with IndexedDB Persistence.
 */
import { getFromIDB, setToIDB } from './idbHelper'
import { TABLES_SCHEMA } from './schema'
import { DATABASE_MIGRATIONS } from './migrations_data'
import { useLoadingStore } from '@/stores/loading'

export interface SQLiteResult {
  columns: string[];
  values: unknown[][];
}

export interface SQLiteDatabase {
  run: (sql: string, params?: unknown[]) => void;
  exec: (sql: string, params?: unknown[]) => SQLiteResult[];
  export: () => Uint8Array;
  prepare: (sql: string) => unknown;
}

let _sqliteDb: SQLiteDatabase | null = null
let _initPromise: Promise<SQLiteDatabase | null> | null = null
let _sqliteKey = 'pokevicio_sqlite_v2'
let _isInMemory = false

export { getFromIDB, setToIDB }

export async function queryLocal(sql: string, params: unknown[] = []): Promise<Record<string, unknown>[]> {
  if (!_sqliteDb) await initSQLite()
  if (!_sqliteDb) return []
  const res = _sqliteDb.exec(sql, params)
  if (!res.length) return []
  return res[0].values.map((row: unknown[]) => {
    const obj: Record<string, unknown> = {}
    res[0].columns.forEach((col: string, i: number) => obj[col] = row[i])
    return obj
  })
}

export async function persistSQLite(): Promise<void> {
  if (!_sqliteDb || _isInMemory) return
  try {
    const binary = _sqliteDb.export()
    await setToIDB(_sqliteKey, binary)
    // Shadow Backup for DB
    await setToIDB(_sqliteKey + '_backup', binary)
    console.log(`[SQLite] Persistence successful (Main + Backup)`)
  } catch (e: unknown) { console.error('[SQLite] Persistence failed', e) }
}

export async function initSQLite(options: { sqliteKey?: string, inMemory?: boolean } = {}): Promise<SQLiteDatabase | null> {
  if (_initPromise) return _initPromise
  _initPromise = (async () => {
    if (options.sqliteKey) _sqliteKey = options.sqliteKey
    if (options.inMemory !== undefined) _isInMemory = options.inMemory

    const SQL = await (window as any).initSqlJs({ locateFile: (file: string) => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.12.0/${file}` })
    let savedBinary = await getFromIDB(_sqliteKey)

    if (!savedBinary) {
      console.warn('[SQLite] Primary database missing, checking Shadow Backup...')
      savedBinary = await getFromIDB(_sqliteKey + '_backup')
      if (savedBinary) {
        console.log('[SQLite] Restored from Shadow Backup!')
      }
    }

    if (savedBinary) {
      try {
        _sqliteDb = new SQL.Database(new Uint8Array(savedBinary)) as unknown as SQLiteDatabase
        console.log('[SQLite] Loaded from IndexedDB')
      } catch (dbErr) {
        console.error('[SQLite] Database corruption detected! Attempting Backup Rescue...', dbErr)
        const backupBinary = await getFromIDB(_sqliteKey + '_backup')
        if (backupBinary) {
          _sqliteDb = new SQL.Database(new Uint8Array(backupBinary)) as unknown as SQLiteDatabase
          console.log('[SQLite] Rescue successful from Backup.')
        } else {
          throw dbErr
        }
      }
    } else {
      _sqliteDb = new SQL.Database() as unknown as SQLiteDatabase
      console.log('[SQLite] Created new in-memory database')
      TABLES_SCHEMA.forEach(schema => { if (_sqliteDb) _sqliteDb.run(`CREATE TABLE IF NOT EXISTS ${schema}`) })
      await persistSQLite()
    }

    await ensureSchemaIntegrity()
    await runMigrations()
    return _sqliteDb
  })()
  return _initPromise
}

async function ensureSchemaIntegrity(): Promise<void> {
  if (!_sqliteDb) return
  console.log('[SQLite] Verifying schema integrity...')

  for (const schemaStr of TABLES_SCHEMA) {
    try {
      const parts = schemaStr.split('(')
      if (parts.length < 2) continue
      const tableName = parts[0]!.replace('CREATE TABLE IF NOT EXISTS', '').trim()
      const info = _sqliteDb!.exec(`PRAGMA table_info(${tableName})`)

      if (!info.length) {
        console.warn(`[SQLite] Table "${tableName}" missing from DB, creating...`)
        _sqliteDb!.run(`CREATE TABLE IF NOT EXISTS ${schemaStr}`)
        continue
      }

      const existingCols = info[0]!.values.map((v: unknown[]) => (v[1] as string).toLowerCase())
      const colPart = schemaStr.substring(schemaStr.indexOf('(') + 1, schemaStr.lastIndexOf(')'))

      const colDefs: string[] = []
      let current = ''
      let depth = 0
      for (let i = 0; i < colPart.length; i++) {
        if (colPart[i] === '(') depth++
        else if (colPart[i] === ')') depth--

        if (colPart[i] === ',' && depth === 0) {
          colDefs.push(current.trim())
          current = ''
        } else {
          current += colPart[i]
        }
      }
      if (current.trim()) colDefs.push(current.trim())

      for (const def of colDefs) {
        const upperDef = def.toUpperCase()
        if (upperDef.startsWith('PRIMARY KEY') || upperDef.startsWith('FOREIGN KEY') || upperDef.startsWith('UNIQUE')) {
          continue
        }

        const colName = def.split(/\s+/)[0]!.toLowerCase()
        if (!existingCols.includes(colName)) {
          console.log(`[SQLite] Auto-repair: Adding missing column "${colName}" to "${tableName}"`)
          try {
            const cleanDef = def.replace(/\s+PRIMARY\s+KEY/gi, '').replace(/\s+AUTOINCREMENT/gi, '')
            _sqliteDb!.run(`ALTER TABLE ${tableName} ADD COLUMN ${cleanDef}`)
          } catch (e: unknown) {
            console.warn(`[SQLite] Auto-repair failed for ${tableName}.${colName}:`, (e as Error).message)
          }
        }
      }
    } catch (e: unknown) {
      console.error(`[SQLite] Error during integrity check for: ${schemaStr}`, e)
    }
  }
  console.log('[SQLite] Schema integrity check complete.')
  await persistSQLite()
}

async function runMigrations(): Promise<void> {
  if (!_sqliteDb) return
  _sqliteDb.run("PRAGMA foreign_keys = OFF") // Disable FKs during structural changes
  _sqliteDb.run("CREATE TABLE IF NOT EXISTS _migrations (id TEXT PRIMARY KEY, applied_at TEXT DEFAULT (datetime('now')))")
  const appliedRes = _sqliteDb.exec("SELECT id FROM _migrations")
  const applied = appliedRes[0]?.values.map((v: unknown[]) => v[0] as string) || []

  const loadingStore = useLoadingStore()

  for (const m of DATABASE_MIGRATIONS as { id: string, sql: string }[]) {
    if (!applied.includes(m.id)) {
      console.log(`[SQLite] Applying migration: ${m.id}`)
      loadingStore.start('db_migration', 'Actualizando Base de Datos...', `Aplicando: ${m.id}`, false)
      try {
        const statements = splitSQLStatements(m.sql)
        statements.forEach(stmt => {
          const sql = translatePostgresToSqlite(stmt)
          if (sql) {
            try {
              if (_sqliteDb) _sqliteDb.run(sql)
            } catch (stmtErr: unknown) {
              const msg = (stmtErr as Error).message.toLowerCase()
              const isDuplicate = msg.includes('duplicate column name') || msg.includes('already exists')
              const isMissing = msg.includes('no such column')

              if (isDuplicate || isMissing) {
                console.warn(`[SQLite] Statement skipped (idempotent/safe): ${stmt}`)
              } else {
                console.error(`[SQLite] Statement failed: ${stmt}`)
                throw stmtErr
              }
            }
          }
        })
        _sqliteDb.run("INSERT OR IGNORE INTO _migrations (id) VALUES (?)", [m.id])
        console.log(`[SQLite] Migration applied successfully: ${m.id}`)
        await persistSQLite()
        loadingStore.finish('db_migration')
      } catch (e: unknown) { 
        loadingStore.finish('db_migration')
        console.error(`[SQLite] Migration ${m.id} failed:`, (e as Error).message) 
      }
    }
  }
  // Update system_config.db_version to match the latest migration
  if (DATABASE_MIGRATIONS.length > 0) {
    const latestId = DATABASE_MIGRATIONS[DATABASE_MIGRATIONS.length - 1]!.id
    const version = parseInt(latestId.split('_')[0] || '0')
    console.log(`[SQLite] Updating system_config.db_version to ${version}`)
    _sqliteDb.run("INSERT OR REPLACE INTO system_config (key, value, updated_at) VALUES ('db_version', ?, datetime('now'))", [version])
  }

  _sqliteDb.run("PRAGMA foreign_keys = ON")
}

/**
 * Splits SQL by semicolon, respecting $$ blocks and strings.
 */
export function splitSQLStatements(sql: string): string[] {
  const statements: string[] = [];
  let current = '';
  let inDollarQuote = false;
  let inString = false;
  let inBlockComment = false;
  let inLineComment = false;

  for (let i = 0; i < sql.length; i++) {
    const char = sql[i];
    const nextChar = sql[i + 1];

    // 1. Handle Line Comments (--)
    if (inLineComment) {
      if (char === '\n') inLineComment = false;
      // If we reached the end of the string without a newline, close the comment
      if (i === sql.length - 1) inLineComment = false; 
      continue;
    }

    // 2. Handle Block Comments (/* */)
    if (inBlockComment) {
      if (char === '*' && nextChar === '/') {
        inBlockComment = false;
        i++;
      }
      continue;
    }

    if (!inDollarQuote && !inString) {
      // Detect start of Line Comment
      if (char === '-' && nextChar === '-') {
        inLineComment = true;
        i++;
        continue;
      }
      // Detect start of Block Comment
      if (char === '/' && nextChar === '*') {
        inBlockComment = true;
        i++;
        continue;
      }

      if (char === '$' && nextChar === '$') {
        inDollarQuote = true;
        current += '$$';
        i++;
        continue;
      }
      if (char === "'") {
        inString = true;
        current += "'";
        continue;
      }
      if (char === ';') {
        if (current.trim()) statements.push(current.trim());
        current = '';
        continue;
      }
    } else if (inDollarQuote) {
      if (char === '$' && nextChar === '$') {
        inDollarQuote = false;
        current += '$$';
        i++;
        continue;
      }
    } else if (inString) {
      if (char === "'" && sql[i-1] !== '\\') {
        inString = false;
        current += "'";
        continue;
      }
    }
    current += char;
  }

  if (current.trim()) statements.push(current.trim());
  return statements.filter(s => s.length > 0);
}

/**
 * Translates common Postgres syntax to SQLite.
 */
export function translatePostgresToSqlite(sql: string): string {
  if (!sql) return '';
  const cleanSql = sql.trim();
  const upperSql = cleanSql.toUpperCase();

  // Logic Skipping for PostgreSQL-only constructs
  const skipPatterns = [
    'CREATE FUNCTION',
    'CREATE OR REPLACE FUNCTION',
    'DO $$',
    'CREATE POLICY',
    'DROP POLICY',
    'ALTER PUBLICATION',
    'COMMENT ON',
    'CREATE TRIGGER',
    'DROP TRIGGER',
    'CREATE EXTENSION',
    'ALTER TABLE PROFILES ENABLE ROW LEVEL SECURITY'
  ];

  if (skipPatterns.some(pattern => upperSql.startsWith(pattern))) {
    console.warn(`[SQLite] Skipping Postgres-only statement: ${cleanSql.substring(0, 50)}...`);
    return '';
  }

  return cleanSql
    .replace(/public\./gi, '')
    // 1. Types & Casts
    .replace(/\bJSONB\b/gi, 'TEXT')
    .replace(/\bUUID\b/gi, 'TEXT')
    .replace(/\bTIMESTAMPTZ\b/gi, 'TEXT')
    .replace(/\bTIMESTAMP\b/gi, 'TEXT')
    .replace(/\bBIGINT\b/gi, 'INTEGER')
    .replace(/\b(BIGSERIAL|SERIAL)\s+PRIMARY\s+KEY\b/gi, 'INTEGER PRIMARY KEY AUTOINCREMENT')
    .replace(/\b(BIGSERIAL|SERIAL)\b/gi, 'INTEGER')
    .replace(/::[a-z0-9]+/gi, '')
    // 2. Functions
    .replace(/\bNOW\(\)/gi, "datetime('now')")
    .replace(/\bgen_random_uuid\(\)/gi, "hex(randomblob(16))")
    .replace(/\bEXTRACT\(epoch\s+FROM\s+([^)]+)\)/gi, "unixepoch($1)")
    .replace(/\bARRAY_AGG\b/gi, "json_group_array")
    .replace(/\bstring_agg\b/gi, "group_concat")
    .replace(/\bjsonb_build_object\b/gi, "json_object")
    .replace(/\bjsonb_set\b/gi, "json_set")
    .replace(/\bjsonb_agg\b/gi, "json_group_array")
    .replace(/\bjsonb_object_agg\b/gi, "json_group_object")
    .replace(/\bjsonb_build_array\b/gi, "json_array")
    .replace(/\bjsonb_array_elements\b/gi, "json_each")
    .replace(/\bjsonb_array_length\b/gi, "json_array_length")
    .replace(/\bto_jsonb\b/gi, "json")
    .replace(/\bjsonb_(\w+)\b/gi, "json_$1")
    .replace(/\bSUBSTRING\b/gi, "SUBSTR")
    // 3. Operators & Constants
    .replace(/\bTRUE\b/gi, '1')
    .replace(/\bFALSE\b/gi, '0')
    .replace(/->>/g, '->>')
    .replace(/->/g, '->')
    // 4. SQL Patterns
    .replace(/FOR\s+UPDATE/gi, '')
    .replace(/DEFAULT\s+datetime\('now'\)/gi, "DEFAULT (datetime('now'))")
    .replace(/DEFAULT\s+hex\(randomblob\(16\)\)/gi, "DEFAULT (hex(randomblob(16)))")
    .replace(/RAISE\s+EXCEPTION\s+'[^']*'/gi, 'SELECT 1')
    .replace(/\bADD\s+COLUMN\s+IF\s+NOT\s+EXISTS\b/gi, 'ADD COLUMN')
    // 5. References & Schemas
    .replace(/REFERENCES\s+auth\.users/gi, 'REFERENCES profiles')
    .trim();
}

export function resetSQLite(): void {
  _sqliteDb = null;
  _initPromise = null;
  _isInMemory = false;
  _sqliteKey = 'pokevicio_sqlite_v2';
}

interface QueryFilter {
  col: string;
  val: unknown;
  op: string;
}

export interface QueryBuilder {
  _table: string;
  _filters: QueryFilter[];
  _limit: number | null;
  _order: string | null;
  _select: string;
  select: (fields: string) => QueryBuilder;
  eq: (col: string, val: unknown) => QueryBuilder;
  neq: (col: string, val: unknown) => QueryBuilder;
  in: (col: string, vals: unknown[]) => QueryBuilder;
  order: (col: string, options?: { ascending?: boolean }) => QueryBuilder;
  limit: (n: number) => QueryBuilder;
  single: () => Promise<{ data: Record<string, unknown> | null, error: string | null }>;
  then: (resolve?: (val: Record<string, unknown>[]) => void) => Promise<Record<string, unknown>[]>;
  insert: (payload: unknown) => Promise<{ data: unknown, error: string | null }>;
  update: (payload: Record<string, unknown>) => Promise<{ data: Record<string, unknown>, error: string | null }>;
  delete: () => Promise<{ data: boolean, error: string | null }>;
  rpc: (_fn: string, _params: unknown) => Promise<{ data: boolean, error: string | null }>;
}

export const db: {
  run: (sql: string, params?: unknown[]) => void;
  exec: (sql: string, params?: unknown[]) => SQLiteResult[];
  prepare: (sql: string) => unknown;
  from: (table: string) => QueryBuilder;
} = {
  run: (sql: string, params: unknown[] = []) => { if (!_sqliteDb) return; _sqliteDb.run(sql, params); persistSQLite() },
  exec: (sql: string, params: unknown[] = []) => { if (!_sqliteDb) return []; return _sqliteDb.exec(sql, params) },
  prepare: (sql: string) => { if (!_sqliteDb) return null; return _sqliteDb.prepare(sql) },
  from: (table: string) => {
    const builder: QueryBuilder = {
      _table: table, 
      _filters: [], 
      _limit: null, 
      _order: null, 
      _select: '*',
      select: (fields: string) => { builder._select = fields; return builder },
      eq: (col: string, val: unknown) => { builder._filters.push({ col, val, op: '=' }); return builder },
      neq: (col: string, val: unknown) => { builder._filters.push({ col, val, op: '!=' }); return builder },
      in: (col: string, vals: unknown[]) => { builder._filters.push({ col, val: vals, op: 'IN' }); return builder },
      order: (col: string, { ascending = true } = {}) => { builder._order = `${col} ${ascending ? 'ASC' : 'DESC'}`; return builder },
      limit: (n: number) => { builder._limit = n; return builder },
      single: async () => {
        const res = await builder.then()
        return { data: res[0] || null, error: null }
      },
      then: async (resolve?: (val: Record<string, unknown>[]) => void) => {
        if (!_sqliteDb) return []
        let sql = `SELECT ${builder._select} FROM ${builder._table}`
        const params: unknown[] = []
        if (builder._filters.length) {
          sql += ' WHERE ' + builder._filters.map((f: QueryFilter) => {
            if (f.op === 'IN') {
              const placeholders = (f.val as unknown[]).map(() => '?').join(',');
              (f.val as unknown[]).forEach((v) => params.push(v));
              return `${f.col} IN (${placeholders})`
            }
            params.push(f.val)
            return `${f.col} ${f.op} ?`
          }).join(' AND ')
        }
        if (builder._order) sql += ` ORDER BY ${builder._order}`
        if (builder._limit) sql += ` LIMIT ${builder._limit}`

        const res = _sqliteDb.exec(sql, params)
        const data = res[0] ? res[0].values.map((row: unknown[]) => {
          const obj: Record<string, unknown> = {}
          res[0].columns.forEach((col: string, i: number) => obj[col] = row[i])
          return obj
        }) : []
        if (resolve) resolve(data)
        return data
      },
      insert: async (payload: unknown) => {
        if (!_sqliteDb) return { data: null, error: 'DB not ready' }
        const items = Array.isArray(payload) ? payload : [payload]
        for (const item of items) {
          if (typeof item !== 'object' || item === null) continue;
          const r = item as Record<string, unknown>;
          const cols = Object.keys(r)
          const vals = Object.values(r)
          const sql = `INSERT INTO ${builder._table} (${cols.join(',')}) VALUES (${cols.map(() => '?').join(',')})`
          _sqliteDb.run(sql, vals)
        }
        await persistSQLite()
        return { data: payload, error: null }
      },
      update: async (payload: Record<string, unknown>) => {
        if (!_sqliteDb) return { data: null, error: 'DB not ready' }
        const cols = Object.keys(payload)
        const vals = Object.values(payload)
        let sql = `UPDATE ${builder._table} SET ` + cols.map(c => `${c} = ?`).join(',')
        const params = [...vals]
        if (builder._filters.length) {
          sql += ' WHERE ' + builder._filters.map((f: QueryFilter) => { params.push(f.val); return `${f.col} ${f.op} ?` }).join(' AND ')
        }
        _sqliteDb.run(sql, params)
        await persistSQLite()
        return { data: payload, error: null }
      },
      delete: async () => {
        if (!_sqliteDb) return { data: null, error: 'DB not ready' }
        let sql = `DELETE FROM ${builder._table}`
        const params: unknown[] = []
        if (builder._filters.length) {
          sql += ' WHERE ' + builder._filters.map((f: QueryFilter) => { params.push(f.val); return `${f.col} ${f.op} ?` }).join(' AND ')
        }
        _sqliteDb.run(sql, params)
        await persistSQLite()
        return { data: true, error: null }
      },
      rpc: async (_fn: string, _params: unknown) => {
        // Mock RPC for local mode
        return { data: true, error: null }
      }
    }
    return builder
  }
}

