/**
 * Service for administrative and debug operations related to Pokémon.
 * CLI-First implementation.
 */
export const pokemonDebugService = {
  /**
   * Generates a custom pokemon object with specific overrides.
   */
  generate(params: GenerateParams = {}): Pokemon {
    const {
      id = 'pidgey',
      level = 5,
      ivs = null,
      isShiny = false,
      isGuardian = false,
      nature = null,
      ability = null,
      gender = null,
      moves = null,
      nickname = null,
      friendship = 70,
      heldItem = null
    } = params;

    // 1. Create base instance
    const p = makePokemon(id, level, { isShiny, nature, ability, gender, heldItem }) as Pokemon;

    // 2. Apply Overrides
    if (ivs) {
      p.ivs = { ...p.ivs, ...ivs };
    }

    if (isGuardian) p.isGuardian = true;
    if (nickname) p.nickname = nickname;
    if (friendship !== undefined) p.friendship = friendship;

    // 3. Handle Moves
    if (moves && Array.isArray(moves)) {
      p.moves = moves.map((mName: string) => {
        const mData = pokemonDataProvider.getMoveData(mName)
        return { 
          name: mName || '???', 
          pp: mData?.pp || 35, 
          maxPP: mData?.pp || 35,
          type: mData?.type || 'normal',
          power: mData?.power || 0,
          acc: mData?.acc || 100,
          cat: (mData?.cat || 'physical') as 'physical' | 'special' | 'status'
        };
      }).slice(0, 4);
    }

    // 4. Final Recalc
    recalcPokemonStats(p);
    p.hp = p.maxHp;
    p.expNeeded = getExpNeeded(p.level);

    return p;
  },

  /**
   * Adds the pokemon to the state using a specific protocol.
   */
  async executeProtocol(p: Pokemon, protocol: string = 'catch'): Promise<void> {
    const game = useGameStore();
    const ui = useUIStore();
    const animationsEnabled = ui.debugAnimationsEnabled ?? true;

    console.log(`[DEBUG] Executing ${protocol.toUpperCase()} protocol for ${p.name}`);

    switch (protocol) {
      case 'catch':
        // Protocol: Standard catch (wild origin)
        p.obtainedMethod = 'wild';
        game.addPokemon(p, { notify: !animationsEnabled });

        if (animationsEnabled) {
          ui.notify(`[DEBUG] Pokémon atrapado: ${p.name}`, '✨');
        }
        break;

      case 'hatch':
      case 'egg_silent': {
        // Protocol: Add UNHATCHED egg to inventory
        const eggForInventory: Partial<EggData> = {
          uid: `egg_${Date.now()}`,
          id: p.id,
          name: 'Huevo Pokémon',
          isEgg: true,
          steps: 100, // Low steps for quick debug testing
          ivs: p.ivs,
          nature: p.nature,
          movesAtBirth: p.moves.map(m => m?.name || '???'),
          abilitySlot: (p as any).abilityIndex || 0,
          isShiny: p.isShiny,
          isGuardian: p.isGuardian
        };

        const state = game.state as Record<string, any>;
        const key = `${p.id}TicketSecs`;
        if (state[key] !== undefined) {
          state[key] = (state[key] || 0) + 12 * 3600;
        }

        if (!game.state.eggs) game.state.eggs = [];
        const eggToPush: EggData = {
          ...(eggForInventory as any),
          uid: `${eggForInventory.id}-${Date.now()}`,
          ready: false
        };
        game.state.eggs.push(eggToPush as any);
        ui.notify(`[DEBUG] Huevo de ${p.name} añadido a la mochila`, '🥚');
        break;
      }

      case 'hatch_anim':
      case 'egg_anim':
        // Protocol: Visual hatching sequence (VUE MIGRATED)
        p.obtainedMethod = 'egg';

        // Add to game state silently first
        game.addPokemon(p, { notify: false });

        // Trigger Vue Modal Sequence
        ui.open('HatchAnimation', { pokemon: p });
        break;

      default:
        console.error(`[DEBUG] Unknown protocol: ${protocol}`);
    }

    await game.save(false);
  },

  /**
   * Starts a custom encounter.
   */
  async triggerEncounter(p: Pokemon, mapId: string = 'plains'): Promise<void> {
    const battleStore = useBattleStore();
    // const _ui = useUIStore();

    // 1. Force flee if there's an active battle
    if (battleStore.isBattleActive) {
      console.warn('[DEBUG] Combate activo detectado. Forzando huida del anterior para iniciar el nuevo...');
      await battleStore.endBattle(false, true);
    }

    console.log(`[DEBUG] Triggering encounter with ${p.name} at ${mapId}`);

    // Register as seen
    const game = useGameStore();
    game.registerPokedex(p.id, false);

    // Start battle
    await battleStore._startBattle(p, { 
      locationId: mapId,
      battleOptions: { isDebug: true }
    });

    const modalStore = useModalStore();
    modalStore.closeAll();
  }
};

import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider';
import { GAME_RATIOS } from '@/data/constants';
import { makePokemon } from '@/logic/pokemonFactory';
import { getDayCycle } from '@/logic/timeUtils';
import { isDisputePhase } from '@/logic/war/warEngine';
import { getGuardianData, GUARDIAN_CHANCE } from '@/logic/war/guardianEngine';
import { applyEncounterBonuses } from '@/logic/war/bonusEngine';
import { useEventStore } from '@/stores/events';
import type { Pokemon } from '@/types/pokemon';
import type { MapLocation, Encounter, EncounterOptions, EncounterState } from '@/types/encounters';

const WEATHER_BUFF_MULTIPLIER = 1.5;

/**
 * Determina si una especie recibe el buff del clima actual basado en sus tipos.
 */
function isSpeciesBoosted(id: string, weather: string): boolean {
  const pData = pokemonDataProvider.getPokemonData(id);
  if (!pData || !weather || weather === 'clear') return false;

  const types = Array.isArray(pData.type) ? pData.type : [pData.type];
  const w = weather.toLowerCase();

  const weatherBoosts: Record<string, string[]> = {
    rain: ['water', 'bug', 'grass'],
    storm: ['electric', 'dragon'],
    sun: ['fire', 'grass'],
    snow: ['ice', 'steel'],
    sandstorm: ['rock', 'ground', 'steel'],
    fog: ['ghost', 'psychic', 'dark'],
    heatwave: ['fire']
  };

  const boostedTypes = weatherBoosts[w] || [];
  return types.some((t: string) => boostedTypes.includes(t.toLowerCase()));
}


/**
 * Gets the valid pool of Pokémon for a location and time cycle.
 * Incorporates active events.
 */
export function getEncounterPool(loc: MapLocation, cycle: string, weather: string = 'clear', activeEvents: any[] = []) {
  if (!loc || !loc.wild) return { pool: [] as string[], rates: [] as number[] };

  const pool = [...(loc.wild[cycle] || loc.wild.day || [])];
  const rates = [...((loc.rates && (loc.rates[cycle] || loc.rates.day)) ? (loc.rates[cycle] || loc.rates.day) : []) as number[]];

  // Ensure rates match pool length before transformations
  while (rates.length < pool.length) rates.push(10);

  // 1. Inyección por Clima (Visitantes y Exclusivos)
  if (weather && weather !== 'clear' && loc.weather?.[weather]) {
    const wConfig = loc.weather[weather];

    // Especies Exclusivas (Pesos dinámicos o base 5)
    if (wConfig.exclusive) {
      const exclusives = Array.isArray(wConfig.exclusive) ? wConfig.exclusive : Object.keys(wConfig.exclusive);
      exclusives.forEach(id => {
        if (!pool.includes(id)) {
          pool.push(id);
          const weight = Array.isArray(wConfig.exclusive) ? 5 : ((wConfig.exclusive as Record<string, number>)[id] || 5);
          rates.push(weight); 
        }
      });
    }

    // Visitantes (Marcados con peso negativo para normalización proporcional)
    if (wConfig.visitors) {
      const visitors = Array.isArray(wConfig.visitors) ? wConfig.visitors : Object.keys(wConfig.visitors);
      visitors.forEach(id => {
        if (!pool.includes(id)) {
          pool.push(id);
          const weight = Array.isArray(wConfig.visitors) ? -10 : -((wConfig.visitors as Record<string, number>)[id] || 10);
          rates.push(weight); 
        }
      });
    }

  }

  // 2. Apply Event Injections
  activeEvents.forEach(ev => {
    if (ev.active && ev.config?.ignoreTimeRestrictions && ev.config.species) {
      const eventSpecies = ev.config.species.split(',').map((s: string) => s.trim().toLowerCase());
      eventSpecies.forEach((spId: string) => {
        if (!pool.includes(spId)) {
          // Check if species exists in other cycles for this map
          for (const c in loc.wild) {
            const cyclePool = (loc.wild as any)[c];
            if (!cyclePool) continue;
            const idx = cyclePool.indexOf(spId);
            if (idx !== -1) {
              pool.push(spId);
              const originalRates = (loc.rates as any)?.[c] || [];
              rates.push(originalRates[idx] || 10);
              break;
            }
          }
        }
      });
    }
  });

  return { pool, rates };
}


/**
 * Selects a random Pokémon ID from a pool using weights.
 */
export function selectFromPool(pool: string[], rates: number[]): string {
  if (!pool.length) return '';
  const totalRate = rates.reduce((a, b) => a + b, 0);
  const rand = Math.random() * totalRate;
  let cumulative = 0;

  for (let i = 0; i < pool.length; i++) {
    cumulative += rates[i] || 0;
    if (rand <= cumulative) return pool[i] || '';
  }
  return pool[0] || '';
}

/**
 * Main logic to generate a wild encounter.
 * Handles repellent, incense, fishing, and specialty spawns.
 */
export async function generateEncounter(locId: string, state: EncounterState, options: EncounterOptions = {}): Promise<Encounter | null> {
  const maps = pokemonDataProvider.getMaps() as unknown as MapLocation[];
  const loc = maps.find(l => l.id === locId);
  if (!loc) return null;

  const cycle = getDayCycle();
  const eventStore = useEventStore() as { activeEvents: any[] };
  const activeEvents = options.activeEvents || (eventStore.activeEvents || []) || [];
  const allMapIds = maps.map(m => m.id);

  // 1. Especial: Fase de Dominancia (Finde) - Batallas de Defensores
  if (!isDisputePhase() && !options.forceEncounter) {
    // Chance de encontrar defensor (20% normal)
    if (Math.random() < 0.20 && state.faction) {
      // Determinamos si el mapa está dominado por el enemigo
      const winner = (options.dominanceData || {})[locId];
      if (winner && winner !== state.faction) {
        return { type: 'defender', faction: winner };
      }
    }
  }

  // 2. Especial: Guardianes (Pokémon Alfa)
  const guardian = getGuardianData(locId, allMapIds);
  if (guardian && !options.forceEncounter) {
    // Verificar si ya fue capturado hoy
    const capturedToday = (state.dailyGuardianCaptures || []).includes(locId);
    if (!capturedToday && Math.random() < GUARDIAN_CHANCE) {
      return { 
        type: 'guardian', 
        pokemon: makePokemon(guardian.id, guardian.lv, { shinyMultiplier: options.shinyMultiplier }) as Pokemon,
        pts: guardian.pts
      };
    }
  }

  // 3. Repellent Logic
  const repellentActive = (state.repelSecs || 0) > 0;
  const firstPokemon = state.team?.[0];

  if (repellentActive && !options.forceEncounter) {
    if (Math.random() < GAME_RATIOS.encounters.trainerRepel) {
      return { type: 'trainer' };
    }

    const weather = options.weather || 'clear';
    const { pool, rates: rawRates } = getEncounterPool(loc, cycle, weather, activeEvents);

    // Normalizar pesos para Repelente
    const rates = rawRates.map(r => r === -1 ? 5 : r); 

    // Find a pokemon with level >= firstPokemon.level
    for (let attempt = 0; attempt < 10; attempt++) {
      const selectedId = selectFromPool(pool, rates);
      const minLv = loc.lv[0] || 2;
      const maxLv = loc.lv[1] || 5;
      const level = Math.floor(Math.random() * (maxLv - minLv + 1)) + minLv;

      if (!firstPokemon || level >= firstPokemon.level) {
        return { type: 'wild', pokemon: makePokemon(selectedId, level, { shinyMultiplier: options.shinyMultiplier }) as Pokemon };
      }
    }
    return { type: 'trainer' }; // Fallback to trainer
  }

  // 2. Base Trainer Chance
  const trainerBonus = options.eventTrainerBonus || 1;
  const tChance = Math.min(state.trainerChance || GAME_RATIOS.encounters.trainerBase, GAME_RATIOS.encounters.trainerMax) * trainerBonus;
  if (!options.forceEncounter && Math.random() * 100 < tChance) {
    return { type: 'trainer' };
  }

  // 3. Fishing Chance (if applicable)
  const fishingBonus = options.eventFishingBonus || 1;
  if (loc.fishing && Math.random() < GAME_RATIOS.encounters.fishing * fishingBonus) {
    const { pool, rates } = loc.fishing;
    const selectedId = selectFromPool(pool, rates);
    const minLv = loc.fishing.lv[0] || 10;
    const maxLv = loc.fishing.lv[1] || 20;
    const level = Math.floor(Math.random() * (maxLv - minLv + 1)) + minLv;
    const totalRate = rates.reduce((a, b) => a + b, 0);
    const rateIdx = pool.indexOf(selectedId);
    const rateVal = rates[rateIdx];
    const rarity = ((rateVal !== undefined ? rateVal : 0) / (totalRate || 1)) * 100;

    return { 
      type: 'fishing', 
      pokemon: makePokemon(selectedId, level, { shinyMultiplier: options.shinyMultiplier }) as Pokemon,
      rarity 
    };
  }

  // 4. Wild Pokemon Pool Selection (Normal)
  const weather = options.weather || 'clear';
  let { pool, rates } = getEncounterPool(loc, cycle, weather, activeEvents);

  // 4.1 Lógica de Clima: Multiplicadores e Invasiones
  if (weather && weather !== 'clear') {
    const visitorIndices = rates.map((r, i) => r < 0 ? i : -1).filter(i => i !== -1);
    const nativeIndices = rates.map((r, i) => r >= 0 ? i : -1).filter(i => i !== -1);

    // Buff x1.5 a nativos que coinciden con el clima
    nativeIndices.forEach(idx => {
      const spId = pool[idx];
      if (spId && isSpeciesBoosted(spId, weather)) {
        rates[idx] = (rates[idx] || 0) * WEATHER_BUFF_MULTIPLIER;
      }
    });

    // Normalización Proporcional de Visitantes (10% del peso total)
    if (visitorIndices.length > 0) {
      const totalNativeWeight = nativeIndices.reduce((sum, idx) => sum + (rates[idx] || 0), 0);
      const visitorQuota = totalNativeWeight / 9; // 10% del total final

      // Calculamos la suma de los pesos relativos (valores absolutos de los pesos negativos)
      const sumRelativeWeights = visitorIndices.reduce((sum, idx) => sum + Math.abs(rates[idx] || 0), 0);

      visitorIndices.forEach(idx => {
        const relativeWeight = Math.abs(rates[idx] || 0) / (sumRelativeWeights || 1);
        rates[idx] = visitorQuota * relativeWeight;
      });
    }
  }

  // 5. Incense Effect
  if (state.incenseSecs && state.incenseSecs > 0 && state.incenseType) {
    const typeIndices = pool.map((id, idx) => {
      const pData = pokemonDataProvider.getPokemonData(id);
      return (pData && (pData.type === state.incenseType || pData.type2 === state.incenseType)) ? idx : -1;
    }).filter(idx => idx !== -1);

    if (typeIndices.length > 0) {
      pool = typeIndices.map(idx => pool[idx]).filter((id): id is string => id !== undefined);
      rates = typeIndices.map(idx => rates[idx]).filter((r): r is number => r !== undefined);
    }
  }

  // 6. Final Select
  const selectedId = selectFromPool(pool, rates);
  const minLv = loc.lv[0] || 2;
  const maxLv = loc.lv[1] || 5;
  const level = Math.floor(Math.random() * (maxLv - minLv + 1)) + minLv;

  const pokemon = makePokemon(selectedId, level, { shinyMultiplier: options.shinyMultiplier }) as Pokemon;
  if (!pokemon) return null;

  // Marcar si es atmosférico para efectos visuales posteriores
  const weatherCfg = loc.weather?.[weather];
  const isVisitor = !!(weatherCfg?.visitors && (
    (!Array.isArray(weatherCfg.visitors) && (weatherCfg.visitors as Record<string, number>)[selectedId]) || 
    (Array.isArray(weatherCfg.visitors) && weatherCfg.visitors.includes(selectedId))
  ));
  const isExclusive = !!(weatherCfg?.exclusive && (
    (!Array.isArray(weatherCfg.exclusive) && (weatherCfg.exclusive as Record<string, number>)[selectedId]) || 
    (Array.isArray(weatherCfg.exclusive) && weatherCfg.exclusive.includes(selectedId))
  ));

  const isBuffed = !isVisitor && !isExclusive && isSpeciesBoosted(selectedId, weather);

  if (isVisitor || isExclusive || isBuffed) {
    pokemon.isAtmospheric = true;
    pokemon.weatherOrigin = weather;
  }


  // 7. Apply War Dominance Bonuses
  return { 
    type: 'wild', 
    pokemon: applyEncounterBonuses(pokemon, locId, state.faction, options.dominanceData) 
  };
}

/**
 * Event Engine - Global Event Logic
 * Handles scheduled intervals, bonus multipliers, and competition validation.
 * 
 * Absolute isolation: This module does not store state or connect to DB.
 */

export interface EventConfig {
  expMult?: number;
  moneyMult?: number;
  bcMult?: number;
  shinyMult?: number;
  eggShinyMult?: number;
  hatchMult?: number;
  rivalMult?: number;
  trainerMult?: number;
  fishingMult?: number;
  species?: string;
  speciesRateMult?: number;
  speciesShinyMult?: number;
  ignoreTimeRestrictions?: boolean;
  banner?: string;
}

export interface Event {
  id: string;
  name: string;
  description: string;
  type?: 'competition' | 'boost' | string;
  icon?: string;
  active: boolean;
  manual?: boolean;
  start_at?: string;
  ends_at?: string;
  schedule?: string | any;
  config?: string | EventConfig;
}

const safeParse = (val: any): any => {
  if (typeof val === 'string') {
    try { return JSON.parse(val); } catch (_e) { return {}; }
  }
  return val || {};
};


/**
 * Checks if an event is active based on current time (America/Argentina/Buenos_Aires).
 */
export function isEventActiveNow(event: Event, date: Date = new Date()): boolean {
  if (!event.active) return false
  if (event.manual) return true

  // 1. Absolute date check
  if (event.start_at && event.ends_at) {
    const start = new Date(event.start_at)
    const end = new Date(event.ends_at)
    if (date >= start && date <= end) return true
  }

  // 2. Weekly schedule check (Argentina Time UTC-3)
  const sched = safeParse(event.schedule)
  if (!sched || sched.type !== 'weekly' || !sched.days) return false

  // Convert current date to Argentina Time
  const argTime = new Date(date.toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' }))
  const day = argTime.getDay()
  const hour = argTime.getHours() + argTime.getMinutes() / 60

  // Check if today is one of the scheduled days
  const isScheduledToday = (sched.days as number[]).includes(day)

  // Check if yesterday was one of the scheduled days (for midnight crossover)
  const yesterday = (day + 6) % 7
  const isScheduledYesterday = (sched.days as number[]).includes(yesterday)

  const start = sched.startHour ?? 0
  const end = sched.endHour ?? 24

  if (start < end) {
    // Normal range (e.g., 10 to 18)
    if (isScheduledToday && hour >= start && hour < end) return true
  } else {
    // Midnight crossover (e.g., 22 to 02)
    // 1. Current day after start (e.g., Monday 23:00)
    if (isScheduledToday && hour >= start) return true
    // 2. Next day before end (e.g., Tuesday 01:00)
    if (isScheduledYesterday && hour < end) return true
  }

  return false
}

/**
 * Calculates global multipliers from a list of active events.
 */
export function getGlobalMultipliers(activeEvents: Event[]): any {
  const multipliers: any = {
    exp: 1,
    money: 1,
    bc: 1,
    shiny: 1,
    eggShiny: 1,
    hatch: 1,
    rival: 1,
    trainer: 1,
    fishing: 1
  }

  for (const ev of activeEvents) {
    const cfg = safeParse(ev.config) as EventConfig;
    multipliers.exp *= (cfg.expMult || 1)
    multipliers.money *= (cfg.moneyMult || 1)
    multipliers.bc *= (cfg.bcMult || 1)
    multipliers.shiny *= (cfg.shinyMult || 1)
    multipliers.eggShiny *= (cfg.eggShinyMult || 1)
    multipliers.hatch *= (cfg.hatchMult || 1)
    multipliers.rival *= (cfg.rivalMult || 1)
    multipliers.trainer *= (cfg.trainerMult || 1)
    multipliers.fishing *= (cfg.fishingMult || 1)
  }

  return multipliers
}

/**
 * Checks if a specific species has active boosts.
 */
export function getSpeciesBoosts(activeEvents: Event[], speciesId: string): { rate: number; shiny: number } {
  let rateMult = 1
  let shinyMult = 1
  const sId = speciesId.toLowerCase()

  for (const ev of activeEvents) {
    const cfg = safeParse(ev.config) as EventConfig;
    if (!cfg.species) continue

    const speciesList = cfg.species.split(',').map(s => s.trim().toLowerCase())
    if (speciesList.includes(sId)) {
      rateMult *= (cfg.speciesRateMult || 1)
      shinyMult *= (cfg.speciesShinyMult || 1)
    }
  }

  return { rate: rateMult, shiny: shinyMult }
}

/**
 * Validates if the new entry is better for a competition.
 * @param {string} sortBy (e.g., 'data.total_ivs', 'data.level')
 */
export function isNewEntryBetter(existingData: any, newData: any, sortBy: string = 'data.total_ivs'): boolean {
  if (!existingData) return true

  const getVal = (obj: any, path: string): number => {
    return path.split('.').reduce((acc, part) => acc && acc[part], obj) || 0
  }

  const oldScore = getVal(existingData, sortBy)
  const newScore = getVal(newData, sortBy)

  return newScore > oldScore
}

import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider';
import { EVOLUTION_TABLE, STONE_EVOLUTIONS, TRADE_EVOLUTIONS } from '@/data/evolutionData';
import { recalcPokemonStats } from '@/logic/pokemonFactory';
import type { Pokemon, PokemonMove } from '@/types/pokemon';
import type { PokemonData, LearnsetMove } from '@/types/database';

/**
 * Realiza la evolución de los datos de un Pokémon.
 * @returns {Object} { pendingMoves, fromId, toId }
 */
export function evolvePokemonData(pokemon: Pokemon, toId: string) {
  const toData: PokemonData | null = pokemonDataProvider.getPokemonData(toId);
  if (!toData) return null;

  const fromId = pokemon.id;
  const oldMaxHp = pokemon.maxHp;

  // Actualizar especie
  pokemon.id = toId;
  pokemon.name = toData.name;
  if (toData.emoji) pokemon.emoji = toData.emoji;
  pokemon.type = toData.type;

  // Actualizar habilidad si no es compatible
  const abilityList = pokemonDataProvider.getSpeciesAbilities(toId);
  if (!pokemon.ability || !abilityList.includes(pokemon.ability)) {
    pokemon.ability = abilityList[Math.floor(Math.random() * abilityList.length)];
  }

  // Recalcular stats
  recalcPokemonStats(pokemon);
  // Sanar proporcionalmente
  pokemon.hp = Math.min(pokemon.hp + (pokemon.maxHp - oldMaxHp), pokemon.maxHp);

  // Movimientos pendientes del nuevo learnset para el nivel actual
  const pendingMoves: PokemonMove[] = [];
  if (toData.learnset) {
    (toData.learnset as LearnsetMove[]).filter(m => m.lv === pokemon.level).forEach(m => {
      if (!pokemon.moves.find(em => em && em.name === m.name)) {
        pendingMoves.push({ name: m.name, pp: m.pp, maxPP: m.pp });
      }
    });
  }

  return { pendingMoves, fromId, toId };
}

/**
 * Comprueba si un Pokémon puede evolucionar por nivel.
 */
export function checkLevelUpEvolution(pokemon: Pokemon): string | null {
  // Tyrogue special case
  if (pokemon.id === 'tyrogue' && pokemon.level >= 20) {
    const toId = pokemon.atk > pokemon.def ? 'hitmonlee' : 
                 (pokemon.def > pokemon.atk ? 'hitmonchan' : 
                 (Math.random() < 0.5 ? 'hitmonlee' : 'hitmonchan'));
    return toId;
  }

  const evo = (EVOLUTION_TABLE as Record<string, { level: number; to: string }>)[pokemon.id];
  if (!evo || pokemon.level < evo.level) return null;
  if (evo.to === pokemon.id) return null;

  if (!pokemonDataProvider.getPokemonData(evo.to)) return null;
  return evo.to;
}

/**
 * Comprueba si un Pokémon puede evolucionar por intercambio.
 */
export function checkTradeEvolution(pokemon: Pokemon): string | null {
  const toId = (TRADE_EVOLUTIONS as Record<string, string>)[pokemon.id];
  if (!toId || !pokemonDataProvider.getPokemonData(toId)) return null;
  return toId;
}

/**
 * Obtiene la forma evolucionada ideal para un nivel dado (backtracking hasta base).
 */
export function getEvolvedForm(id: string, level: number): string {
  // 1. Build reverse map to find base form
  const PRE_EVO: Record<string, string> = {};
  for (const [from, data] of Object.entries(EVOLUTION_TABLE)) {
    PRE_EVO[data.to] = from;
  }
  for (const [from, data] of Object.entries(STONE_EVOLUTIONS)) {
    if (!PRE_EVO[(data as any).to]) PRE_EVO[(data as any).to] = from;
  }
  for (const [from, to] of Object.entries(TRADE_EVOLUTIONS)) {
     if (!PRE_EVO[to]) PRE_EVO[to] = from;
  }

  // 2. Backtrack to the very first base form
  let current = id;
  while (PRE_EVO[current]) {
    current = PRE_EVO[current] || current;
  }

  // 3. Evolve forward as much as level permits
  let evolved = current;
  let canEvolve = true;
  while (canEvolve) {
    let changed = false;

    // Level Evolution
    const levelEvo = (EVOLUTION_TABLE as Record<string, { level: number; to: string }>)[evolved];
    if (levelEvo && level >= levelEvo.level) {
      evolved = levelEvo.to;
      changed = true;
    } 

    // Stone Evolution (50% chance if level >= 30)
    if (!changed && level >= 30 && Math.random() < 0.5) {
      if (evolved === 'eevee') {
        const options = ['vaporeon', 'jolteon', 'flareon'];
        evolved = options[Math.floor(Math.random() * options.length)] || evolved;
        changed = true;
      } else {
        const stoneEvo = (STONE_EVOLUTIONS as Record<string, { stone: string; to: string }>)[evolved];
        if (stoneEvo) {
          evolved = stoneEvo.to;
          changed = true;
        }
      }
    }

    // Trade Evolution (50% chance if level >= 32)
    if (!changed && level >= 32 && Math.random() < 0.5) {
      const tradeEvo = (TRADE_EVOLUTIONS as Record<string, string>)[evolved];
      if (tradeEvo) {
        evolved = tradeEvo;
        changed = true;
      }
    }

    if (!changed) canEvolve = false;
  }
  return evolved;
}

/**
 * Comprueba si un Pokémon puede evolucionar con una piedra específica.
 */
export function checkStoneEvolution(pokemon: Pokemon, stoneName: string): string | null {
  const evo = (STONE_EVOLUTIONS as Record<string, { stone: string; to: string }>)[pokemon.id];
  if (!evo) {
    // Eevee special handling in evolutionData keys?
    // eevee_water, eevee_thunder, eevee_fire
    if (pokemon.id === 'eevee') {
      if (stoneName === 'Piedra Agua') return 'vaporeon';
      if (stoneName === 'Piedra Trueno') return 'jolteon';
      if (stoneName === 'Piedra Fuego') return 'flareon';
    }
    return null;
  }

  return (evo.stone === stoneName) ? evo.to : null;
}

/**
 * gameBus.ts
 * A simple global event bus to decouple logic from visual components.
 * Replaces the old PhaserBridge to remove all engine dependencies.
 */
class GameBus extends EventTarget {
  emit(event: string, detail: any = {}): void {
    this.dispatchEvent(new CustomEvent(event, { detail }))
  }

  on(event: string, callback: EventListenerOrEventListenerObject): void {
    this.addEventListener(event, callback)
  }

  off(event: string, callback: EventListenerOrEventListenerObject): void {
    this.removeEventListener(event, callback)
  }

  // Compatibility method for the old bridge
  sendCommand(_scene: string, command: string, payload: any): void {
    // For now, we just emit the command as a global event
    this.emit(command, payload)
  }
}

export const gameBus = new GameBus()

/**
 * src/logic/gym/gymEngine.ts
 * Logic for Gym rewards, rematches, and progress.
 */

export interface Gym {
  id: string;
  leader: string;
  rewardTM?: string;
  level?: number;
}

export const GYM_RATIOS = {
  rematchTMRateNormal: 0.03,
  rematchTMRateHard: 0.05
};

import type { GameState } from '@/types/game';

/**
 * Calculates the rewards for a gym battle.
 * @param {Gym} gym - Gym definition (id, leader, rewardTM, etc.)
 * @param {string} difficulty - 'easy' | 'normal' | 'hard'
 * @param {GameState} state - Current player state
 * @returns {any} { newInventory, extraCoins, tmDropped, newProgress }
 */
export function processGymVictory(gym: Gym, difficulty: 'easy' | 'normal' | 'hard', state: GameState): any {
  const diffMap: Record<string, number> = { easy: 1, normal: 2, hard: 3 };
  const diffValue = diffMap[difficulty] || 1;
  const isFirstTime = !state.defeatedGyms.includes(gym.id);

  let tmDropped = false;
  let extraCoins = 0;
  let newProgress = 0;
  const currentEntry = state.gymProgress?.[gym.id];
  if (typeof currentEntry === 'number') newProgress = currentEntry;
  else if (currentEntry && typeof currentEntry === 'object') newProgress = currentEntry.attempts || 0; // Fallback to attempts or similar if it was object

  if (isFirstTime) {
    tmDropped = !!gym.rewardTM;
    newProgress = Math.max(newProgress, diffValue);
  } else {
    // Rematch logic
    extraCoins = diffValue * 150;

    let tmChance = 0;
    if (difficulty === 'normal') tmChance = GYM_RATIOS.rematchTMRateNormal;
    else if (difficulty === 'hard') tmChance = GYM_RATIOS.rematchTMRateHard;

    if (tmChance > 0 && Math.random() < tmChance) {
      tmDropped = !!gym.rewardTM;
    }

    newProgress = Math.max(newProgress, diffValue);
  }

  return {
    tmDropped,
    extraCoins,
    newProgress,
    isFirstTime
  };
}

