export interface MarketListing {
  id: string;
  listing_type: 'pokemon' | 'item';
  price: number;
  data: any;
  seller_id: string;
  created_at: string;
}

export interface MarketFilters {
  mode: 'pokemon' | 'item';
  search: string;
  priceMin: number;
  priceMax: number;
  tier: string;
  type: string;
  levelMin: number;
  levelMax: number;
  ivTotalMin: number;
  ivTotalMax: number;
  ivAny31: boolean;
  itemCat: string;
}

export function ensureMarketSoldSeenState(state: any): string[] {
  if (!Array.isArray(state.marketSoldSeenIds)) state.marketSoldSeenIds = [];
  state.marketSoldSeenIds = [...new Set(
    (state.marketSoldSeenIds as string[])
      .filter((id) => typeof id === 'string' && id.trim().length > 0)
  )].slice(-250);
  return state.marketSoldSeenIds;
}

export function isMarketSoldSeen(listingId: string, state: any): boolean {
  if (!listingId) return true;
  return ensureMarketSoldSeenState(state).includes(listingId);
}

export function markMarketSoldSeen(listingId: string, state: any): void {
  if (!listingId) return;
  const seen = ensureMarketSoldSeenState(state);
  if (seen.includes(listingId)) return;
  seen.push(listingId);
  state.marketSoldSeenIds = seen.slice(-250);
}

export function buildMarketSaleLabel(listing: MarketListing): string {
  if (!listing) return 'una publicación';
  if (listing.listing_type === 'pokemon') {
    return `tu Pokémon ${listing.data?.name || ''}`.trim();
  }
  const qty = Math.max(1, parseInt(listing.data?.qty, 10) || 1);
  const itemName = listing.data?.name || 'objeto';
  return `tu objeto ${itemName} x${qty}`;
}

/**
 * Filter market listings based on search, tier, type, etc.
 */
export function applyMarketFilters(list: MarketListing[], filters: MarketFilters, context: 'explore' | 'my-listings', options: any = {}): MarketListing[] {
  const { getPokemonTier, SHOP_ITEMS } = options;

  return list.filter(item => {
    const offer = item.data || item;
    const listingType = item.listing_type || (filters.mode || 'pokemon');
    const price = item.price || 0;

    // Base filter: Mode (Pokemon vs Items)
    if (context === 'explore' && listingType !== filters.mode) return false;

    // Price
    if (context === 'explore') {
      if (price < filters.priceMin || price > filters.priceMax) return false;
    }

    // Search
    if (filters.search) {
      const query = filters.search.toLowerCase();
      const nameMatch = offer.name?.toLowerCase().includes(query);
      const nickMatch = offer.nickname?.toLowerCase().includes(query);
      if (!nameMatch && !nickMatch) return false;
    }

    if (listingType === 'pokemon') {
      // Tier
      if (filters.tier !== 'all') {
        const { tier } = typeof getPokemonTier === 'function' ? getPokemonTier(offer) : { tier: '?' };
        if (tier !== filters.tier) return false;
      }
      // Type
      if (filters.type !== 'all' && offer.type !== filters.type) return false;
      // Level
      if ((offer.level||1) < filters.levelMin || (offer.level||1) > filters.levelMax) return false;
      // IVs
      const ivs = offer.ivs || {};
      const total = (Number(ivs.hp)||0)+(Number(ivs.atk)||0)+(Number(ivs.def)||0)+(Number(ivs.spa)||0)+(Number(ivs.spd)||0)+(Number(ivs.spe)||0);
      if (total < filters.ivTotalMin || total > filters.ivTotalMax) return false;
      if (filters.ivAny31 && !Object.values(ivs).some(v => v === 31)) return false;
    } else {
      // Item Category
      if (filters.itemCat !== 'all') {
        const shopItem = (SHOP_ITEMS as any[])?.find(x => x.name === offer.name);
        if (shopItem?.cat !== filters.itemCat) return false;
      }
    }

    return true;
  });
}

/**
 * src/logic/player/classEngine.ts
 * Core engine for calculating class modifiers and mission validation.
 */
import { PLAYER_CLASSES } from '@/data/playerClasses';

export interface ModifierContext {
  isPvP?: boolean;
  isTrainer?: boolean;
  isGym?: boolean;
}

/**
 * Returns the processed modifier for a specific type and context.
 */
export function getClassModifier(playerClass: string, type: string, context: ModifierContext = {}): number {
  // PvP Balance: No advantages allowed during PvP
  if (context.isPvP) {
    if (type === 'shopDiscount') return 0;
    return 1.0;
  }

  const cls = (PLAYER_CLASSES as any)[playerClass];
  if (!cls) return type === 'shopDiscount' ? 0 : 1.0;

  const m = cls.modifiers;

  switch (type) {
    case 'expMult':
      if (playerClass === 'cazabichos' && context.isTrainer) return m.expMultTrainer || 1.0;
      return m.expMult || 1.0;
    case 'bcMult':
      if (playerClass === 'entrenador' && context.isGym) return m.bcGymMult || 1.0;
      return m.bcMult || 1.0;
    case 'healCostMult':
      return m.healCostMult || 1.0;
    case 'daycareCostMult':
      return m.daycareCostMult || 1.0;
    case 'catchMult':
      return m.catchMult || 1.0;
    case 'shopDiscount':
      return m.shopDiscount || 0;
    default:
      return 1.0;
  }
}

/**
 * Calculates the rewards and costs for a passive mission.
 */
export function getMissionCostInfo(missionId: string, playerClass: string): any {
  const cls = (PLAYER_CLASSES as any)[playerClass];
  if (!cls) return null;

  if (playerClass === 'cazabichos') {
    const data: Record<string, any> = {
      mission_6h: { cost: 5000, ivFloor: 5, shinyDiv: 2 },
      mission_12h: { cost: 10000, ivFloor: 10, shinyDiv: 4 },
      mission_24h: { cost: 20000, ivFloor: 15, shinyDiv: 8 }
    };
    return { type: 'money', ...data[missionId] };
  }

  if (playerClass === 'rocket') {
    const data: Record<string, any> = {
      mission_6h: { pokReq: 1, mult: 1.0 },
      mission_12h: { pokReq: 2, mult: 1.3 },
      mission_24h: { pokReq: 3, mult: 1.8 }
    };
    return { type: 'pokemon_sacrifice', ...data[missionId] };
  }

  if (playerClass === 'entrenador') {
    const data: Record<string, any> = {
      mission_6h: { cost: 5000, blocks: 1, bonusLevel: false },
      mission_12h: { cost: 10000, blocks: 2, bonusLevel: false },
      mission_24h: { cost: 20000, blocks: 4, bonusLevel: true }
    };
    return { type: 'money_pokemon', ...data[missionId] };
  }

  if (playerClass === 'criador') {
    const data: Record<string, any> = {
      mission_6h: { cost: 300, blocks: 1, vigorSaveChance: 0 },
      mission_12h: { cost: 600, blocks: 2, vigorSaveChance: 0 },
      mission_24h: { cost: 1000, blocks: 4, vigorSaveChance: 0.10 }
    };
    return { type: 'bc_pokemon', ...data[missionId] };
  }

  return null;
}

