import { ROUTE_WEATHER_TABLES } from '@/data/weather-tables';
import { getServerTime, getDayCycle } from '@/logic/timeUtils';

/**
 * Simple 32-bit hash function (DJB2) for string to number.
 */
function hashString(str: string): number {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash) + str.charCodeAt(i);
  }
  return hash >>> 0;
}

/**
 * Mulberry32 PRNG
 * Fast, high quality PRNG for JavaScript
 * @param {number} a - The seed
 * @returns {function} A function that returns a float between 0 (inclusive) and 1 (exclusive)
 */
export function mulberry32(a: number): () => number {
  return function() {
    let t = a += 0x6D2B79F5;
    t = Math.imul(t ^ t >>> 15, t | 1);
    t ^= t + Math.imul(t ^ t >>> 7, t | 61);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  }
}

/**
 * Deterministically calculates the weather for a given route, season, and epoch hour.
 * 
 * @param {string} mapId - The route identifier.
 * @param {string} seasonId - The season identifier (spring, summer, autumn, winter).
 * @param {number} epochHour - The continuous epoch hour.
 * @returns {string} The weather string (e.g., 'clear', 'rain', 'snow').
 */
export function getRouteWeather(mapId: string, seasonId: string, epochHour: number): string {
  // 1. Get Probability Table
  const routeTables = (ROUTE_WEATHER_TABLES as Record<string, any>)[mapId];
  if (!routeTables || !routeTables[seasonId]) {
    return 'clear'; // Fallback for missing tables
  }

  // Calculate cycle based on epochHour (continuous hours from epoch)
  const cycle = getDayCycle(epochHour * 3600000);
  const seasonTable = routeTables[seasonId];

  // Get the specific table for the cycle, or fallback to the season root if not using cycles yet
  const table = seasonTable[cycle] || seasonTable;

  // 2. Generate Deterministic Seed
  const mapHash = hashString(mapId);
  // Mix map hash and epoch hour to ensure different maps have different weather at the same hour
  const seed = (mapHash + epochHour) >>> 0;

  // 3. Initialize PRNG and discard first few values to break seed correlation
  const prng = mulberry32(seed);
  prng();
  prng();
  prng();
  const randNum = prng() * 100; // 0 to 99.999...

  // 4. Iterate and accumulate probabilities
  let cumulative = 0;
  for (const [weather, prob] of Object.entries(table as Record<string, number>)) {
    cumulative += prob;
    if (randNum < cumulative) {
      return weather;
    }
  }

  // Fallback in case table probabilities don't sum to 100 or something goes wrong
  return 'clear'; 
}

/**
 * Gets the current epoch hour for deterministic math.
 */
export function getCurrentEpochHour(): number {
  return Math.floor(getServerTime() / 3600000);
}

import { defineStore } from 'pinia';
import { ref } from 'vue';
import { gameBus } from '@/logic/gameBus';
import * as engine from '@/logic/audioEngine';

/**
 * AudioStore
 * Handles 8-bit sound synthesis using Web Audio API via audioEngine logic.
 */
export const useAudioStore = defineStore('audio', () => {
  const context = ref<AudioContext | null>(null);
  const masterGain = ref<GainNode | null>(null);
  const isInitialized = ref(false);

  /**
   * Initializes the audio context.
   */
  const init = () => {
    if (isInitialized.value) return;

    try {
      const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext) as typeof AudioContext;
      context.value = new AudioContextClass();
      masterGain.value = context.value.createGain();
      masterGain.value.gain.value = 0.15; // Global volume
      masterGain.value.connect(context.value.destination);
      isInitialized.value = true;
      initListeners();
    } catch (e) {
      console.error('[Audio] Web Audio API not supported', e);
    }
  };

  const initListeners = () => {
    gameBus.on('PLAY_SOUND', (e: any) => {
      const type = e.detail || e
      play(type)
    })
  }

  /**
   * Resumes the context.
   */
  const resume = async () => {
    if (!context.value) init();
    if (context.value && context.value.state === 'suspended') {
      await context.value.resume();
    }
  };

  /**
   * Plays a sound using the centralized engine.
   */
  const play = async (type: string) => {
    if (!isInitialized.value) init();
    await resume();

    const ctx = context.value;
    const dest = masterGain.value;
    if (!ctx || !dest) return;

    switch (type) {
      case 'shiny': engine.playShinySound(ctx, dest); break;
      case 'rival': engine.playRivalEncounterSound(ctx, dest); break;
      case 'levelUp': engine.playLevelUpSound(ctx, dest); break;
      case 'evolution': engine.playEvolutionSound(ctx, dest); break;
      case 'caught': engine.playCaptureSuccessSound(ctx, dest); break;
      case 'flee': engine.playFleeSound(ctx, dest); break;
      case 'item': engine.playItemSound(ctx, dest); break;
      case 'sentMsg': engine.playMessageSentSound(ctx, dest); break;
      case 'receivedMsg': engine.playMessageReceivedSound(ctx, dest); break;
      case 'money': engine.playMoneySound(ctx, dest); break;
      case 'heal': engine.playHealSound(ctx, dest); break;
      case 'faint': engine.playFaintSound(ctx, dest); break;
      case 'wobble': engine.playWobbleSound(ctx, dest); break;
      case 'ballHit': engine.playBallHitSound(ctx, dest); break;
      case 'statusDamage': engine.playStatusDamageSound(ctx, dest); break;
    }
  };

  return {
    isInitialized,
    init,
    resume,
    play,
    // Shortcuts
    shiny: () => play('shiny'),
    rival: () => play('rival'),
    levelUp: () => play('levelUp'),
    evolution: () => play('evolution'),
    caught: () => play('caught'),
    flee: () => play('flee'),
    item: () => play('item'),
    sentMsg: () => play('sentMsg'),
    receivedMsg: () => play('receivedMsg'),
    money: () => play('money'),
    heal: () => play('heal'),
    faint: () => play('faint'),
    wobble: () => play('wobble'),
    ballHit: () => play('ballHit'),
    statusDamage: () => play('statusDamage')
  };
});

import { defineStore } from 'pinia'
import { ref, computed, watch } from 'vue'
import { useGameStore } from './game'
import { useWarStore } from './war'
import { useEventStore } from './events'
import { usePlayerClassStore } from './playerClass'
import { useAudioStore } from './audio'
import { useMapStore } from './map'
import { useUIStore } from './ui'
import { createBattleStateMachine, BATTLE_STATES, BATTLE_SUBSTATES } from '../logic/battle/battleStateMachine'
import { clearVolatileStatus, tickStatus, tickLeechSeed } from '../logic/battle/battleStatus'
import { startBattleSequence, initBattleSequence, restoreBattleState } from '../logic/battle/orchestrator'
import { processFaint, terminateBattle, syncAndPersist } from '../logic/battle/resolution'
import { handleBattleFlowCompletion, triggerNextEncounter, startEncounter } from '../logic/battle/searchLoop'
import { formatBattleLog } from '../logic/battle/battleLogger'
import { executeTurn, runEnemyAction } from '../logic/battle/battleTurn'
import { applyEndTurnWeather, handleEntryAbilities } from '../logic/battle/battleFlow'
import { handleItemUsage } from '../logic/battle/battleItems'
import { gameBus } from '@/logic/gameBus'

// Types
import type { BattleState, BattleStages, BattleLog } from '@/types/battle'
import type { Pokemon, Move } from '@/types/pokemon'
import type { BattleContext } from '@/types/battleContext'

const INITIAL_STAGES: BattleStages = { 
  atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, 
  reflect: 0, lightScreen: 0, safeguard: 0, mist: 0, spikes: 0 
}

export const useBattleStore = defineStore('battle', () => {
  const gs = useGameStore()
  const warStore = useWarStore()
  const eventStore = useEventStore()
  const classStore = usePlayerClassStore()
  const audio = useAudioStore()
  const uiStore = useUIStore()
  const mapStore = useMapStore()
  
  const activeBattle = ref<BattleState | null>(null)
  const fsm = createBattleStateMachine()
  const currentFsmState = computed(() => fsm.currentState.value)
  const currentSubState = computed(() => fsm.currentSubState.value)
  const faintedSides = ref(new Set<string>())
  
  const isBattleActive = computed(() => 
    fsm.currentState.value === BATTLE_STATES.ACTIVE_BATTLE || 
    fsm.currentState.value === BATTLE_STATES.REWARDS_PHASE ||
    fsm.currentState.value === BATTLE_STATES.LEVEL_UP_MODAL ||
    fsm.currentState.value === BATTLE_STATES.POST_BATTLE_STABILIZATION ||
    fsm.currentState.value === BATTLE_STATES.REORDER_TEAM ||
    fsm.currentState.value === BATTLE_STATES.FIRST_INTRO ||
    fsm.currentState.value === BATTLE_STATES.INITIALIZING ||
    fsm.currentState.value === BATTLE_STATES.SEARCH_PHASE
  )
  const isFinishing = computed(() => 
    fsm.currentState.value === BATTLE_STATES.REWARDS_PHASE || 
    fsm.currentState.value === BATTLE_STATES.LEVEL_UP_MODAL ||
    fsm.currentState.value === BATTLE_STATES.POST_BATTLE_STABILIZATION ||
    fsm.currentSubState.value === BATTLE_SUBSTATES.ENEMY_FAINT ||
    fsm.currentSubState.value === BATTLE_SUBSTATES.PLAYER_FAINT_SEQ ||
    fsm.currentSubState.value === BATTLE_SUBSTATES.CATCH_SUCCESS
  )
  const isSearching = computed(() => fsm.currentState.value === BATTLE_STATES.SEARCH_PHASE)
  const isReadyToExit = computed(() => 
    fsm.currentState.value === BATTLE_STATES.POST_BATTLE_STABILIZATION && 
    fsm.currentSubState.value === BATTLE_SUBSTATES.DEFEAT_WAIT
  )
  const isIntroAnimating = ref(false)

  
  const isProcessing = ref(false)
  const debugBinoculars = ref(false)
  const battleLogs = ref<BattleLog[]>([])
  const logQueue = ref<BattleLog[]>([])
  const isProcessingLogs = ref(false)
  const battleEndCallback = ref<(() => void) | null>(null)
  const attackerSide = ref<'player' | 'enemy' | null>(null)
  const activeMove = ref<Move | null>(null)

  const playerStages = ref<BattleStages>({ ...INITIAL_STAGES })
  const enemyStages = ref<BattleStages>({ ...INITIAL_STAGES })
  const upcomingPokemon = ref<Pokemon | null>(null)
  const debugLoopPokemon = ref<Pokemon | null>(null)

  const player = computed(() => activeBattle.value?.player)
  const enemy = computed(() => activeBattle.value?.enemy)
  
  watch(() => mapStore.currentWeather, (newWeather) => {
    if (activeBattle.value && activeBattle.value.weather && activeBattle.value.weather.turns === -1) {
      activeBattle.value.weather.type = newWeather || 'clear'
    }
  })

  const getContext = (): BattleContext => ({
    gs: gs as any, 
    warStore, 
    eventStore, 
    classStore, 
    audio, 
    uiStore: uiStore as any,
    activeBattle, 
    player, 
    enemy, 
    fsm, 
    BATTLE_STATES, 
    BATTLE_SUBSTATES,
    isBattleActive: isBattleActive as any, 
    isFinishing, 
    isSearching, 
    isReadyToExit, 
    isIntroAnimating,
    isProcessing, 
    debugBinoculars, 
    upcomingPokemon, 
    debugLoopPokemon,
    playerStages, 
    enemyStages, 
    battleLogs, 
    attackerSide, 
    activeMove,
    faintedSides,
    addLog, 
    endBattle, 
    completeBattleFlow, 
    persistBattle, 
    waitForLogs, 
    clearLogs, 
    clearVolatileStatus, 
    startBattle, 
    _startBattle: startBattle, 
    initBattle,
    handleFaint
  })

  const restoreBattle = (battleData: BattleState) => restoreBattleState(getContext(), battleData)

  const persistBattle = () => syncAndPersist(getContext())

  const startBattle = async (enemyPoke: Pokemon, options?: { isTrainer?: boolean, trainerName?: string, isGym?: boolean, gymId?: string }) => 
    startBattleSequence(getContext(), enemyPoke, options)
    
  const initBattle = async (locId: string, isTr: boolean, trName: string, isGym: boolean, gymId: string, wasSearching: boolean) => 
    initBattleSequence(getContext(), { 
      locationId: locId, isTrainer: isTr, trainerName: trName, isGym, gymId, wasSearching,
      initialEnemy: activeBattle.value?.enemy,
      initialPlayer: gs.state.team[0]
    })

  const addLog = (msg: string, type = 'log-info', source: unknown = null, sideOverride: 'player' | 'enemy' | null = null) => {
    const ctx = {
      gs,
      activeBattle: activeBattle.value,
      attackerSide: attackerSide.value
    }
    
    const logItem = formatBattleLog(msg, type, source, ctx) as BattleLog
    if (sideOverride) logItem.side = sideOverride

    logQueue.value.push(logItem)
    if (!isProcessingLogs.value) processNextLog()
  }


  const processNextLog = async () => {
    if (isProcessingLogs.value) return 
    isProcessingLogs.value = true

    while (true) {
      if (logQueue.value.length === 0) {
        isProcessingLogs.value = false
        if (logQueue.value.length > 0) {
          isProcessingLogs.value = true
          continue
        }
        break
      }

      const batchSize = logQueue.value.length > 6 ? 3 : (logQueue.value.length > 3 ? 2 : 1)
      
      for (let i = 0; i < batchSize; i++) {
        if (logQueue.value.length === 0) break
        const nextItem = logQueue.value.shift()
        if (nextItem) {
          battleLogs.value.push(nextItem)
          if (battleLogs.value.length > 30) battleLogs.value.shift()
        }
      }

      const delay = logQueue.value.length > 0 ? 100 : 350
      await new Promise(r => setTimeout(r, delay))
    }
  }

  const clearLogs = () => {
    battleLogs.value = []; logQueue.value = []; isProcessingLogs.value = false;
    playerStages.value = { ...INITIAL_STAGES }
    enemyStages.value = { ...INITIAL_STAGES }
    activeMove.value = null
    attackerSide.value = null
  }

  const waitForLogs = async () => {
    while (isProcessingLogs.value || logQueue.value.length > 0) {
      await new Promise(r => setTimeout(r, 100))
    }
  }

  const executeMove = async (moveIndex: number) => {
    if (isProcessing.value || !isBattleActive.value) return
    isProcessing.value = true
    fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.EXEC_TURN as any)
    fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.TURN_ENGINE as any)
    await executeTurn(getContext(), moveIndex)
    
    if (!activeBattle.value) {
      isProcessing.value = false
      return
    }

    if (!activeBattle.value.over) await applyEndTurnEffects()
    activeMove.value = null
    
    if (activeBattle.value && !activeBattle.value.over) {
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ANIM_SYNC as any)
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.UPDATE_BUTTON as any)
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.WAIT_INPUT as any)
      isProcessing.value = false
    }
  }

  const applyEndTurnEffects = async () => {
    const p = activeBattle.value?.player
    const e = activeBattle.value?.enemy
    if (!p || !e) return
    
    const active = activeBattle.value
    if (active && active.futureSightTurns && active.futureSightTurns > 0) {
      active.futureSightTurns--
      if (active.futureSightTurns === 0) {
        const fsTarget = active.futureSightTarget
        if (fsTarget && fsTarget.hp > 0) {
          const dmg = Math.max(10, Math.floor(fsTarget.maxHp * 0.15))
          fsTarget.hp = Math.max(0, fsTarget.hp - dmg)
          addLog(`¡Se cumplió la premonición! ${fsTarget.name} recibió daño.`, 'log-info', fsTarget)
          gameBus.emit('PLAY_SOUND', 'statusDamage')
        }
      }
    }

    tickStatus(p, addLog, 'player')
    tickStatus(e, addLog, 'enemy')
    tickLeechSeed(p, e, addLog)
    tickLeechSeed(e, p, addLog)
    
    const w = activeBattle.value?.weather
    if (w && w.turns > 0) {
      w.turns--
      if (w.turns === 0) {
        addLog(`¡El efecto de ${w.type} se desvaneció!`, 'log-info')
        w.type = mapStore.currentWeather || 'clear'
        w.turns = -1
      }
    }

    const fieldEffects = ['reflect', 'lightScreen', 'safeguard', 'mist'] as const
    const sides = [
      { stages: playerStages, name: 'Jugador', log: 'log-player' as const },
      { stages: enemyStages, name: 'Enemigo', log: 'log-enemy' as const }
    ]
    sides.forEach(side => {
      fieldEffects.forEach(effect => {
        const stages = side.stages.value
        if ((stages as any)[effect] > 0) {
          (stages as any)[effect]--
          if ((stages as any)[effect] === 0) {
            const effectLabel = effect === 'reflect' ? 'Reflejo' : effect === 'lightScreen' ? 'Pantalla Luz' : effect
            addLog(`¡El efecto de ${effectLabel} del ${side.name} se desvaneció!`, side.log)
          }
        }
      })
    })

    if (activeBattle.value) applyEndTurnWeather(p, e, activeBattle.value.weather, addLog)
    
    if (p.hp <= 0) await handleFaint('player')
    if (isBattleActive.value && e.hp <= 0) await handleFaint('enemy')
    
    persistBattle()
    if (activeBattle.value && !activeBattle.value.over) {
      activeBattle.value.turnCount++
    }
  }

  const handleFaint = async (side: 'player' | 'enemy') => await processFaint(getContext(), side)

  const useItemInBattle = async (itemName: string, targetIndex: number | null = null) => {
    if (isProcessing.value || !isBattleActive.value || !activeBattle.value) return
    isProcessing.value = true
    
    const targetPoke = (targetIndex !== null) ? gs.state.team[targetIndex] : activeBattle.value.player
    if (!targetPoke) { isProcessing.value = false; return }

    attackerSide.value = 'player'
    const ctx = {
      turnCount: activeBattle.value.turnCount,
      locationId: activeBattle.value.locationId,
      weather: activeBattle.value.weather,
      cycle: mapStore.currentCycle
    }
    const res = await handleItemUsage(itemName, targetPoke, activeBattle.value.enemy, { 
      gs: gs as any, eventStore, addLog, audio, consumeItem, ctx, fsm 
    })
    attackerSide.value = null
    activeMove.value = null
    
    const castRes = res as any
    if (castRes.action === 'capture') {
      activeBattle.value.isCapture = true
      activeBattle.value.over = true 
      gs.addPokemon(castRes.pokemon, { notify: true })
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT as any)
      activeBattle.value.enemy = null
      await new Promise(r => setTimeout(r, 2000))
      
      isProcessing.value = false
      await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT as any)
      await endBattle(true, false)
      return
    } else if (castRes.action !== 'fail') {
      if (castRes.pokemon && activeBattle.value?.player) {
        activeBattle.value.player = { ...castRes.pokemon }
        syncTeamHP()
      }
      
      persistBattle()
      await new Promise(r => setTimeout(r, 800))
      
      await runEnemyAction(getContext())
    }
    
    if (activeBattle.value && !activeBattle.value.over) {
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.WAIT_INPUT as any)
    }
    isProcessing.value = false
  }

  const endBattle = async (win: boolean, fled: boolean) => await terminateBattle(getContext(), win, fled)

  const syncTeamHP = () => {
    // Sincronización manual de HP
    const team = gs.state.team;
    const active = activeBattle.value;
    if (active?.player && team && team[active.playerTeamIndex]) {
      const p = team[active.playerTeamIndex];
      if (p) p.hp = active.player.hp
    }
  }
  
  const _executeSwitch = async (teamIndex: number, isForced = false) => {
    if (isProcessing.value && !isForced) return
    isProcessing.value = true
    
    await fsm.transition(BATTLE_STATES.REORDER_TEAM)
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.FIND_HEALTHY as any)
    
    activeMove.value = null
    attackerSide.value = null
    
    const newPoke = gs.state.team[teamIndex]
    if (!newPoke || newPoke.hp <= 0) { isProcessing.value = false; return }
    
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.CHECK_ACTIVE_SEAT as any)
    if (!activeBattle.value) { isProcessing.value = false; return }
    const oldPoke = activeBattle.value.player
    
    if (oldPoke && oldPoke.uid === newPoke.uid) {
      isProcessing.value = false
      return
    }

    if (oldPoke && oldPoke.hp > 0) {
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.SWITCHING as any)
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_RECALL as any)
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.RENDER_BALL as any)
      addLog(`¡Bien hecho, ${oldPoke.name}! ¡Regresa!`, 'log-info', 'player')
      gameBus.emit('PLAY_WITHDRAW', { side: 'player' })
      
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.WAIT_TIMER as any, 500)
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.VACATE_SEAT as any)
      activeBattle.value.player = null
      clearVolatileStatus(oldPoke)
    }

    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_CALL as any)
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.RENDER_BALL as any)
    
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.OCCUPY_SEAT as any)
    activeBattle.value.player = newPoke; 
    activeBattle.value.playerTeamIndex = teamIndex
    
    gameBus.emit('PLAY_SEND_OUT', { side: 'player', pokemon: newPoke })
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.ENERGY_RELEASE as any)
    await new Promise(r => setTimeout(r, 800))
    
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_APPEAR as any)
    
    if (!activeBattle.value.participants.includes(newPoke.uid)) {
      activeBattle.value.participants.push(newPoke.uid)
    }
    
    const s = playerStages.value
    playerStages.value = { ...INITIAL_STAGES, 
      reflect: s.reflect || 0, lightScreen: s.lightScreen || 0, safeguard: s.safeguard || 0, mist: s.mist || 0, spikes: s.spikes || 0 }
    
    addLog(`¡Adelante, ${newPoke.name}!`, 'log-player', newPoke)
    await new Promise(r => setTimeout(r, 400))

    if (playerStages.value.spikes > 0 && newPoke.type !== 'flying' && newPoke.type2 !== 'flying' && newPoke.ability !== 'Levitación') {
      const dmg = Math.floor(newPoke.maxHp * (playerStages.value.spikes / 8))
      newPoke.hp = Math.max(0, newPoke.hp - dmg)
      addLog(`¡${newPoke.name} recibió daño por las púas!`, 'log-info', newPoke)
      gameBus.emit('PLAY_SOUND', 'statusDamage')
    }
    
    handleEntryAbilities(newPoke, activeBattle.value.enemy, playerStages.value, enemyStages.value, addLog)
    persistBattle()
    
    if (!isForced) await runEnemyAction(getContext())
    
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.WAIT_INPUT as any)
    isProcessing.value = false
  }

  const consumeItem = (itemName: string) => {
    if (gs.state.inventory[itemName]) {
      gs.state.inventory[itemName]--
      if (gs.state.inventory[itemName] <= 0) delete gs.state.inventory[itemName]
    }
  }

  const completeBattleFlow = async (option: unknown) => await handleBattleFlowCompletion(getContext(), option)

  const triggerSearchEncounter = async () => await triggerNextEncounter(getContext())


  if (typeof window !== 'undefined') {
    const win = window as any
    win.__VITE_DEBUG__ = win.__VITE_DEBUG__ || {};
    win.__VITE_DEBUG__.forceFlee = async () => {
      console.warn('[DEBUG] Forzando huida del combate...')
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.FLEE_ATTEMPT as any)
      await endBattle(false, true)
    };

    win.__VITE_DEBUG__.battle = {
      setPlayerStatus: (s: Pokemon['status']) => { if (activeBattle.value?.player) activeBattle.value.player.status = s },
      setEnemyStatus: (s: Pokemon['status']) => { if (activeBattle.value?.enemy) activeBattle.value.enemy.status = s },
      setPlayerStage: (stat: keyof BattleStages, val: number) => { playerStages.value[stat] = val },
      setEnemyStage: (stat: keyof BattleStages, val: number) => { enemyStages.value[stat] = val },
      setWeather: (w: string) => { if (activeBattle.value) activeBattle.value.weather = { type: w, turns: 5 } },
      fullHeal: () => {
        const p = activeBattle.value?.player;
        if (p) {
          p.hp = p.maxHp; p.status = null; (p as any).confused = 0; (p as any).seeded = false
        }
      },
      killEnemy: () => { if (activeBattle.value?.enemy) activeBattle.value.enemy.hp = 0 },
      store: () => useBattleStore()
    }
  }

  return {
    state: activeBattle,
    battleLogs,
    isBattleActive,
    isFinishing,
    isProcessing,
    player,
    enemy,
    playerStages,
    enemyStages,
    attackerSide,
    activeMove,
    upcomingPokemon,
    debugLoopPokemon,
    restoreBattle,
    addLog,
    clearLogs,
    executeMove,
    persistBattle,
    flee: async () => {
      if (isProcessing.value) return;
      
      if (activeBattle.value && (activeBattle.value.isTrainer || activeBattle.value.isGym)) {
        addLog('¡No puedes huir de un combate de entrenador!', 'log-error', 'player');
        return;
      }

      uiStore.openConfirm({
        title: 'HUIR DEL COMBATE',
        message: '¿Estás seguro que deseas huir de este encuentro?',
        confirmText: 'SÍ, HUIR',
        cancelText: 'VOLVER',
        type: 'primary',
        variant: 'retro',
        onConfirm: async () => {
          isProcessing.value = true;
          if (!activeBattle.value) { isProcessing.value = false; return }
          activeBattle.value.escapeAttempts = (activeBattle.value.escapeAttempts || 0);
          
          if (!activeBattle.value.player || !activeBattle.value.enemy) { isProcessing.value = false; return }
          
          const { calculateEscapeChance } = await import('../logic/battle/battleEngine');
          const canEscape = calculateEscapeChance(
            activeBattle.value.player, 
            activeBattle.value.enemy, 
            activeBattle.value.escapeAttempts, 
            { 
              playerStages: playerStages.value, 
              enemyStages: enemyStages.value, 
              weather: activeBattle.value.weather 
            }
          );

          if (canEscape) {
            audio.flee();
            addLog('¡Escapaste sin problemas!', 'log-info', 'player');
            
            fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ESCAPE_PROCESS as any);
            fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAY_ESCAPE_ANIM as any);
            gameBus.emit('PLAY_ESCAPE_ANIM', { side: 'player' });
            
            await new Promise(r => setTimeout(r, 1000));
            await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT as any);
            if (activeBattle.value) activeBattle.value.enemy = null;
            await endBattle(false, true);
          } else {
            if (activeBattle.value) activeBattle.value.escapeAttempts++;
            addLog('¡No pudiste escapar!', 'log-info', 'player');
            
            await runEnemyAction(getContext());
          }
          isProcessing.value = false;
        }
      });
    },
    completeBattleFlow,
    triggerSearchEncounter,
    setFinishing: (cb: () => void) => { fsm.transition(BATTLE_STATES.REWARDS_PHASE); battleEndCallback.value = cb },
    useItemInBattle,
    endBattle,
    handleFaint,
    applyEndTurnEffects,
    startBattle,
    _startBattle: startBattle,
    startEncounter: async () => await startEncounter(getContext()),
    executeSwitch: _executeSwitch,
    isSearching,
    isIntroAnimating,
    debugBinoculars,
    fsm,
    currentFsmState,
    currentSubState
  }
})
rrentSubState
  }
})

import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import { useGameStore } from './game';
import { useUIStore } from './ui';
import { 
  checkCompatibility, 
  calculateInheritance, 
  inheritNature,
  inheritMoves,
  inheritAbility,
  calculateShinyChance,
} from '@/logic/breeding/breedingEngine';
import { generateMission, validateMissionPokemon } from '@/logic/breeding/missionEngine';
import { EGG_SPAWN_INTERVAL_MS } from '@/logic/breeding/breedingData';
import { POKEMON_DB } from '@/data/pokemonDB';
import { usePlayerClassStore } from './playerClass';
import { useEventStore } from './events';
import type { DaycareSlot, DaycareEgg, DaycareMission } from '@/types/breeding';
import type { Pokemon, PokemonEgg } from '@/types/pokemon';

export const useBreedingStore = defineStore('breeding', () => {
  const gameStore = useGameStore();
  const uiStore = useUIStore();
  const classStore = usePlayerClassStore();
  const eventStore = useEventStore();

  // --- STATE ---
  const slots = ref<DaycareSlot[]>([]); // [{ pokemon, slot_index, deposited_at }]
  const warehouseEggs = ref<DaycareEgg[]>([]); // Eggs waiting to be claimed
  const dailyMissions = computed<DaycareMission[]>({
    get: () => gameStore.state.daycare_missions || [],
    set: (val) => { gameStore.state.daycare_missions = val }
  });
  const missionRefreshes = computed<number>({
    get: () => gameStore.state.daycare_mission_refreshes || 0,
    set: (val) => { gameStore.state.daycare_mission_refreshes = val }
  });
  const loading = ref(false);

  // --- GETTERS ---
  const isBreeding = computed(() => slots.value.length === 2 && !!slots.value[0]?.pokemon && !!slots.value[1]?.pokemon);

  const compatibility = computed(() => {
    if (!isBreeding.value) {
      return { level: 0, reason: 'Deposita 2 Pokémon', sharedGroups: [] };
    }
    const p1 = slots.value[0]?.pokemon;
    const p2 = slots.value[1]?.pokemon;
    if (!p1 || !p2) return { level: 0, reason: 'Deposita 2 Pokémon', sharedGroups: [] };
    return checkCompatibility(p1, p2);
  });

  const nextEggTime = computed(() => {
    const level = compatibility.value.level;
    if (level === 0) return null;
    const interval = (EGG_SPAWN_INTERVAL_MS as any)[level];
    if (!interval) return null;

    if (!slots.value[0]?.deposited_at || !slots.value[1]?.deposited_at) return null;

    const depA = new Date(slots.value[0].deposited_at).getTime();
    const depB = new Date(slots.value[1].deposited_at).getTime();
    const earliest = Math.max(depA, depB);

    return earliest + interval;
  });

  // --- ACTIONS ---

  async function loadDaycare() {
    loading.value = true;
    try {
      // Simulate hydration
    } finally {
      loading.value = false;
    }
  }

  async function deposit(pokemon: Pokemon, slotIndex: number) {
    if (pokemon.onMission || pokemon.onDefense) {
      uiStore.notify('Este Pokémon está ocupado.', '⚠️');
      return false;
    }

    pokemon.inDaycare = true;

    const now = new Date().toISOString();
    const existing = slots.value.findIndex((s) => s.slotIndex === slotIndex);
    if (existing !== -1) {
      slots.value[existing] = { pokemon, slotIndex, deposited_at: now };
    } else {
      slots.value.push({ pokemon, slotIndex, deposited_at: now });
    }

    slots.value.forEach((s) => s.deposited_at = now);

    uiStore.notify(`¡${pokemon.name} depositado en la Guardería!`, '🏡');
    gameStore.scheduleSave();
    return true;
  }

  async function checkAndGenerateEgg() {
    if (!isBreeding.value || compatibility.value.level === 0) return;
    if (!slots.value[0]?.pokemon || !slots.value[1]?.pokemon) return;

    const now = Date.now();
    if (nextEggTime.value && now < nextEggTime.value) return;

    const pA = slots.value[0].pokemon as Pokemon;
    const pB = slots.value[1].pokemon as Pokemon;
    const compat = compatibility.value as any; // breedingEngine might need better typing too

    if ((pA.vigor || 0) <= 0 || (pB.vigor || 0) <= 0) {
      uiStore.notify('Uno de los padres no tiene vigor suficiente.', '💤');
      return;
    }

    const eggSpecies = compat.eggSpecies;
    const itemA = pA.heldItem || '';
    const itemB = pB.heldItem || '';
    const playerClass = classStore.playerClass as string;

    const abilityName = inheritAbility(pA, pB);
    const abilityIndex = abilityName ? 1 : 0; // Simplified conversion for now

    const egg: DaycareEgg = {
      id: `egg_${now}_${Math.random().toString(36).substring(2, 7)}`,
      species: eggSpecies,
      name: 'Huevo Pokémon',
      level: 1,
      isEgg: true,
      steps: 2500,
      mother_id: compat.motherId,
      deposited_at: new Date().toISOString(),
      ivs: calculateInheritance(pA, pB, itemA, itemB, playerClass),
      nature: inheritNature(pA, pB, itemA, itemB) || 'Serio',
      movesAtBirth: inheritMoves(pA, pB, eggSpecies),
      abilityIndex: abilityIndex,
      isShiny: Math.random() < calculateShinyChance(pA, pB, 1/4096, eventStore.globalMultipliers?.shiny || 1),
      cost: 5000
    };

    warehouseEggs.value.push(egg);

    const isoNow = new Date().toISOString();
    if (slots.value[0]) slots.value[0].deposited_at = isoNow;
    if (slots.value[1]) slots.value[1].deposited_at = isoNow;

    uiStore.notify(' ¡Apareció un huevo en la Guardería!', '🥚');
    gameStore.scheduleSave();
  }

  function claimEgg(eggId: string) {
    const eggIndex = warehouseEggs.value.findIndex((e) => e.id === eggId);
    if (eggIndex === -1) return;

    const egg = warehouseEggs.value[eggIndex];
    if (!egg) return;

    if (gameStore.state.money < egg.cost) {
      uiStore.notify(`No tienes suficiente dinero ($${egg.cost.toLocaleString()}).`, '💰');
      return;
    }

    if (!gameStore.state.eggs) gameStore.state.eggs = [];

    const eggForInventory: PokemonEgg = {
      uid: egg.id,
      id: egg.species,
      steps: egg.steps,
      ready: false,
      ivs: egg.ivs,
      nature: egg.nature,
      movesAtBirth: egg.movesAtBirth,
      abilitySlot: egg.abilityIndex,
      isShiny: egg.isShiny
    };

    const eggToPush = {
      ...eggForInventory,
      uid: `${eggForInventory.id}-${Date.now()}`,
      ready: false
    };
    gameStore.state.eggs.push(eggToPush as any);
    gameStore.state.money -= egg.cost;
    warehouseEggs.value.splice(eggIndex, 1);

    uiStore.notify('¡Huevo recogido! Camina para eclosionarlo.', '🥚');
    gameStore.scheduleSave();
  }

  function scanEgg(eggId: string) {
    if (classStore.playerClass !== 'criador') {
      uiStore.notify('Solo los Criadores pueden escanear huevos.', '🔒');
      return;
    }

    const egg = warehouseEggs.value.find((e) => e.id === eggId);
    if (!egg) return;

    if (egg.ivs) {
      if (!egg.inherited_ivs) egg.inherited_ivs = { };
      egg.inherited_ivs._scanned = true;
      uiStore.notify(`¡Huevo de ${(POKEMON_DB as any)[egg.species]?.name} escaneado!`, '🔍');
      gameStore.scheduleSave();
    }
  }

  function checkDailyReset() {
    const today = new Date().toISOString().split('T')[0] as string;
    const missions = dailyMissions.value;
    const lastDate = missions.length > 0 && missions[0] ? missions[0].date : '';

    if (lastDate !== today) {
      regenerateMissions(today);
      missionRefreshes.value = 3;
    }
  }

  function regenerateMissions(dateStr: string) {
    const level = gameStore.state.trainerLevel || 1;
    const m1 = generateMission(level, dateStr) as DaycareMission;
    let m2 = generateMission(level, dateStr) as DaycareMission;

    while (m2.targetId === m1.targetId) {
      m2 = generateMission(level, dateStr) as DaycareMission;
    }

    dailyMissions.value = [m1, m2];
    gameStore.scheduleSave();
  }

  function refreshMissions() {
    if (missionRefreshes.value <= 0) {
      uiStore.notify('No te quedan refrescos por hoy.', '⚠️');
      return;
    }

    missionRefreshes.value--;
    const today = new Date().toISOString().split('T')[0] as string;
    regenerateMissions(today);
    uiStore.notify('Misiones actualizadas.', '🔄');
  }

  function completeMission(missionIndex: number, pokemonUid: string) {
    const mission = dailyMissions.value[missionIndex];
    if (!mission || mission.completed) return;

    const team = gameStore.state.team || [];
    const box = gameStore.state.box || [];
    const all = [...team, ...box];
    const pokemon = all.find(p => p.uid === pokemonUid);

    if (!pokemon) return;
    if (!validateMissionPokemon(pokemon, mission as any)) {
      uiStore.notify('Este Pokémon no cumple los requisitos.', '❌');
      return;
    }

    if (team.length <= 1 && team.some((p) => p.uid === pokemonUid)) {
      uiStore.notify('No puedes entregar tu único Pokémon.', '⚠️');
      return;
    }

    if (!gameStore.removePokemon(pokemonUid)) {
      uiStore.notify('Error al procesar la entrega.', '❌');
      return;
    }

    mission.completed = true;
    const inv = gameStore.state.inventory as any;
    inv[mission.reward.name] = (inv[mission.reward.name] || 0) + mission.reward.qty;

    uiStore.notify(`¡Misión completada! Recibiste ${mission.reward.name} x${mission.reward.qty}`, mission.reward.icon);
    gameStore.scheduleSave();
  }

  function reduceHatchTimers(activity: 'battle' | 'capture' | 'gym') {
    const REDUCTIONS = { battle: 2 * 60000, capture: 3 * 60000, gym: 10 * 60000 };
    const reduction = REDUCTIONS[activity] || 0;
    if (reduction === 0) return;

    const eggs = gameStore.state.eggs || [];
    if (eggs.length === 0) return;

    let newlyReady = false;
    eggs.forEach((egg) => {
      if (egg.steps > 0) {
        egg.steps = Math.max(0, egg.steps - (reduction / 1000));
        if (egg.steps === 0) newlyReady = true;
      }
    });

    if (newlyReady) {
      uiStore.notify('¡Un huevo está listo para eclosionar!', '🐣');
    }
  }

  return {
    slots,
    warehouseEggs,
    dailyMissions,
    missionRefreshes,
    loading,
    isBreeding,
    compatibility,
    nextEggTime,
    loadDaycare,
    deposit,
    claimEgg,
    checkDailyReset,
    refreshMissions,
    regenerateMissions,
    completeMission,
    reduceHatchTimers,
    scanEgg,
    checkAndGenerateEgg
  };
});

import { defineStore } from 'pinia'
import { computed } from 'vue'
import { useGameStore } from './game'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'

export const useBuffsStore = defineStore('buffs', () => {
  const gameStore = useGameStore()

  let tickInterval: ReturnType<typeof setInterval> | null = null

  function initTick() {
    if (tickInterval) clearInterval(tickInterval)
    tickInterval = setInterval(() => {
      // Pause timers if player is in an active battle
      if (gameStore.state.battle && !gameStore.state.battle.over) return;

      const s = gameStore.state
      let changed = false
      if (s.repelSecs > 0) { s.repelSecs--; changed = true }
      if (s.shinyBoostSecs > 0) { s.shinyBoostSecs--; changed = true }
      if (s.amuletCoinSecs > 0) { s.amuletCoinSecs--; changed = true }
      if (s.luckyEggSecs > 0) { s.luckyEggSecs--; changed = true }
      if (s.safariTicketSecs > 0) { s.safariTicketSecs--; changed = true }
      if (s.ceruleanTicketSecs > 0) { s.ceruleanTicketSecs--; changed = true }
      if (s.articunoTicketSecs > 0) { s.articunoTicketSecs--; changed = true }
      if (s.mewtwoTicketSecs > 0) { s.mewtwoTicketSecs--; changed = true }
      if (s.ivScannerSecs > 0) { s.ivScannerSecs--; changed = true }
      if (s.incenseSecs > 0) { s.incenseSecs--; changed = true }

      if (changed) {
        // Silent save every 30 seconds to persist timers
        if (s.repelSecs % 30 === 0) {
          gameStore.save(false)
        }
      }
    }, 1000)
  }

  function addBuff(buffName: string, seconds: number, extraData: string | null = null) {
    const s = gameStore.state
    if (buffName === 'repel') s.repelSecs = (s.repelSecs || 0) + seconds
    else if (buffName === 'shiny') s.shinyBoostSecs = (s.shinyBoostSecs || 0) + seconds
    else if (buffName === 'amulet') s.amuletCoinSecs = (s.amuletCoinSecs || 0) + seconds
    else if (buffName === 'lucky-egg') s.luckyEggSecs = (s.luckyEggSecs || 0) + seconds
    else if (buffName === 'safari') s.safariTicketSecs = (s.safariTicketSecs || 0) + seconds
    else if (buffName === 'cerulean') s.ceruleanTicketSecs = (s.ceruleanTicketSecs || 0) + seconds
    else if (buffName === 'articuno') s.articunoTicketSecs = (s.articunoTicketSecs || 0) + seconds
    else if (buffName === 'mewtwo') s.mewtwoTicketSecs = (s.mewtwoTicketSecs || 0) + seconds
    else if (buffName === 'iv-scanner') s.ivScannerSecs = (s.ivScannerSecs || 0) + seconds
    else if (buffName === 'incense') {
      s.incenseSecs = (s.incenseSecs || 0) + seconds
      if (extraData) s.incenseType = extraData
    }
    gameStore.save(false)
  }

  const activeBuffs = computed(() => {
    const s = gameStore.state as any
    const list = []
    if (s.repelSecs > 0) list.push({ id: 'repel', secs: s.repelSecs, name: 'Repelente', desc: 'Aleja Pokémon salvajes de nivel inferior al tuyo.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'repel') })
    if (s.shinyBoostSecs > 0) list.push({ id: 'shiny', secs: s.shinyBoostSecs, name: '✨ Ticket Shiny', desc: 'Aumenta la probabilidad de encontrar Pokémon shiny.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'eon-ticket') })
    if (s.amuletCoinSecs > 0) list.push({ id: 'amulet', secs: s.amuletCoinSecs, name: '💰 Moneda Amuleto', desc: 'Duplica el dinero ganado en combate.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'amulet-coin') })
    if (s.luckyEggSecs > 0) list.push({ id: 'lucky-egg', secs: s.luckyEggSecs, name: '🥚 Huevo Suerte Pequeño', desc: 'Aumenta la EXP ganada en un 50% durante 30 minutos.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'lucky-egg') })
    if (s.safariTicketSecs > 0) list.push({ id: 'safari', secs: s.safariTicketSecs, name: '🎫 Ticket Safari', desc: 'Permite entrar a la Zona Safari.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'eon-ticket') })
    if (s.ceruleanTicketSecs > 0) list.push({ id: 'cerulean', secs: s.ceruleanTicketSecs, name: '🌀 Ticket Cueva Celeste', desc: 'Permite entrar a la Cueva Celeste.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'eon-ticket') })
    if (s.articunoTicketSecs > 0) list.push({ id: 'articuno', secs: s.articunoTicketSecs, name: '❄️ Ticket Articuno', desc: 'Permite entrar a las Islas Espuma.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'eon-ticket') })
    if (s.mewtwoTicketSecs > 0) list.push({ id: 'mewtwo', secs: s.mewtwoTicketSecs, name: '🧬 Ticket Mewtwo', desc: 'Permite entrar a la Cueva Celeste (Mewtwo).', icon: getAssetUrl(ASSET_TYPES.ITEM, 'eon-ticket') })
    if (s.ivScannerSecs > 0) list.push({ id: 'iv-scanner', secs: s.ivScannerSecs, name: '🔍 Escáner de IVs', desc: 'Muestra los IVs totales de Pokémon salvajes.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'poke-radar') })

    if (s.incenseSecs > 0) {
      const types: Record<string, string> = { fire: 'Fuego', water: 'Agua', grass: 'Planta', normal: 'Normal', ghost: 'Fantasma', psychic: 'Psíquico' }
      const sprites: Record<string, string> = { fire: 'incense', water: 'sea-incense', grass: 'rose-incense', normal: 'luck-incense', ghost: 'pure-incense', psychic: 'odd-incense' }
      const tName = types[s.incenseType] || 'Desconocido'
      const tSprite = sprites[s.incenseType] || 'incense'
      list.push({ 
        id: 'incense', 
        secs: s.incenseSecs, 
        name: `💨 Incienso ${tName}`, 
        desc: `Atrae Pokémon de tipo ${tName}.`, 
        icon: getAssetUrl(ASSET_TYPES.ITEM, tSprite)
      })
    }

    return list
  })

  return { initTick, addBuff, activeBuffs }
})

import { defineStore } from 'pinia'
import { ref, reactive, watch } from 'vue'
import { useAuthStore } from './auth'
import { useGameStore } from './game'
import { useUIStore } from './ui'
import { useAudioStore } from './audio'

export const useChatStore = defineStore('chat', () => {
  const authStore = useAuthStore()
  const gameStore = useGameStore()
  const uiStore = useUIStore()
  const audioStore = useAudioStore()

  const globalMessages = ref<any[]>([])
  const activeChatId = ref('global') // 'global' or userId

  let globalChannel: any = null
  let inboxChannel: any = null
  const outboxChannels: any = {}

  // Computed proxy to private chats in game state for persistence
  const privateChats = reactive(gameStore.state.chats || {})

  // Watch for game state changes (e.g. after a load) to sync privateChats
  watch(() => gameStore.state.chats, (newChats) => {
    Object.assign(privateChats, newChats || {})
  }, { deep: true })

  async function loadGlobalHistory() {
    // If offline, ProxyQuery will handle the local SELECT

    const db = gameStore.db
    if (!db) return
    const { data, error } = await db
      .from('global_chat_messages')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(50)

    if (!error && data) {
      globalMessages.value = data.reverse()
    }
  }

  async function initGlobalChat() {
    if (globalChannel) return

    await loadGlobalHistory()

    const db = gameStore.db
    if (!db) return
    globalChannel = db.channel('global-chat-room')
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'global_chat_messages'
      }, ({ new: row }: { new: any }) => {
        if (!globalMessages.value.some(m => m.id === row.id)) {
          globalMessages.value.push(row)
          if (globalMessages.value.length > 50) globalMessages.value.shift()

          // Sonido si el mensaje no es mío
          if (row.user_id !== authStore.user?.id) {
            audioStore.receivedMsg();
          }
        }
      })
      .subscribe()
  }

  async function initPrivateInbox() {
    if (!authStore.user || inboxChannel) return

    const db = gameStore.db
    if (!db) return
    inboxChannel = db.channel(`chat-inbox-${authStore.user.id}`)
      inboxChannel.on('broadcast', { event: 'private_message' }, ({ payload }: { payload: any }) => {
        handleIncomingPrivate(payload)
        audioStore.receivedMsg(); // Sonido al recibir mensaje privado
      })
      .subscribe()
  }

  function handleIncomingPrivate(payload: any) {
    const friendId = payload.senderId

    if (!privateChats[friendId]) {
      privateChats[friendId] = {
        username: payload.senderName || 'Entrenador',
        messages: [],
        unreadCount: 0,
        isCollapsed: false,
        lastInteraction: Date.now()
      }
    }

    const chat = privateChats[friendId]

    // Evitar duplicados sutiles (broadcast propio)
    const isDup = chat.messages.some((m: any) => m.timestamp === payload.timestamp && m.text === payload.text)
    if (isDup) return

    chat.messages.push(payload)
    chat.lastInteraction = Date.now()

    // Limitar historial por chat (25 mensajes)
    if (chat.messages.length > 25) chat.messages.shift()

    if (activeChatId.value !== friendId && payload.senderId !== authStore.user?.id) {
      chat.unreadCount++
      uiStore.notify(`Mensaje de ${chat.username}`, '💬')
    }

    // Sincronizar de vuelta al estado del juego para persistencia en el save_data
    gameStore.state.chats = { ...privateChats }
  }

  async function sendGlobalMessage(text: string) {
    if (!authStore.user || !text.trim() || !gameStore.db) return

    const payload = {
      user_id: authStore.user.id,
      username: gameStore.state.trainer || (authStore.user as any).user_metadata?.username || 'Entrenador',
      message: text.slice(0, 180),
      player_class: gameStore.state.playerClass,
      trainer_level: gameStore.state.trainerLevel || 1
    }

    const { error } = await gameStore.db.from('global_chat_messages').insert(payload)
    if (error) {
      console.error('[ChatStore] Global message error:', error)
    } else {
      audioStore.sentMsg(); // Sonido al enviar satisfactoriamente

      // En modo Offline, no hay disparador de Postgres Realtime, así que pusheamos manualmente
      if (authStore.sessionMode === 'offline') {
        const localRow = {
          id: Date.now(),
          ...payload,
          created_at: new Date().toISOString()
        }
        globalMessages.value.push(localRow as any)
        if (globalMessages.value.length > 50) globalMessages.value.shift()
      }
    }
  }

  async function sendPrivateMessage(friendId: string, text: string) {
    if (!authStore.user || !text.trim() || !privateChats[friendId] || !gameStore.db) return

    const payload = {
      senderId: authStore.user.id,
      senderName: gameStore.state.trainer || (authStore.user as any).user_metadata?.username || 'Entrenador',
      text: text.slice(0, 250),
      timestamp: new Date().toISOString()
    }

    const db = gameStore.db
    // 1. Enviar vía broadcast
    if (!(outboxChannels as any)[friendId]) {
      (outboxChannels as any)[friendId] = db.channel(`chat-inbox-${friendId}`).subscribe((status: string) => {
        if (status === 'SUBSCRIBED' && (outboxChannels as any)[friendId]) {
          (outboxChannels as any)[friendId].send({ type: 'broadcast', event: 'private_message', payload })
        }
      })
    } else {
      (outboxChannels as any)[friendId].send({ type: 'broadcast', event: 'private_message', payload })
    }

    // 2. Agregar a historial propio y persistir
    handleIncomingPrivate({ ...payload, senderId: authStore.user.id })
    audioStore.sentMsg(); // Sonido al enviar privado
  }

  function openChat(friendId: string, username: string) {
    if (!privateChats[friendId]) {
      privateChats[friendId] = {
        username: username || 'Entrenador',
        messages: [],
        unreadCount: 0,
        isCollapsed: false,
        lastInteraction: Date.now()
      }
    }
    privateChats[friendId].unreadCount = 0
    privateChats[friendId].isCollapsed = false
    activeChatId.value = friendId
  }

  function closeChat(friendId: string) {
    if (privateChats[friendId]) {
      delete privateChats[friendId]
      gameStore.state.chats = { ...privateChats }
    }
    if (activeChatId.value === friendId) {
      activeChatId.value = 'global'
    }
  }

  return {
    globalMessages,
    privateChats,
    activeChatId,
    initGlobalChat,
    initPrivateInbox,
    sendGlobalMessage,
    sendPrivateMessage,
    openChat,
    closeChat
  }
})

import { defineStore } from 'pinia'
import { reactive } from 'vue'

/**
 * Combat Shadow Store
 * Centralized management for shadows in the virtual battle arena.
 */
export const useCombatShadowStore = defineStore('combatShadows', () => {
  const activeShadows = reactive(new Map<string, any>())
  const feetCache = reactive(new Map<string, any>()) // Caché persistente de puntos de anclaje por spriteUrl

  async function detectFeetPoints(url: string): Promise<{ feetY: number, feetX: number }> {
    if (!url) return { feetY: 0.9, feetX: 0.5 }

    // Si ya está en caché, lo devolvemos inmediatamente
    if (feetCache.has(url)) return feetCache.get(url)

    return new Promise((resolve) => {
      const img = new Image()
      img.crossOrigin = 'anonymous'
      img.onload = () => {
        // [PureVue-Ignore]
        const canvas = document.createElement('canvas')
        const ctx = canvas.getContext('2d')
        if (!ctx) { resolve({ feetY: 0.9, feetX: 0.5 }); return }
        canvas.width = img.width
        canvas.height = img.height
        ctx.drawImage(img, 0, 0)
        try {
          const { data } = ctx.getImageData(0, 0, canvas.width, canvas.height)

          // Buscamos los límites de la caja de colisión (bounding box) para centrar la sombra
          let minX = canvas.width, maxX = 0, lowestY = -1

          for (let y = 0; y < canvas.height; y++) {
            for (let x = 0; x < canvas.width; x++) {
              const index = (y * canvas.width + x) * 4
              const alpha = data[index + 3] || 0
              if (alpha > 50) {
                if (x < minX) minX = x
                if (x > maxX) maxX = x
                if (y > lowestY) lowestY = y
              }
            }
          }

          if (lowestY !== -1) {
            const centerX = (minX + maxX) / 2
            const result = { 
              feetY: lowestY / canvas.height, 
              feetX: centerX / canvas.width 
            }
            feetCache.set(url, result)
            resolve(result)
            return
          }
        } catch (err) {
          console.warn('[SHADOW] Canvas data extraction failed:', err)
        }
        resolve({ feetY: 0.9, feetX: 0.5 })
      }
      img.onerror = () => resolve({ feetY: 0.9, feetX: 0.5 })
      img.src = url
    })
  }

  async function requestShadow(id: string, options: any = {}) {
    if (!id) return
    const existing = activeShadows.get(id)

    // Bloqueo de propiedad: Si ya tiene una sombra activa para este sprite, no le damos otra (Evitar parpadeos)
    if (existing && options.spriteUrl === existing.spriteUrl && !options.force) {
      // Solo actualizamos visibilidad si cambió, sin disparar todo el proceso de re-creación
      if (options.visible !== undefined && existing.visible !== options.visible) {
        existing.visible = options.visible
      }
      return Promise.resolve(existing)
    }

    // Intentar obtener valores de la caché para evitar el salto inicial (Sync)
    const cachedPoints = options.spriteUrl ? feetCache.get(options.spriteUrl) : null

    let feetY = options.feetY || (cachedPoints?.feetY ?? (existing?.feetY ?? 0.9))
    // Si es volador, ignoramos el valor detectado y forzamos el suelo
    if (options.isFlying) feetY = 0.9

    const feetX = options.feetX || (cachedPoints?.feetX ?? (existing?.feetX ?? 0.5))
    const visible = options.visible !== undefined ? options.visible : true

    // Guardamos/actualizamos la sombra inmediatamente para que sea visible
    const newShadow = {
      id,
      side: options.side || 'generic',
      entityX: options.entityX ?? (existing?.entityX ?? 0),
      entityY: options.entityY ?? (existing?.entityY ?? 0),
      entitySize: options.entitySize ?? (existing?.entitySize ?? 300),
      width: options.width || (existing?.width ?? '70%'),
      isFlying: options.isFlying || false,
      feetY,
      feetX,
      spriteUrl: options.spriteUrl || existing?.spriteUrl,
      visible
    }

    activeShadows.set(id, newShadow)

    // Si el sprite cambió y no estaba en caché, calculamos nuevos puntos de anclaje EN SEGUNDO PLANO
    if (options.spriteUrl && options.spriteUrl !== existing?.spriteUrl && !cachedPoints) {
      return detectFeetPoints(options.spriteUrl).then(points => {
        // Solo actualizamos si la sombra sigue existiendo y es del mismo sprite
        const current = activeShadows.get(id)
        if (current && current.spriteUrl === options.spriteUrl) {
          // Si es volador, forzamos el anclaje al suelo (90%) 
          // para que los items (pokebolas) no caigan "en el aire"
          const finalFeetY = current.isFlying ? 0.9 : points.feetY

          activeShadows.set(id, {
            ...current,
            feetY: finalFeetY,
            feetX: points.feetX
          })
        }
        return points
      })
    }

    return Promise.resolve(newShadow)
  }

  function showShadow(id: string) {
    if (!id) return
    const shadow = activeShadows.get(id)
    if (shadow) {
      shadow.visible = true
    }
  }

  function hideShadow(id: string) {
    if (!id) return
    const shadow = activeShadows.get(id)
    if (shadow) {
      shadow.visible = false
    }
  }

  function removeShadow(id: string) {
    activeShadows.delete(id)
  }

  function clearAll() {
    activeShadows.clear()
  }

  return {
    activeShadows,
    feetCache,
    detectFeetPoints,
    requestShadow,
    showShadow,
    hideShadow,
    removeShadow,
    clearAll
  }
})

import { defineStore } from 'pinia'
import { ref, computed, watch } from 'vue'
import { useAuthStore } from './auth'
import { useGameStore } from './game'
import { useUIStore } from './ui'
import { useMapStore } from './map'
import { usePvPStore } from './pvp'
import { useBreedingStore } from './breeding'
import { useModalStore } from './modals'
import { useErrorStore } from './errorStore'

// Section Registrations
import { registerStatsTools } from './debug/sections/statsTools'
import { registerMapTools } from './debug/sections/mapTools'
import { registerPokeTools } from './debug/sections/pokeTools'
import { registerTimeTools } from './debug/sections/timeTools'
import { registerItemTools } from './debug/sections/itemTools'
import { registerSystemTools } from './debug/sections/systemTools'
import { registerAudioTools } from './debug/sections/audioTools'

export interface DebugTool {
  id: string
  command: string
  action: (...args: any[]) => any
  description?: string
}

export interface DebugContext {
  game: ReturnType<typeof useGameStore>
  ui: ReturnType<typeof useUIStore>
  pvp: ReturnType<typeof usePvPStore>
  auth: ReturnType<typeof useAuthStore>
  map: ReturnType<typeof useMapStore>
  mapStore: ReturnType<typeof useMapStore>
  breedingStore: ReturnType<typeof useBreedingStore>
  modalStore: ReturnType<typeof useModalStore>
  errorStore: ReturnType<typeof useErrorStore>
  eventStoreModule?: any
}

declare global {
  interface Window {
    __VITE_DEBUG__?: Record<string, (...args: any[]) => any>
  }
}

export const useDebugStore = defineStore('debug', () => {
  const auth = useAuthStore()
  const game = useGameStore()
  const ui = useUIStore()
  const map = useMapStore()
  const pvp = usePvPStore()
  const modalStore = useModalStore()
  const errorStore = useErrorStore()
  const breedingStore = useBreedingStore()

  const tools = ref<DebugTool[]>([])

  const canAccess = computed(() => {
    if (auth.sessionMode === 'offline') return true
    return auth.user?.role === 'admin'
  })

  function securityCheck() {
    if (auth.sessionMode === 'online' && auth.user?.role !== 'admin') {
      console.error('[SECURITY] Unauthorized debug access detected. Banning user and force logout.')
      const userId = auth.user?.id
      if (userId) {
        // game.db is typed as SupabaseClient | null in game.ts, but let's assume it has from()
        const db = (game as any).db
        if (db) {
          db.from('profiles').update({ 
            is_banned: true, 
            ban_reason: 'Intento de uso indebido de herramientas de debug' 
          }).eq('id', userId).then(() => {
            console.log('[SECURITY] DB Ban applied.')
          })
        }
      }
      auth.logout()
      return false
    }
    return true
  }

  function register(config: DebugTool) {
    const existingIdx = tools.value.findIndex(t => t.id === config.id)
    if (existingIdx !== -1) {
      tools.value[existingIdx] = config 
    } else {
      tools.value.push(config)
    }
    updateGlobalProxy()
  }

  function unregister(id: string) {
    tools.value = tools.value.filter(t => t.id !== id)
    updateGlobalProxy()
  }

  function updateGlobalProxy() {
    if (typeof window === 'undefined') return
    if (!canAccess.value) {
      delete window.__VITE_DEBUG__
      return
    }
    if (!window.__VITE_DEBUG__) window.__VITE_DEBUG__ = {}

    tools.value.forEach(tool => {
      window.__VITE_DEBUG__![tool.command] = (...args: any[]) => {
        if (securityCheck()) {
          return tool.action(...args)
        }
      }
    })
  }

  async function init() {
    console.log('[DEBUG] Initializing debug tools (Modular)...');

    // Pass all necessary stores to the specialized registration functions
    const context: DebugContext = { game, ui, pvp, auth, map, mapStore: map, breedingStore, modalStore, errorStore }

    // Synchronous registrations (fastest availability)
    registerStatsTools({ register }, context as any)
    registerMapTools({ register }, context as any)
    registerPokeTools({ register }, context as any)
    registerTimeTools({ register }, context as any)
    registerItemTools({ register }, context as any)
    registerAudioTools({ register }, context as any)

    // SystemTools registration (now synchronous registration, async module resolution)
    registerSystemTools({ register }, { ...context } as any)

    updateGlobalProxy()

    // Delayed dependency resolution for Admin tools
    try {
      const eventStoreModule = await import('./events')
      registerSystemTools({ register }, { ...context, eventStoreModule } as any)
      updateGlobalProxy()
    } catch (e) {
      console.warn('[DEBUG] Failed to load optional eventStoreModule for SystemTools', e)
    }
  }

  watch(canAccess, () => updateGlobalProxy())

  init()

  return {
    tools,
    canAccess,
    securityCheck,
    register,
    unregister,
    updateGlobalProxy
  }
})

import { gameBus } from '@/logic/gameBus'
import { useAudioStore } from '@/stores/audio'
import type { Pokemon } from '@/types/pokemon'
import type { BattleStages } from '@/types/battle'

interface DebugAction {
  id: string;
  label?: string;
  command: string;
  description: string;
  action: (...args: any[]) => string | void;
}

interface DebugRegisterOptions {
  register: (action: DebugAction) => void;
}

export function registerAudioTools({ register }: DebugRegisterOptions, _context: unknown) {
  const audio = useAudioStore()

  register({
    id: 'audio-play-sound',
    label: 'REPRODUCIR SONIDO',
    command: 'playSound',
    description: 'Reproducir un sonido del sistema.',
    action: (type: string) => {
      audio.play(type)
      return `Reproduciendo sonido: ${type}`
    }
  })

  register({
    id: 'audio-stop-all',
    label: 'DETENER AUDIO',
    command: 'stopAllAudio',
    description: 'Detener todos los sonidos y música.',
    action: () => {
      audio.stopAll()
      return 'Todos los audios detenidos'
    }
  })

  register({
    id: 'audio-set-volume',
    label: 'FIJAR VOLUMEN',
    command: 'setVolume',
    description: 'Ajustar el volumen maestro.',
    action: (val: number) => {
      audio.setVolume(val)
      return `Volumen ajustado a ${val}`
    }
  })

  register({
    id: 'trigger_anim',
    command: 'triggerAnim',
    description: 'Disparar una animación de combate via Bus.',
    action: (type: string, side = 'enemy', options: Record<string, unknown> = {}) => {
      const eventMap: Record<string, string> = {
        'release': 'PLAY_RELEASE_ENERGY',
        'catch': 'PLAY_CATCH_ENERGY',
        'shake': 'CATCH_SHAKE',
        'success': 'CATCH_SUCCESS',
        'faint': 'POKEMON_FAINT',
        'attack': 'PLAY_ATTACK_ANIM',
        'emergence': 'START_BATTLE',
        'reveal': 'START_BATTLE'
      }

      const event = eventMap[type] || type
      const payload: Record<string, unknown> = { side, ...options }

      // Manejo especial para START_BATTLE (Introducciones)
      if (type === 'emergence') payload.animationPhase = 1
      if (type === 'reveal') payload.animationPhase = 3

      gameBus.emit(event, payload)
      return `Evento emitido: ${event} para ${side}`
    }
  })

  register({
    id: 'set_status',
    command: 'setStatus',
    description: 'Cambiar estado de un pokemon (burn, poison, paralyze, freeze, sleep, null). Toggle si ya lo tiene.',
    action: (side: string, status: string) => {
      import('@/stores/battle').then(({ useBattleStore }) => {
        const battle = useBattleStore()
        const poke = side === 'player' ? battle.activeBattle?.player : (battle.upcomingPokemon || battle.activeBattle?.enemy)
        if (poke) {
          if (status === 'null') {
            poke.status = null
          } else {
            // Toggle logic
            poke.status = poke.status === (status as any) ? null : (status as any)
            if (poke.status === 'sleep') poke.sleepTurns = 3
          }
        }
      })
      return `Comando setStatus(${side}, ${status}) enviado.`
    }
  })

  register({
    id: 'set_secondary_status',
    command: 'setSecondaryStatus',
    description: 'Cambiar estados secundarios (confused, attracted, cursed, seeded). Toggle automático.',
    action: (side: string, type: string) => {
      import('@/stores/battle').then(({ useBattleStore }) => {
        const battle = useBattleStore()
        const poke = (side === 'player' ? battle.activeBattle?.player : (battle.upcomingPokemon || battle.activeBattle?.enemy)) as (Pokemon & Record<string, unknown>) | undefined
        if (poke) {
          if (type === 'confused') poke.confused = (poke.confused || 0) > 0 ? 0 : 4
          if (type === 'attracted') poke.attracted = !poke.attracted
          if (type === 'cursed') poke.cursed = !poke.cursed
          if (type === 'seeded') poke.seeded = !poke.seeded
          if (type === 'trapped') (poke as any).trapped = !(poke as any).trapped
          if (type === 'ingrain') poke.ingrain = !poke.ingrain
          if (type === 'protect') poke.protect = !poke.protect
          if (type === 'endure') poke.endure = !poke.endure
          if (type === 'focus_energy') poke.focusEnergy = !poke.focusEnergy
          if (type === 'lock_on') poke.lockOn = !poke.lockOn
        }
      })
      return `Comando setSecondaryStatus(${side}, ${type}) enviado.`
    }
  })

  register({
    id: 'set_stat_stage',
    command: 'setStatStage',
    description: 'Cambiar nivel de estadística (-6 a +6).',
    action: (side: string, stat: string, val: string) => {
      import('@/stores/battle').then(({ useBattleStore }) => {
        const battle = useBattleStore()
        const stages = side === 'player' ? battle.playerStages : battle.enemyStages
        if (stages && (stages as any)[stat] !== undefined) {
          (stages as any)[stat] = Math.max(-6, Math.min(6, parseInt(val)))
        }
      })
      return `setStatStage(${side}, ${stat}, ${val})`
    }
  })

  register({
    id: 'modify_stat_stage',
    command: 'modifyStatStage',
    description: 'Modificar nivel de estadística relativo (ej: +1, -1).',
    action: (side: string, stat: string, delta: string) => {
      import('@/stores/battle').then(({ useBattleStore }) => {
        const battle = useBattleStore()
        const stages = side === 'player' ? battle.playerStages : battle.enemyStages
        if (stages && (stages as any)[stat] !== undefined) {
          (stages as any)[stat] = Math.max(-6, Math.min(6, ((stages as any)[stat] || 0) + parseInt(delta)))
        }
      })
      return `modifyStatStage(${side}, ${stat}, ${delta})`
    }
  })

  register({
    id: 'set_field_effect',
    command: 'setFieldEffect',
    description: 'Activar efecto de campo (screens, weather). Toggle automático.',
    action: (side: string, effect: string, val: string) => {
      import('@/stores/battle').then(({ useBattleStore }) => {
        const battle = useBattleStore()
        const stages = (side === 'player' ? battle.playerStages : battle.enemyStages) as any

        // Screens & Hazards (Stage based)
        const isStageEffect = ['reflect', 'lightScreen', 'safeguard', 'mist', 'spikes'].includes(effect)
        if (isStageEffect && stages) {
          // Lógica FLIP: si ya tiene el efecto (>0), lo quitamos (0). Si no, lo ponemos (val o 5).
          stages[effect] = stages[effect] > 0 ? 0 : (parseInt(val) || 5)
        }

        // Weather (Context based)
        const ALL_WEATHER = ['sun', 'rain', 'hail', 'sandstorm', 'snow', 'fog', 'clear', 'storm', 'blizzard', 'heatwave']
        if (ALL_WEATHER.includes(effect)) {
          if (battle.activeBattle) {
            const current = battle.state?.weather?.type
            // Lógica FLIP: si el clima actual es el mismo que tocamos, lo limpiamos.
            if (current === effect && effect !== 'clear') {
              if (battle.state) battle.state.weather = { type: 'clear', visual: 'clear', turns: -1 }
            } else {
              if (battle.state) {
                battle.state.weather = { 
                  type: effect as any, 
                  visual: effect as any,
                  turns: effect === 'clear' ? -1 : (parseInt(val) || 5) 
                }
              }
            }
          }
        }
      })
      return `setFieldEffect(${side}, ${effect}, ${val})`
    }
  })
}

import { SHOP_ITEMS } from '@/data/items'

export function registerItemTools(debug: any, { game, ui, breedingStore }: { game: any, ui: any, breedingStore: any }) {
  debug.register({
    id: 'item-add',
    label: 'AÑADIR ITEM',
    command: 'addItem',
    category: 'items',
    action: (name: string, qty = 10) => {
      game.state.inventory[name] = (game.state.inventory[name] || 0) + qty
      ui.notify(`Debug: +${qty} ${name}`, '🎒')
      game.saveGame(false)
    },
    description: 'Añade una cantidad de un item a la mochila.'
