import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { useAuthStore } from './auth'
import { useUIStore } from './ui'
import { useGameStore } from './game'
import { isEventActiveNow, getGlobalMultipliers, getSpeciesBoosts, type Event as GameEvent } from '@/logic/events/eventEngine'
import { getServerTime } from '@/logic/timeUtils'
import type { Pokemon } from '@/types/pokemon'

interface CompetitionResult {
  id: string
  event_id: string
  winner_id: string
  winner_name: string
  winner_email: string
  data: any
  ended_at: string
}

interface PendingAward {
  id: string
  winner_id: string
  prize: string
  received_at: string | null
}

export const useEventStore = defineStore('events', () => {
  const gameStore = useGameStore()
  const authStore = useAuthStore()
  const uiStore = useUIStore()

  const allEvents = ref<GameEvent[]>([])
  const activeEvents = ref<GameEvent[]>([])
  const finishedEvents = ref<CompetitionResult[]>([])
  const pendingAwards = ref<PendingAward[]>([])
  const isLoading = ref(false)

  // Computed multipliers derived from active events
  const globalMultipliers = computed(() => getGlobalMultipliers(activeEvents.value))

  /**
   * Fetches the full event configuration and filters based on Engine logic.
   */
  async function fetchEvents() {
    if (isLoading.value) return
    isLoading.value = true
    
      const db = gameStore.db
      if (!db) {
        isLoading.value = false
        return
      }
    try {
      // 1. Fetch from config (DBRouter handles source)
      const { data: events, error } = await db.from('events_config').select('*').eq('active', true)
      if (error) throw error

      allEvents.value = events || []
      
      // 2. Filter using Engine logic with synchronized time
      const synchronizedDate = new Date(getServerTime())
      activeEvents.value = (events || []).filter((ev: GameEvent) => isEventActiveNow(ev, synchronizedDate))

      // 3. Load finished competition results (Last 24h)
      const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
      const { data: results } = await db.from('competition_results')
        .select('*')
        .gt('ended_at', twentyFourHoursAgo)
        .order('ended_at', { ascending: false })

      finishedEvents.value = (results || []) as CompetitionResult[]

      // 4. Check for unclaimed prizes
      await checkPendingAwards()
    } catch (e) {
      console.error('[Events] Error fetching events:', e)
    } finally {
      isLoading.value = false
    }
  }

  function isEventActive(ev: string) {
    return activeEvents.value.some(e => e.id === ev)
  }

  function getEventMultiplier(_pokemon: Pokemon, eventId: string) {
    if (!isEventActive(eventId)) return 1
    const ev = activeEvents.value.find(e => e.id === eventId)
    return (ev as any)?.multiplier || 1
  }

  /**
   * Submits a competitive entry to an active event.
   */
  async function submitCompetitionEntry(pokemon: Pokemon, eventId: string) {
    if (!authStore.user) return

    const event = activeEvents.value.find(e => e.id === eventId)
    if (!event) return

    // Calculate generic total IVs for legacy compatibility
    const totalIvs = Object.values(pokemon.ivs || {}).reduce((a: number, b: number) => a + b, 0)

    try {
      const entryData = {
        event_id: eventId,
        player_id: authStore.user.id,
        player_name: gameStore.state.trainer || 'Trainer',
        player_email: authStore.user.email,
        data: {
          pokemon_name: pokemon.name,
          ivs: pokemon.ivs,
          total_ivs: totalIvs,
          level: pokemon.level,
          isShiny: pokemon.isShiny || false
        },
        submitted_at: new Date().toISOString()
      }

      const db = gameStore.db
      if (!db) return

      // Check if current entry is better before upserting (Utility check)
      // This is often handled by DB constraint but useful for UI feedback
      const { error } = await db.from('competition_entries').upsert(entryData, {
        onConflict: 'event_id, player_id'
      })

      if (error) throw error
      uiStore.notify(`¡Registro exitoso en ${event.name}!`, event.icon || '🏆')
    } catch (e) {
      console.error('[Events] Error submitting entry:', e)
      uiStore.notify('Error al inscribir en el concurso.', '❌')
    }
  }

  /**
   * Syncs pending awards for the user.
   */
  async function checkPendingAwards() {
    if (!authStore.user || !gameStore.db) return

    const { data: awards, error } = await gameStore.db.from('awards')
      .select('*')
      .eq('winner_id', authStore.user.id)
      .is('received_at', null)

    if (!error) {
      pendingAwards.value = (awards || []) as PendingAward[]
    }
  }

  /**
   * Claim a specific award using the backend RPC.
   */
  async function claimAward(awardId: string): Promise<string | null> {
    if (!gameStore.db) return null
    const { data, error } = await gameStore.db.rpc('claim_award', { p_award_id: awardId })
    
    if (!error && data?.ok) {
      pendingAwards.value = pendingAwards.value.filter(a => a.id !== awardId)
      uiStore.notify('¡Recompensa reclamada!', '🎁')
      // Return details for local state updates (e.g., adding to inventory)
      return data.prize as string
    }
    return null
  }

  /**
   * Helper to get boosts for a specific species.
   */
  function getSpeciesBonuses(speciesId: string) {
    return getSpeciesBoosts(activeEvents.value, speciesId)
  }

  function getCaptureEvent(speciesId: string) {
    return activeEvents.value.find(e => (e as any).type === 'capture' && (e as any).targetId === speciesId)
  }

  // Listen for time-sync updates from DBRouter (Debug mode)
  if (typeof window !== 'undefined') {
    window.addEventListener('time-sync-update', () => {
      console.log('[Events] Time sync update received, refreshing events...');
      fetchEvents();
    });
  }

  return {
    activeEvents,
    finishedEvents,
    pendingAwards,
    isLoading,
    globalMultipliers,
    fetchEvents,
    submitCompetitionEntry,
    checkPendingAwards,
    claimAward,
    getSpeciesBonuses,
    getCaptureEvent,
    getEventMultiplier
  }
})

import { defineStore } from 'pinia';
import { ref } from 'vue';
import { evolvePokemonData } from '@/logic/evolutionLogic';
import { useGameStore } from '@/stores/game';

export const useEvolutionStore = defineStore('evolution', () => {
  const gameStore = useGameStore() as any;

  // --- STATE ---
  const isEvolving = ref(false);
  const sourcePokemon = ref<any>(null);
  const targetId = ref<string | null>(null);
  const onComplete = ref<((data: any) => void) | null>(null);
  const pendingMoves = ref<any[]>([]);

  // --- ACTIONS ---

  /**
   * Starts the evolution sequence.
   * @param {Object} pokemon - The pokemon instance to evolve.
   * @param {String} targetSpeciesId - The ID of the target species.
   * @param {Function} callback - Callback after the animation finishes.
   */
  function startEvolution(pokemon: any, targetSpeciesId: string, callback: ((data: any) => void) | null = null) {
    sourcePokemon.value = pokemon;
    targetId.value = targetSpeciesId;
    isEvolving.value = true;
    onComplete.value = callback;
    pendingMoves.value = [];
  }

  /**
   * Performs the data transformation of the pokemon species.
   * Mutates the sourcePokemon object.
   */
  function evolve() {
    if (!sourcePokemon.value || !targetId.value) return;

    const result = evolvePokemonData(sourcePokemon.value, targetId.value);
    if (!result) return;

    pendingMoves.value = (result as any).pendingMoves;

    // Pokédex registration
    gameStore.registerPokedex(targetId.value, true); // true = caught

    // Persistence
    gameStore.scheduleSave();

    return { 
      oldName: (result as any).oldName, 
      newName: sourcePokemon.value.name,
      fromId: (result as any).fromId,
      toId: (result as any).toId
    };
  }

  /**
   * Resets the evolution state and triggers the callback.
   */
  function finishEvolution() {
    isEvolving.value = false;
    if (onComplete.value) {
      onComplete.value({
        pokemon: sourcePokemon.value,
        pendingMoves: pendingMoves.value
      });
    }
    sourcePokemon.value = null;
    targetId.value = null;
    onComplete.value = null;
  }

  return {
    isEvolving,
    sourcePokemon,
    targetId,
    pendingMoves,
    startEvolution,
    evolve,
    finishEvolution
  };
});

import { defineStore } from 'pinia'
import { reactive, ref, computed, watch } from 'vue'
import { useAuthStore } from './auth'
import { supabase } from '@/logic/supabase'
import { INITIAL_STATE } from './gameInitialState'
import type { GameState } from '@/types/game'


// Actions Modules
import { useSaveActions } from './game/actions/saveActions'
import { usePokemonActions } from './game/actions/pokemonActions'
import { useTrainerActions } from './game/actions/trainerActions'
import { useBreedingActions } from './game/actions/breedingActions'
import { useTeamActions } from './game/actions/teamActions'

import type { SupabaseClient } from '@supabase/supabase-js'

export const useGameStore = defineStore('game', () => {
  const authStore = useAuthStore()
  const state = reactive<GameState>(JSON.parse(JSON.stringify(INITIAL_STATE)))

  const db = ref<SupabaseClient | null>(supabase as any)
  const isDataLoaded = ref(false)
  const isEngineReady = ref(false)
  const isReady = computed(() => isDataLoaded.value && isEngineReady.value)

  function updateState(newData: Partial<GameState>) {
    if (newData.team && newData.team.length > 0) newData.starterChosen = true
    Object.assign(state, newData)
    console.log('[STORE] Game state updated.');
  }

  function resetToInitial() {
    Object.keys(state).forEach(key => {
      delete (state as Record<string, unknown>)[key]
    })
    Object.assign(state, JSON.parse(JSON.stringify(INITIAL_STATE)))
    isDataLoaded.value = false
  }

  // --- ACTIONS INITIALIZATION ---

  // 1. Save Actions (Basics needed for others)
  const { loadGame: rawLoad, save, scheduleSave, claimAsset, fetchClaimQueue } = useSaveActions(state, authStore, db, updateState)

  // 2. Team Actions (Special teams management)
  const { autoFillPvpTeam, swapPvpSlot, reorderPvpTeam, autoFillWarTeam, swapWarSlot, reorderWarTeam } = useTeamActions(state, scheduleSave)

  // 3. Pokemon Actions
  const { registerPokedex, chooseStarter, addPokemon, removePokemon, reorderTeam, reorderMoves, sendToBox, togglePokeTag } = usePokemonActions(state, scheduleSave, autoFillPvpTeam, autoFillWarTeam)

  // 4. Trainer Actions
  const { getTrainerRank, addTrainerExp, checkLevelUp, getMaxObeyLevel } = useTrainerActions(state, scheduleSave)

  // 5. Breeding Actions
  const { hatchEggs, executeHatch } = useBreedingActions(state, scheduleSave, addPokemon)

  // Wrapper for LoadGame to manage local state
  async function loadGame(): Promise<void> {
    const res = await rawLoad()

    if (res.success) {
      isDataLoaded.value = true
      isEngineReady.value = true
    }
  }

  // --- WATCHERS ---
  watch(() => state.team.length, (newLen, oldLen) => {
    if (newLen > oldLen && state.pvpTeam.length < 3) autoFillPvpTeam()
  })

  return {
    state,
    db,
    updateState,
    resetToInitial,
    registerPokedex,
    scheduleSave,
    hatchEggs,
    claimAsset,
    fetchClaimQueue,
    loadGame,
    save,
    isDataLoaded,
    isEngineReady,
    isReady,
    chooseStarter,
    addTrainerExp,
    checkLevelUp,
    getTrainerRank,
    getMaxObeyLevel,
    reorderTeam,
    reorderPvpTeam,
    reorderWarTeam,
    reorderMoves,
    sendToBox,
    addPokemon,
    removePokemon,
    autoFillPvpTeam,
    swapPvpSlot,
    autoFillWarTeam,
    swapWarSlot,
    togglePokeTag,
    executeHatch,
    saveGame: save // Alias
  }
})

import { makePokemon } from '@/logic/pokemonFactory'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { useUIStore } from '@/stores/ui'
import { useEventStore } from '@/stores/events'
import type { GameState } from '@/types/game'
import type { Pokemon, PokemonEgg } from '@/types/pokemon'

export function useBreedingActions(
  state: GameState, 
  scheduleSave: () => Promise<void>, 
  addPokemon: (pokemon: Pokemon, options?: { notify: boolean }) => any
) {
  function hatchEggs() {
    if (!state.eggs || state.eggs.length === 0) return false
    let anyReady = false
    const eventStore = useEventStore()
    const evHatchMult = (eventStore.globalMultipliers?.hatch || 1) - 1
    const hatchMult = 1 + evHatchMult

    state.eggs.forEach((egg: PokemonEgg) => {
      if (!egg.ready && typeof egg.steps === 'number' && egg.steps > 0) {
        egg.steps -= hatchMult
        if (egg.steps <= 0) {
          egg.steps = 0
          egg.ready = true
          anyReady = true
          useUIStore().notify('¡Un Huevo Pokémon está listo para eclosionar!', '🥚')
        }
      }
    })
    return anyReady
  }

  async function executeHatch(egg: PokemonEgg) {
    const { recalcPokemonStats } = await import('@/logic/pokemonFactory')

    const p = makePokemon(egg.id, 1, {
      isShiny: egg.isShiny,
      isGuardian: egg.isGuardian,
      nature: egg.nature,
      abilitySlot: egg.abilitySlot,
      gender: egg.gender
    })

    if (!p) throw new Error(`Failed to create pokemon from egg ${egg.id}`)

    if (egg.ivs) {
      p.ivs = { ...p.ivs, ...egg.ivs }
    }

    if (egg.movesAtBirth) {
      p.moves = egg.movesAtBirth.map(mName => {
        const mData = pokemonDataProvider.getMoveData(mName)
        return { name: mName, pp: mData?.pp || 35, maxPP: mData?.pp || 35 }
      })
    }

    p.obtainedMethod = 'egg'
    recalcPokemonStats(p)
    p.hp = p.maxHp

    state.eggs = state.eggs.filter(e => e.uid !== egg.uid)
    addPokemon(p, { notify: false })

    await scheduleSave()
    return p
  }

  return { hatchEggs, executeHatch }
}

import { loadBestSave } from '@/logic/auth/loadService'
import { saveGame as performSave } from '@/logic/auth/saveService'
import { useLoadingStore } from '@/stores/loading'
import { useUIStore } from '@/stores/ui'
import type { GameState, ClaimItem } from '@/types/game'
import type { AuthUser } from '@/types/auth'
import type { Ref } from 'vue'

export function useSaveActions(
  state: GameState, 
  authStore: { user: AuthUser | null }, 
  db: Ref<any>, 
  updateState: (data: GameState) => void
) {
  async function loadGame() {
    const loadingStore = useLoadingStore()
    loadingStore.start('game_data', 'Cargando datos...', 'Leyendo partida guardada', false)

    if (!authStore.user) {
      return { success: true, guest: true }
    }

    const uiStore = useUIStore()
    let data: GameState | null = null;
    let issues: string[] = [];
    let lastSaveId: string | null = null;
    let isNewerThanCloud: boolean | undefined;
    let attempts = 0;
    const maxAttempts = 2;
    let lastError: any = null;

    while (attempts < maxAttempts) {
      try {
        const loadPromise = loadBestSave(authStore.user as any, db.value)
        const timeoutPromise = new Promise((_, reject) => 
          setTimeout(() => reject(new Error('LOAD_TIMEOUT')), 8000)
        );

        const result = await Promise.race([loadPromise, timeoutPromise]) as { data: GameState, issues: string[], lastSaveId: string | null, isNewerThanCloud: boolean };
        data = result.data;
        issues = result.issues;
        lastSaveId = result.lastSaveId;
        isNewerThanCloud = result.isNewerThanCloud;

        if (typeof sessionStorage !== 'undefined') {
          sessionStorage.setItem('load_retry_count', '0');
        }
        break;
      } catch (error) {
        attempts++
        lastError = error;
        console.warn(`[LOAD] Intento ${attempts} de carga fallido:`, error);

        if (attempts < maxAttempts) {
          loadingStore.setProgress('game_data', 'Conexión lenta...', `Reintentando (${attempts}/${maxAttempts})...`);
          await new Promise(resolve => setTimeout(resolve, 1500));
        }
      }
    }

    if (!data && lastError) {
      console.error('[LOAD] Todos los intentos de carga fallaron.', lastError);

      const isTimeout = lastError.message === 'LOAD_TIMEOUT';
      const isNetworkError = lastError.message && (
        lastError.message.toLowerCase().includes('fetch') ||
        lastError.message.toLowerCase().includes('network')
      );

      if (isTimeout || isNetworkError || !navigator.onLine) {
        if (!navigator.onLine) {
          loadingStore.setProgress('game_data', 'Sin conexión a Internet', 'Esperando señal para reintentar...');
          window.addEventListener('online', () => { window.location.reload(); }, { once: true });
          return { success: false, offline: true };
        } else {
          const retryCount = typeof sessionStorage !== 'undefined' ? parseInt(sessionStorage.getItem('load_retry_count') || '0') : 0;
          if (retryCount < 1) {
            if (typeof sessionStorage !== 'undefined') sessionStorage.setItem('load_retry_count', (retryCount + 1).toString());
            loadingStore.setProgress('game_data', 'Red inestable...', 'Reconectando al servidor...');
            window.location.reload();
            return { success: false, reconnecting: true };
          } else {
            loadingStore.setProgress('game_data', 'Error de conexión', 'La red no responde. Toca en cualquier lugar para reintentar.');
            window.addEventListener('click', () => {
              if (typeof sessionStorage !== 'undefined') sessionStorage.setItem('load_retry_count', '0');
              window.location.reload();
            }, { once: true });
            return { success: false, error: true };
          }
        }
      }
    }

    if (data && authStore.user) {
      updateState(data)
      authStore.user.last_save_id = lastSaveId || undefined

      if (issues && issues.length > 0) {
        console.warn('[LOAD] Saneamiento realizado:', issues)
        uiStore.notify('Partida saneada y cargada', '🛡️')
      } else {
        uiStore.notify(`¡Bienvenido, ${state.trainer || authStore.user.user_metadata?.username}!`, '👋')
      }

      if (authStore.user.db_version < 2) authStore.user.db_version = 2

      if (isNewerThanCloud) {
        uiStore.notify('Sincronizando progreso local más reciente...', '🔄')
        setTimeout(() => save(false), 3000)
      }
    }

    loadingStore.finish('game_data')
    return { success: true }
  }

  async function save(showNotif = true) {
    if (!authStore.user) return

    const uiStore = useUIStore()
    const notifyFn = uiStore.notify
    const result = await performSave(state, authStore.user, { 
      showNotif, 
      notifyFn, 
      db: db.value,
      userVersion: authStore.user.db_version,
      lastSaveId: authStore.user.last_save_id
    }) as { success: boolean, migrated?: boolean, lastSaveId?: string, rollback?: boolean, outOfSync?: boolean, error?: string }

    if (result) {
      if (result.migrated) authStore.user.db_version = 2
      if (result.lastSaveId) authStore.user.last_save_id = result.lastSaveId

      if (result.rollback && db.value) {
        if (result.outOfSync) notifyFn('Desincronización detectada. Restaurando...', '🔄')
        const { data: freshSave } = await db.value.from('game_saves').select('save_data, last_save_id').eq('user_id', authStore.user.id).single()
        if (freshSave) {
          updateState(freshSave.save_data)
          authStore.user.last_save_id = freshSave.last_save_id
        }
      }
    }
  }

  async function scheduleSave() {
    await save(false)
  }

  async function claimAsset(claimId: string) {
    if (!authStore.user || !db.value) return false
    try {
      const { data, error } = await db.value.rpc('claim_asset_v2', { p_claim_id: claimId })
      if (error) throw error
      if (data) {
        updateState(data as GameState)
        state.claimQueue = state.claimQueue.filter((c: ClaimItem) => c.id !== claimId)
        return true
      }
    } catch (e) {
      console.error('[CLAIM ERROR]', e)
      useUIStore().notify('Error al reclamar activo', '❌')
      return false
    }
    return false
  }

  async function fetchClaimQueue() {
    if (!authStore.user || !db.value) return
    const { data, error } = await db.value.from('claim_queue')
      .select('*')
      .eq('user_id', authStore.user.id)
      .order('created_at', { ascending: true })
    if (!error) state.claimQueue = data || []
  }

  return { loadGame, save, scheduleSave, claimAsset, fetchClaimQueue }
}

import { TRAINER_RANKS, MARKET_UNLOCKS } from '@/data/trainer'
import { levelUpPokemon } from '@/logic/pokemonFactory'
import { useUIStore } from '@/stores/ui'
import { useEventStore } from '@/stores/events'
import type { GameState } from '@/types/game'
import type { Pokemon } from '@/types/pokemon'

export function useTrainerActions(state: GameState, scheduleSave: () => Promise<void>) {
  function getTrainerRank() {
    const idx = Math.min(state.trainerLevel - 1, TRAINER_RANKS.length - 1)
    return TRAINER_RANKS[idx]
  }

  function addTrainerExp(amount: number) {
    const uiStore = useUIStore()
    const eventStore = useEventStore()
    const evBonus = (eventStore.globalMultipliers?.exp || 1) - 1
    const totalMult = 1 + evBonus
    if (totalMult > 1) amount = Math.round(amount * totalMult)

    state.trainerExp += amount
    const MAX_LEVEL = 30

    let currentRank = getTrainerRank()
    if (!currentRank) return

    while (state.trainerExp >= (currentRank?.expNeeded || 0) && state.trainerLevel < MAX_LEVEL) {
      state.trainerExp -= (currentRank?.expNeeded || 0)
      state.trainerLevel++

      currentRank = getTrainerRank()
      if (currentRank) {
        uiStore.notify(`¡Subiste al rango ${currentRank.title}! Nivel ${state.trainerLevel}`, '⭐')
      }

      const unlocks = (MARKET_UNLOCKS as any)[state.trainerLevel]
      if (unlocks) {
        setTimeout(() => uiStore.notify(`¡Nuevos items en el Poké Market!`, '🛒'), 1500)
      }
    }

    scheduleSave()
  }

  function checkLevelUp(pokemon: Pokemon) {
    const uiStore = useUIStore()
    const learnQueue: any[] = []

    while (pokemon.exp >= pokemon.expNeeded && pokemon.level < 100) {
      pokemon.exp -= pokemon.expNeeded
      const pendingMoves = levelUpPokemon(pokemon)

      if (pendingMoves === null) break // Blocked by Everstone

      uiStore.notify(`¡${pokemon.name} subió al nivel ${pokemon.level}!`, '📈')

      if (pendingMoves && pendingMoves.length > 0) {
        pendingMoves.forEach(m => learnQueue.push({ pokemon, move: m }))
      }
    }

    if (learnQueue.length > 0) {
      uiStore.addToLearnQueue(learnQueue)
    }

    scheduleSave()
  }

  function getMaxObeyLevel() {
    const badges = state.defeatedGyms?.length || 0
    if (badges >= 8) return 100
    if (badges >= 7) return 75
    if (badges >= 6) return 65
    if (badges >= 5) return 55
    if (badges >= 4) return 45
    if (badges >= 3) return 35
    if (badges >= 2) return 30
    if (badges >= 1) return 25
    return 20
  }

  return { getTrainerRank, addTrainerExp, checkLevelUp, getMaxObeyLevel }
}

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { useAuthStore } from './auth'
import { useGameStore } from './game'
import { useUIStore } from './ui'
import { useAudioStore } from './audio'
import { applyMarketFilters, markMarketSoldSeen, isMarketSoldSeen } from '@/logic/market'
import type { MarketFilters } from '@/logic/market'
import { SHOP_ITEMS } from '@/data/items'

export const useGTSStore = defineStore('gts', () => {
  const auth = useAuthStore() as any
  const game = useGameStore() as any
  const ui = useUIStore() as any
  const audio = useAudioStore() as any

  // State
  const listings = ref<any[]>([])
  const myListings = ref<any[]>([])
  const salesHistory = ref<any[]>([])
  const loading = ref(false)
  const publishing = ref(false)

  // Filters state
  const filters = ref<MarketFilters>({
    mode: 'pokemon', // 'pokemon' | 'item'
    search: '',
    priceMin: 0,
    priceMax: 1000000,
    tier: 'all',
    type: 'all',
    levelMin: 1,
    levelMax: 100,
    ivTotalMin: 0,
    ivTotalMax: 186,
    ivAny31: false,
    itemCat: 'all'
  })

  // Constants
  const MARKET_FEE = 0.05
  const MAX_LISTINGS = 10

  let salesChannel: any = null

  // Getters
  const filteredListings = computed(() => {
    return applyMarketFilters(listings.value, filters.value, 'explore', {
      SHOP_ITEMS
    })
  })

  const activeMyListings = computed(() => {
    return myListings.value.filter(l => l.status === 'active')
  })

  // Actions
  async function fetchListings() {
    if (auth.sessionMode === 'offline') return

    loading.value = true
    try {
      const { data, error } = await (game.db as any).from('market_listings')
        .select('*')
        .eq('status', 'active')
        .order('created_at', { ascending: false })
        .limit(100)

      if (!error) listings.value = data || []
    } finally {
      loading.value = false
    }
  }

  async function fetchUserData() {
    if (auth.sessionMode === 'offline' || !auth.user) return

    const [mine, history] = await Promise.all([
      game.db.from('market_listings')
        .select('*')
        .eq('seller_id', auth.user.id)
        .neq('status', 'sold')
        .order('created_at', { ascending: false }),
      game.db.from('market_listings')
        .select('*')
        .eq('seller_id', auth.user.id)
        .eq('status', 'sold')
        .order('created_at', { ascending: false })
        .limit(20)
    ])

    myListings.value = mine.data || []
    salesHistory.value = history.data || []

    // Check for new sales
    if (history.data && history.data.length > 0) {
      (history.data as any[]).forEach(sale => {
        if (!isMarketSoldSeen(sale.id, game.state)) {
          ui.notify(`¡Tu ${sale.data.name} se vendió por ₽${sale.price.toLocaleString()}!`, '💰')
          markMarketSoldSeen(sale.id, game.state)
        }
      })
    }
  }

  function initRealtime() {
    if (auth.sessionMode === 'offline' || !auth.user) return
    if (salesChannel) return

    salesChannel = game.db.channel(`market-sales-${auth.user.id}`)
      .on('postgres_changes', {
        event: 'UPDATE',
        schema: 'public',
        table: 'market_listings',
        filter: `seller_id=eq.${auth.user.id}`
      }, (payload: any) => {
        if (payload.new.status === 'sold' && payload.old.status !== 'sold') {
          ui.notify('¡ Venta realizada en el GTS !', '💰')
          audio.money()
          fetchUserData()
        }
      })
      .subscribe()
  }

  function stopRealtime() {
    if (salesChannel) {
      salesChannel.unsubscribe()
      salesChannel = null
    }
  }

  async function buyListing(listing: any) {
    if (game.state.money < listing.price) {
      ui.notify('Saldo insuficiente', '💸')
      return false
    }

    try {
      ui.setLoading(true)

      // MANDATORY: Pre-Action Flush
      ui.notify('Sincronizando fondos...', '🔄')
      await game.save(false)

      const { data: newSave, error } = await (game.db as any).rpc('buy_listing_v2', {
        p_listing_id: listing.id
      })

      if (error) throw error

      if (newSave) {
        game.updateState(newSave)

        ui.notify('¡ Compra exitosa ! Objeto enviado a tus Reclamos.', '✅')
        await game.fetchClaimQueue()
        fetchListings()
        return true
      }
      return false
    } catch (e) {
      console.error('[GTS BUY ERROR]', e)
      ui.notify((e as any).message || 'Error en la compra', '❌')
      return false
    } finally {
      ui.setLoading(false)
    }
  }

  async function publishListing(type: string, selection: any, price: number) {
    if (activeMyListings.value.length >= MAX_LISTINGS) {
      ui.notify(`Límite de publicaciones alcanzado (${MAX_LISTINGS})`, '⚠️')
      return false
    }

    publishing.value = true
    try {
      // MANDATORY: Pre-Action Flush
      ui.notify('Sincronizando inventario...', '🔄')
      await game.save(false)

      const { data: _listingId, error } = await (game.db as any).rpc('publish_listing_v2', {
        p_listing_type: type,
        p_asset_data: type === 'pokemon' ? selection : { name: selection.name, qty: 1 },
        p_price: Math.floor(price)
      })

      if (error) throw error

      // Refresh state to confirm removal
      const { data: save } = await (game.db as any).from('game_saves').select('save_data').eq('user_id', auth.user.id).single()
      if (save?.save_data) {
        game.updateState(save.save_data)
      }

      ui.notify('¡ Publicación exitosa ! Objeto en custodia.', '🚀')
      fetchUserData()
      return true
    } catch (e) {
      console.error('[GTS PUB ERROR]', e)
      ui.notify((e as any).message || 'Error al publicar', '❌')
      return false
    } finally {
      publishing.value = false
    }
  }

  async function cancelListing(listingId: string | number) {
    try {
      ui.notify('Retirando publicación...', '🔄')
      const { error } = await (game.db as any).rpc('cancel_listing_v2', {
        p_listing_id: listingId
      })

      if (error) throw error

      ui.notify('Publicación retirada. Reclámala en tus Reclamos.', '↩️')
      await game.fetchClaimQueue()
      fetchUserData()
      return true
    } catch (e) {
      console.error('[GTS CANCEL ERROR]', e)
      ui.notify((e as any).message || 'Error al retirar', '❌')
      return false
    }
  }

  return {
    listings,
    myListings,
    salesHistory,
    loading,
    publishing,
    filters,
    MARKET_FEE,
    MAX_LISTINGS,
    filteredListings,
    activeMyListings,
    fetchListings,
    fetchUserData,
    initRealtime,
    stopRealtime,
    buyListing,
    publishListing,
    cancelListing
  }
})

