import { defineStore } from 'pinia'
import { ref, computed, watch } from 'vue'
import { useGameStore } from './game'
import { useBattleStore } from './battle'
import { useUIStore } from './ui'
import { safeStorage } from '@/logic/utils/storage'
import { SHOP_ITEMS } from '@/data/items'
import { itemEffects as ITEM_EFFECTS, getDynamicItemEffect } from '@/logic/items/itemEffects'
import { isGlobalItem } from '../logic/providers/itemProvider'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import type { Pokemon } from '@/types/pokemon'

export interface Item {
  name: string;
  qty: number;
  id?: string;
  cat?: string;
  type?: string;
  sprite?: string;
  desc?: string;
  price?: number;
}

export const useInventoryStore = defineStore('inventory', () => {
  const gameStore = useGameStore()
  const uiStore = useUIStore()

  // --- BAG STATE ---
  const bagSellMode = ref(false)
  const bagSellSelected = ref<Record<string, number>>({}) // { itemName: quantity }
  const activeCategory = ref(safeStorage.getItem('inventory_last_tab') || 'todos')
  const searchQuery = ref('')

  watch(activeCategory, (newVal) => {
    safeStorage.setItem('inventory_last_tab', newVal)
  })

  // We no longer force "utilizables" category on target change 
  // to respect the user's last selected tab as requested.

  // --- GETTERS ---
  const bagItems = computed(() => {
    const inventory = gameStore.state.inventory || {}
    let items: Item[] = Object.entries(inventory)
      .map(([name, qty]) => {
        const item = SHOP_ITEMS.find(i => i.name === name)
        if (!item) return { name, qty, id: name, cat: 'otros', sprite: '', desc: 'Objeto desconocido' } as Item
        return { ...item, qty } as Item
      })

    if (activeCategory.value === 'utilizables') {
      const target = uiStore.inventoryTarget
      if (target) {
        const list = target.context === 'team' ? gameStore.state.team : gameStore.state.box
        const pokemon = list[target.index]
        if (pokemon) {
          items = items.filter(item => isItemUsableOn(item.name, pokemon))
        }
      }
    }

    return items.filter(item => {
      if (activeCategory.value !== 'todos' && activeCategory.value !== 'utilizables' && item.cat !== activeCategory.value) return false
      if (searchQuery.value && !item.name.toLowerCase().includes(searchQuery.value.toLowerCase())) return false
      return true
    })
  })

  const CATEGORY_LABELS = {
    utilizables: 'Utilizables',
    todos: 'Todos',
    pokeballs: 'Balls',
    pociones: 'Cura',
    stones: 'Piedras',
    held: 'Equipo',
    breeding: 'Crianza',
    especial: 'Otros'
  }

  // --- BAG ACTIONS ---
  function toggleBagSellMode() {
    bagSellMode.value = !bagSellMode.value
    bagSellSelected.value = {}
  }

  function toggleBagSellSelect(itemName: string, maxQty: number) {
    if (bagSellSelected.value[itemName]) {
      delete bagSellSelected.value[itemName]
    } else {
      bagSellSelected.value[itemName] = maxQty
    }
  }

  function updateBagSellQty(itemName: string, qty: string | number, maxQty: number) {
    let q = typeof qty === 'string' ? parseInt(qty) : qty
    if (isNaN(q) || q < 1) q = 1
    if (q > maxQty) q = maxQty
    bagSellSelected.value[itemName] = q
  }

  function getBagSellTotalGain() {
    let total = 0
    Object.entries(bagSellSelected.value).forEach(([name, q]) => {
      const itemInfo = SHOP_ITEMS.find(i => i.name === name)
      if (itemInfo) total += Math.floor((itemInfo.price || 0) * 0.5) * q
    })
    return total
  }

  function confirmBagSell() {
    const selectedEntries = Object.entries(bagSellSelected.value)
    if (selectedEntries.length === 0) return false

    const totalGain = getBagSellTotalGain()

    selectedEntries.forEach(([name, qty]) => {
      const inv = gameStore.state.inventory
      if (!inv) return
      inv[name] = (inv[name] || 0) - qty
      if (inv[name] <= 0) delete inv[name]
      gameStore.state.inventory = { ...inv }
    })

    gameStore.state.money += totalGain
    toggleBagSellMode()
    gameStore.save()
    return totalGain
  }

  function removeItem(itemName: string, qty: number = 1) {
    if (!gameStore.state.inventory || !gameStore.state.inventory[itemName]) return

    if (qty === 999) {
      delete gameStore.state.inventory[itemName]
    } else {
      gameStore.state.inventory[itemName] -= qty
      if (gameStore.state.inventory[itemName] <= 0) delete gameStore.state.inventory[itemName]
    }

    // Force reactivity for inventory object
    gameStore.state.inventory = { ...gameStore.state.inventory }
    gameStore.save(false)
  }

  function addItem(itemName: string, qty: number = 1) {
    if (!itemName) return
    const inventory = gameStore.state.inventory || {}
    inventory[itemName] = (inventory[itemName] || 0) + qty
    gameStore.state.inventory = { ...inventory } // Force reactivity
    gameStore.save(false)
  }

  function sellItem(itemName: string, qty: number = 1) {
    const itemInfo = SHOP_ITEMS.find(i => i.name === itemName || i.id === itemName)
    if (!itemInfo) return

    const actualName = itemInfo.name
    if (!gameStore.state.inventory || !gameStore.state.inventory[actualName]) return

    const inventoryQty = gameStore.state.inventory[actualName]
    const sellQty = qty === 999 ? inventoryQty : Math.min(qty, inventoryQty)

    const gain = Math.floor((itemInfo.price || 0) * 0.5) * sellQty

    removeItem(actualName, sellQty)
    gameStore.state.money += gain
    gameStore.save(false)
  }

  /**
   * Processes multiple actions in a single save cycle to ensure reactivity and performance.
   * @param {Map<string, number>} itemMap - name -> quantity
   * @param {string} mode - 'sell' | 'release'
   */
  async function processBatchAction(itemMap: Map<string, number>, mode: 'sell' | 'release') {
    let totalGain = 0
    const inventory = gameStore.state.inventory || {}

    for (const [name, qty] of itemMap.entries()) {
      if (!inventory[name]) continue

      const actualQty = Math.min(qty, inventory[name])

      if (mode === 'sell') {
        const itemInfo = SHOP_ITEMS.find(i => i.name === name)
        if (itemInfo) totalGain += Math.floor((itemInfo.price || 0) * 0.5) * actualQty
      }

      inventory[name] -= actualQty
      if (inventory[name] <= 0) delete inventory[name]
    }

    gameStore.state.inventory = { ...inventory }
    if (mode === 'sell') gameStore.state.money += totalGain

    await gameStore.save(false)
    return totalGain
  }

  // --- ITEM ACTIONS ---
  function useItem(itemName: string, context: 'team' | 'box' | null = null, index: number | null = null) {
    const list = context === 'team' ? gameStore.state.team : gameStore.state.box
    const pokemon = index !== null ? list[index] : null

    // --- INTEGRACIÓN CON COMBATE (Prioridad Absoluta) ---
    // Si estamos en combate, delegamos toda la lógica (aplicación, consumo y logs) 
    // al battleStore para mantener la sincronía del turno.
    const battleStore = useBattleStore()
    if (battleStore.isBattleActive && !battleStore.isProcessing) {
      (battleStore as any).useItemInBattle(itemName, context === 'team' ? index : null)
      return { success: true, msg: 'Usando objeto en combate...' }
    }

    // --- LÓGICA FUERA DE COMBATE ---
    // Global items (Repels, etc.)
    if (isGlobalItem(itemName)) {
      const effectFn = (ITEM_EFFECTS as Record<string, any>)[itemName]
      if (!effectFn) return { success: false, msg: 'Efecto global no implementado.' }

      const result = effectFn(gameStore.state)
      consumeItem(itemName)
      return { success: true, msg: result }
    }

    if (!pokemon) return { success: false, msg: 'Seleccioná un Pokémon.' }

    const effectFn = (ITEM_EFFECTS as Record<string, any>)[itemName]
    let result: any;

    if (effectFn) {
      result = effectFn(pokemon)
    } else {
      // Check dynamic effects (TMs, etc)
      result = getDynamicItemEffect(itemName, pokemon)
    }

    if (!result || !result.success) return { success: false, msg: result?.message || 'Efecto no implementado.' }

    // --- DEFERRED LOGIC (Modals) ---
    if (result.resultType === 'relearner') {
      uiStore.activePokemonForRelearner = pokemon
      uiStore.isMoveRelearnerOpen = true
      return { success: true, msg: result.message }
    }

    if (result.resultType === 'evolution') {
      uiStore.startEvolution(pokemon, result.targetId, itemName)
      return { success: true, msg: result.message }
    }

    if (result.resultType === 'levelup') {
      gameStore.checkLevelUp(pokemon)
      consumeItem(itemName)
      return { success: true, msg: result.message }
    }

    if (result.resultType === 'learn_move') {
      const moveData = pokemonDataProvider.getMoveData(result.moveName)
      const moveObj = { 
        name: result.moveName, 
        pp: moveData?.pp || 35, 
        maxPP: moveData?.pp || 35 
      }

      if (pokemon.moves.length < 4) {
        pokemon.moves.push(moveObj)
        uiStore.notify(`¡${pokemon.name} aprendió ${result.moveName}!`, '📖')
      } else {
        uiStore.addToLearnQueue({ pokemon, move: moveObj })
      }
      consumeItem(itemName)
      return { success: true, msg: result.message }
    }

    if (result.resultType === 'nature_patch') {
      uiStore.activePokemonForNature = pokemon
      uiStore.isNaturePatchOpen = true
      consumeItem(itemName)
      return { success: true, msg: result.message }
    }

    if (result.resultType === 'pp_up') {
      uiStore.activePokemonForPPUp = pokemon
      uiStore.isPPUpOpen = true
      consumeItem(itemName)
      return { success: true, msg: result.message }
    }

    if (result.resultType === 'ability_pill') {
      uiStore.activePokemonForAbility = pokemon
      uiStore.isAbilityPillOpen = true
      consumeItem(itemName)
      return { success: true, msg: result.message }
    }

    // --- LÓGICA DE PERSISTENCIA (Fuera de Combate) ---
    consumeItem(itemName)
    gameStore.save()

    return { success: true, msg: result.message }
  }

  function consumeItem(itemName: string) {
    const inv = gameStore.state.inventory
    if (inv && inv[itemName]) {
      inv[itemName]--
      if (inv[itemName] <= 0) {
        delete inv[itemName]
      }
    }
  }

  function isItemUsableOn(itemName: string, pokemon: Pokemon) {
    if (!pokemon) return false
    if (isGlobalItem(itemName)) return false

    // Check if it's a held item (always equippable)
    const item = SHOP_ITEMS.find(i => i.name === itemName)
    if (item && (item.cat === 'held' || item.type === 'held')) return true

    // Deep clone to avoid side effects during check
    const p = JSON.parse(JSON.stringify(pokemon))

    // Check main effects
    const effectFn = (ITEM_EFFECTS as Record<string, any>)[itemName]
    if (effectFn) {
      const res = effectFn(p)
      return res && res.success
    }

    // Check dynamic effects (TMs, stones)
    const dynamicRes = getDynamicItemEffect(itemName, p)
    return dynamicRes && dynamicRes.success
  }

  function equipItem(itemName: string, context: 'team' | 'box', index: number) {
    const list = context === 'team' ? gameStore.state.team : gameStore.state.box
    const pokemon = list[index]
    if (!pokemon) return false

    // If already has an item, return it to inventory
    if (pokemon.heldItem) {
      const oldItem = pokemon.heldItem
      gameStore.state.inventory[oldItem] = (gameStore.state.inventory[oldItem] || 0) + 1
    }

    pokemon.heldItem = itemName
    const inv = gameStore.state.inventory
    if (inv) {
      inv[itemName] = (inv[itemName] || 0) - 1
      if (inv[itemName] <= 0) delete inv[itemName]
      gameStore.state.inventory = { ...inv }
    }

    gameStore.save()
    return true
  }

  function unequipItem(context: 'team' | 'box', index: number) {
    const list = context === 'team' ? gameStore.state.team : gameStore.state.box
    const pokemon = list[index]
    if (!pokemon || !pokemon.heldItem) return false

    const item = pokemon.heldItem
    gameStore.state.inventory[item] = (gameStore.state.inventory[item] || 0) + 1;
    pokemon.heldItem = null

    gameStore.save()
    return item
  }


  return {
    // Bag
    bagSellMode,
    bagSellSelected,
    activeCategory,
    searchQuery,
    bagItems,
    CATEGORY_LABELS,
    toggleBagSellMode,
    toggleBagSellSelect,
    updateBagSellQty,
    getBagSellTotalGain,
    confirmBagSell,
    // Items
    useItem,
    equipItem,
    unequipItem,
    addItem,
    removeItem,
    sellItem,
    processBatchAction
  }
})
ction
  }
})

import { defineStore } from 'pinia'
import { ref, reactive, onUnmounted } from 'vue'
import { useAuthStore } from './auth'
import { useGameStore } from './game'
import { useUIStore } from './ui'
import { usePvPStore } from './pvp'
import { resolvePvPTurn, applyPvPTurnResult, type PvPBattleState, type PvPTurnResult, type PvPAction } from '@/logic/pvp/pvpEngine'
import type { Pokemon } from '@/types/pokemon'

export interface BattleInvite {
  id: string;
  challenger_id: string;
  opponent_id: string;
  status: 'pending' | 'accepted' | 'declined' | 'ranked_match' | 'ranked_accepted';
  created_at: string;
}

export const useLivePvPStore = defineStore('livePvP', () => {
  const authStore = useAuthStore()
  const gameStore = useGameStore()
  const uiStore = useUIStore()
  const _pvpStore = usePvPStore()

  const activeInvite = ref<BattleInvite | null>(null)
  const isSearching = ref(false)

  interface LiveBattleState extends PvPBattleState {
    active: boolean;
    opponentId: string | null;
    opponentName: string;
    opponentElo: number;
    deadline: number | null;
  }

  const battleState = reactive<LiveBattleState>({
    active: false, 
    ch: { 
      send: () => {}, 
      on: () => ({ on: () => ({ on: () => ({ on: () => ({ subscribe: () => {} }) }) }) }), 
      subscribe: () => {}, 
      unsubscribe: () => {} 
    } as any, 
    isHost: false, isRanked: false,
    opponentId: null, opponentName: 'Rival', opponentElo: 1000,
    phase: 'sync', myTeam: [], enemyTeam: [],
    myActiveIdx: 0, enemyActiveIdx: 0, myHp: [], enemyHp: [],
    myStages: { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, reflect: 0, lightScreen: 0, safeguard: 0, mist: 0, spikes: 0 },
    enemyStages: { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, reflect: 0, lightScreen: 0, safeguard: 0, mist: 0, spikes: 0 },
    myPick: null, enemyPick: null, logs: [], deadline: null,
  })

  let invitePoller: ReturnType<typeof setInterval> | null = null
  let matchmakingPoller: ReturnType<typeof setInterval> | null = null

  function _pollMatchmaking() {
    if (!isSearching.value || !gameStore.db || !authStore.user) return
    gameStore.db.from('ranked_queue').select('*').neq('user_id', authStore.user.id).order('looking_since', { ascending: true }).limit(1).then(async ({ data }: { data: any[] | null }) => {
      if (data?.length && authStore.user && gameStore.db) {
        const match = data[0]
        const { data: invite, error } = await gameStore.db.from('battle_invites').insert({ challenger_id: authStore.user.id, opponent_id: match.user_id, status: 'ranked_match' }).select().single()
        if (!error && invite) {
          await gameStore.db.from('ranked_queue').delete().in('user_id', [authStore.user.id, match.user_id])
          isSearching.value = false; startBattle(invite, true, true)
        }
      }
    })
  }

  function initInvitePoller() {
    if (invitePoller) clearInterval(invitePoller)
    if (authStore.sessionMode === 'offline') return
    invitePoller = setInterval(async () => {
      if (!authStore.user || !gameStore.db) return
      const { data } = await gameStore.db.from('battle_invites').select('*').eq('opponent_id', authStore.user.id).in('status', ['pending', 'ranked_match']).order('created_at', { ascending: false }).limit(1)
      if (data?.length && gameStore.db) {
        const inv = data[0]
        if (Date.now() - new Date(inv.created_at).getTime() > 60000) return
        if (inv.status === 'ranked_match') { if (isSearching.value) acceptInvite(inv.id, true); else await gameStore.db.from('battle_invites').update({ status: 'declined' }).eq('id', inv.id) }
        else activeInvite.value = inv
      }
    }, 4000) as any
  }

  async function startSearch() {
    if (!authStore.user || !gameStore.db) return
    isSearching.value = true
    await gameStore.db.from('ranked_queue').upsert({ user_id: authStore.user.id, elo: gameStore.state.eloRating || 1000, looking_since: new Date().toISOString() })
    uiStore.notify('Buscando oponente...', '🔍')
    if (matchmakingPoller) clearInterval(matchmakingPoller)
    matchmakingPoller = setInterval(_pollMatchmaking, 3000) as any
  }

  async function cancelSearch() {
    if (!authStore.user || !gameStore.db) return
    isSearching.value = false; if (matchmakingPoller) clearInterval(matchmakingPoller)
    await gameStore.db.from('ranked_queue').delete().eq('user_id', authStore.user.id)
  }

  async function sendInvite(opponentId: string, opponentName: string) {
    if (!authStore.user || !gameStore.db) return
    const { data, error } = await gameStore.db.from('battle_invites').insert({ challenger_id: authStore.user.id, opponent_id: opponentId, status: 'pending' }).select().single()
    if (error) { uiStore.notify('Error al enviar invitación', '❌'); return }
    uiStore.notify(`Invitación enviada a ${opponentName}`, '✉️'); startBattle(data, true, false)
  }

  async function acceptInvite(inviteId: string, isRanked = false) {
    if (!gameStore.db) return
    const status = isRanked ? 'ranked_accepted' : 'accepted'
    await gameStore.db.from('battle_invites').update({ status }).eq('id', inviteId)
    const { data: invite } = await gameStore.db.from('battle_invites').select('*').eq('id', inviteId).single()
    if (invite) startBattle(invite, false, isRanked)
    activeInvite.value = null
  }

  async function declineInvite(inviteId: string) { 
    if (!gameStore.db) return
    await gameStore.db.from('battle_invites').update({ status: 'declined' }).eq('id', inviteId); 
    activeInvite.value = null 
  }

  function _commitPick(pick: PvPAction) { if (battleState.phase !== 'choosing') return; battleState.myPick = pick; battleState.phase = 'waiting'; if (battleState.isHost) { if (battleState.enemyPick) resolveTurn() } else { if (battleState.ch) battleState.ch.send({ type: 'broadcast', event: 'pvp_pick', payload: pick }) } }

  function _forfeit() { if (battleState.ch) battleState.ch.send({ type: 'broadcast', event: 'pvp_forfeit', payload: {} }); endBattle(false, 'Te has rendido.') }

  async function endBattle(won: boolean, reason: string) {
    battleState.active = false; battleState.phase = 'over'; if (battleState.ch) (battleState.ch as any).unsubscribe()
    let eloDelta = 0; if (battleState.isRanked) eloDelta = await _pvpStore.updateElo(won)
    uiStore.notify(`${reason || (won ? '¡Has ganado!' : 'Has perdido.')}${eloDelta !== 0 ? ` (${eloDelta > 0 ? '+' : ''}${eloDelta} ELO)` : ''}`, won ? '🏆' : '💀')
    if (gameStore.state) { (gameStore.state as any).activeBattle = null; gameStore.save(false) }
  }

  function resolveTurn() { const res = resolvePvPTurn(battleState); if (res) applyTurnResult(res) }
  async function applyTurnResult(result: PvPTurnResult) { await applyPvPTurnResult(battleState, result, endBattle) }

  function startBattle(invite: BattleInvite, isHost: boolean, isRanked: boolean) {
    battleState.active = true; battleState.isHost = isHost; battleState.isRanked = isRanked; battleState.opponentId = isHost ? invite.opponent_id : invite.challenger_id
    battleState.myTeam = JSON.parse(JSON.stringify(gameStore.state.team)); 
    battleState.myHp = battleState.myTeam.map((p: Pokemon) => p.hp); 
    battleState.myActiveIdx = 0
    battleState.phase = 'sync'; battleState.logs = ['¡Comienza la batalla!']; battleState.myPick = null; battleState.enemyPick = null
    setupBattleChannel(invite.id)
    const broadcastTeam = () => { if (battleState.ch) battleState.ch.send({ type: 'broadcast', event: 'pvp_team', payload: { team: battleState.myTeam } }) }
    setTimeout(broadcastTeam, 500); setTimeout(broadcastTeam, 2000)
  }

  function setupBattleChannel(inviteId: string) {
    if (!gameStore.db) return
    battleState.ch = gameStore.db.channel(`pvp-${inviteId}`)
    battleState.ch.on('broadcast', { event: 'pvp_team' }, handleOpponentTeam).on('broadcast', { event: 'pvp_pick' }, handleOpponentPick).on('broadcast', { event: 'pvp_turn_result' }, handleTurnResult).on('broadcast', { event: 'pvp_forfeit' }, handleOpponentForfeit)
      .subscribe((status: string) => { if (status === 'SUBSCRIBED' && battleState.ch) battleState.ch.send({ type: 'broadcast', event: 'pvp_team', payload: { team: battleState.myTeam } }) })
  }

  function handleOpponentTeam({ payload }: { payload: { team: Pokemon[] } }) {
    if (battleState.enemyTeam.length > 0) return
    battleState.enemyTeam = payload.team; 
    battleState.enemyHp = payload.team.map((p: Pokemon) => p.hp); 
    battleState.enemyActiveIdx = 0
    if (battleState.phase === 'sync') { battleState.phase = 'choosing'; battleState.logs.push(`¡El rival está listo!`) }
  }

  function handleOpponentPick({ payload }: { payload: PvPAction }) { battleState.enemyPick = payload; if (battleState.isHost && battleState.myPick) resolveTurn() }
  function handleTurnResult({ payload }: { payload: PvPTurnResult }) { if (!battleState.isHost) applyTurnResult(payload) }
  function handleOpponentForfeit() { endBattle(true, 'El oponente se ha rendido.') }

  function _checkPostTurn() {
    const myHp = battleState.myHp[battleState.myActiveIdx] || 0
    const enHp = battleState.enemyHp[battleState.enemyActiveIdx] || 0
    if (myHp <= 0) {
      if (!battleState.myHp.some(h => h > 0)) endBattle(false, '¡Has sido derrotado!')
      else battleState.phase = 'faint_switch'
    } else if (enHp <= 0) {
      if (!battleState.enemyHp.some(h => h > 0)) endBattle(true, '¡Has ganado la batalla!')
      else battleState.phase = 'waiting'
    } else {
      battleState.phase = 'choosing'
      battleState.myPick = null
      battleState.enemyPick = null
    }
  }

  onUnmounted(() => { if (invitePoller) clearInterval(invitePoller); if (matchmakingPoller) clearInterval(matchmakingPoller); if (battleState.ch) battleState.ch.unsubscribe() })

  return { activeInvite, isSearching, battleState, initInvitePoller, sendInvite, acceptInvite, declineInvite, startBattle, startSearch, cancelSearch, _commitPick, _forfeit, handleOpponentPick, _checkPostTurn }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { FIRE_RED_MAPS } from '@/data/maps'
import { generateEncounter } from '@/logic/encounters'
import { getDayCycle, getSeason, syncServerTime, getServerTime } from '@/logic/timeUtils'
import { getRouteWeather } from '@/logic/weatherUtils'
import { useGameStore } from './game'
import { useBattleStore } from './battle'
import { useUIStore } from './ui'
import { useEventStore } from './events'
import type { GameStore, BattleStore, UIStore, EventStore } from '@/types/stores'
import type { Pokemon } from '@/types/pokemon'

export const useMapStore = defineStore('map', () => {
  const gs = useGameStore() as unknown as GameStore
  const currentMap = computed({
    get: () => gs.state.map?.currentMap || 'route1',
    set: (val) => { if (gs.state.map) gs.state.map.currentMap = val }
  })
  const region = computed(() => gs.state.map?.region || 'kanto')

  const globalWeather = ref(null) // Si está forzado anula el determinístico
  const forcedCycle = ref(null) // null, morning, day, dusk, night
  const forcedSeason = ref(null) // null, spring, summer, autumn, winter
  const currentEpochHour = ref(Math.floor(getServerTime() / 3600000))

  // Sync epoch hour every minute
  if (typeof window !== 'undefined' && typeof process !== 'undefined' && process.env.NODE_ENV !== 'test') {
    setInterval(() => {
      currentEpochHour.value = Math.floor(getServerTime() / 3600000)
    }, 60000)
  }

  const currentCycle = computed(() => {
    if (forcedCycle.value) return forcedCycle.value
    return getDayCycle(currentEpochHour.value * 3600000)
  })

  const currentSeason = computed(() => {
    if (forcedSeason.value) return forcedSeason.value
    return getSeason(currentEpochHour.value * 3600000)
  })

  const currentWeather = computed(() => {
    if (globalWeather.value) return globalWeather.value
    return getRouteWeather(currentMap.value, currentSeason.value.id, currentEpochHour.value)
  })

  // React to debug time changes immediately
  if (typeof window !== 'undefined') {
    window.addEventListener('time-sync-update', () => {
      console.log('[MapStore] Time sync detected');
      currentEpochHour.value = Math.floor(getServerTime() / 3600000);
    });
  }

  // Sync time on store init (safer than onMounted in a store)
  syncServerTime()
  const maps = ref(FIRE_RED_MAPS)
  const activeEvents = ref<any[]>([])
  const lastNavigateTime = ref(0)
  const dailyGuardianCaptures = ref<string[]>([])
  const mapWinners = ref<Record<string, string>>({}) // locId -> winner
  const pendingAwards = ref<any[]>([])

  const setGlobalWeather = (w: any) => { globalWeather.value = w }
  const setGlobalCycle = (c: any) => { forcedCycle.value = c }

  const navigate = async (locId: string) => {
    const now = Date.now()
    if (now - lastNavigateTime.value < 400) return // Throttling
    lastNavigateTime.value = now

    const gs = useGameStore() as unknown as GameStore
    const battleStore = useBattleStore() as unknown as BattleStore
    const uiStore = useUIStore() as unknown as UIStore

    // 1. Verificar salud del equipo
    const healthy = (gs.state.team as any[]).find(p => (p as any).hp > 0 && !(p as any).onMission && !(p as any).onDefense)
    if (!healthy) {
      uiStore.notify('Todos tus Pokémon están debilitados. ¡Ve al Centro Pokémon!', '🏥')
      return
    }

    // Actualizar ubicación actual y sincronizar tiempo ambiental
    await syncServerTime()
    currentEpochHour.value = Math.floor(getServerTime() / 3600000)
    currentMap.value = locId

    // 2. Progreso de eclosión
    gs.hatchEggs()

    // 3. Generar Encuentro
    const eventStore = useEventStore() as unknown as EventStore

    // MODO DEBUG: Si hay un bucle infinito activo, lo usamos
    const encounter = battleStore.debugLoopPokemon 
      ? (() => {
          const nextPoke = JSON.parse(JSON.stringify(battleStore.debugLoopPokemon)) as Pokemon
          nextPoke.hp = nextPoke.maxHp
          nextPoke.status = null
          nextPoke.confused = 0
          nextPoke.flinched = false
          console.log('[DEBUG] Navegación: Usando bucle infinito de', nextPoke.name)
          return { type: 'wild', pokemon: nextPoke }
        })()
      : await generateEncounter(locId, gs.state, {
          activeEvents: activeEvents.value,
          dominanceData: mapWinners.value,
          shinyMultiplier: eventStore.globalMultipliers?.shiny || 1,
          weather: currentWeather.value
        })


    if (!encounter) {
      // No pasó nada, solo nos movemos (efecto visual en el componente)
      return
    }

    // 4. Procesar Tipo de Encuentro
    const wildEnc = encounter as { type: string; pokemon: Pokemon; pts?: number; faction?: string };
    if (wildEnc.type === 'wild') {
      battleStore._startBattle(wildEnc.pokemon, { 
        locationId: locId,
        wasSearching: true 
      })
    } else if (wildEnc.type === 'guardian') {
      // El componente MapView debe manejar la notificación visual o podemos dispararla aquí si es modal
      // Por ahora, iniciamos la batalla marcando que es un Guardián;
      wildEnc.pokemon.isGuardian = true
      battleStore._startBattle(wildEnc.pokemon, { 
        locationId: locId,
        wasSearching: true,
        battleOptions: { isGuardian: true, pts: wildEnc.pts }
      })
    } else if (wildEnc.type === 'defender') {
      // TODO: Implementar búsqueda de defensores reales desde Supabase
      // Por ahora notificamos
      uiStore.notify(`¡Defensor del Team ${wildEnc.faction?.toUpperCase()} detectado!`, '⚔️')
    }
  }

  return {
    currentMap,
    region,
    currentEpochHour,
    currentCycle,
    currentSeason,
    currentWeather,
    globalWeather,
    forcedCycle,
    forcedSeason,
    maps,
    activeEvents,
    pendingAwards,
    dailyGuardianCaptures,
    mapWinners,
    setGlobalWeather,
    setGlobalCycle,
    navigate
  }
})

import { defineStore } from 'pinia'
import { ref, markRaw } from 'vue'

import { MODAL_REGISTRY } from '@/logic/modals/registry'

import type { Component } from 'vue'

export interface Modal {
  id: string;
  name: string;
  component: Component;
  props: Record<string, unknown>;
  opening: boolean;
  closing: boolean;
}

/**
 * Modal Store
 * Manages a dynamic stack of active modals (LIFO).
 */
export const useModalStore = defineStore('modals', () => {
  const stack = ref<Modal[]>([])

  /**
   * Opens a new modal.
   * @param {string} name - Key in MODAL_REGISTRY
   * @param {Object} props - Props to pass to the component
   */
  const open = (name: string, props: Record<string, any> = {}) => {
    const component = (MODAL_REGISTRY as any)[name]
    if (!component) {
      console.warn(`[Modals] Modal "${name}" not found in registry.`)
      return null
    }

    const id = `${name}-${Date.now()}`

    const modal = {
      id,
      name,
      component: markRaw(component),
      props,
      opening: true, // Initial state for animations
      closing: false
    }

    stack.value.push(modal)

    // After the opening animation (400ms), we mark it as no longer opening
    // This allows the UI to delay "Performance Mode" until the modal is fully visible
    setTimeout(() => {
      const target = stack.value.find(m => m.id === id)
      if (target) {
        target.opening = false
      }
    }, 450)

    return id
  }

  /**
   * Closes a specific modal by ID or Name.
   * @param {string} identifier - The id or name of the modal to close.
   */
  const close = (identifier: string) => {
    const index = stack.value.findIndex(m => m.id === identifier || m.name === identifier)
    if (index !== -1) {
      const modal = stack.value[index]
      if (!modal || modal.closing) return // Already closing

      modal.closing = true

      // We wait for the animation to finish before removing from stack
      // 550ms ensures BaseModal.vue 500ms transitions finish first
      setTimeout(() => {
        const finalIndex = stack.value.findIndex(m => m.id === modal.id)
        if (finalIndex !== -1) {
          stack.value.splice(finalIndex, 1)
        }
      }, 550)
    }
  }

  /**
   * Closes the top-most modal in the stack (LIFO).
   */
  const closeTop = () => {
    if (stack.value.length > 0) {
      const topModal = stack.value[stack.value.length - 1]
      if (topModal) close(topModal.id)
    }
  }

  const closeAll = () => {
    stack.value = []
  }

  const isOpen = (name: string) => {
    return stack.value.some(m => m.name === name && !m.closing)
  }

  return {
    stack,
    open,
    close,
    closeTop,
    closeAll,
    isOpen
  }
})

import { defineStore } from 'pinia';
import { ref } from 'vue';
import { useGameStore } from './game';
import { useAuthStore } from './auth';
import { useUIStore } from './ui';
import { supabase } from '@/logic/supabase';

export const usePassivePvpStore = defineStore('passivePvp', () => {
  const gameStore = useGameStore();
  const authStore = useAuthStore();
  const uiStore = useUIStore();

  const isPassiveActive = ref(false);
  const lastKnownElo = ref(1000);
  const watcherInterval = ref<any>(null);

  /**
   * Carga el estado inicial del equipo pasivo desde la DB.
   */
  async function loadStatus() {
    if (!authStore.user) return;

    try {
      const { data, error } = await supabase
        .from('passive_teams')
        .select('is_active')
        .eq('user_id', authStore.user.id)
        .maybeSingle();

      if (!error && data) {
        isPassiveActive.value = data.is_active;
      }
    } catch (e) {
      console.error('[PassivePvP] Error loading status:', e);
    }
  }

  /**
   * Inicia el monitoreo de ELO en segundo plano.
   */
  function startWatcher() {
    if (watcherInterval.value || !authStore.user) return;

    lastKnownElo.value = gameStore.state.eloRating || 1000;

    watcherInterval.value = setInterval(async () => {
      if (!authStore.user || authStore.sessionMode === 'offline') return;

      try {
        const { data, error } = await supabase
          .from('profiles')
          .select('elo_rating, pvp_wins, pvp_losses, pvp_draws')
          .eq('id', authStore.user.id)
          .single();

        if (!error && data) {
          const newElo = data.elo_rating || 1000;

          if (newElo !== lastKnownElo.value) {
            const delta = newElo - lastKnownElo.value;
            const won = delta > 0 || (data.pvp_wins || 0) > ((gameStore.state.pvpStats as any)?.wins || 0);

            // Notificar si no estamos en una batalla activa para evitar distracciones
            if (!gameStore.state.activeBattle) {
              uiStore.notify(
                `🛡️ Defensa Pasiva: ${won ? '¡Victoria!' : 'Derrota.'} (${delta > 0 ? '+' : ''}${delta} ELO)`,
                won ? '⚔️' : '💀'
              );
            }

            // Sincronizar stats en gameStore
            gameStore.state.eloRating = newElo;
            gameStore.state.pvpStats = {
              wins: data.pvp_wins || 0,
              losses: data.pvp_losses || 0,
              draws: data.pvp_draws || 0
            } as any;

            lastKnownElo.value = newElo;
            gameStore.save(false); // Guardado silencioso de la metadata
          }
        }
      } catch (e) {
        console.warn('[PassivePvP] Watcher error:', e);
      }
    }, 30000); // Cada 30 segundos
  }

  function stopWatcher() {
    if (watcherInterval.value) {
      clearInterval(watcherInterval.value);
      watcherInterval.value = null;
    }
  }

  return {
    isPassiveActive,
    loadStatus,
    startWatcher,
    stopWatcher
  };
});

import { defineStore } from 'pinia'
import { computed, watch } from 'vue'
import { useGameStore } from './game'
import { useUIStore } from './ui'
import { PLAYER_CLASSES, CLASS_MISSIONS } from '@/data/playerClasses'
import { supabase } from '@/logic/supabase'
import { useInventoryStore } from '@/stores/inventory'
import { getClassModifier } from '@/logic/player/classEngine'
import type { Pokemon } from '@/types/pokemon'


interface ActiveMission {
  id: string
  startedAt: number
  endsAt: number
  targetPokemonIdx?: number
  projectedReward?: number
  [key: string]: unknown
}

interface ClassData {
  captureStreak?: number
  longestStreak?: number
  reputation?: number
  blackMarketSales?: number
  criminality?: number
  activeMission?: ActiveMission | null
  blackMarketDaily?: { date: string, items: unknown[], purchased: unknown[] }
  extortedRouteId?: string | null
  officialRouteId?: string | null
  kitCaptures?: number
}

interface ClassDefinition {
  id: string
  name: string
  icon: string
  color: string
  colorDark: string
  description: string
}



export const usePlayerClassStore = defineStore('playerClass', () => {
  const gameStore = useGameStore()
  const uiStore = useUIStore()

  const db = supabase

  // --- Getters ---
  const playerClass = computed(() => gameStore.state.playerClass)
  const classLevel = computed(() => gameStore.state.classLevel || 1)
  const classXP = computed(() => gameStore.state.classXP || 0)
  const classData = computed<ClassData>(() => (gameStore.state.classData as ClassData) || {})

  const currentClassDef = computed<ClassDefinition | null>(() => {
    if (!playerClass.value) return null
    return (PLAYER_CLASSES as Record<string, ClassDefinition>)[playerClass.value] || null
  })

  const activeMission = computed(() => classData.value.activeMission || null)

  /**
   * Obtiene modificadores de clase para batalla o economía.
   * Centraliza la lógica de getClassModifier() de legacy.
   */
  function getModifier(type: string, context: Record<string, unknown> = {}) {
    return getClassModifier(playerClass.value || '', type, {
      ...context,
      isPvP: (gameStore.state as { activeBattle?: { isPvP?: boolean } }).activeBattle?.isPvP
    })
  }

  /**
   * Sincroniza las variables CSS globales con el tema de la clase activa.
   */
  function syncTheme() {
    if (typeof document === 'undefined') return
    const root = document.documentElement
    const cls = currentClassDef.value

    if (!cls) {
      root.style.setProperty('--class-primary', '#3b82f6')
      root.style.setProperty('--class-dark', '#1e40af')
      return
    }

    root.style.setProperty('--class-primary', cls.color)
    root.style.setProperty('--class-dark', cls.colorDark)
  }

  watch(playerClass, () => syncTheme())

  // --- Actions ---

  /**
   * Selecciona o cambia la clase del jugador.
   */
  async function selectClass(classId: string) {
    const cls = (PLAYER_CLASSES as Record<string, ClassDefinition>)[classId]
    if (!cls) return { success: false, msg: 'Clase no válida' }

    const isChange = !!playerClass.value
    if (isChange) {
      const cost = 10000
      if ((gameStore.state.battleCoins || 0) < cost) {
        uiStore.notify(`Necesitas ${cost.toLocaleString()} Battle Coins para cambiar.`, '❌')
        return { success: false, msg: `Necesitas ${cost.toLocaleString()} Battle Coins para cambiar.` }
      }
      gameStore.state.battleCoins -= cost
    }

    // Reset de datos específicos y liberación de Pokémon en misión
    [...(gameStore.state.team || []), ...(gameStore.state.box || [])].forEach((p: Pokemon) => {
      if (p.onMission) p.onMission = false
    })

    gameStore.state.playerClass = classId
    gameStore.state.classLevel = 1
    gameStore.state.classXP = 0
    gameStore.state.classData = {
      captureStreak: 0,
      longestStreak: 0,
      reputation: 0,
      blackMarketSales: 0,
      criminality: 0,
      blackMarketDaily: { date: '', items: [], purchased: [] },
      extortedRouteId: null,
      officialRouteId: null,
      kitCaptures: 0
    }

    uiStore.notify(`¡Elegiste ser ${cls.name}!`, cls.icon)
    await gameStore.save(false)
    return { success: true }
  }

  /**
   * Establece la facción del jugador (Unión o Poder).
   */
  async function setFaction(factionId: string) {
    if (!['union', 'poder', 'rocket'].includes(factionId)) return { success: false }

    const currentFaction = gameStore.state.faction
    if (currentFaction === factionId) {
      uiStore.notify('Ya perteneces a este bando.', '⚠️')
      return { success: false }
    }

    // Costo de cambio (si ya tenía uno)
    if (currentFaction) {
      const cost = 25000
      if ((gameStore.state.money || 0) < cost) {
        uiStore.notify(`Necesitas 🪙 ${cost.toLocaleString()} para cambiar de bando.`, '❌')
        return { success: false }
      }
      gameStore.state.money -= cost
      uiStore.notify(`Cambiaste de bando por 🪙 ${cost.toLocaleString()}`, '💸')
    }

    gameStore.state.faction = factionId
    uiStore.notify(`¡Te uniste al Equipo ${factionId.toUpperCase()}!`, '🚩')
    await gameStore.save(false)
    return { success: true }
  }

  /**
   * Incrementa XP de clase (se sincroniza con el nivel de entrenador por ahora, como en legacy).
   */
  function addXP(amount: number) {
    if (!playerClass.value || amount <= 0) return
    gameStore.addTrainerExp(amount)
  }

  /**
   * Maneja el nivel de criminalidad del Rocket.
   */
  function addCriminality(amount: number) {
    if (playerClass.value !== 'rocket' || amount <= 0) return
    const currentData = gameStore.state.classData as ClassData
    const prev = currentData.criminality || 0
    currentData.criminality = Math.min(100, prev + amount)

    if (prev < 100 && currentData.criminality >= 100) {
      uiStore.notify("¡Nivel de criminalidad máximo! La policía te busca.", "🚔")
    }
  }

  /**
   * Inicia una misión idle con validación de tiempo del servidor.
   */
  async function startMission(missionId: string, extraData: Record<string, unknown> = {}) {
    const m = CLASS_MISSIONS.find(x => x.id === missionId)
    if (!m) return

    // Marcar pokemon como ocupado
    if (extraData.targetPokemonIdx !== undefined) {
      const p = gameStore.state.box[extraData.targetPokemonIdx as number]
      if (p) p.onMission = true
    }

    const now = await (db as any).getServerTime()
    const currentData = gameStore.state.classData as ClassData

    currentData.activeMission = {
      id: missionId,
      startedAt: now as number,
      endsAt: (now as number) + (m.durationHs * 3600 * 1000),
      ...extraData
    }

    uiStore.notify(`¡Misión iniciada! (${m.durationHs}h)`, '📋')
    await gameStore.save(false)
  }

  /**
   * Finaliza y cobra una misión. (Implementación de Phase 21).
   */
  async function collectMission() {
    const mission = activeMission.value
    if (!mission) return

    const now = await (db as any).getServerTime()
    if ((now as number) < mission.endsAt) {
      uiStore.notify('La misión aún no ha terminado.', '⏳')
      return;
    }

    const cls = playerClass.value
    let msg = 'Misión completada. '

    if (cls === 'rocket') {
      // Recompensa en dinero (el Pokémon ya no está)
      const reward = mission.projectedReward || 0
      gameStore.state.battleCoins = (gameStore.state.battleCoins || 0) + reward
      msg += `¡Recibiste ₽${reward.toLocaleString()}! 🚀`

      // Eliminar el Pokémon de la caja (sacrificio)
      if (mission.targetPokemonIdx !== undefined) {
        const p = gameStore.state.box[mission.targetPokemonIdx]
        if (p) {
          if (p.heldItem) {
            const invStore = useInventoryStore()
            invStore.addItem(p.heldItem, 1)
          }
          gameStore.removePokemon(p.uid)
        }
      }
    } else if (cls === 'cazabichos') {
      // Aquí iría la lógica de generar encuentros salvajes bicho o recompensas de IVs
      msg += '¡Nuevos Pokémon Bicho avistados!'
    } else if (cls === 'entrenador') {
      // Recompensa en EXP para el Pokémon enviado
      if (mission.targetPokemonIdx !== undefined) {
        const p = gameStore.state.box[mission.targetPokemonIdx]
        if (p) {
          const blocks = (mission.endsAt - mission.startedAt) / (3600000 * 6) // bloques de 6h
          const expGain = (25000 + (p.level || 1) * 1000) * blocks;
          p.exp = (p.exp || 0) + expGain;

          p.onMission = false;
          msg += `¡${p.name} ganó ${expGain.toLocaleString()} EXP! 🏅`
        }
      }
    } else if (cls === 'criador') {
      // Recompensa en IVs aleatorios a cambio de Vigor
      if (mission.targetPokemonIdx !== undefined) {
        const p = gameStore.state.box[mission.targetPokemonIdx]
        if (p) {
          const stats = ['hp', 'atk', 'def', 'spa', 'spd', 'spe']
          const stat = stats[Math.floor(Math.random() * stats.length)]
          const gain = Math.floor(Math.random() * 3) + 1;
          if (!p.ivs) p.ivs = { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 };
          const curVal = (p.ivs as Record<string, number>)[stat] || 0;
          (p.ivs as Record<string, number>)[stat] = Math.min(31, curVal + gain);
          p.vigor = Math.max(0, (p.vigor || 20) - 5);
          p.onMission = false;
          msg += `¡${p.name} mejoró su ${String(stat).toUpperCase()} (+${gain})! 🧬`
        }
      }
    } else {
      // Liberar al Pokémon que estaba en misión
      if (mission.targetPokemonIdx !== undefined) {
        const p = gameStore.state.box[mission.targetPokemonIdx]
        if (p) p.onMission = false
      }
      msg += 'Tus Pokémon han regresado con éxito.'
    }

    const currentData = gameStore.state.classData as ClassData
    currentData.activeMission = null
    uiStore.notify(msg, '🎁')
    await gameStore.save()
  }

  return {
    playerClass,
    classLevel,
    classXP,
    classData,
    currentClassDef,
    activeMission,
    getModifier,
    selectClass,
    addXP,
    addCriminality,
    startMission,
    collectMission,
    setFaction,
    syncTheme
  }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { useAuthStore } from './auth'
import { useGameStore } from './game'
import { useUIStore } from './ui'
import { RANKED_REWARD_MILESTONES } from '@/data/rankedData'
export { RANKED_REWARD_MILESTONES }
import { getEloTier } from '@/logic/pvp/rankedEngine'
import type { Pokemon } from '@/types/pokemon'

export const RANKED_REWARD_TIER_MARKS = [
  { name: 'Plata', elo: 1200, color: '#9E9E9E' },
  { name: 'Oro', elo: 1600, color: '#FFB800' },
  { name: 'Platino', elo: 2100, color: '#E5C100' },
  { name: 'Diamante', elo: 2700, color: '#89CFF0' },
  { name: 'Maestro', elo: 3400, color: '#FFD700' }
]

interface PvPStats {
  wins: number
  losses: number
  draws: number
}

interface SeasonRules {
  name: string
  startDate?: string
  endDate?: string
  [key: string]: any
}

interface LeaderboardEntry {
  id: string
  username: string | null
  elo_rating: number
  trainer_level: number
  player_class: string
  nick_style: string | null
  avatar_style: string | null
}

/**
 * usePvPStore - Gestor de Arena Clasificatoria y Defensa Pasiva.
 * Centraliza el ELO, las temporadas y el registro de equipos competitivos.
 */
export const usePvPStore = defineStore('pvp', () => {
  const authStore = useAuthStore()
  const gameStore = useGameStore()
  const uiStore = useUIStore()

  const elo = ref(1000)
  const stats = ref<PvPStats>({ wins: 0, losses: 0, draws: 0 })
  const maxElo = ref(1000)
  const rewardsClaimed = ref<string[]>([])
  const passiveTeamActive = ref(false)
  const currentSeasonRules = ref<SeasonRules | null>(null)
  const leaderboard = ref<LeaderboardEntry[]>([])
  const lastSyncAt = ref(0)
  const isLoading = ref(false)
  const error = ref('')

  const eloTier = computed(() => getEloTier(elo.value))

  async function loadPvPData() {
    if (!authStore.user || !gameStore.db) return

    const { data: profile } = await gameStore.db.from('profiles')
      .select('elo_rating, pvp_wins, pvp_losses, pvp_draws, role')
      .eq('id', authStore.user.id)
      .single()

    if (profile) {
      elo.value = profile.elo_rating || 1000
      stats.value = { 
        wins: profile.pvp_wins || 0, 
        losses: profile.pvp_losses || 0, 
        draws: profile.pvp_draws || 0 
      }

      // Admin Check (requested by user)
      if (profile.role === 'admin' && authStore.user) {
        (authStore.user as any).role = 'admin'
      }
    }

    // Sync maxElo from game state for rewards
    maxElo.value = (gameStore.state.rankedMaxElo as number) || elo.value
    rewardsClaimed.value = (gameStore.state.rankedRewardsClaimed as string[]) || []

    const { data: passive } = await gameStore.db.from('passive_teams')
      .select('is_active')
      .eq('user_id', authStore.user.id)
      .maybeSingle()

    passiveTeamActive.value = passive?.is_active || false

    await fetchSeasonRules()
  }

  async function fetchSeasonRules() {
    if (!gameStore.db) return
    const { data } = await gameStore.db.from('ranked_rules_config').select('*').eq('id', 'current').maybeSingle()
    if (data) {
      currentSeasonRules.value = {
        name: data.season_name,
        ...JSON.parse(data.config || '{}')
      }
    }
  }

  async function fetchLeaderboard(force = false) {
    if (!force && lastSyncAt.value && (Date.now() - lastSyncAt.value < 1800000)) {
      return // 30 min cache
    }

    isLoading.value = true
    error.value = ''

    try {
      if (!gameStore.db) return
      const { data, error: err } = await gameStore.db
        .from('profiles')
        .select('id, username, elo_rating, trainer_level, player_class, nick_style, avatar_style')
        .not('username', 'is', null)
        .order('elo_rating', { ascending: false })
        .limit(100)

      if (err) throw err
      leaderboard.value = (data || []) as LeaderboardEntry[]
      lastSyncAt.value = Date.now()
    } catch (e) {
      error.value = 'No se pudo cargar el ranking global.'
      console.error('[PvPStore] Leaderboard error:', e)
    } finally {
      isLoading.value = false
    }
  }

  async function togglePassiveTeam() {
    const newState = !passiveTeamActive.value

    if (newState) {
      if (!gameStore.db || !authStore.user) return
      // Create Snapshot
      const snapshot = (gameStore.state.team as Pokemon[]).map((p) => ({
        id: p.id,
        name: p.name,
        level: p.level,
        type: p.type,
        stats: p.stats, 
        moves: p.moves.map((m) => ({ name: m.name, pp: m.maxPP || 20 })),
        heldItem: p.heldItem,
        isShiny: p.isShiny
      }))

      const { error } = await gameStore.db.from('passive_teams').upsert({
        user_id: authStore.user.id,
        team_data: JSON.stringify(snapshot),
        is_active: true,
        updated_at: new Date().toISOString()
      })

      if (!error) {
        passiveTeamActive.value = true
        uiStore.notify('Equipo de Defensa Pasiva activado.', '🛡️')
      }
    } else {
      if (!gameStore.db || !authStore.user) return
      await gameStore.db.from('passive_teams').update({ is_active: false }).eq('user_id', authStore.user.id)
      passiveTeamActive.value = false
      uiStore.notify('Defensa Pasiva desactivada.', '⏸️')
    }
  }

  async function claimReward(milestoneId: string) {
    if (rewardsClaimed.value.includes(milestoneId)) return

    const milestone = RANKED_REWARD_MILESTONES.find(m => m.id === milestoneId)
    if (!milestone) return

    if (maxElo.value < milestone.elo) {
      uiStore.notify('Hito no alcanzado', '⚠️')
      return
    }

    // Add items to inventory
    const inventory = gameStore.state.inventory as Record<string, number>
    Object.entries(milestone.rewards).forEach(([itemName, qty]) => {
      inventory[itemName] = (inventory[itemName] || 0) + (qty as number)
    })

    rewardsClaimed.value.push(milestoneId)
    gameStore.state.rankedRewardsClaimed = [...rewardsClaimed.value]
    uiStore.notify('¡Recompensa reclamada!', '🎁')
    await gameStore.saveGame(true)
  }

  const seasonRange = computed(() => {
    const rules = currentSeasonRules.value || { name: 'Default' }
    const start = rules.startDate ? new Date(rules.startDate) : new Date('2026-04-01T00:00:00-03:00')
    const end = rules.endDate ? new Date(rules.endDate) : new Date(start)
    if (!rules.endDate) end.setMonth(end.getMonth() + 3)

    return {
      start,
      end,
      daysLeft: Math.max(0, Math.ceil((end.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24)))
    }
  })

  async function updateElo(won: boolean) {
    if (!authStore.user || !gameStore.db) return 0

    const delta = won ? 15 + Math.floor(Math.random() * 5) : -(10 + Math.floor(Math.random() * 5))
    elo.value = Math.max(0, elo.value + delta)

    if (won) {
      stats.value.wins++
      if (elo.value > maxElo.value) {
        maxElo.value = elo.value
        gameStore.state.rankedMaxElo = maxElo.value
      }
    } else {
      stats.value.losses++
    }

    // Save to DB
    await gameStore.db.from('profiles').update({
      elo_rating: elo.value,
      pvp_wins: stats.value.wins,
      pvp_losses: stats.value.losses
    }).eq('id', authStore.user.id)

    gameStore.save(false)
    return delta
  }

  return {
    elo,
    stats,
    maxElo,
    eloTier,
    rewardsClaimed,
    passiveTeamActive,
    currentSeasonRules,
    seasonRange,
    loadPvPData,
    togglePassiveTeam,
    claimReward,
    updateElo,
    fetchLeaderboard,
    leaderboard,
    isLoading,
    error,
    rules: currentSeasonRules,
    currentTier: getEloTier
  }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { useGameStore } from './game'
import { useUIStore } from './ui'
import { SHOP_ITEMS, ITEM_CATEGORIES, CATEGORY_LABELS } from '@/data/items'
import { PLAYER_CLASSES } from '@/data/playerClasses'
import { TRAINER_RANKS } from '@/data/trainer'

export const useShopStore = defineStore('shop', () => {
  const gameStore = useGameStore()
  const uiStore = useUIStore()
  
  
  const marketCategory = ref('todos')
  const searchQuery = ref('')
  const quantities = ref({})

  const getTrainerRank = computed(() => {
    const lv = gameStore.state.trainerLevel || 1
    const idx = Math.min(lv - 1, TRAINER_RANKS.length - 1)
    return TRAINER_RANKS[idx]
  })

  function getQuantity(itemId: string) {
    return (quantities.value as any)[itemId] || 1
  }

  function setQuantity(itemId: string, val: any) {
    let q = parseInt(val)
    if (isNaN(q) || q < 1) q = 1
    if (q > 999) q = 999
    ;(quantities.value as any)[itemId] = q
  }

  /**
   * Calculates the price modifier based on player class.
   */
  function getPriceModifier() {
    const playerClass = gameStore.state.playerClass as keyof typeof PLAYER_CLASSES | null
    if (!playerClass) return 1.0
    
    const classDef = PLAYER_CLASSES[playerClass]
    if (!classDef || !classDef.modifiers) return 1.0
    
    // For regular shop, we use the recargo penalty if member of Rocket
    if ((playerClass as string) === 'rocket') return 1.20 
    return 1.0
  }

  function buyItem(itemId: string) {
    const item = SHOP_ITEMS.find(i => i.id === itemId)
    if (!item) return
    
    if (gameStore.state.trainerLevel < (item.unlockLv || 1)) {
      uiStore.notify('¡Item bloqueado!', '🔒')
      return
    }

    const qty = getQuantity(itemId)
    let unitPrice = item.price
    unitPrice = Math.floor(unitPrice * getPriceModifier())
    
    const total = unitPrice * qty

    if (gameStore.state.money < total) {
      uiStore.notify('¡No tenés suficiente dinero!', '💸')
      return
    }

    // Process purchase
    gameStore.state.money -= total
    gameStore.state.inventory[item.name] = (gameStore.state.inventory[item.name] || 0) + qty
    
    // Process special category effects (like balls count)
    if (item.cat === 'pokeballs') {
       const mult = item.id === 'great_ball' ? 1.5 : (item.id === 'ultra_ball' ? 2 : 1)
       gameStore.state.balls = (gameStore.state.balls || 0) + Math.floor(qty * mult)
    }

    uiStore.notify(`¡Compraste x${qty} ${item.name}!`, item.icon)
    gameStore.scheduleSave()
  }

  function buyItemBC(itemId: string) {
    const item = SHOP_ITEMS.find(i => i.id === itemId)
    if (!item || !item.trainerShop) return

    if (gameStore.state.trainerLevel < (item.unlockLv || 1)) {
      uiStore.notify('¡Ítem bloqueado!', '🔒')
      return
    }

    if ((gameStore.state.battleCoins || 0) < (item.bcPrice || 0)) {
      uiStore.notify('¡No tenés suficientes Battle Coins!', '💰')
      return
    }

    gameStore.state.battleCoins = (gameStore.state.battleCoins || 0) - (item.bcPrice || 0)
    gameStore.state.inventory[item.name] = (gameStore.state.inventory[item.name] || 0) + 1
    
    if (item.cat === 'pokeballs') {
       const mult = item.id === 'great_ball' ? 1.5 : (item.id === 'ultra_ball' ? 2 : 1)
       gameStore.state.balls = (gameStore.state.balls || 0) + Math.floor(1 * mult)
    }

    
    uiStore.notify(`¡Compraste ${item.name}!`, '🏅')
    gameStore.scheduleSave()
  }

  // ── POKÉMON CENTER HEALING ─────────────────────────────────────────────────

  function getHealCost() {
    const team = gameStore.state.team || []
    const damagedCount = team.filter(p => {
      const isDamaged = (p).hp < (p).maxHp
      const hasStatus = !!(p).status
      const needsPP = (p).moves?.some(m => m && m.pp < (m.maxPP || 0)) || false
      return isDamaged || hasStatus || needsPP
    }).length

    if (damagedCount === 0) return 0

    // Force explicit check for Rocket class
    const pClass = String(gameStore.state.playerClass || '').toLowerCase()
    
    if (pClass === 'rocket') {
      // Rocket pays 50 per damaged pokemon (base cost for penalized classes)
      return 50 * damagedCount
    }

    return 0
  }

  function healAllPokemon(manualCost = null) {
    const costToCharge = manualCost !== null ? manualCost : getHealCost()
    
    if (gameStore.state.money < costToCharge) {
      uiStore.notify('No tenés suficiente dinero para la enfermería.', '💸')
      return false
    }

    gameStore.state.money -= costToCharge
    
    // Restore all pokemon in team
    gameStore.state.team.forEach(p => {
      (p).hp = (p).maxHp;
      (p).status = null
      if ((p).moves) {
        (p).moves.forEach(m => {
          if (m) m.pp = m.maxPP || 20
        })
      }
    })

    if (costToCharge > 0) {
      uiStore.notify(`¡Sanación pagada! Gastaste ₽${costToCharge.toLocaleString()}`, '💰')
    } else {
      uiStore.notify('¡Tus Pokémon están totalmente recuperados!', '🏥')
    }

    gameStore.scheduleSave()
    return true
  }

  // ── BLACK MARKET (TEAM ROCKET) ─────────────────────────────────────────────

  function getBlackMarketItems() {
    if (gameStore.state.playerClass !== 'rocket') return []
    
    if (!gameStore.state.classData) {
      gameStore.state.classData = {
        captureStreak: 0,
        longestStreak: 0,
        reputation: 0,
        blackMarketSales: 0,
        criminality: 0,
        blackMarketDaily: { date: '', items: [], purchased: [] }
      }
    }
    if (!gameStore.state.classData.blackMarketDaily) {
      gameStore.state.classData.blackMarketDaily = { date: '', items: [], purchased: [] }
    }

    const today = new Date().toISOString().split('T')[0]
    const daily = gameStore.state.classData.blackMarketDaily

    if (daily.date !== today) {
      const possibleItems = SHOP_ITEMS.filter(i => i.trainerShop === true && (i.bcPrice || 0) > 0)
      const shuffled = [...possibleItems].sort(() => 0.5 - Math.random())
      const bmd = (gameStore.state.classData as any).blackMarketDaily
      if (bmd) {
        bmd.items = shuffled.slice(0, 3).map(i => (i.id || '') as string)
        bmd.date = today
        bmd.purchased = [] as string[]
      }
      gameStore.scheduleSave()
    }
    
    return daily.items.map(id => SHOP_ITEMS.find(i => i.id === id)).filter(Boolean)
  }

  function buyBlackMarketItem(itemId: string) {
    if (gameStore.state.playerClass !== 'rocket') return
    const daily = gameStore.state.classData.blackMarketDaily
    if (!daily || !daily.items.includes(itemId)) return
    
    if (daily.purchased.includes(itemId)) {
      useUIStore().notify('Ya compraste este objeto hoy.', '🚫')
      return
    }

    const item = SHOP_ITEMS.find(i => i.id === itemId)
    if (!item) return

    const discount = PLAYER_CLASSES.rocket.modifiers?.shopDiscount || 0.20
    const priceInMoney = Math.floor(((item.bcPrice || 0) * 50) * (1 - discount))
    
    if (gameStore.state.money < priceInMoney) {
      useUIStore().notify('No tenés suficiente dinero (₽).', '❌')
      return
    }

    gameStore.state.money -= priceInMoney
    daily.purchased.push(itemId)
    
    // Add to inventory
    gameStore.state.inventory[item.name] = (gameStore.state.inventory[item.name] || 0) + 1
    
    useUIStore().notify(`¡Compraste ${item.name} en el Mercado Negro! 🚀`, '💰')
    gameStore.scheduleSave()
  }

  return {
    marketCategory,
    searchQuery,
    ITEM_CATEGORIES,
    CATEGORY_LABELS,
    SHOP_ITEMS,
    getTrainerRank,
    getQuantity,
    setQuantity,
    buyItem,
    buyItemBC,
    healAllPokemon,
    getHealCost,
    getBlackMarketItems,
    buyBlackMarketItem
  }
})

import { defineStore } from 'pinia'
import { ref, reactive } from 'vue'
import { useAuthStore } from './auth'
import { useGameStore } from './game'
import { useUIStore } from './ui'
import { useAudioStore } from './audio'

export interface Friend {
  id: string;
  username: string;
  level: number;
  badges: number;
  playerClass?: string;
  nick_style?: string;
  isOnline: boolean;
  lastSeen: Date | null;
}

export interface PendingRequest {
  id: string;
  requester_id: string;
  status: string;
  profiles?: { username: string };
}

export interface SearchResult {
  id: string;
  username: string;
  level: number;
  playerClass?: string;
  status: string;
  relId: string | null;
  isRequester: boolean;
}

export interface LeaderboardEntry {
  id: string;
  username: string;
  elo: number;
  level: number;
  badges: number;
  playerClass?: string;
  faction?: string;
  nick_style?: string;
  isOnline: boolean;
}


interface FriendshipRow {
  id: string
  requester_id: string
  addressee_id: string
  status: string
}

interface ProfileRow {
  id: string
  username: string
  elo_rating?: number
  trainer_level?: number
  badges?: number
  player_class?: string
  faction?: string
  nick_style?: string
}

interface GameSaveRow {
  user_id: string
  save_data: Record<string, unknown>
  updated_at: string
}

interface PendingRequestRow extends FriendshipRow {
  profiles?: { username: string }
}

export const useSocialStore = defineStore('social', () => {
  const authStore = useAuthStore()
  const gameStore = useGameStore()
  const uiStore = useUIStore()
  const audioStore = useAudioStore()

  const friends = ref<Friend[]>([])
  const pendingRequests = ref<PendingRequest[]>([])
  const searchResults = ref<SearchResult[]>([])
  const searchLoading = ref(false)
  const loading = ref(false)

  const notifications = reactive({
    friends: 0,
    trades: 0,
    battles: 0,
    total: 0
  })

  let presenceInterval: ReturnType<typeof setInterval> | null = null

  /**
   * Carga datos sociales (amigos y solicitudes) usando DBRouter.
   */
  async function loadSocialData() {
    if (!authStore.user || authStore.sessionMode === 'offline') {
      friends.value = []
      pendingRequests.value = []
      return
    }

    loading.value = true
    const db = gameStore.db
    if (!db) { loading.value = false; return }

    try {
      // 1. Obtener amistades confirmadas
      const { data: friendships, error: fErr } = await db
        .from('friendships')
        .select('*')
        .or(`requester_id.eq.${authStore.user.id},addressee_id.eq.${authStore.user.id}`)
        .eq('status', 'accepted')

      if (fErr) throw fErr

      if (friendships && friendships.length > 0) {
        const friendIds = friendships.map((f: FriendshipRow) => 
          f.requester_id === authStore.user?.id ? f.addressee_id : f.requester_id
        )

        const [profRes, saveRes] = await Promise.all([
          db.from('profiles').select('*').in('id', friendIds),
          db.from('game_saves').select('user_id,save_data,updated_at').in('user_id', friendIds)
        ])

        friends.value = (profRes.data as ProfileRow[] || []).map((p: ProfileRow) => {
          const saveRow = (saveRes.data as GameSaveRow[] | null)?.find(s => s.user_id === p.id)
          const save = (saveRow?.save_data as Record<string, any>) || {}
          const lastSeen = saveRow?.updated_at ? new Date(saveRow.updated_at) : null
          const isOnline = !!(lastSeen && (Date.now() - lastSeen.getTime()) < 5 * 60 * 1000)

          return {
            id: p.id,
            username: p.username,
            level: (save.trainerLevel as number) || 1,
            badges: typeof save.badges === 'object' ? Object.keys(save.badges).length : ((save.badges as number) || 0),
            playerClass: save.playerClass as string,
            nick_style: save.nick_style as string,
            isOnline,
            lastSeen
          }
        })
      } else {
        friends.value = []
      }

      // 2. Solicitudes pendientes
      const { data: pending } = await db
        .from('friendships')
        .select('*, profiles:requester_id(username)')
        .eq('addressee_id', authStore.user?.id)
        .eq('status', 'pending')

      pendingRequests.value = (pending as PendingRequestRow[] || []) as any

      await refreshNotificationCount()
    } catch (err) {
      console.error('[SocialStore] Error loading data:', err)
    } finally {
      loading.value = false
    }
  }

  async function searchPlayers(query: string) {
    if (!query || query.length < 2 || authStore.sessionMode === 'offline') {
      searchResults.value = []
      return
    }

    searchLoading.value = true
    const db = gameStore.db
    if (!db) { searchLoading.value = false; return }

    try {
      const { data: profiles } = await db
        .from('profiles')
        .select('*')
        .ilike('username', `%${query}%`)
        .neq('id', authStore.user?.id)
        .limit(10)

      if (profiles && profiles.length > 0) {
        const ids = profiles.map((p: ProfileRow) => p.id)
        const [saveRes, relRes] = await Promise.all([
          db.from('game_saves').select('user_id,save_data').in('user_id', ids),
          db.from('friendships')
            .select('*')
            .or(`requester_id.eq.${authStore.user?.id},addressee_id.eq.${authStore.user?.id}`)
        ])

        searchResults.value = (profiles as ProfileRow[]).map((p: ProfileRow) => {
          const save = (saveRes.data as GameSaveRow[] | null)?.find(s => s.user_id === p.id)?.save_data || {}
          const rel = (relRes.data as FriendshipRow[] | null)?.find(f => 
            (f.requester_id === authStore.user?.id && f.addressee_id === p.id) ||
            (f.requester_id === p.id && f.addressee_id === authStore.user?.id)
          )

          return {
            id: p.id,
            username: p.username,
            level: (save.trainerLevel as number) || 1,
            playerClass: save.playerClass as string,
            status: rel ? (rel.status as string) : 'none',
            relId: rel ? (rel.id as string) : null,
            isRequester: rel ? rel.requester_id === authStore.user?.id : false
          }
        })
      } else {
        searchResults.value = []
      }
    } finally {
      searchLoading.value = false
    }
  }

  async function sendFriendRequest(targetId: string) {
    if (authStore.sessionMode === 'offline' || !gameStore.db || !authStore.user) return

    const { error } = await gameStore.db.from('friendships').insert({
      requester_id: authStore.user?.id,
      addressee_id: targetId,
      status: 'pending'
    })

    if (error) {
      uiStore.notify('Error al enviar solicitud', '❌')
    } else {
      uiStore.notify('Solicitud enviada correctamente', '👥')
      audioStore.sentMsg() // Sonido al enviar solicitud
      const res = searchResults.value.find((p: SearchResult) => p.id === targetId)
      if (res) { 
        res.status = 'pending';
        res.isRequester = true 
      }
    }
  }

  async function respondRequest(fId: string, status: string) {
    if (!gameStore.db) return
    const { error } = await gameStore.db.from('friendships').update({ status }).eq('id', fId)
    if (!error) {
      uiStore.notify(status === 'accepted' ? '¡Amistad aceptada!' : 'Solicitud rechazada', '✅')
      await loadSocialData()
    }
  }

  async function removeFriend(targetId: string) {
    if (!authStore.user || !gameStore.db) return
    const { error } = await gameStore.db.from('friendships')
      .delete()
      .or(`and(requester_id.eq.${authStore.user?.id},addressee_id.eq.${targetId}),and(requester_id.eq.${targetId},addressee_id.eq.${authStore.user?.id})`)

    if (!error) {
      uiStore.notify('Amigo eliminado', '👋')
      await loadSocialData()
    }
  }

  async function refreshNotificationCount() {
    if (!authStore.user || authStore.sessionMode === 'offline') return

    const db = gameStore.db
    if (!db) return
    const [
      res1,
      res2,
      res3,
      res4
    ] = await Promise.all([
      db.from('friendships').select('id', { count: 'exact', head: true }).eq('addressee_id', authStore.user?.id).eq('status', 'pending'),
      db.from('trade_offers').select('id', { count: 'exact', head: true }).eq('receiver_id', authStore.user?.id).eq('status', 'pending'),
      db.from('trade_offers').select('id', { count: 'exact', head: true }).eq('sender_id', authStore.user?.id).eq('status', 'accepted'),
      db.from('battle_invites').select('id', { count: 'exact', head: true }).eq('opponent_id', authStore.user?.id).eq('status', 'pending').gte('created_at', new Date(Date.now() - 60000).toISOString())
    ])

    notifications.friends = res1.count || 0
    notifications.trades = (res2.count || 0) + (res3.count || 0)
    notifications.battles = res4.count || 0
    notifications.total = notifications.friends + notifications.trades + notifications.battles
  }

  function startPresence() {
    if (presenceInterval) clearInterval(presenceInterval)
    if (authStore.sessionMode === 'offline') return

    const ping = async () => {
      if (!authStore.user || !gameStore.db) return
      await gameStore.db.from('game_saves').update({ 
        updated_at: new Date().toISOString() 
      }).eq('user_id', authStore.user?.id)
    }

    ping()
    presenceInterval = setInterval(ping, 120000) as any
  }

  function stopPresence() {
    if (presenceInterval) clearInterval(presenceInterval)
    presenceInterval = null
  }

  const leaderboard = ref<LeaderboardEntry[]>([])
  const leaderboardLoading = ref(false)

  /**
   * Obtiene el Top 100 mundial basado en el criterio especificado.
   * @param {string} sortBy - 'elo_rating' | 'trainer_level' | 'badges'
   */
  async function fetchLeaderboard(sortBy = 'elo_rating') {
    if (authStore.sessionMode === 'offline' || !gameStore.db) {
      leaderboard.value = []
      return
    }

    leaderboardLoading.value = true
    const db = gameStore.db
    if (!db) {
      leaderboardLoading.value = false
      return
    }

    try {
      const { data, error } = await db
        .from('profiles')
        .select('*')
        .order(sortBy, { ascending: false })
        .limit(100)

      if (error) throw error

      if (data && data.length > 0) {
        const ids = data.map((p: ProfileRow) => p.id)
        const { data: saves } = await db
          .from('game_saves')
          .select('user_id, updated_at')
          .in('user_id', ids)

        leaderboard.value = (data as ProfileRow[]).map((p: ProfileRow) => {
          const saveRow = (saves as GameSaveRow[] | null)?.find(s => s.user_id === p.id)
          const lastSeen = saveRow?.updated_at ? new Date(saveRow.updated_at) : null
          const isOnline = lastSeen && (Date.now() - lastSeen.getTime()) < 5 * 60 * 1000

          return {
            id: p.id,
            username: p.username,
            elo: p.elo_rating || 1000,
            level: p.trainer_level || 1,
            badges: p.badges || 0,
            playerClass: p.player_class,
            faction: p.faction,
            nick_style: p.nick_style,
            isOnline: !!isOnline
          }
        })
      }
    } catch (err) {
      console.error('[SocialStore] Leaderboard error:', err)
    } finally {
      leaderboardLoading.value = false
    }
  }

  return {
    friends,
    pendingRequests,
    searchResults,
    searchLoading,
    loading,
    notifications,
    leaderboard,
    leaderboardLoading,
    loadSocialData,
    searchPlayers,
    sendFriendRequest,
    respondRequest,
    removeFriend,
    startPresence,
    stopPresence,
    refreshNotificationCount,
    fetchLeaderboard
  }
})

import { defineStore } from 'pinia'
import { ref, reactive, computed } from 'vue'
import { useAuthStore } from './auth'
import { useGameStore } from './game'
import { useUIStore } from './ui'
import { useSocialStore } from './social'
import { useAudioStore } from './audio'
import { useLoadingStore } from './loading'

export const useTradeStore = defineStore('trade', () => {
  const authStore = useAuthStore() as any
  const gameStore = useGameStore() as any
  const uiStore = useUIStore() as any
  const socialStore = useSocialStore() as any
  const audioStore = useAudioStore() as any
  const loadingStore = useLoadingStore() as any

  const tradeTarget = ref<{ id: string; username: string } | null>(null)
  const tradeFriendSave = ref<any>(null)

  const tradeOfferPoke = ref<any>(null)
  const tradeRequestPoke = ref<any>(null)
  const tradeOfferItems = reactive<Record<string, number>>({})
  const tradeRequestItems = reactive<Record<string, number>>({})

  const pendingIncoming = ref<any[]>([])
  const pendingOutgoing = ref<any[]>([])
  const pendingAccepted = ref<any[]>([])

  let tradeChannel: any = null

  async function subscribeTradeNotifs() {
    if (!authStore.user || authStore.sessionMode === 'offline') return
    if (tradeChannel) tradeChannel.unsubscribe()

    const db = gameStore.db
    tradeChannel = db.channel('trade-notifs-' + authStore.user.id)
      .on('postgres_changes', {
        event: 'INSERT', schema: 'public', table: 'claim_queue',
        filter: `user_id=eq.${authStore.user.id}`
      }, () => {
        uiStore.notify(' ¡Nuevos activos disponibles para reclamar!', '🎁')
        gameStore.fetchClaimQueue()
      })
      .on('postgres_changes', {
        event: 'INSERT', schema: 'public', table: 'trade_offers',
        filter: `receiver_id=eq.${authStore.user.id}`
      }, () => {
        uiStore.notify('¡Has recibido una nueva oferta de intercambio!', '🔄')
        audioStore.notif()
        refreshPendingTrades()
      })
      .subscribe()
  }

  async function refreshPendingTrades() {
    if (!authStore.user || authStore.sessionMode === 'offline') return

    const db = gameStore.db
    const [incomingRes, outgoingRes, acceptedRes] = await Promise.all([
      db.from('trade_offers').select('*').eq('receiver_id', authStore.user.id).eq('status', 'pending'),
      db.from('trade_offers').select('*').eq('sender_id', authStore.user.id).eq('status', 'pending'),
      db.from('trade_offers').select('*').eq('sender_id', authStore.user.id).eq('status', 'accepted')
    ])

    pendingIncoming.value = incomingRes.data || []
    pendingOutgoing.value = outgoingRes.data || []
    pendingAccepted.value = acceptedRes.data || []

    // Sincronizar contador en socialStore
    await socialStore.refreshNotificationCount()
  }

  async function openTradeModal(friendId: string, friendUsername: string) {
    tradeTarget.value = { id: friendId, username: friendUsername }
    tradeOfferPoke.value = null
    tradeRequestPoke.value = null
    Object.keys(tradeOfferItems).forEach(k => delete tradeOfferItems[k])
    Object.keys(tradeRequestItems).forEach(k => delete tradeRequestItems[k])

    const db = gameStore.db
    const { data, error } = await (db as any).from('game_saves').select('save_data').eq('user_id', friendId).single()

    if (error || !data) {
      tradeFriendSave.value = { team: [], inventory: {}, money: 0 }
      uiStore.notify('No se pudo cargar el inventario del amigo.', '⚠️')
    } else {
      tradeFriendSave.value = data.save_data
    }
  }

  async function sendTradeOffer({ isGift, offerMoney, requestMoney, message }: { isGift: boolean; offerMoney: number; requestMoney: number; message: string }) {
    if (!tradeTarget.value) return false
    if (authStore.sessionMode === 'offline') return false

    const hasOffer = tradeOfferPoke.value !== null || Object.keys(tradeOfferItems).length > 0 || offerMoney > 0
    if (!hasOffer) {
      uiStore.notify('Tenés que ofrecer algo.', '⚠️')
      return false
    }

    if (offerMoney > gameStore.state.money) {
      uiStore.notify('No tenés suficiente dinero.', '💸')
      return false
    }

    // Anti-Duplicate check
    if (tradeOfferPoke.value && lockedUids.value.has(tradeOfferPoke.value.uid)) {
      uiStore.notify('Este Pokémon ya está en otra oferta pendiente.', '⚠️')
      return false
    }

    // MANDATORY: Pre-Action Flush (Always save before social actions with assets)
    uiStore.notify('Sincronizando inventario...', '🔄')
    await gameStore.save(false)

    const { data: tradeId, error } = await (gameStore.db as any).rpc('send_trade_offer_v2', {
      p_receiver_id: tradeTarget.value.id,
      p_offer_pokemon: tradeOfferPoke.value,
      p_offer_items: { ...tradeOfferItems },
      p_offer_money: offerMoney,
      p_request_pokemon: isGift ? null : tradeRequestPoke.value,
      p_request_items: isGift ? {} : { ...tradeRequestItems },
      p_request_money: isGift ? 0 : requestMoney,
      p_message: message || ''
    })

    if (!error && tradeId) {
      uiStore.notify(`¡Oferta enviada a ${tradeTarget.value.username}!`, '🔄')
      audioStore.sentMsg() 
      refreshPendingTrades()
      return true
    }

    uiStore.notify('Error al enviar: ' + (error?.message || 'Error desconocido'), '❌')
    return false
  }

  async function acceptTrade(tradeId: string | number) {
    if (authStore.sessionMode === 'offline') return false

    try {
      loadingStore.start('accept_trade', 'Procesando intercambio...', 'Sincronizando con el servidor')

      // MANDATORY: Pre-Action Flush
      uiStore.notify('Sincronizando inventario...', '🔄')
      await gameStore.save(false)

      const db = gameStore.db
      const { error: rpcErr } = await (db as any).rpc('accept_trade_v2', {
        p_trade_id: tradeId
      })

      if (rpcErr) throw new Error((rpcErr as any).message)

      uiStore.notify('¡Intercambio aceptado! Los activos están en tu cola de reclamo.', '🎉')
      await gameStore.fetchClaimQueue()

      loadingStore.finish('accept_trade')
      await refreshPendingTrades()
      return true
    } catch (err) {
      loadingStore.finish('accept_trade')
      console.error('[TRADE ERROR]', err)
      uiStore.notify('Error en el intercambio: ' + (err as any).message, '❌')
      return false
    }
  }

  async function rejectTrade(tradeId: string | number) {
    await (gameStore.db as any).from('trade_offers').update({ status: 'rejected' }).eq('id', tradeId)
    uiStore.notify('Oferta rechazada.', '👋')
    await refreshPendingTrades()
  }

  async function claimTrade(tradeId: string | number) {
    const { error } = await (gameStore.db as any).from('trade_offers').update({ status: 'claimed' }).eq('id', tradeId)
    if (!error) await refreshPendingTrades()
  }

  const lockedUids = computed(() => {
    const locked = new Set<string>()
    pendingIncoming.value.forEach(t => {
      if (t.request_pokemon?.uid) locked.add(t.request_pokemon.uid)
    })
    pendingOutgoing.value.forEach(t => {
      if (t.offer_pokemon?.uid) locked.add(t.offer_pokemon.uid)
    })
    return locked
  })

  return {
    tradeTarget,
    tradeFriendSave,
    tradeOfferPoke,
    tradeRequestPoke,
    tradeOfferItems,
    tradeRequestItems,
    pendingIncoming,
    pendingOutgoing,
    pendingAccepted,
    lockedUids,
    subscribeTradeNotifs,
    refreshPendingTrades,
    openTradeModal,
    sendTradeOffer,
    acceptTrade,
    rejectTrade,
    claimTrade
  }
})

